const e=[{id:0,oaid:"W2781738013",doi:"10.22331/q-2018-08-06-79",title:"Quantum Computing in the NISQ era and beyond",authors:[{name:"John Preskill",institutions:["California Institute of Technology"]}],authorString:"John Preskill",institutions:["California Institute of Technology"],countries:["US"],year:2018,journal:"Quantum",citations:8381,abstract:"Noisy Intermediate-Scale Quantum (NISQ) technology will be available in the near future. Quantum computers with 50-100 qubits may be able to perform tasks which surpass the capabilities of today's classical digital computers, but noise in quantum gates will limit the size of quantum circuits that can be executed reliably. NISQ devices will be useful tools for exploring many-body quantum physics, and may have other useful applications, but the 100-qubit quantum computer will not change the world right away - we should regard it as a significant step toward the more powerful quantum technologies of the future. Quantum technologists should continue to strive for more accurate quantum gates and, eventually, fully fault-tolerant quantum computing.",keywords:["Quantum computer","Qubit","Quantum gate","Computer engineering","Quantum network","Quantum error correction","Quantum information"],concepts:["Quantum computer","Qubit","Quantum gate","Computer engineering","Quantum network","Quantum error correction","Quantum information"],pdf_url:"https://quantum-journal.org/papers/q-2018-08-06-79/pdf/",is_oa:!0,n_refs:82,n_refs_in_core:4,degree:129,community:0,deg_w:1864.5,betweenness:.0581,pagerank:.01349,eigenvector:.1367},{id:1,oaid:"W2982169647",doi:"10.1038/s41586-019-1666-5",title:"Quantum supremacy using a programmable superconducting processor",authors:[{name:"Frank Arute",institutions:["Google (United States)"]},{name:"Kunal Arya",institutions:["Google (United States)"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Dave Bacon",institutions:["Google (United States)"]},{name:"Joseph C. Bardin",institutions:["Google (United States)","University of Massachusetts Amherst"]},{name:"Rami Barends",institutions:["Google (United States)"]},{name:"Rupak Biswas",institutions:["Ames Research Center"]},{name:"Sergio Boixo",institutions:["Google (United States)"]},{name:"Fernando G. S. L. Brandao",institutions:["California Institute of Technology","Google (United States)"]},{name:"David A. Buell",institutions:["Google (United States)"]},{name:"Brian Burkett",institutions:["Google (United States)"]},{name:"Yu Chen",institutions:["Google (United States)"]},{name:"Zijun Chen",institutions:["Google (United States)"]},{name:"Ben Chiaro",institutions:["University of California, Santa Barbara"]},{name:"Roberto Collins",institutions:["Google (United States)"]},{name:"William Courtney",institutions:["Google (United States)"]},{name:"Andrew Dunsworth",institutions:["Google (United States)"]},{name:"Edward Farhi",institutions:["Google (United States)"]},{name:"Brooks Foxen",institutions:["Google (United States)","University of California, Santa Barbara"]},{name:"Austin Fowler",institutions:["Google (United States)"]},{name:"Craig Gidney",institutions:["Google (United States)"]},{name:"Marissa Giustina",institutions:["Google (United States)"]},{name:"Rob Graff",institutions:["Google (United States)"]},{name:"Keith Guerin",institutions:["Google (United States)"]},{name:"Steve Habegger",institutions:["Google (United States)"]},{name:"Matthew P. Harrigan",institutions:["Google (United States)"]},{name:"Michael J. Hartmann",institutions:["Google (United States)","Friedrich-Alexander-Universität Erlangen-Nürnberg"]},{name:"Alan Ho",institutions:["Google (United States)"]},{name:"Markus Hoffmann",institutions:["Google (United States)"]},{name:"Trent Huang",institutions:["Google (United States)"]},{name:"Travis S. Humble",institutions:["Oak Ridge National Laboratory","Quantum Science Center"]},{name:"Sergei V. Isakov",institutions:["Google (United States)"]},{name:"Evan Jeffrey",institutions:["Google (United States)"]},{name:"Zhang Jiang",institutions:["Google (United States)"]},{name:"Dvir Kafri",institutions:["Google (United States)"]},{name:"Kostyantyn Kechedzhi",institutions:["Google (United States)"]},{name:"Julian Kelly",institutions:["Google (United States)"]},{name:"Paul V. Klimov",institutions:["Google (United States)"]},{name:"Sergey Knysh",institutions:["Google (United States)"]},{name:"Alexander Korotkov",institutions:["University of California, Riverside","Google (United States)"]},{name:"Fedor Kostritsa",institutions:["Google (United States)"]},{name:"David Landhuis",institutions:["Google (United States)"]},{name:"Mike Lindmark",institutions:["Google (United States)"]},{name:"Erik Lucero",institutions:["Google (United States)"]},{name:"Dmitry Lyakh",institutions:["Oak Ridge National Laboratory"]},{name:"Salvatore Mandrà",institutions:["Ames Research Center","Stinger Ghaffarian Technologies (United States)"]},{name:"Jarrod R. McClean",institutions:["Google (United States)"]},{name:"Matthew McEwen",institutions:["University of California, Santa Barbara"]},{name:"Anthony Megrant",institutions:["Google (United States)"]},{name:"Xiao Mi",institutions:["Google (United States)"]},{name:"Kristel Michielsen",institutions:["Forschungszentrum Jülich","RWTH Aachen University"]},{name:"Masoud Mohseni",institutions:["Google (United States)"]},{name:"Josh Mutus",institutions:["Google (United States)"]},{name:"Ofer Naaman",institutions:["Google (United States)"]},{name:"Matthew Neeley",institutions:["Google (United States)"]},{name:"Charles Neill",institutions:["Google (United States)"]},{name:"Murphy Yuezhen Niu",institutions:["Google (United States)"]},{name:"Eric Ostby",institutions:["Google (United States)"]},{name:"Andre Petukhov",institutions:["Google (United States)"]},{name:"John C. Platt",institutions:["Google (United States)"]},{name:"Chris Quintana",institutions:["Google (United States)"]},{name:"Eleanor G. Rieffel",institutions:["Ames Research Center"]},{name:"Pedram Roushan",institutions:["Google (United States)"]},{name:"Nicholas C. Rubin",institutions:["Google (United States)"]},{name:"Daniel Sank",institutions:["Google (United States)"]},{name:"Kevin J. Satzinger",institutions:["Google (United States)"]},{name:"Vadim Smelyanskiy",institutions:["Google (United States)"]},{name:"Kevin J. Sung",institutions:["Google (United States)","University of Michigan"]},{name:"Matthew D. Trevithick",institutions:["Google (United States)"]},{name:"Amit Vainsencher",institutions:["Google (United States)"]},{name:"Benjamin Villalonga",institutions:["Google (United States)","University of Illinois Urbana-Champaign"]},{name:"Theodore White",institutions:["Google (United States)"]},{name:"Z. Jamie Yao",institutions:["Google (United States)"]},{name:"Ping Yeh",institutions:["Google (United States)"]},{name:"Adam Zalcman",institutions:["Google (United States)"]},{name:"Hartmut Neven",institutions:["Google (United States)"]},{name:"John M. Martinis",institutions:["Google (United States)","University of California, Santa Barbara"]}],authorString:"Frank Arute; Kunal Arya; Ryan Babbush; Dave Bacon; Joseph C. Bardin; Rami Barends; Rupak Biswas; Sergio Boixo; Fernando G. S. L. Brandao; David A. Buell; Brian Burkett; Yu Chen et al.",institutions:["Ames Research Center","California Institute of Technology","Forschungszentrum Jülich","Friedrich-Alexander-Universität Erlangen-Nürnberg","Google (United States)","Oak Ridge National Laboratory","Quantum Science Center","RWTH Aachen University","Stinger Ghaffarian Technologies (United States)","University of California, Riverside","University of California, Santa Barbara","University of Illinois Urbana-Champaign","University of Massachusetts Amherst","University of Michigan"],countries:["DE","US"],year:2019,journal:"Nature",citations:7059,abstract:"The promise of quantum computers is that certain computational tasks might be executed exponentially faster on a quantum processor than on a classical processor1. A fundamental challenge is to build a high-fidelity processor capable of running quantum algorithms in an exponentially large computational space. Here we report the use of a processor with programmable superconducting qubits2–7 to create quantum states on 53 qubits, corresponding to a computational state-space of dimension 253 (about 1016). Measurements from repeated experiments sample the resulting probability distribution, which we verify using classical simulations. Our Sycamore processor takes about 200 seconds to sample one instance of a quantum circuit a million times—our benchmarks currently indicate that the equivalent task for a state-of-the-art classical supercomputer would take approximately 10,000 years. This dramatic increase in speed compared to all known classical algorithms is an experimental realization of quantum supremacy8–14 for this specific computational task, heralding a much-anticipated computing paradigm. Quantum supremacy is demonstrated using a programmable superconducting processor known as Sycamore, taking approximately 200 seconds to sample one instance of a quantum circuit a million times, which would take a state-of-the-art supercomputer around ten thousand years to compute.",keywords:["Quantum computer","Quantum","Realization","Dimension","Quantum algorithm","Task","Quantum circuit","Sample"],concepts:["Quantum computer","Quantum","Realization","Dimension","Quantum algorithm","Task","Quantum circuit"],pdf_url:"https://www.nature.com/articles/s41586-019-1666-5.pdf",is_oa:!0,n_refs:54,n_refs_in_core:5,degree:68,community:3,deg_w:939,betweenness:.0148,pagerank:.00714,eigenvector:.0775},{id:2,oaid:"W2161685427",doi:"10.1038/ncomms5213",title:"A variational eigenvalue solver on a photonic quantum processor",authors:[{name:"Alberto Peruzzo",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Jarrod R. McClean",institutions:["Harvard University","Harvard University Press"]},{name:"Peter Shadbolt",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Man‐Hong Yung",institutions:["Harvard University","Beijing Academy of Quantum Information Sciences"]},{name:"Xiaoqi Zhou",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Peter J. Love",institutions:["Haverford College"]},{name:"Alán Aspuru‐Guzik",institutions:["Harvard University"]},{name:"Jeremy L. O’Brien",institutions:["University of Bristol"]}],authorString:"Alberto Peruzzo; Jarrod R. McClean; Peter Shadbolt; Man‐Hong Yung; Xiaoqi Zhou; Peter J. Love; Alán Aspuru‐Guzik; Jeremy L. O’Brien",institutions:["Beijing Academy of Quantum Information Sciences","Bristol Robotics Laboratory","Harvard University","Harvard University Press","Haverford College","University of Bristol"],countries:["CN","GB","US"],year:2014,journal:"Nature Communications",citations:4640,abstract:"Quantum computers promise to efficiently solve important problems that are intractable on a conventional computer. For quantum systems, where the physical dimension grows exponentially, finding the eigenvalues of certain operators is one such intractable problem and remains a fundamental challenge. The quantum phase estimation algorithm efficiently finds the eigenvalue of a given eigenvector but requires fully coherent evolution. Here we present an alternative approach that greatly reduces the requirements for coherent evolution and combine this method with a new approach to state preparation based on ansätze and classical optimization. We implement the algorithm by combining a highly reconfigurable photonic quantum processor with a conventional computer. We experimentally demonstrate the feasibility of this approach with an example from quantum chemistry—calculating the ground-state molecular energy for He–H+. The proposed approach drastically reduces the coherence time requirements, enhancing the potential of quantum resources available today and in the near future. Quantum computers promise to efficiently solve problems that would be practically impossible with a normal computer. Peruzzo et al. develop a variational computation approach that uses any available quantum resources and, with a photonic quantum processing unit, find the ground-state molecular energy of He–H+.",keywords:["Eigenvalues and eigenvectors","Quantum","Quantum computer","Coherence","Solver","Quantum algorithm","Photonics"],concepts:["Eigenvalues and eigenvectors","Quantum","Quantum computer","Coherence","Solver","Quantum algorithm","Photonics"],pdf_url:"https://www.nature.com/articles/ncomms5213.pdf",is_oa:!0,n_refs:47,n_refs_in_core:1,degree:169,community:1,deg_w:2187.5,betweenness:.1046,pagerank:.01561,eigenvector:.1518},{id:3,oaid:"W1492999010",doi:"10.1103/physrevlett.103.150502",title:"Quantum Algorithm for Linear Systems of Equations",authors:[{name:"Aram W. Harrow",institutions:["University of Bristol"]},{name:"Avinatan Hassidim",institutions:["Cambridge Electronics (United States)"]},{name:"Seth Lloyd",institutions:["Cambridge Electronics (United States)"]}],authorString:"Aram W. Harrow; Avinatan Hassidim; Seth Lloyd",institutions:["Cambridge Electronics (United States)","University of Bristol"],countries:["GB","US"],year:2009,journal:"Physical Review Letters",citations:3321,abstract:"Solving linear systems of equations is a common problem that arises both on its own and as a subroutine in more complex problems: given a matrix $A$ and a vector $\\stackrel{\\ensuremath{\\rightarrow}}{b}$, find a vector $\\stackrel{\\ensuremath{\\rightarrow}}{x}$ such that $A\\stackrel{\\ensuremath{\\rightarrow}}{x}=\\stackrel{\\ensuremath{\\rightarrow}}{b}$. We consider the case where one does not need to know the solution $\\stackrel{\\ensuremath{\\rightarrow}}{x}$ itself, but rather an approximation of the expectation value of some operator associated with $\\stackrel{\\ensuremath{\\rightarrow}}{x}$, e.g., ${\\stackrel{\\ensuremath{\\rightarrow}}{x}}^{\\ifmmode\\dagger\\else\\textdagger\\fi{}}M\\stackrel{\\ensuremath{\\rightarrow}}{x}$ for some matrix $M$. In this case, when $A$ is sparse, $N\\ifmmode\\times\\else\\texttimes\\fi{}N$ and has condition number $\\ensuremath{\\kappa}$, the fastest known classical algorithms can find $\\stackrel{\\ensuremath{\\rightarrow}}{x}$ and estimate ${\\stackrel{\\ensuremath{\\rightarrow}}{x}}^{\\ifmmode\\dagger\\else\\textdagger\\fi{}}M\\stackrel{\\ensuremath{\\rightarrow}}{x}$ in time scaling roughly as $N\\sqrt{\\ensuremath{\\kappa}}$. Here, we exhibit a quantum algorithm for estimating ${\\stackrel{\\ensuremath{\\rightarrow}}{x}}^{\\ifmmode\\dagger\\else\\textdagger\\fi{}}M\\stackrel{\\ensuremath{\\rightarrow}}{x}$ whose runtime is a polynomial of $\\mathrm{log}\uFEFF(N)$ and $\\ensuremath{\\kappa}$. Indeed, for small values of $\\ensuremath{\\kappa}$ [i.e., $\\mathrm{poly}\\mathrm{log}\uFEFF(N)$], we prove (using some common complexity-theoretic assumptions) that any classical algorithm for this problem generically requires exponentially more time than our quantum algorithm.",keywords:["Combinatorics","Quantum algorithm","Mathematical physics","Quantum","Quantum mechanics"],concepts:["Combinatorics","Quantum algorithm","Mathematical physics","Quantum"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevLett.103.150502",is_oa:!0,n_refs:35,n_refs_in_core:1,degree:53,community:0,deg_w:411.5,betweenness:.0116,pagerank:.00382,eigenvector:.0268},{id:4,oaid:"W2060904747",doi:"10.1103/physreva.69.062320",title:"Cavity quantum electrodynamics for superconducting electrical circuits: An architecture for quantum computation",authors:[{name:"Alexandre Blais",institutions:["Yale University"]},{name:"Ren-Shou Huang",institutions:["Yale University","Indiana University Bloomington"]},{name:"Andreas Wallraff",institutions:["Yale University"]},{name:"S. M. Girvin",institutions:["Yale University"]},{name:"Robert Schoelkopf",institutions:["Yale University"]}],authorString:"Alexandre Blais; Ren-Shou Huang; Andreas Wallraff; S. M. Girvin; Robert Schoelkopf",institutions:["Indiana University Bloomington","Yale University"],countries:["US"],year:2004,journal:"Physical Review A",citations:2988,abstract:"We propose a realizable architecture using one-dimensional transmission line resonators to reach the strong-coupling limit of cavity quantum electrodynamics in superconducting electrical circuits. The vacuum Rabi frequency for the coupling of cavity photons to quantized excitations of an adjacent electrical circuit (qubit) can easily exceed the damping rates of both the cavity and qubit. This architecture is attractive both as a macroscopic analog of atomic physics experiments and for quantum computing and control, since it provides strong inhibition of spontaneous emission, potentially leading to greatly enhanced qubit lifetimes, allows high-fidelity quantum nondemolition measurements of the state of multiple qubits, and has a natural mechanism for entanglement of qubits separated by centimeter distances. In addition it would allow production of microwave photon states of fundamental importance for quantum communication.",keywords:["Circuit quantum electrodynamics","Qubit","Cavity quantum electrodynamics","Superconducting quantum computing","Phase qubit","Photon","Quantum computer"],concepts:["Circuit quantum electrodynamics","Qubit","Cavity quantum electrodynamics","Superconducting quantum computing","Phase qubit","Photon","Quantum computer"],pdf_url:"https://arxiv.org/pdf/cond-mat/0402216",is_oa:!0,n_refs:43,n_refs_in_core:0,degree:14,community:3,deg_w:127,betweenness:2e-4,pagerank:.00169,eigenvector:.0069},{id:5,oaid:"W2257937122",doi:"10.1088/1367-2630/18/2/023023",title:"The theory of variational hybrid quantum-classical algorithms",authors:[{name:"Jarrod R. McClean",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Jonathan Romero",institutions:["Harvard University"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Alán Aspuru‐Guzik",institutions:["Harvard University"]}],authorString:"Jarrod R. McClean; Jonathan Romero; Ryan Babbush; Alán Aspuru‐Guzik",institutions:["Google (United States)","Harvard University","Lawrence Berkeley National Laboratory"],countries:["US"],year:2016,journal:"New Journal of Physics",citations:2286,abstract:"Many quantum algorithms have daunting resource requirements when compared to what is available today. To address this discrepancy, a quantum-classical hybrid optimization scheme known as 'the quantum variational eigensolver' was developed (Peruzzo et al 2014 Nat. Commun. 5 4213) with the philosophy that even minimal quantum resources could be made useful when used in conjunction with classical routines. In this work we extend the general theory of this algorithm and suggest algorithmic improvements for practical implementations. Specifically, we develop a variational adiabatic ansatz and explore unitary coupled cluster where we establish a connection from second order unitary coupled cluster to universal gate sets through a relaxation of exponential operator splitting. We introduce the concept of quantum variational error suppression that allows some errors to be suppressed naturally in this algorithm on a pre-threshold quantum device. Additionally, we analyze truncation and correlated sampling in Hamiltonian averaging as ways to reduce the cost of this procedure. Finally, we show how the use of modern derivative free optimization techniques can offer dramatic computational savings of up to three orders of magnitude over previously used optimization techniques.",keywords:["Quantum machine learning","Hamiltonian","Quantum","Quantum computer","Quantum algorithm","Ansatz","Coupled cluster"],concepts:["Quantum machine learning","Hamiltonian","Quantum","Quantum computer","Quantum algorithm","Ansatz","Coupled cluster"],pdf_url:"https://iopscience.iop.org/article/10.1088/1367-2630/18/2/023023/pdf",is_oa:!0,n_refs:98,n_refs_in_core:3,degree:130,community:1,deg_w:2113.5,betweenness:.0462,pagerank:.01471,eigenvector:.1564},{id:6,oaid:"W2419175238",doi:"10.1126/science.aag2302",title:"Solving the quantum many-body problem with artificial neural networks",authors:[{name:"Giuseppe Carleo",institutions:["ETH Zurich"]},{name:"Matthias Troyer",institutions:["Microsoft (United States)","ETH Zurich"]}],authorString:"Giuseppe Carleo; Matthias Troyer",institutions:["ETH Zurich","Microsoft (United States)"],countries:["CH","US"],year:2017,journal:"Science",citations:2255,abstract:"The challenge posed by the many-body problem in quantum physics originates from the difficulty of describing the nontrivial correlations encoded in the exponential complexity of the many-body wave function. Here we demonstrate that systematic machine learning of the wave function can reduce this complexity to a tractable computational form for some notable cases of physical interest. We introduce a variational representation of quantum states based on artificial neural networks with a variable number of hidden neurons. A reinforcement-learning scheme we demonstrate is capable of both finding the ground state and describing the unitary time evolution of complex interacting quantum systems. Our approach achieves high accuracy in describing prototypical interacting spins models in one and two dimensions.",keywords:["Unitary state","Quantum","Quantum machine learning","Artificial neural network","Reinforcement learning","Wave function","Spins"],concepts:["Unitary state","Quantum","Quantum machine learning","Artificial neural network","Reinforcement learning","Wave function","Spins"],pdf_url:"https://arxiv.org/pdf/1606.02318",is_oa:!0,n_refs:57,n_refs_in_core:0,degree:28,community:0,deg_w:168.5,betweenness:.0021,pagerank:.00206,eigenvector:.0114},{id:7,oaid:"W2794444783",doi:"10.1038/s41467-018-07090-4",title:"Barren plateaus in quantum neural network training landscapes",authors:[{name:"Jarrod R. McClean",institutions:["Google (United States)"]},{name:"Sergio Boixo",institutions:["Google (United States)"]},{name:"Vadim Smelyanskiy",institutions:["Google (United States)"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Hartmut Neven",institutions:["Google (United States)"]}],authorString:"Jarrod R. McClean; Sergio Boixo; Vadim Smelyanskiy; Ryan Babbush; Hartmut Neven",institutions:["Google (United States)"],countries:["US"],year:2018,journal:"Nature Communications",citations:2174,abstract:"Many experimental proposals for noisy intermediate scale quantum devices involve training a parameterized quantum circuit with a classical optimization loop. Such hybrid quantum-classical algorithms are popular for applications in quantum simulation, optimization, and machine learning. Due to its simplicity and hardware efficiency, random circuits are often proposed as initial guesses for exploring the space of quantum states. We show that the exponential dimension of Hilbert space and the gradient estimation complexity make this choice unsuitable for hybrid quantum-classical algorithms run on more than a few qubits. Specifically, we show that for a wide class of reasonable parameterized quantum circuits, the probability that the gradient along any reasonable direction is non-zero to some fixed precision is exponentially small as a function of the number of qubits. We argue that this is related to the 2-design characteristic of random circuits, and that solutions to this problem must be studied.",keywords:["Qubit","Parameterized complexity","Quantum circuit","Quantum algorithm","Quantum","Quantum gate","Quantum error correction"],concepts:["Qubit","Parameterized complexity","Quantum circuit","Quantum algorithm","Quantum","Quantum gate","Quantum error correction"],pdf_url:"https://www.nature.com/articles/s41467-018-07090-4.pdf",is_oa:!0,n_refs:63,n_refs_in_core:11,degree:99,community:0,deg_w:1676.5,betweenness:.0271,pagerank:.01192,eigenvector:.1348},{id:8,oaid:"W2066500891",doi:"10.1126/science.1231930",title:"Superconducting Circuits for Quantum Information: An Outlook",authors:[{name:"Michel Devoret",institutions:["Collège de France","Yale University"]},{name:"Robert Schoelkopf",institutions:["Yale University"]}],authorString:"Michel Devoret; Robert Schoelkopf",institutions:["Collège de France","Yale University"],countries:["FR","US"],year:2013,journal:"Science",citations:2118,abstract:"The performance of superconducting qubits has improved by several orders of magnitude in the past decade. These circuits benefit from the robustness of superconductivity and the Josephson effect, and at present they have not encountered any hard physical limits. However, building an error-corrected information processor with many such qubits will require solving specific architecture problems that constitute a new field of research. For the first time, physicists will have to master quantum error correction to design and operate complex active systems that are dissipative in nature, yet remain coherent indefinitely. We offer a view on some directions for the field and speculate on its future.",keywords:["Qubit","Robustness","Superconducting quantum computing","Dissipative system","Quantum","Superconductivity","Quantum information"],concepts:["Qubit","Robustness","Superconducting quantum computing","Dissipative system","Quantum","Superconductivity","Quantum information"],pdf_url:null,is_oa:!1,n_refs:71,n_refs_in_core:1,degree:23,community:3,deg_w:291,betweenness:.0013,pagerank:.00294,eigenvector:.0153},{id:9,oaid:"W2103956991",doi:"10.1103/physrevlett.113.130503",title:"Quantum Support Vector Machine for Big Data Classification",authors:[{name:"Patrick Rebentrost",institutions:["Massachusetts Institute of Technology"]},{name:"Masoud Mohseni",institutions:["Google (United States)"]},{name:"Seth Lloyd",institutions:["Massachusetts Institute of Technology"]}],authorString:"Patrick Rebentrost; Masoud Mohseni; Seth Lloyd",institutions:["Google (United States)","Massachusetts Institute of Technology"],countries:["US"],year:2014,journal:"Physical Review Letters",citations:1975,abstract:"Supervised machine learning is the classification of new data based on already classified training examples. In this work, we show that the support vector machine, an optimized binary classifier, can be implemented on a quantum computer, with complexity logarithmic in the size of the vectors and the number of training examples. In cases where classical sampling algorithms require polynomial time, an exponential speedup is obtained. At the core of this quantum big data algorithm is a nonsparse matrix exponentiation technique for efficiently performing a matrix inversion of the training data inner-product (kernel) matrix.",keywords:["Support vector machine","Logarithm","Quantum computer","Quantum","Exponentiation","Quantum machine learning"],concepts:["Support vector machine","Logarithm","Quantum computer","Quantum","Exponentiation","Quantum machine learning"],pdf_url:"https://arxiv.org/pdf/1307.0471",is_oa:!0,n_refs:31,n_refs_in_core:2,degree:43,community:0,deg_w:359.5,betweenness:.0051,pagerank:.0036,eigenvector:.0172},{id:10,oaid:"W1521266393",doi:"10.1103/revmodphys.93.025005",title:"Circuit quantum electrodynamics",authors:[{name:"Alexandre Blais",institutions:["Canadian Institute for Advanced Research","Université de Sherbrooke"]},{name:"Arne L. Grimsmo",institutions:["Canadian Institute for Advanced Research","The University of Sydney","Université de Sherbrooke","ARC Centre of Excellence for Engineered Quantum Systems"]},{name:"S. M. Girvin",institutions:["Canadian Institute for Advanced Research","Université de Sherbrooke","Yale University"]},{name:"Andreas Wallraff",institutions:["Canadian Institute for Advanced Research","Université de Sherbrooke","ETH Zurich"]}],authorString:"Alexandre Blais; Arne L. Grimsmo; S. M. Girvin; Andreas Wallraff",institutions:["ARC Centre of Excellence for Engineered Quantum Systems","Canadian Institute for Advanced Research","ETH Zurich","The University of Sydney","Université de Sherbrooke","Yale University"],countries:["AU","CA","CH","US"],year:2021,journal:"Reviews of Modern Physics",citations:1912,abstract:"This review surveys the development over the last 15 years of circuit quantum electrodynamics, the nonlinear quantum optics of microwave electrical circuits. In analogy to cavity quantum electrodynamics, lasers are replaced by rf signal generators, optical cavities by superconducting resonators, and atoms by superconducting qubits. Circuit QED offers enhanced light-matter coupling in which strong quantum optical nonlinearities are observable at the level of individual photons. This new parameter regime leads to unique capabilities for fundamental studies in quantum optics, nearly ideal quantum-limited measurements, and quantum computation.",keywords:["Circuit quantum electrodynamics","Qubit","Cavity quantum electrodynamics","Superconducting quantum computing","Quantum technology","Quantum decoherence","Photon"],concepts:["Circuit quantum electrodynamics","Qubit","Cavity quantum electrodynamics","Superconducting quantum computing","Quantum technology","Quantum decoherence","Photon"],pdf_url:"https://arxiv.org/pdf/2005.12667",is_oa:!0,n_refs:747,n_refs_in_core:16,degree:34,community:3,deg_w:1032.5,betweenness:.003,pagerank:.00799,eigenvector:.0657},{id:11,oaid:"W2950805899",doi:"10.1063/1.5089550",title:"A quantum engineer's guide to superconducting qubits",authors:[{name:"Philip Krantz",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology","Chalmers University of Technology"]},{name:"Morten Kjærgaard",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology","Chalmers University of Technology"]},{name:"Fei Yan",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology","Chalmers University of Technology"]},{name:"Terry P. Orlando",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology","Chalmers University of Technology"]},{name:"Simon Gustavsson",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology","Chalmers University of Technology"]},{name:"William D. Oliver",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology","Chalmers University of Technology"]}],authorString:"Philip Krantz; Morten Kjærgaard; Fei Yan; Terry P. Orlando; Simon Gustavsson; William D. Oliver",institutions:["Chalmers University of Technology","MIT Lincoln Laboratory","Massachusetts Institute of Technology"],countries:["SE","US"],year:2019,journal:"Applied Physics Reviews",citations:1904,abstract:"The aim of this review is to provide quantum engineers with an introductory guide to the central concepts and challenges in the rapidly accelerating field of superconducting quantum circuits. Over the past twenty years, the field has matured from a predominantly basic research endeavor to a one that increasingly explores the engineering of larger-scale superconducting quantum systems. Here, we review several foundational elements—qubit design, noise properties, qubit control, and readout techniques—developed during this period, bridging fundamental concepts in circuit quantum electrodynamics and contemporary, state-of-the-art applications in gate-model quantum computation.",keywords:["Qubit","Quantum computer","Quantum technology","Quantum","Superconducting quantum computing","Bridging","Quantum information"],concepts:["Qubit","Quantum computer","Quantum technology","Quantum","Superconducting quantum computing","Bridging","Quantum information"],pdf_url:"https://aip.scitation.org/doi/pdf/10.1063/1.5089550",is_oa:!0,n_refs:466,n_refs_in_core:11,degree:40,community:3,deg_w:1208,betweenness:.0049,pagerank:.00919,eigenvector:.0874},{id:12,oaid:"W2792946961",doi:"10.1103/physrevlett.122.040504",title:"Quantum Machine Learning in Feature Hilbert Spaces",authors:[{name:"Maria Schuld",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"]}],authorString:"Maria Schuld; Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"],countries:["CA"],year:2019,journal:"Physical Review Letters",citations:1702,abstract:"A basic idea of quantum computing is surprisingly similar to that of kernel methods in machine learning, namely, to efficiently perform computations in an intractably large Hilbert space. In this Letter we explore some theoretical foundations of this link and show how it opens up a new avenue for the design of quantum machine learning algorithms. We interpret the process of encoding inputs in a quantum state as a nonlinear feature map that maps data to quantum Hilbert space. A quantum computer can now analyze the input data in this feature space. Based on this link, we discuss two approaches for building a quantum model for classification. In the first approach, the quantum device estimates inner products of quantum states to compute a classically intractable kernel. The kernel can be fed into any classical kernel method such as a support vector machine. In the second approach, we use a variational quantum circuit as a linear model that classifies data explicitly in Hilbert space. We illustrate these ideas with a feature map based on squeezing in a continuous-variable system, and visualize the working principle with two-dimensional minibenchmark datasets.",keywords:["Hilbert space","Kernel","Quantum computer","Reproducing kernel Hilbert space","Quantum machine learning","Quantum state","Feature vector"],concepts:["Hilbert space","Kernel","Quantum computer","Reproducing kernel Hilbert space","Quantum machine learning","Quantum state","Feature vector"],pdf_url:"https://arxiv.org/pdf/1803.07128",is_oa:!0,n_refs:40,n_refs_in_core:3,degree:42,community:0,deg_w:405.5,betweenness:.0036,pagerank:.00384,eigenvector:.0269},{id:13,oaid:"W4213212652",doi:"10.1103/revmodphys.94.015004",title:"Noisy intermediate-scale quantum algorithms",authors:[{name:"Kishor Bharti",institutions:["Centre for Quantum Technologies","National University of Singapore"]},{name:"Alba Cervera-Lierta",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Toronto"]},{name:"Thi Ha Kyaw",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Toronto"]},{name:"Tobias Haug",institutions:["Centre for Quantum Technologies","National University of Singapore","Imperial College London"]},{name:"Sumner Alperin-Lea",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Toronto"]},{name:"Abhinav Anand",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Toronto"]},{name:"Matthias Degroote",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Toronto"]},{name:"Hermanni Heimonen",institutions:["Centre for Quantum Technologies","National University of Singapore"]},{name:"Jakob S. Kottmann",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Toronto"]},{name:"Tim Menke",institutions:["Centre for Quantum Technologies","National University of Singapore","Massachusetts Institute of Technology"]},{name:"Wai‐Keong Mok",institutions:["Centre for Quantum Technologies","National University of Singapore"]},{name:"Sukin Sim",institutions:["Centre for Quantum Technologies","Harvard University","National University of Singapore"]},{name:"L. C. Kwek",institutions:["Centre for Quantum Technologies","National University of Singapore","UMI MajuLab"]},{name:"Alán Aspuru‐Guzik",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Toronto","Vector Institute"]}],authorString:"Kishor Bharti; Alba Cervera-Lierta; Thi Ha Kyaw; Tobias Haug; Sumner Alperin-Lea; Abhinav Anand; Matthias Degroote; Hermanni Heimonen; Jakob S. Kottmann; Tim Menke; Wai‐Keong Mok; Sukin Sim et al.",institutions:["Centre for Quantum Technologies","Harvard University","Imperial College London","Massachusetts Institute of Technology","National University of Singapore","UMI MajuLab","University of Toronto","Vector Institute"],countries:["CA","GB","SG","US"],year:2022,journal:"Reviews of Modern Physics",citations:1686,abstract:"Noisy quantum computers can in principle perform reliable quantum computations, but truly scalable systems require noise levels lower than are presently achieved. Still, moderate-complexity computations can be performed. This review discusses what is possible in this ``noisy intermediate scale'' quantum (NISQ) era. Topic areas include the simulation of many-body physics and chemistry, combinatorial optimization, and machine learning. It is evident that the NISQ era has produced new paradigms for programming that will be built upon as quantum computers are further perfected.",keywords:["Quantum computer","Computation","Scalability","Scale","Quantum","Quantum algorithm","Computational science","Noise"],concepts:["Quantum computer","Computation","Scalability","Scale","Quantum","Quantum algorithm","Computational science","Noise"],pdf_url:"http://link.aps.org/pdf/10.1103/RevModPhys.94.015004",is_oa:!0,n_refs:896,n_refs_in_core:85,degree:117,community:0,deg_w:3937.5,betweenness:.0414,pagerank:.02696,eigenvector:.3462},{id:14,oaid:"W2790388700",doi:"10.1103/physreva.98.032309",title:"Quantum circuit learning",authors:[{name:"Kosuke Mitarai",institutions:["The University of Osaka"]},{name:"Makoto Negoro",institutions:["Japan Science and Technology Agency","The University of Osaka"]},{name:"Masahiro Kitagawa",institutions:["The University of Osaka"]},{name:"Keisuke Fujii",institutions:["Kyoto University","Japan Science and Technology Agency"]}],authorString:"Kosuke Mitarai; Makoto Negoro; Masahiro Kitagawa; Keisuke Fujii",institutions:["Japan Science and Technology Agency","Kyoto University","The University of Osaka"],countries:["JP"],year:2018,journal:"Physical review. A/Physical review, A",citations:1628,abstract:"We propose a classical-quantum hybrid algorithm for machine learning on near-term quantum processors, which we call quantum circuit learning. A quantum circuit driven by our framework learns a given task by tuning parameters implemented on it. The iterative optimization of the parameters allows us to circumvent the high-depth circuit. Theoretical investigation shows that a quantum circuit can approximate nonlinear functions, which is further confirmed by numerical simulations. Hybridizing a low-depth quantum circuit and a classical computer for machine learning, the proposed framework paves the way toward applications of near-term quantum devices for quantum machine learning.",keywords:["Quantum","Quantum circuit","Quantum machine learning","Quantum computer","Quantum algorithm","Electronic engineering","Quantum network"],concepts:["Quantum","Quantum circuit","Quantum machine learning","Quantum computer","Quantum algorithm","Electronic engineering","Quantum network"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.98.032309",is_oa:!0,n_refs:29,n_refs_in_core:5,degree:68,community:0,deg_w:752.5,betweenness:.0096,pagerank:.00622,eigenvector:.0488},{id:15,oaid:"W2947902637",doi:"10.1146/annurev-conmatphys-031119-050605",title:"Superconducting Qubits: Current State of Play",authors:[{name:"Morten Kjaergaard",institutions:["Massachusetts Institute of Technology"]},{name:"Mollie E. Schwartz",institutions:["MIT Lincoln Laboratory"]},{name:"Jochen Braumüller",institutions:["Massachusetts Institute of Technology"]},{name:"Philip Krantz",institutions:["Chalmers University of Technology"]},{name:"Joel I.-J. Wang",institutions:["Massachusetts Institute of Technology"]},{name:"Simon Gustavsson",institutions:["Massachusetts Institute of Technology"]},{name:"William D. Oliver",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology"]}],authorString:"Morten Kjaergaard; Mollie E. Schwartz; Jochen Braumüller; Philip Krantz; Joel I.-J. Wang; Simon Gustavsson; William D. Oliver",institutions:["Chalmers University of Technology","MIT Lincoln Laboratory","Massachusetts Institute of Technology"],countries:["SE","US"],year:2019,journal:"Annual Review of Condensed Matter Physics",citations:1431,abstract:"Superconducting qubits are leading candidates in the race to build a quantum computer capable of realizing computations beyond the reach of modern supercomputers. The superconducting qubit modality has been used to demonstrate prototype algorithms in the noisy intermediate-scale quantum (NISQ) technology era, in which non-error-corrected qubits are used to implement quantum simulations and quantum algorithms. With the recent demonstrations of multiple high-fidelity, two-qubit gates as well as operations on logical qubits in extensible superconducting qubit systems, this modality also holds promise for the longer-term goal of building larger-scale error-corrected quantum computers. In this brief review, we discuss several of the recent experimental advances in qubit hardware, gate implementations, readout capabilities, early NISQ algorithm implementations, and quantum error correction using superconducting qubits. Although continued work on many aspects of this technology is certainly necessary, the pace of both conceptual and technical progress in recent years has been impressive, and here we hope to convey the excitement stemming from this progress.",keywords:["Quantum computer","Qubit","Superconducting quantum computing","Quantum error correction","Superconductivity","Quantum","Flux qubit","Quantum gate"],concepts:["Quantum computer","Qubit","Superconducting quantum computing","Quantum error correction","Superconductivity","Quantum mechanics","Quantum"],pdf_url:"https://www.annualreviews.org/doi/pdf/10.1146/annurev-conmatphys-031119-050605",is_oa:!0,n_refs:184,n_refs_in_core:17,degree:43,community:3,deg_w:1003,betweenness:.0061,pagerank:.00765,eigenvector:.0814},{id:16,oaid:"W2949253647",doi:"10.1063/1.5088164",title:"Trapped-ion quantum computing: Progress and challenges",authors:[{name:"Colin D. Bruzewicz",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology"]},{name:"John Chiaverini",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology"]},{name:"Robert McConnell",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology"]},{name:"Jeremy M. Sage",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology"]}],authorString:"Colin D. Bruzewicz; John Chiaverini; Robert McConnell; Jeremy M. Sage",institutions:["MIT Lincoln Laboratory","Massachusetts Institute of Technology"],countries:["US"],year:2019,journal:"Applied Physics Reviews",citations:1296,abstract:"Trapped ions are among the most promising systems for practical quantum computing (QC). The basic requirements for universal QC have all been demonstrated with ions, and quantum algorithms using few-ion-qubit systems have been implemented. We review the state of the field, covering the basics of how trapped ions are used for QC and their strengths and limitations as qubits. In addition, we discuss what is being done, and what may be required, to increase the scale of trapped ion quantum computers while mitigating decoherence and control errors. Finally, we explore the outlook for trapped-ion QC. In particular, we discuss near-term applications, considerations impacting the design of future systems of trapped ions, and experiments and demonstrations that may further inform these considerations.",keywords:["Quantum decoherence","Quantum","Quantum computer","Scale","Quantum technology","Ion","State","Quantum sensor"],concepts:["Quantum decoherence","Quantum","Quantum computer","Scale","Quantum technology","Ion"],pdf_url:"https://arxiv.org/pdf/1904.04178",is_oa:!0,n_refs:343,n_refs_in_core:3,degree:25,community:3,deg_w:389,betweenness:.0012,pagerank:.00342,eigenvector:.0306},{id:17,oaid:"W2613386458",doi:"10.1021/acs.jctc.7b00174",title:"<scp>Psi4</scp> 1.1: An Open-Source Electronic Structure Program Emphasizing Automation, Advanced Libraries, and Interoperability",authors:[{name:"Robert M. Parrish",institutions:["Georgia Institute of Technology"]},{name:"Lori A. Burns",institutions:["Georgia Institute of Technology"]},{name:"Daniel G. A. Smith",institutions:["Georgia Institute of Technology"]},{name:"Andrew C. Simmonett",institutions:["National Institutes of Health","National Heart Lung and Blood Institute"]},{name:"A. Eugene DePrince",institutions:["Florida State University"]},{name:"Edward G. Hohenstein",institutions:["City College of New York"]},{name:"Uğur Bozkaya",institutions:["Hacettepe University"]},{name:"Alexander Yu. Sokolov",institutions:["California Institute of Technology"]},{name:"Roberto Di Remigio",institutions:["UiT The Arctic University of Norway"]},{name:"Ryan M. Richard",institutions:["Georgia Institute of Technology"]},{name:"Jérôme F. Gonthier",institutions:["Georgia Institute of Technology"]},{name:"Andrew M. James",institutions:["Virginia Tech"]},{name:"Harley R. McAlexander",institutions:["Virginia Tech"]},{name:"Ashutosh Kumar",institutions:["Virginia Tech"]},{name:"Masaaki Saitow",institutions:["Rikkyo University"]},{name:"Xiao Wang",institutions:["Virginia Tech"]},{name:"Benjamin P. Pritchard",institutions:["Georgia Institute of Technology"]},{name:"Prakash Verma",institutions:["Emory University"]},{name:"Henry F. Schaefer",institutions:["University of Georgia"]},{name:"Konrad Patkowski",institutions:["Auburn University"]},{name:"Rollin A. King",institutions:["Bethel University"]},{name:"Edward F. Valeev",institutions:["Virginia Tech"]},{name:"Francesco A. Evangelista",institutions:["Emory University"]},{name:"Justin M. Turney",institutions:["University of Georgia"]},{name:"T. Daniel Crawford",institutions:["Virginia Tech"]},{name:"C. David Sherrill",institutions:["Georgia Institute of Technology"]}],authorString:"Robert M. Parrish; Lori A. Burns; Daniel G. A. Smith; Andrew C. Simmonett; A. Eugene DePrince; Edward G. Hohenstein; Uğur Bozkaya; Alexander Yu. Sokolov; Roberto Di Remigio; Ryan M. Richard; Jérôme F. Gonthier; Andrew M. James et al.",institutions:["Auburn University","Bethel University","California Institute of Technology","City College of New York","Emory University","Florida State University","Georgia Institute of Technology","Hacettepe University","National Heart Lung and Blood Institute","National Institutes of Health","Rikkyo University","UiT The Arctic University of Norway","University of Georgia","Virginia Tech"],countries:["JP","NO","TR","US"],year:2017,journal:"Journal of Chemical Theory and Computation",citations:1248,abstract:'Psi4 is an ab initio electronic structure program providing methods such as Hartree-Fock, density functional theory, configuration interaction, and coupled-cluster theory. The 1.1 release represents a major update meant to automate complex tasks, such as geometry optimization using complete-basis-set extrapolation or focal-point methods. Conversion of the top-level code to a Python module means that Psi4 can now be used in complex workflows alongside other Python tools. Several new features have been added with the aid of libraries providing easy access to techniques such as density fitting, Cholesky decomposition, and Laplace denominators. The build system has been completely rewritten to simplify interoperability with independent, reusable software components for quantum chemistry. Finally, a wide range of new theoretical methods and analyses have been added to the code base, including functional-group and open-shell symmetry adapted perturbation theory, density-fitted coupled cluster with frozen natural orbitals, orbital-optimized perturbation and coupled-cluster methods (e.g., OO-MP2 and OO-LCCD), density-fitted multiconfigurational self-consistent field, density cumulant functional theory, algebraic-diagrammatic construction excited states, improvements to the geometry optimizer, and the "X2C" approach to relativistic corrections, among many other improvements.',keywords:["Interoperability","Open source","Automation","World Wide Web","Software engineering","Data science"],concepts:["Interoperability","Open source","Automation","World Wide Web","Software engineering","Data science"],pdf_url:"https://www.osti.gov/servlets/purl/1925215",is_oa:!0,n_refs:168,n_refs_in_core:0,degree:18,community:1,deg_w:117.5,betweenness:3e-4,pagerank:.0015,eigenvector:.008},{id:18,oaid:"W2903221501",doi:"10.1103/physreva.99.032331",title:"Evaluating analytic gradients on quantum hardware",authors:[{name:"Maria Schuld",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Ville Bergholm",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Christian Gogolin",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Josh Izaac",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"]}],authorString:"Maria Schuld; Ville Bergholm; Christian Gogolin; Josh Izaac; Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"],countries:["CA"],year:2019,journal:"Physical review. A/Physical review, A",citations:1075,abstract:"An important application for near-term quantum computing lies in optimization tasks, with applications ranging from quantum chemistry and drug discovery to machine learning. In many settings, most prominently in so-called parametrized or variational algorithms, the objective function is a result of hybrid quantum-classical processing. To optimize the objective, it is useful to have access to exact gradients of quantum circuits with respect to gate parameters. This paper shows how gradients of expectation values of quantum measurements can be estimated using the same, or almost the same, architecture that executes the original circuit. It generalizes previous results for qubit-based platforms, and proposes recipes for the computation of gradients of continuous-variable circuits. Interestingly, in many important instances it is sufficient to run the original quantum circuit twice while shifting a single gate parameter to obtain the corresponding component of the gradient. More general cases can be solved by conditioning a single gate on an ancilla.",keywords:["Quantum computer","Quantum circuit","Quantum","Computation","Qubit","Electronic circuit","Quantum algorithm"],concepts:["Quantum computer","Quantum circuit","Quantum","Computation","Qubit","Electronic circuit","Quantum algorithm"],pdf_url:"https://arxiv.org/pdf/1811.11184",is_oa:!0,n_refs:12,n_refs_in_core:4,degree:51,community:0,deg_w:458,betweenness:.0049,pagerank:.00405,eigenvector:.031},{id:19,oaid:"W3136233239",doi:"10.1038/s41467-021-21728-w",title:"Cost function dependent barren plateaus in shallow parametrized quantum circuits",authors:[{name:"M. Cerezo",institutions:["Los Alamos National Laboratory","Los Alamos National Security (United States)"]},{name:"Akira Sone",institutions:["Los Alamos National Laboratory"]},{name:"Tyler Volkoff",institutions:["Los Alamos National Laboratory"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"M. Cerezo; Akira Sone; Tyler Volkoff; Łukasz Cincio; Patrick J. Coles",institutions:["Los Alamos National Laboratory","Los Alamos National Security (United States)"],countries:["US"],year:2021,journal:"Nature Communications",citations:1072,abstract:"Variational quantum algorithms (VQAs) optimize the parameters θ of a parametrized quantum circuit V(θ) to minimize a cost function C. While VQAs may enable practical applications of noisy quantum computers, they are nevertheless heuristic methods with unproven scaling. Here, we rigorously prove two results, assuming V(θ) is an alternating layered ansatz composed of blocks forming local 2-designs. Our first result states that defining C in terms of global observables leads to exponentially vanishing gradients (i.e., barren plateaus) even when V(θ) is shallow. Hence, several VQAs in the literature must revise their proposed costs. On the other hand, our second result states that defining C with local observables leads to at worst a polynomially vanishing gradient, so long as the depth of V(θ) is [Formula: see text]. Our results establish a connection between locality and trainability. We illustrate these ideas with large-scale simulations, up to 100 qubits, of a quantum autoencoder implementation.",keywords:["Function","Electronic circuit","Quantum","Statistical physics","Quantum mechanics"],concepts:["Function","Electronic circuit","Quantum","Statistical physics"],pdf_url:"https://www.nature.com/articles/s41467-021-21728-w.pdf",is_oa:!0,n_refs:95,n_refs_in_core:21,degree:63,community:0,deg_w:1317,betweenness:.0072,pagerank:.00953,eigenvector:.1193},{id:20,oaid:"W2103912183",doi:"10.1103/physrevlett.107.240501",title:"Observation of High Coherence in Josephson Junction Qubits Measured in a Three-Dimensional Circuit QED Architecture",authors:[{name:"Hanhee Paik",institutions:["Yale University"]},{name:"David Schuster",institutions:["Yale University","University of Chicago"]},{name:"Lev S. Bishop",institutions:["Yale University","Joint Quantum Institute","University of Maryland, College Park"]},{name:"Gerhard Kirchmair",institutions:["Yale University"]},{name:"Gianluigi Catelani",institutions:["Yale University"]},{name:"Adam Sears",institutions:["Yale University"]},{name:"Blake Johnson",institutions:["RTX (United States)","Yale University"]},{name:"Matthew J. Reagor",institutions:["Yale University"]},{name:"Luigi Frunzio",institutions:["Yale University"]},{name:"L. I. Glazman",institutions:["Yale University"]},{name:"S. M. Girvin",institutions:["Yale University"]},{name:"Michel Devoret",institutions:["Yale University"]},{name:"Robert Schoelkopf",institutions:["Yale University"]}],authorString:"Hanhee Paik; David Schuster; Lev S. Bishop; Gerhard Kirchmair; Gianluigi Catelani; Adam Sears; Blake Johnson; Matthew J. Reagor; Luigi Frunzio; L. I. Glazman; S. M. Girvin; Michel Devoret et al.",institutions:["Joint Quantum Institute","RTX (United States)","University of Chicago","University of Maryland, College Park","Yale University"],countries:["US"],year:2011,journal:"Physical Review Letters",citations:1068,abstract:"Superconducting quantum circuits based on Josephson junctions have made rapid progress in demonstrating quantum behavior and scalability. However, the future prospects ultimately depend upon the intrinsic coherence of Josephson junctions, and whether superconducting qubits can be adequately isolated from their environment. We introduce a new architecture for superconducting quantum circuits employing a three-dimensional resonator that suppresses qubit decoherence while maintaining sufficient coupling to the control signal. With the new architecture, we demonstrate that Josephson junction qubits are highly coherent, with T2 ∼ 10 to 20 μs without the use of spin echo, and highly stable, showing no evidence for 1/f critical current noise. These results suggest that the overall quality of Josephson junctions in these qubits will allow error rates of a few 10(-4), approaching the error correction threshold.",keywords:["Josephson effect","Qubit","Coherence","Pi Josephson junction","Superconducting tunnel junction","Josephson energy","Josephson phase"],concepts:["Josephson effect","Qubit","Coherence","Pi Josephson junction","Superconducting tunnel junction","Josephson energy","Josephson phase"],pdf_url:"https://arxiv.org/pdf/1105.4652",is_oa:!0,n_refs:30,n_refs_in_core:1,degree:12,community:3,deg_w:164,betweenness:1e-4,pagerank:.00196,eigenvector:.0092},{id:21,oaid:"W2980446414",doi:"10.1088/2058-9565/ab4eb5",title:"Parameterized quantum circuits as machine learning models",authors:[{name:"Marcello Benedetti",institutions:["Cambridge Quantum Computing (United Kingdom)","University College London"]},{name:"Erika Lloyd",institutions:["Cambridge Quantum Computing (United Kingdom)"]},{name:"Stefan Sack",institutions:["Cambridge Quantum Computing (United Kingdom)"]},{name:"Mattia Fiorentini",institutions:["Cambridge Quantum Computing (United Kingdom)"]}],authorString:"Marcello Benedetti; Erika Lloyd; Stefan Sack; Mattia Fiorentini",institutions:["Cambridge Quantum Computing (United Kingdom)","University College London"],countries:["GB"],year:2019,journal:"Quantum Science and Technology",citations:1060,abstract:"Abstract Hybrid quantum–classical systems make it possible to utilize existing quantum computers to their fullest extent. Within this framework, parameterized quantum circuits can be regarded as machine learning models with remarkable expressive power. This Review presents the components of these models and discusses their application to a variety of data-driven tasks, such as supervised learning and generative modeling. With an increasing number of experimental demonstrations carried out on actual quantum hardware and with software being actively developed, this rapidly growing field is poised to have a broad spectrum of real-world applications.",keywords:["Parameterized complexity","Variety","Field","Quantum","Generative grammar","Software","Generative model"],concepts:["Parameterized complexity","Variety","Field","Quantum","Generative grammar","Software"],pdf_url:"https://iopscience.iop.org/article/10.1088/2058-9565/ab4eb5/pdf",is_oa:!0,n_refs:112,n_refs_in_core:17,degree:51,community:0,deg_w:748.5,betweenness:.0047,pagerank:.00632,eigenvector:.0497},{id:22,oaid:"W2954369586",doi:"10.1038/s41467-019-10988-2",title:"An adaptive variational algorithm for exact molecular simulations on a quantum computer",authors:[{name:"Harper R. Grimsley",institutions:["Virginia Tech"]},{name:"Sophia E. Economou",institutions:["Virginia Tech"]},{name:"Edwin Barnes",institutions:["Virginia Tech"]},{name:"Nicholas J. Mayhall",institutions:["Virginia Tech"]}],authorString:"Harper R. Grimsley; Sophia E. Economou; Edwin Barnes; Nicholas J. Mayhall",institutions:["Virginia Tech"],countries:["US"],year:2019,journal:"Nature Communications",citations:1058,abstract:"Quantum simulation of chemical systems is one of the most promising near-term applications of quantum computers. The variational quantum eigensolver, a leading algorithm for molecular simulations on quantum hardware, has a serious limitation in that it typically relies on a pre-selected wavefunction ansatz that results in approximate wavefunctions and energies. Here we present an arbitrarily accurate variational algorithm that, instead of fixing an ansatz upfront, grows it systematically one operator at a time in a way dictated by the molecule being simulated. This generates an ansatz with a small number of parameters, leading to shallow-depth circuits. We present numerical simulations, including for a prototypical strongly correlated molecule, which show that our algorithm performs much better than a unitary coupled cluster approach, in terms of both circuit depth and chemical accuracy. Our results highlight the potential of our adaptive algorithm for exact simulations with present-day and near-term quantum hardware.",keywords:["Ansatz","Wave function","Quantum computer","Algorithm","Quantum","Quantum algorithm","Quantum phase estimation algorithm"],concepts:["Ansatz","Wave function","Quantum computer","Algorithm","Quantum","Quantum algorithm","Quantum phase estimation algorithm"],pdf_url:"https://www.nature.com/articles/s41467-019-10988-2.pdf",is_oa:!0,n_refs:62,n_refs_in_core:8,degree:59,community:1,deg_w:1038,betweenness:.0057,pagerank:.00739,eigenvector:.09},{id:23,oaid:"W2792315573",doi:"10.1088/1361-6633/aab406",title:"Machine learning &amp; artificial intelligence in the quantum domain: a review of recent progress",authors:[{name:"Vedran Dunjko",institutions:["Universität Innsbruck","Max Planck Institute of Quantum Optics"]},{name:"Hans J. Briegel",institutions:["University of Konstanz","Universität Innsbruck"]}],authorString:"Vedran Dunjko; Hans J. Briegel",institutions:["Max Planck Institute of Quantum Optics","University of Konstanz","Universität Innsbruck"],countries:["AT","DE"],year:2018,journal:"Reports on Progress in Physics",citations:1040,abstract:"Quantum information technologies, on the one hand, and intelligent learning systems, on the other, are both emergent technologies that are likely to have a transformative impact on our society in the future. The respective underlying fields of basic research-quantum information versus machine learning (ML) and artificial intelligence (AI)-have their own specific questions and challenges, which have hitherto been investigated largely independently. However, in a growing body of recent work, researchers have been probing the question of the extent to which these fields can indeed learn and benefit from each other. Quantum ML explores the interaction between quantum computing and ML, investigating how results and techniques from one field can be used to solve the problems of the other. Recently we have witnessed significant breakthroughs in both directions of influence. For instance, quantum computing is finding a vital application in providing speed-ups for ML problems, critical in our 'big data' world. Conversely, ML already permeates many cutting-edge technologies and may become instrumental in advanced quantum technologies. Aside from quantum speed-up in data analysis, or classical ML optimization used in quantum experiments, quantum enhancements have also been (theoretically) demonstrated for interactive learning tasks, highlighting the potential of quantum-enhanced learning agents. Finally, works exploring the use of AI for the very design of quantum experiments and for performing parts of genuine research autonomously, have reported their first successes. Beyond the topics of mutual enhancement-exploring what ML/AI can do for quantum physics and vice versa-researchers have also broached the fundamental issue of quantum generalizations of learning and AI concepts. This deals with questions of the very meaning of learning and intelligence in a world that is fully described by quantum mechanics. In this review, we describe the main ideas, recent developments and progress in a broad spectrum of research investigating ML and AI in the quantum domain.",keywords:["Transformative learning","Quantum","Quantum machine learning","Quantum computer","Quantum information science","Field","Quantum information"],concepts:["Transformative learning","Quantum","Quantum machine learning","Quantum computer","Quantum information science","Field","Quantum information"],pdf_url:"https://arxiv.org/abs/1709.02779",is_oa:!0,n_refs:397,n_refs_in_core:7,degree:30,community:0,deg_w:577.5,betweenness:.0012,pagerank:.00514,eigenvector:.0373},{id:24,oaid:"W2796293949",doi:"10.1103/physreva.101.032308",title:"Circuit-centric quantum classifiers",authors:[{name:"Maria Schuld",institutions:["University of KwaZulu-Natal"]},{name:"Alex Bocharov",institutions:["Microsoft (United States)"]},{name:"Krysta M. Svore",institutions:["Microsoft (United States)"]},{name:"Nathan Wiebe",institutions:["Microsoft (United States)","Pacific Northwest National Laboratory","University of Washington"]}],authorString:"Maria Schuld; Alex Bocharov; Krysta M. Svore; Nathan Wiebe",institutions:["Microsoft (United States)","Pacific Northwest National Laboratory","University of KwaZulu-Natal","University of Washington"],countries:["US","ZA"],year:2020,journal:"Physical review. A/Physical review, A",citations:1032,abstract:"A machine learning design is developed to train a quantum circuit specialized in solving a classification problem. In addition to discussing the training method and effect of noise, it is shown that the circuits perform reasonably well on classical benchmarks.",keywords:["Electronic circuit","Quantum circuit","Quantum","Noise","Computer engineering"],concepts:["Electronic circuit","Quantum circuit","Quantum","Noise","Computer engineering"],pdf_url:"https://arxiv.org/pdf/1804.00633",is_oa:!0,n_refs:54,n_refs_in_core:7,degree:37,community:0,deg_w:521.5,betweenness:.0016,pagerank:.00463,eigenvector:.0353},{id:25,oaid:"W3212169067",doi:"10.1016/j.physrep.2022.08.003",title:"The Variational Quantum Eigensolver: A review of methods and best practices",authors:[{name:"Jules Tilly",institutions:["University College London"]},{name:"Hongxiang Chen",institutions:["University College London"]},{name:"Shuxiang Cao",institutions:["University of Oxford"]},{name:"Dario Picozzi",institutions:["University College London"]},{name:"Kanav Setia",institutions:[]},{name:"Ying Li",institutions:["China Academy of Engineering Physics"]},{name:"Edward Grant",institutions:["University College London"]},{name:"Leonard Wossnig",institutions:["University College London"]},{name:"Ivan Rungger",institutions:["National Physical Laboratory"]},{name:"George H. Booth",institutions:["King's College London"]},{name:"Jonathan Tennyson",institutions:["University College London"]}],authorString:"Jules Tilly; Hongxiang Chen; Shuxiang Cao; Dario Picozzi; Kanav Setia; Ying Li; Edward Grant; Leonard Wossnig; Ivan Rungger; George H. Booth; Jonathan Tennyson",institutions:["China Academy of Engineering Physics","King's College London","National Physical Laboratory","University College London","University of Oxford"],countries:["CN","GB"],year:2022,journal:"Physics Reports",citations:1020,abstract:"The variational quantum eigensolver (or VQE), first developed by Peruzzo et al. (2014), has received significant attention from the research community in recent years. It uses the variational principle to compute the ground state energy of a Hamiltonian, a problem that is central to quantum chemistry and condensed matter physics. Conventional computing methods are constrained in their accuracy due to the computational limits facing exact modeling of the exponentially growing electronic wavefunction for these many-electron systems. The VQE may be used to model these complex wavefunctions in polynomial time, making it one of the most promising near-term applications for quantum computing. One important advantage is that variational algorithms have been shown to present some degree of resilience to the noise in the quantum hardware. Finding a path to navigate the relevant literature has rapidly become an overwhelming task, with many methods promising to improve different parts of the algorithm, but without clear descriptions of how the diverse parts fit together. The potential practical advantages of the algorithm are also widely discussed in the literature, but with varying conclusions. Despite strong theoretical underpinnings suggesting excellent scaling of individual VQE components, studies have pointed out that their various pre-factors could be too large to reach a quantum computing advantage over conventional methods. This review aims at disentangling the relevant literature to provide a comprehensive overview of the progress that has been made on the different parts of the algorithm, and to discuss future areas of research that are fundamental for the VQE to deliver on its promises. All the different components of the algorithm are reviewed in detail. These include the representation of Hamiltonians and wavefunctions on a quantum computer, the optimization process to find ground state energies, the post processing mitigation of quantum errors, and suggested best practices. We identify four main areas of future research: (1) optimal measurement schemes for reduction of circuit repetitions required; (2) large scale parallelization across many quantum computers; (3) ways to overcome the potential appearance of vanishing gradients in the optimization process for large systems, and how the number of iterations required for the optimization scales with system size; (4) the extent to which VQE suffers for quantum noise, and whether this noise can be mitigated in a tractable manner. The answers to these open research questions will determine the routes for the VQE to achieve quantum advantage as the quantum computing hardware scales up and as the noise levels are reduced.",keywords:["Quantum computer","Wave function","Quantum","Hamiltonian","Quantum algorithm","Scaling"],concepts:["Quantum computer","Wave function","Quantum","Hamiltonian","Quantum algorithm","Scaling"],pdf_url:"https://doi.org/10.1016/j.physrep.2022.08.003",is_oa:!0,n_refs:961,n_refs_in_core:84,degree:99,community:1,deg_w:3636,betweenness:.0224,pagerank:.02434,eigenvector:.325},{id:26,oaid:"W2051446825",doi:"10.1103/physrevlett.100.160501",title:"Quantum Random Access Memory",authors:[{name:"Vittorio Giovannetti",institutions:["Scuola Normale Superiore"]},{name:"Seth Lloyd",institutions:["IIT@MIT"]},{name:"Lorenzo Maccone",institutions:["University of Pavia","Istituto Nazionale di Fisica Nucleare, Sezione di Pavia"]}],authorString:"Vittorio Giovannetti; Seth Lloyd; Lorenzo Maccone",institutions:["IIT@MIT","Istituto Nazionale di Fisica Nucleare, Sezione di Pavia","Scuola Normale Superiore","University of Pavia"],countries:["IT","US"],year:2008,journal:"Physical Review Letters",citations:949,abstract:"A random access memory (RAM) uses n bits to randomly address N=2(n) distinct memory cells. A quantum random access memory (QRAM) uses n qubits to address any quantum superposition of N memory cells. We present an architecture that exponentially reduces the requirements for a memory call: O(logN) switches need be thrown instead of the N used in conventional (classical or quantum) RAM designs. This yields a more robust QRAM algorithm, as it in general requires entanglement among exponentially less gates, and leads to an exponential decrease in the power needed for addressing. A quantum optical implementation is presented.",keywords:["Quantum entanglement","Superposition principle","Quantum memory","Qubit","Quantum","Quantum computer","Random access"],concepts:["Quantum entanglement","Superposition principle","Quantum memory","Qubit","Quantum","Quantum computer","Random access"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevLett.100.160501",is_oa:!0,n_refs:18,n_refs_in_core:0,degree:22,community:0,deg_w:118.5,betweenness:.0013,pagerank:.00164,eigenvector:.0076},{id:27,oaid:"W3103810096",doi:"10.48550/arxiv.1512.06860",title:"Scalable Quantum Simulation of Molecular Energies",authors:[{name:"P. O’Malley",institutions:["University of California, Santa Barbara"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Ian Kivlichan",institutions:["Harvard University"]},{name:"Jonathan Romero",institutions:["Harvard University"]},{name:"Jarrod R. McClean",institutions:["Lawrence Berkeley National Laboratory"]},{name:"R. Barends",institutions:["Google (United States)"]},{name:"J. Kelly",institutions:["Google (United States)"]},{name:"P. Roushan",institutions:["Google (United States)"]},{name:"Andrew Tranter",institutions:["Tufts University","University College London"]},{name:"Nan Ding",institutions:["Google (United States)"]},{name:"B. Campbell",institutions:["University of California, Santa Barbara"]},{name:"Yuquan Chen",institutions:["Google (United States)"]},{name:"Z. Chen",institutions:["University of California, Santa Barbara"]},{name:"Benjamin Chiaro",institutions:["University of California, Santa Barbara"]},{name:"A. Dunsworth",institutions:["University of California, Santa Barbara"]},{name:"Austin G. Fowler",institutions:["Google (United States)"]},{name:"E. Jeffrey",institutions:["Google (United States)"]},{name:"A. Megrant",institutions:["Google (United States)"]},{name:"J. Mutus",institutions:["Google (United States)"]},{name:"C. Neill",institutions:["Google (United States)"]},{name:"Chris Quintana",institutions:["Google (United States)"]},{name:"D. Sank",institutions:["University of California, Santa Barbara"]},{name:"A. Vainsencher",institutions:["University of California, Santa Barbara"]},{name:"J. Wenner",institutions:["Google (United States)"]},{name:"T. White",institutions:["University of California, Santa Barbara"]},{name:"Peter V. Coveney",institutions:["University of California, Santa Barbara"]},{name:"Peter J. Love",institutions:["Google (United States)"]},{name:"Hartmut Neven",institutions:["University College London"]},{name:"Alán Aspuru‐Guzik",institutions:["Tufts University"]},{name:"John M. Martinis",institutions:["Google (United States)"]}],authorString:"P. O’Malley; Ryan Babbush; Ian Kivlichan; Jonathan Romero; Jarrod R. McClean; R. Barends; J. Kelly; P. Roushan; Andrew Tranter; Nan Ding; B. Campbell; Yuquan Chen et al.",institutions:["Google (United States)","Harvard University","Lawrence Berkeley National Laboratory","Tufts University","University College London","University of California, Santa Barbara"],countries:["GB","US"],year:2015,journal:"UCL Discovery (University College London)",citations:927,abstract:"We report the first electronic structure calculation performed on a quantum computer without exponentially costly precompilation. We use a programmable array of superconducting qubits to compute the energy surface of molecular hydrogen using two distinct quantum algorithms. First, we experimentally execute the unitary coupled cluster method using the variational quantum eigensolver. Our efficient implementation predicts the correct dissociation energy to within chemical accuracy of the numerically exact result. Second, we experimentally demonstrate the canonical quantum algorithm for chemistry, which consists of Trotterization and quantum phase estimation. We compare the experimental performance of these approaches to show clear evidence that the variational quantum eigensolver is robust to certain errors. This error tolerance inspires hope that variational quantum simulations of classically intractable molecules may be viable in the near future.",keywords:["Quantum","Qubit","Quantum computer","Quantum algorithm","Coupled cluster","Quantum simulator","Scalability"],concepts:["Quantum","Qubit","Quantum computer","Quantum algorithm","Coupled cluster","Quantum simulator","Scalability"],pdf_url:"https://doi.org/10.48550/arxiv.1512.06860",is_oa:!0,n_refs:54,n_refs_in_core:7,degree:80,community:1,deg_w:1321,betweenness:.0131,pagerank:.00924,eigenvector:.1095},{id:28,oaid:"W2530095757",doi:"10.1088/1361-6633/aa7e1a",title:"Quantum information processing with superconducting circuits: a review",authors:[{name:"G Wendin",institutions:["Chalmers University of Technology"]}],authorString:"G Wendin",institutions:["Chalmers University of Technology"],countries:["SE"],year:2017,journal:"Reports on Progress in Physics",citations:866,abstract:"During the last ten years, superconducting circuits have passed from being interesting physical devices to becoming contenders for near-future useful and scalable quantum information processing (QIP). Advanced quantum simulation experiments have been shown with up to nine qubits, while a demonstration of quantum supremacy with fifty qubits is anticipated in just a few years. Quantum supremacy means that the quantum system can no longer be simulated by the most powerful classical supercomputers. Integrated classical-quantum computing systems are already emerging that can be used for software development and experimentation, even via web interfaces. Therefore, the time is ripe for describing some of the recent development of superconducting devices, systems and applications. As such, the discussion of superconducting qubits and circuits is limited to devices that are proven useful for current or near future applications. Consequently, the centre of interest is the practical applications of QIP, such as computation and simulation in Physics and Chemistry.",keywords:["Qubit","Quantum computer","Superconducting quantum computing","Quantum information","Quantum","Quantum technology","Scalability","Superconductivity"],concepts:["Qubit","Quantum computer","Superconducting quantum computing","Quantum information","Quantum","Quantum technology","Scalability"],pdf_url:"https://arxiv.org/pdf/1610.02208",is_oa:!0,n_refs:482,n_refs_in_core:15,degree:39,community:3,deg_w:1125.5,betweenness:.005,pagerank:.00855,eigenvector:.0754},{id:29,oaid:"W2535738892",doi:"10.22331/q-2019-07-12-163",title:"Hamiltonian Simulation by Qubitization",authors:[{name:"Guang Hao Low",institutions:["Massachusetts Institute of Technology"]},{name:"Isaac L. Chuang",institutions:["Massachusetts Institute of Technology"]}],authorString:"Guang Hao Low; Isaac L. Chuang",institutions:["Massachusetts Institute of Technology"],countries:["US"],year:2019,journal:"Quantum",citations:809,abstract:'We present the problem of approximating the time-evolution operator<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:msup><mml:mi>e</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo>−</mml:mo><mml:mi>i</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi>H</mml:mi><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow><mml:mi>t</mml:mi></mml:mrow></mml:msup></mml:math>to error<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>ϵ</mml:mi></mml:math>, where the Hamiltonian<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi>H</mml:mi><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow><mml:mo>=</mml:mo><mml:mo stretchy="false">(</mml:mo><mml:mo fence="false" stretchy="false">⟨</mml:mo><mml:mi>G</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo stretchy="false">|</mml:mo></mml:mrow><mml:mo>⊗</mml:mo><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi class="MJX-tex-caligraphic" mathvariant="script">I</mml:mi></mml:mrow><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow><mml:mo stretchy="false">)</mml:mo><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi>U</mml:mi><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow><mml:mo stretchy="false">(</mml:mo><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo stretchy="false">|</mml:mo></mml:mrow><mml:mi>G</mml:mi><mml:mo fence="false" stretchy="false">⟩</mml:mo><mml:mo>⊗</mml:mo><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi class="MJX-tex-caligraphic" mathvariant="script">I</mml:mi></mml:mrow><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow><mml:mo stretchy="false">)</mml:mo></mml:math>is the projection of a unitary oracle<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi>U</mml:mi><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow></mml:math>onto the state<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo stretchy="false">|</mml:mo></mml:mrow><mml:mi>G</mml:mi><mml:mo fence="false" stretchy="false">⟩</mml:mo></mml:math>created by another unitary oracle. Our algorithm solves this with a query complexity<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi class="MJX-tex-caligraphic" mathvariant="script">O</mml:mi></mml:mrow><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo maxsize="1.2em" minsize="1.2em">(</mml:mo></mml:mrow><mml:mi>t</mml:mi><mml:mo>+</mml:mo><mml:mi>log</mml:mi><mml:mo>⁡</mml:mo><mml:mo stretchy="false">(</mml:mo><mml:mrow class="MJX-TeXAtom-ORD"><mml:mn>1</mml:mn><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo>/</mml:mo></mml:mrow><mml:mi>ϵ</mml:mi></mml:mrow><mml:mo stretchy="false">)</mml:mo><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo maxsize="1.2em" minsize="1.2em">)</mml:mo></mml:mrow></mml:math>to both oracles that is optimal with respect to all parameters in both the asymptotic and non-asymptotic regime, and also with low overhead, using at most two additional ancilla qubits. This approach to Hamiltonian simulation subsumes important prior art considering Hamiltonians which are<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>d</mml:mi></mml:math>-sparse or a linear combination of unitaries, leading to significant improvements in space and gate complexity, such as a quadratic speed-up for precision simulations. It also motivates useful new instances, such as where<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi>H</mml:mi><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow></mml:math>is a density matrix. A key technical result is `qubitization\', which uses the controlled version of these oracles to embed any<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi>H</mml:mi><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow></mml:math>in an invariant<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mtext>SU</mml:mtext><mml:mo stretchy="false">(</mml:mo><mml:mn>2</mml:mn><mml:mo stretchy="false">)</mml:mo></mml:math>subspace. A large class of operator functions of<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi>H</mml:mi><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow></mml:math>can then be computed with optimal query complexity, of which<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:msup><mml:mi>e</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo>−</mml:mo><mml:mi>i</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi>H</mml:mi><mml:mo stretchy="false">^</mml:mo></mml:mover></mml:mrow><mml:mi>t</mml:mi></mml:mrow></mml:msup></mml:math>is a special case.',keywords:["Unitary state","Hamiltonian","Quadratic equation","Class","Operator","Unitary operator","Projection"],concepts:["Unitary state","Hamiltonian","Quadratic equation","Class","Operator","Unitary operator","Applied mathematics"],pdf_url:"https://quantum-journal.org/papers/q-2019-07-12-163/pdf/",is_oa:!0,n_refs:46,n_refs_in_core:3,degree:26,community:1,deg_w:255,betweenness:.0011,pagerank:.00248,eigenvector:.02},{id:30,oaid:"W2261928000",doi:"10.1103/physrevx.6.031007",title:"Scalable Quantum Simulation of Molecular Energies",authors:[{name:"P. J. J. O’Malley",institutions:["University of California, Santa Barbara"]},{name:"R. Babbush",institutions:["Google (United States)"]},{name:"I. D. Kivlichan",institutions:["Harvard University"]},{name:"J. Romero",institutions:["Harvard University"]},{name:"J. R. McClean",institutions:["Lawrence Berkeley National Laboratory"]},{name:"R. Barends",institutions:["Google (United States)"]},{name:"J. Kelly",institutions:["Google (United States)"]},{name:"P. Roushan",institutions:["Google (United States)"]},{name:"A. Tranter",institutions:["Tufts University","University College London"]},{name:"N. Ding",institutions:["Google (United States)"]},{name:"B. Campbell",institutions:["University of California, Santa Barbara"]},{name:"Y. Chen",institutions:["Google (United States)"]},{name:"Z. Chen",institutions:["University of California, Santa Barbara"]},{name:"B. Chiaro",institutions:["University of California, Santa Barbara"]},{name:"A. Dunsworth",institutions:["University of California, Santa Barbara"]},{name:"A. G. Fowler",institutions:["Google (United States)"]},{name:"E. Jeffrey",institutions:["Google (United States)"]},{name:"E. Lucero",institutions:["Google (United States)"]},{name:"A. Megrant",institutions:["Google (United States)"]},{name:"J. Y. Mutus",institutions:["Google (United States)"]},{name:"M. Neeley",institutions:["Google (United States)"]},{name:"C. Neill",institutions:["University of California, Santa Barbara"]},{name:"C. Quintana",institutions:["University of California, Santa Barbara"]},{name:"D. Sank",institutions:["Google (United States)"]},{name:"A. Vainsencher",institutions:["University of California, Santa Barbara"]},{name:"J. Wenner",institutions:["University of California, Santa Barbara"]},{name:"T. C. White",institutions:["Google (United States)"]},{name:"P. V. Coveney",institutions:["University College London"]},{name:"P. J. Love",institutions:["Tufts University"]},{name:"H. Neven",institutions:["Google (United States)"]},{name:"A. Aspuru-Guzik",institutions:["Harvard University"]},{name:"J. M. Martinis",institutions:["Google (United States)","University of California, Santa Barbara"]}],authorString:"P. J. J. O’Malley; R. Babbush; I. D. Kivlichan; J. Romero; J. R. McClean; R. Barends; J. Kelly; P. Roushan; A. Tranter; N. Ding; B. Campbell; Y. Chen et al.",institutions:["Google (United States)","Harvard University","Lawrence Berkeley National Laboratory","Tufts University","University College London","University of California, Santa Barbara"],countries:["GB","US"],year:2016,journal:"Physical Review X",citations:790,abstract:"We report the first electronic structure calculation performed on a quantum computer without exponentially costly precompilation. We use a programmable array of superconducting qubits to compute the energy surface of molecular hydrogen using two distinct quantum algorithms. First, we experimentally execute the unitary coupled cluster method using the variational quantum eigensolver. Our efficient implementation predicts the correct dissociation energy to within chemical accuracy of the numerically exact result. Second, we experimentally demonstrate the canonical quantum algorithm for chemistry, which consists of Trotterization and quantum phase estimation. We compare the experimental performance of these approaches to show clear evidence that the variational quantum eigensolver is robust to certain errors. This error tolerance inspires hope that variational quantum simulations of classically intractable molecules may be viable in the near future.",keywords:["Quantum","Qubit","Quantum computer","Quantum algorithm","Quantum error correction","Quantum simulator","Coupled cluster","Unitary transformation"],concepts:["Quantum","Qubit","Quantum computer","Quantum algorithm","Quantum error correction","Quantum mechanics","Quantum simulator"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.6.031007",is_oa:!0,n_refs:42,n_refs_in_core:7,degree:87,community:1,deg_w:1352,betweenness:.017,pagerank:.00962,eigenvector:.0992},{id:31,oaid:"W2097174474",doi:"10.1103/physrevlett.114.090502",title:"Simulating Hamiltonian Dynamics with a Truncated Taylor Series",authors:[{name:"Dominic W. Berry",institutions:["Macquarie University"]},{name:"Andrew M. Childs",institutions:["Canadian Institute for Advanced Research","University of Waterloo","Joint Center for Quantum Information and Computer Science","University of Maryland, College Park"]},{name:"Richard Cleve",institutions:["Canadian Institute for Advanced Research","University of Waterloo"]},{name:"Robin Kothari",institutions:["University of Waterloo","Massachusetts Institute of Technology"]},{name:"Rolando D. Somma",institutions:["Los Alamos National Laboratory"]}],authorString:"Dominic W. Berry; Andrew M. Childs; Richard Cleve; Robin Kothari; Rolando D. Somma",institutions:["Canadian Institute for Advanced Research","Joint Center for Quantum Information and Computer Science","Los Alamos National Laboratory","Macquarie University","Massachusetts Institute of Technology","University of Maryland, College Park","University of Waterloo"],countries:["AU","CA","US"],year:2015,journal:"Physical Review Letters",citations:774,abstract:"We describe a simple, efficient method for simulating Hamiltonian dynamics on a quantum computer by approximating the truncated Taylor series of the evolution operator. Our method can simulate the time evolution of a wide variety of physical systems. As in another recent algorithm, the cost of our method depends only logarithmically on the inverse of the desired precision, which is optimal. However, we simplify the algorithm and its analysis by using a method for implementing linear combinations of unitary operations together with a robust form of oblivious amplitude amplification.",keywords:["Hamiltonian","Taylor series","Unitary state","Series","Operator","Applied mathematics","Algorithm"],concepts:["Hamiltonian","Taylor series","Unitary state","Series","Operator","Applied mathematics","Algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevLett.114.090502",is_oa:!0,n_refs:21,n_refs_in_core:2,degree:29,community:1,deg_w:252,betweenness:.0014,pagerank:.00246,eigenvector:.018},{id:32,oaid:"W2754868542",doi:"10.3390/a12020034",title:"From the Quantum Approximate Optimization Algorithm to a Quantum Alternating Operator Ansatz",authors:[{name:"Stuart Hadfield",institutions:["Ames Research Center","Research Institute for Advanced Computer Science","Columbia University"]},{name:"Zhihui Wang",institutions:["Ames Research Center","Research Institute for Advanced Computer Science"]},{name:"Bryan O’Gorman",institutions:["Ames Research Center","Stinger Ghaffarian Technologies (United States)","University of California, Berkeley"]},{name:"Eleanor Rieffel",institutions:["Ames Research Center"]},{name:"Davide Venturelli",institutions:["Ames Research Center","Research Institute for Advanced Computer Science"]},{name:"Rupak Biswas",institutions:["Ames Research Center"]}],authorString:"Stuart Hadfield; Zhihui Wang; Bryan O’Gorman; Eleanor Rieffel; Davide Venturelli; Rupak Biswas",institutions:["Ames Research Center","Columbia University","Research Institute for Advanced Computer Science","Stinger Ghaffarian Technologies (United States)","University of California, Berkeley"],countries:["US"],year:2019,journal:"Algorithms",citations:761,abstract:"The next few years will be exciting as prototype universal quantum processors emerge, enabling the implementation of a wider variety of algorithms. Of particular interest are quantum heuristics, which require experimentation on quantum hardware for their evaluation and which have the potential to significantly expand the breadth of applications for which quantum computers have an established advantage. A leading candidate is Farhi et al.’s quantum approximate optimization algorithm, which alternates between applying a cost function based Hamiltonian and a mixing Hamiltonian. Here, we extend this framework to allow alternation between more general families of operators. The essence of this extension, the quantum alternating operator ansatz, is the consideration of general parameterized families of unitaries rather than only those corresponding to the time evolution under a fixed local Hamiltonian for a time specified by the parameter. This ansatz supports the representation of a larger, and potentially more useful, set of states than the original formulation, with potential long-term impact on a broad array of application areas. For cases that call for mixing only within a desired subspace, refocusing on unitaries rather than Hamiltonians enables more efficiently implementable mixers than was possible in the original framework. Such mixers are particularly useful for optimization problems with hard constraints that must always be satisfied, defining a feasible subspace, and soft constraints whose violation we wish to minimize. More efficient implementation enables earlier experimental exploration of an alternating operator approach, in the spirit of the quantum approximate optimization algorithm, to a wide variety of approximate optimization, exact optimization, and sampling problems. In addition to introducing the quantum alternating operator ansatz, we lay out design criteria for mixing operators, detail mappings for eight problems, and provide a compendium with brief descriptions of mappings for a diverse array of problems.",keywords:["Ansatz","Hamiltonian","Quantum","Operator","Quantum computer","Quantum algorithm","Qubit"],concepts:["Ansatz","Hamiltonian","Quantum","Operator","Quantum computer","Quantum algorithm","Qubit"],pdf_url:"https://www.mdpi.com/1999-4893/12/2/34/pdf?version=1550834165",is_oa:!0,n_refs:113,n_refs_in_core:1,degree:32,community:0,deg_w:300.5,betweenness:.0017,pagerank:.00279,eigenvector:.0283},{id:33,oaid:"W3015289174",doi:"10.1126/science.abb9811",title:"Hartree-Fock on a superconducting qubit quantum computer",authors:[{name:"Google AI Quantum and Collaborators",institutions:[]},{name:"Frank Arute",institutions:[]},{name:"Kunal Arya",institutions:[]},{name:"Ryan Babbush",institutions:[]},{name:"Dave Bacon",institutions:[]},{name:"Joseph C. Bardin",institutions:[]},{name:"Rami Barends",institutions:[]},{name:"Sergio Boixo",institutions:[]},{name:"Michael Broughton",institutions:[]},{name:"Bob B. Buckley",institutions:[]},{name:"David A. Buell",institutions:[]},{name:"Brian Burkett",institutions:[]},{name:"Nicholas Bushnell",institutions:[]},{name:"Yu Chen",institutions:[]},{name:"Zijun Chen",institutions:[]},{name:"Benjamin Chiaro",institutions:[]},{name:"Roberto Collins",institutions:[]},{name:"William Courtney",institutions:[]},{name:"Sean Demura",institutions:[]},{name:"Andrew Dunsworth",institutions:[]},{name:"Edward Farhi",institutions:[]},{name:"Austin Fowler",institutions:[]},{name:"Brooks Foxen",institutions:[]},{name:"Craig Gidney",institutions:[]},{name:"Marissa Giustina",institutions:[]},{name:"Rob Graff",institutions:[]},{name:"Steve Habegger",institutions:[]},{name:"Matthew P. Harrigan",institutions:[]},{name:"Alan Ho",institutions:[]},{name:"Sabrina Hong",institutions:[]},{name:"Trent Huang",institutions:[]},{name:"William J. Huggins",institutions:[]},{name:"Lev Ioffe",institutions:[]},{name:"Sergei V. Isakov",institutions:[]},{name:"Evan Jeffrey",institutions:[]},{name:"Zhang Jiang",institutions:[]},{name:"Cody Jones",institutions:[]},{name:"Dvir Kafri",institutions:[]},{name:"Kostyantyn Kechedzhi",institutions:[]},{name:"Julian Kelly",institutions:[]},{name:"Seon Kim",institutions:[]},{name:"Paul V. Klimov",institutions:[]},{name:"Alexander Korotkov",institutions:[]},{name:"Fedor Kostritsa",institutions:[]},{name:"David Landhuis",institutions:[]},{name:"Pavel Laptev",institutions:[]},{name:"Mike Lindmark",institutions:[]},{name:"Erik Lucero",institutions:[]},{name:"Orion Martin",institutions:[]},{name:"John M. Martinis",institutions:[]},{name:"Jarrod R. McClean",institutions:[]},{name:"Matt McEwen",institutions:[]},{name:"Anthony Megrant",institutions:[]},{name:"Xiao Mi",institutions:[]},{name:"Masoud Mohseni",institutions:[]},{name:"Wojciech Mruczkiewicz",institutions:[]},{name:"Josh Mutus",institutions:[]},{name:"Ofer Naaman",institutions:[]},{name:"Matthew Neeley",institutions:[]},{name:"Charles Neill",institutions:[]},{name:"Hartmut Neven",institutions:[]},{name:"Murphy Yuezhen Niu",institutions:[]},{name:"Thomas E. O’Brien",institutions:[]},{name:"Eric Ostby",institutions:[]},{name:"Andre Petukhov",institutions:[]},{name:"Harald Putterman",institutions:[]},{name:"Chris Quintana",institutions:[]},{name:"Pedram Roushan",institutions:[]},{name:"Nicholas C. Rubin",institutions:[]},{name:"Daniel Sank",institutions:[]},{name:"Kevin J. Satzinger",institutions:[]},{name:"Vadim Smelyanskiy",institutions:[]},{name:"Doug Strain",institutions:[]},{name:"Kevin J. Sung",institutions:[]},{name:"Marco Szalay",institutions:[]},{name:"Tyler Y. Takeshita",institutions:[]},{name:"Amit Vainsencher",institutions:[]},{name:"Theodore White",institutions:[]},{name:"Nathan Wiebe",institutions:[]},{name:"Z. Jamie Yao",institutions:[]},{name:"Ping Yeh",institutions:[]},{name:"Adam Zalcman",institutions:[]}],authorString:"Google AI Quantum and Collaborators; Frank Arute; Kunal Arya; Ryan Babbush; Dave Bacon; Joseph C. Bardin; Rami Barends; Sergio Boixo; Michael Broughton; Bob B. Buckley; David A. Buell; Brian Burkett et al.",institutions:[],countries:[],year:2020,journal:"Science",citations:715,abstract:"Twelve-qubit quantum computing for chemistry Accurate electronic structure calculations are considered one of the most anticipated applications of quantum computing that will revolutionize theoretical chemistry and other related fields. Using the Google Sycamore quantum processor, Google AI Quantum and collaborators performed a variational quantum eigensolver (VQE) simulation of two intermediate-scale chemistry problems: the binding energy of hydrogen chains (as large as H 12 ) and the isomerization mechanism of diazene (see the Perspective by Yuan). The simulations were performed on up to 12 qubits, involving up to 72 two-qubit gates, and show that it is possible to achieve chemical accuracy when VQE is combined with error mitigation strategies. The key building blocks of the proposed VQE algorithm are potentially scalable to larger systems that cannot be simulated classically. Science , this issue p. 1084 ; see also p. 1054",keywords:["Ansatz","Quantum computer","Qubit","Quantum","Parameterized complexity","Quantum simulator","Scaling","Superconductivity"],concepts:["Ansatz","Quantum computer","Qubit","Quantum","Parameterized complexity","Quantum simulator","Quantum mechanics"],pdf_url:"https://arxiv.org/pdf/2004.04174",is_oa:!0,n_refs:41,n_refs_in_core:13,degree:46,community:1,deg_w:557.5,betweenness:.0034,pagerank:.00431,eigenvector:.0546},{id:34,oaid:"W3004965358",doi:"10.1038/s41467-020-14454-2",title:"Training deep quantum neural networks",authors:[{name:"Kerstin Beer",institutions:["Leibniz University Hannover"]},{name:"Dmytro Bondarenko",institutions:["Leibniz University Hannover"]},{name:"Terry Farrelly",institutions:["Leibniz University Hannover","ARC Centre of Excellence for Engineered Quantum Systems"]},{name:"Tobias J. Osborne",institutions:["Leibniz University Hannover"]},{name:"Robert Salzmann",institutions:["Leibniz University Hannover","University of Cambridge"]},{name:"Daniel Scheiermann",institutions:["Leibniz University Hannover"]},{name:"Ramona Wolf",institutions:["Leibniz University Hannover"]}],authorString:"Kerstin Beer; Dmytro Bondarenko; Terry Farrelly; Tobias J. Osborne; Robert Salzmann; Daniel Scheiermann; Ramona Wolf",institutions:["ARC Centre of Excellence for Engineered Quantum Systems","Leibniz University Hannover","University of Cambridge"],countries:["AU","DE","GB"],year:2020,journal:"Nature Communications",citations:707,abstract:"Neural networks enjoy widespread success in both research and industry and, with the advent of quantum technology, it is a crucial challenge to design quantum neural networks for fully quantum learning tasks. Here we propose a truly quantum analogue of classical neurons, which form quantum feedforward neural networks capable of universal quantum computation. We describe the efficient training of these networks using the fidelity as a cost function, providing both classical and efficient quantum implementations. Our method allows for fast optimisation with reduced memory requirements: the number of qudits required scales with only the width, allowing deep-network optimisation. We benchmark our proposal for the quantum task of learning an unknown unitary and find remarkable generalisation behaviour and a striking robustness to noisy training data.",keywords:["Quantum","Quantum computer","Artificial neural network","Robustness","Deep learning","Deep neural networks","Fidelity"],concepts:["Quantum","Quantum computer","Artificial neural network","Robustness","Deep learning","Deep neural networks","Fidelity"],pdf_url:"https://www.nature.com/articles/s41467-020-14454-2.pdf",is_oa:!0,n_refs:60,n_refs_in_core:7,degree:27,community:0,deg_w:259.5,betweenness:.0014,pagerank:.00272,eigenvector:.0127},{id:35,oaid:"W3096052452",doi:"10.1038/s41467-021-22539-9",title:"Power of data in quantum machine learning",authors:[{name:"Hsin-Yuan Huang",institutions:["California Institute of Technology","Google (United States)"]},{name:"Michael Broughton",institutions:["Google (United States)"]},{name:"Masoud Mohseni",institutions:["Google (United States)"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Sergio Boixo",institutions:["Google (United States)"]},{name:"Hartmut Neven",institutions:["Google (United States)"]},{name:"Jarrod R. McClean",institutions:["Google (United States)"]}],authorString:"Hsin-Yuan Huang; Michael Broughton; Masoud Mohseni; Ryan Babbush; Sergio Boixo; Hartmut Neven; Jarrod R. McClean",institutions:["California Institute of Technology","Google (United States)"],countries:["US"],year:2021,journal:"Nature Communications",citations:683,abstract:"The use of quantum computing for machine learning is among the most exciting prospective applications of quantum technologies. However, machine learning tasks where data is provided can be considerably different than commonly studied computational tasks. In this work, we show that some problems that are classically hard to compute can be easily predicted by classical machines learning from data. Using rigorous prediction error bounds as a foundation, we develop a methodology for assessing potential quantum advantage in learning tasks. The bounds are tight asymptotically and empirically predictive for a wide range of learning models. These constructions explain numerical results showing that with the help of data, classical machine learning models can be competitive with quantum models even if they are tailored to quantum problems. We then propose a projected quantum model that provides a simple and rigorous quantum speed-up for a learning problem in the fault-tolerant regime. For near-term implementations, we demonstrate a significant prediction advantage over some classical models on engineered data sets designed to demonstrate a maximal quantum advantage in one of the largest numerical tests for gate-based quantum machine learning to date, up to 30 qubits.",keywords:["Quantum machine learning","Quantum","Range","Quantum computer","Quantum algorithm","Simple","Computational learning theory"],concepts:["Quantum machine learning","Quantum","Range","Quantum computer","Quantum algorithm"],pdf_url:"https://www.nature.com/articles/s41467-021-22539-9.pdf",is_oa:!0,n_refs:30,n_refs_in_core:10,degree:27,community:0,deg_w:181,betweenness:.0018,pagerank:.00214,eigenvector:.0088},{id:36,oaid:"W2558921197",doi:"10.1103/physrevx.7.021050",title:"Efficient Variational Quantum Simulator Incorporating Active Error Minimization",authors:[{name:"Ying Li",institutions:["University of Oxford"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]}],authorString:"Ying Li; Simon C. Benjamin",institutions:["University of Oxford"],countries:["GB"],year:2017,journal:"Physical Review X",citations:640,abstract:"Quantum computers will need to be tolerant to errors introduced by noise, but current proposals estimate that the number of qubits required for error correction will be many orders of magnitude larger than the number needed for useful computation. A new proposal uses a classical-quantum hybrid scheme to implement simple error-tolerant quantum processors with relatively few resources.",keywords:["Qubit","Quantum","Minification","Simple","Quantum error correction","Quantum computer","Scheme","Error detection and correction"],concepts:["Qubit","Quantum","Minification","Simple","Quantum error correction","Quantum computer","Scheme"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.7.021050",is_oa:!0,n_refs:51,n_refs_in_core:6,degree:62,community:2,deg_w:804,betweenness:.008,pagerank:.00616,eigenvector:.0605},{id:37,oaid:"W3118800713",doi:"10.1103/prxquantum.3.010313",title:"Connecting Ansatz Expressibility to Gradient Magnitudes and Barren Plateaus",authors:[{name:"Zoë Holmes",institutions:["Los Alamos National Laboratory"]},{name:"Kunal Sharma",institutions:["Louisiana State University","Los Alamos National Laboratory"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Zoë Holmes; Kunal Sharma; M. Cerezo; Patrick J. Coles",institutions:["Los Alamos National Laboratory","Louisiana State University"],countries:["US"],year:2022,journal:"PRX Quantum",citations:597,abstract:"Parametrized quantum circuits serve as ansatze for solving variational problems and provide a flexible paradigm for the programming of near-term quantum computers. Ideally, such ansatze should be highly expressive, so that a close approximation of the desired solution can be accessed. On the other hand, the ansatz must also have sufficiently large gradients to allow for training. Here, we derive a fundamental relationship between these two essential properties: expressibility and trainability. This is done by extending the well-established barren plateau phenomenon, which holds for ansatze that form exact 2-designs, to arbitrary ansatze. Specifically, we calculate the variance in the cost gradient in terms of the expressibility of the ansatz, as measured by its distance from being a 2-design. Our resulting bounds indicate that highly expressive ansatze exhibit flatter cost landscapes and therefore will be harder to train. Furthermore, we provide numerics illustrating the effect of expressibility on gradient scalings and we discuss the implications for designing strategies to avoid barren plateaus.",keywords:["Ansatz","Attribution","Variance","Quantum","License","Mathematical economics"],concepts:["Ansatz","Attribution","Variance","Quantum","License","Mathematical economics"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.3.010313",is_oa:!0,n_refs:86,n_refs_in_core:21,degree:48,community:0,deg_w:1034,betweenness:.0029,pagerank:.00752,eigenvector:.1018},{id:38,oaid:"W2954939433",doi:"10.22331/q-2020-02-06-226",title:"Data re-uploading for a universal quantum classifier",authors:[{name:"Adrián Pérez-Salinas",institutions:["Barcelona Supercomputing Center","Universitat de Barcelona","Universitat Politècnica de Catalunya"]},{name:"Alba Cervera-Lierta",institutions:["Barcelona Supercomputing Center","Universitat de Barcelona","Universitat Politècnica de Catalunya"]},{name:"Elies Gil-Fuster",institutions:["Universitat de Barcelona"]},{name:"José I. Latorre",institutions:["Centre for Quantum Technologies","National University of Singapore","Barcelona Supercomputing Center","National Institute for Subatomic Physics","Universitat de Barcelona","Universitat Politècnica de Catalunya"]}],authorString:"Adrián Pérez-Salinas; Alba Cervera-Lierta; Elies Gil-Fuster; José I. Latorre",institutions:["Barcelona Supercomputing Center","Centre for Quantum Technologies","National Institute for Subatomic Physics","National University of Singapore","Universitat Politècnica de Catalunya","Universitat de Barcelona"],countries:["ES","NL","SG"],year:2020,journal:"Quantum",citations:584,abstract:'A single qubit provides sufficient computational capabilities to construct a universal quantum classifier when assisted with a classical subroutine. This fact may be surprising since a single qubit only offers a simple superposition of two states and single-qubit gates only make a rotation in the Bloch sphere. The key ingredient to circumvent these limitations is to allow for multiple<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mtext class="MJX-tex-mathit" mathvariant="italic">data re-uploading</mml:mtext></mml:mrow></mml:math>. A quantum circuit can then be organized as a series of data re-uploading and single-qubit processing units. Furthermore, both data re-uploading and measurements can accommodate multiple dimensions in the input and several categories in the output, to conform to a universal quantum classifier. The extension of this idea to several qubits enhances the efficiency of the strategy as entanglement expands the superpositions carried along with the classification. Extensive benchmarking on different examples of the single- and multi-qubit quantum classifier validates its ability to describe and classify complex data.',keywords:["Qubit","Quantum entanglement","Classifier","Quantum gate","Quantum","Quantum computer","Superposition principle","Quantum information"],concepts:["Qubit","Quantum entanglement","Classifier","Quantum gate","Quantum","Quantum computer","Theoretical computer science"],pdf_url:"https://quantum-journal.org/papers/q-2020-02-06-226/pdf/",is_oa:!0,n_refs:18,n_refs_in_core:4,degree:24,community:0,deg_w:197,betweenness:8e-4,pagerank:.00228,eigenvector:.0132},{id:39,oaid:"W2268604949",doi:"10.1103/physreva.94.052325",title:"Noise tailoring for scalable quantum computation via randomized compiling",authors:[{name:"Joel J. Wallman",institutions:["University of Waterloo"]},{name:"Joseph Emerson",institutions:["University of Waterloo"]}],authorString:"Joel J. Wallman; Joseph Emerson",institutions:["University of Waterloo"],countries:["CA"],year:2016,journal:"Physical review. A/Physical review, A",citations:566,abstract:"Quantum computers are poised to radically outperform their classical counterparts by manipulating coherent quantum systems. A realistic quantum computer will experience errors due to the environment and imperfect control. When these errors are even partially coherent, they present a major obstacle to performing robust computations. Here, we propose a method for introducing independent random single-qubit gates into the logical circuit in such a way that the effective logical circuit remains unchanged. We prove that this randomization tailors the noise into stochastic Pauli errors, which can dramatically reduce error rates while introducing little or no experimental overhead. Moreover, we prove that our technique is robust to the inevitable variation in errors over the randomizing gates and numerically illustrate the dramatic reductions in worst-case error that are achievable. Given such tailored noise, gates with significantly lower fidelity---comparable to fidelities realized in current experiments---are sufficient to achieve fault-tolerant quantum computation. Furthermore, the worst-case error rate of the tailored noise can be directly and efficiently measured through randomized benchmarking protocols, enabling a rigorous certification of the performance of a quantum computer.",keywords:["Scalability","Computation","Noise","Quantum computer","Randomized controlled trial","Quantum","Algorithm"],concepts:["Scalability","Computation","Noise","Quantum computer","Randomized controlled trial","Quantum"],pdf_url:"https://arxiv.org/pdf/1512.01098",is_oa:!0,n_refs:41,n_refs_in_core:0,degree:19,community:3,deg_w:139.5,betweenness:7e-4,pagerank:.00172,eigenvector:.0132},{id:40,oaid:"W2972223037",doi:"10.1038/s41534-019-0187-2",title:"Variational ansatz-based quantum simulation of imaginary time evolution",authors:[{name:"Sam McArdle",institutions:["University of Oxford"]},{name:"Tyson Jones",institutions:["University of Oxford"]},{name:"Suguru Endo",institutions:["University of Oxford"]},{name:"Ying Li",institutions:["China Academy of Engineering Physics"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]},{name:"Xiao Yuan",institutions:["University of Oxford"]}],authorString:"Sam McArdle; Tyson Jones; Suguru Endo; Ying Li; Simon C. Benjamin; Xiao Yuan",institutions:["China Academy of Engineering Physics","University of Oxford"],countries:["CN","GB"],year:2019,journal:"npj Quantum Information",citations:559,abstract:"Abstract Imaginary time evolution is a powerful tool for studying quantum systems. While it is possible to simulate with a classical computer, the time and memory requirements generally scale exponentially with the system size. Conversely, quantum computers can efficiently simulate quantum systems, but not non-unitary imaginary time evolution. We propose a variational algorithm for simulating imaginary time evolution on a hybrid quantum computer. We use this algorithm to find the ground-state energy of many-particle systems; specifically molecular hydrogen and lithium hydride, finding the ground state with high probability. Our method can also be applied to general optimisation problems and quantum machine learning. As our algorithm is hybrid, suitable for error mitigation and can exploit shallow quantum circuits, it can be implemented with current quantum computers.",keywords:["Quantum computer","Quantum simulator","Quantum algorithm","Imaginary time","Quantum","Quantum phase estimation algorithm","Ansatz"],concepts:["Quantum computer","Quantum simulator","Quantum algorithm","Imaginary time","Quantum","Quantum phase estimation algorithm","Ansatz"],pdf_url:"https://www.nature.com/articles/s41534-019-0187-2.pdf",is_oa:!0,n_refs:52,n_refs_in_core:5,degree:41,community:2,deg_w:624,betweenness:.0017,pagerank:.0047,eigenvector:.0618},{id:41,oaid:"W2297918601",doi:"10.1103/physreva.95.042308",title:"Hybrid quantum-classical hierarchy for mitigation of decoherence and determination of excited states",authors:[{name:"Jarrod R. McClean",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Mollie E. Schwartz",institutions:["University of California, Berkeley"]},{name:"Jonathan Carter",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Wibe A. de Jong",institutions:["Lawrence Berkeley National Laboratory"]}],authorString:"Jarrod R. McClean; Mollie E. Schwartz; Jonathan Carter; Wibe A. de Jong",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"],countries:["US"],year:2017,journal:"Physical review. A/Physical review, A",citations:544,abstract:"Using quantum devices supported by classical computational resources is a promising approach to quantum-enabled computation. One powerful example of such a hybrid quantum-classical approach optimized for classically intractable eigenvalue problems is the variational quantum eigensolver, built to utilize quantum resources for the solution of eigenvalue problems and optimizations with minimal coherence time requirements by leveraging classical computational resources. These algorithms have been placed as leaders among the candidates for the first to achieve supremacy over classical computation. Here, we provide evidence for the conjecture that variational approaches can automatically suppress even nonsystematic decoherence errors by introducing an exactly solvable channel model of variational state preparation. Moreover, we develop a more general hierarchy of measurement and classical computation that allows one to obtain increasingly accurate solutions by leveraging additional measurements and classical resources. We demonstrate numerically on a sample electronic system that this method both allows for the accurate determination of excited electronic states as well as reduces the impact of decoherence, without using any additional quantum coherence time or formal error-correction codes.",keywords:["Quantum decoherence","Excited state","Hierarchy","Quantum mechanics","Quantum","Statistical physics"],concepts:["Quantum decoherence","Excited state","Hierarchy","Quantum mechanics","Quantum","Statistical physics"],pdf_url:"https://arxiv.org/pdf/1603.05681",is_oa:!0,n_refs:43,n_refs_in_core:6,degree:71,community:1,deg_w:1183,betweenness:.0083,pagerank:.00825,eigenvector:.1022},{id:42,oaid:"W2995027688",doi:"10.1103/prxquantum.2.017003",title:"Quantum Simulators: Architectures and Opportunities",authors:[{name:"Ehud Altman",institutions:["University of California, Berkeley"]},{name:"Kenneth R. Brown",institutions:["Duke University"]},{name:"Giuseppe Carleo",institutions:["Flatiron Health (United States)"]},{name:"Lincoln D. Carr",institutions:["Colorado School of Mines"]},{name:"Eugene Demler",institutions:["Harvard University"]},{name:"Cheng Chin",institutions:["University of Chicago"]},{name:"Brian DeMarco",institutions:["University of Illinois Urbana-Champaign"]},{name:"Sophia E. Economou",institutions:[]},{name:"M. A. Eriksson",institutions:["University of Wisconsin–Madison"]},{name:"Kai‐Mei C. Fu",institutions:["University of Washington"]},{name:"Markus Greiner",institutions:["Harvard University"]},{name:"Kaden R. A. Hazzard",institutions:["Rice University"]},{name:"Randall G. Hulet",institutions:["Rice University"]},{name:"Alicia J. Kollár",institutions:["Joint Quantum Institute","University of Maryland, College Park"]},{name:"Benjamin Lev",institutions:["Stanford University"]},{name:"Mikhail D. Lukin",institutions:["Harvard University"]},{name:"Ruichao Ma",institutions:["Purdue University West Lafayette"]},{name:"Xiao Mi",institutions:["Google (United States)"]},{name:"Shashank Misra",institutions:["Sandia National Laboratories"]},{name:"C. Monroe",institutions:["Joint Quantum Institute","University of Maryland, College Park"]},{name:"Kater Murch",institutions:["Washington University in St. Louis"]},{name:"Zaira Nazario",institutions:[]},{name:"Kang-Kuen Ni",institutions:["Harvard University"]},{name:"Andrew C. Potter",institutions:["The University of Texas at Austin"]},{name:"P. Roushan",institutions:["Google (United States)"]},{name:"M. Saffman",institutions:["University of Wisconsin–Madison"]},{name:"Monika Schleier-Smith",institutions:["Stanford University"]},{name:"Irfan Siddiqi",institutions:["University of California, Berkeley"]},{name:"R. W. Simmonds",institutions:["National Institute of Standards and Technology"]},{name:"Meenakshi Singh",institutions:["Colorado School of Mines"]},{name:"I. B. Spielman",institutions:["Joint Quantum Institute","University of Maryland, College Park"]},{name:"Kristan Temme",institutions:[]},{name:"David S. Weiss",institutions:["Pennsylvania State University"]},{name:"Jelena Vučković",institutions:["Stanford University"]},{name:"Vladan Vuletić",institutions:["MIT-Harvard Center for Ultracold Atoms","Massachusetts Institute of Technology"]},{name:"Jun Ye",institutions:["National Institute of Standards and Technology","University of Colorado Boulder"]},{name:"Martin W. Zwierlein",institutions:["MIT-Harvard Center for Ultracold Atoms","Massachusetts Institute of Technology"]}],authorString:"Ehud Altman; Kenneth R. Brown; Giuseppe Carleo; Lincoln D. Carr; Eugene Demler; Cheng Chin; Brian DeMarco; Sophia E. Economou; M. A. Eriksson; Kai‐Mei C. Fu; Markus Greiner; Kaden R. A. Hazzard et al.",institutions:["Colorado School of Mines","Duke University","Flatiron Health (United States)","Google (United States)","Harvard University","Joint Quantum Institute","MIT-Harvard Center for Ultracold Atoms","Massachusetts Institute of Technology","National Institute of Standards and Technology","Pennsylvania State University","Purdue University West Lafayette","Rice University","Sandia National Laboratories","Stanford University","The University of Texas at Austin","University of California, Berkeley","University of Chicago","University of Colorado Boulder","University of Illinois Urbana-Champaign","University of Maryland, College Park","University of Washington","University of Wisconsin–Madison","Washington University in St. Louis"],countries:["US"],year:2021,journal:"PRX Quantum",citations:540,abstract:'Quantum simulators are a promising technology on the spectrum of quantum devices from specialized quantum experiments to universal quantum computers. These quantum devices utilize entanglement and many-particle behavior to explore and solve hard scientific, engineering, and computational problems. Rapid development over the last two decades has produced more than 300 quantum simulators in operation worldwide using a wide variety of experimental platforms. Recent advances in several physical architectures promise a golden age of quantum simulators ranging from highly optimized special purpose simulators to flexible programmable devices. These developments have enabled a convergence of ideas drawn from fundamental physics, computer science, and device engineering. They have strong potential to address problems of societal importance, ranging from understanding vital chemical processes, to enabling the design of new materials with enhanced performance, to solving complex computational problems. It is the position of the community, as represented by participants of the National Science Foundation workshop on "Programmable Quantum Simulators," that investment in a national quantum simulator program is a high priority in order to accelerate the progress in this field and to result in the first practical applications of quantum machines. Such a program should address two areas of emphasis: (1) support for creating quantum simulator prototypes usable by the broader scientific community, complementary to the present universal quantum computer effort in industry; and (2) support for fundamental research carried out by a blend of multi-investigator, multidisciplinary collaborations with resources for quantum simulator software, hardware, and education.This document is a summary from a U.S. National Science Foundation supported workshop held on 16–17 September 2019 in Alexandria, VA. Attendees were charged to identify the scientific and community needs, opportunities, and significant challenges for quantum simulators over the next 2–5 years.',keywords:["Quantum","Computer architecture","Quantum mechanics"],concepts:["Quantum","Computer architecture"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.017003",is_oa:!0,n_refs:183,n_refs_in_core:13,degree:29,community:3,deg_w:424.5,betweenness:.0015,pagerank:.00353,eigenvector:.0304},{id:43,oaid:"W2778498694",doi:"10.1103/physrevx.8.031027",title:"Practical Quantum Error Mitigation for Near-Future Applications",authors:[{name:"Suguru Endo",institutions:["University of Oxford"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]},{name:"Ying Li",institutions:["China Academy of Engineering Physics","University of Oxford"]}],authorString:"Suguru Endo; Simon C. Benjamin; Ying Li",institutions:["China Academy of Engineering Physics","University of Oxford"],countries:["CN","GB"],year:2018,journal:"Physical Review X",citations:520,abstract:"A new analysis of quantum error mitigation, which attempts to limit the effects of errors in near-term quantum computers, shows that two proposed techniques can work in small systems without the need for extra qubits or peripheral devices.",keywords:["Qubit","Quantum error correction","Quantum","Limit","Quantum computer","Work","Quantum sensor","Error detection and correction"],concepts:["Qubit","Quantum error correction","Quantum","Limit","Quantum computer","Work","Quantum sensor"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.8.031027",is_oa:!0,n_refs:28,n_refs_in_core:8,degree:42,community:2,deg_w:535.5,betweenness:.0024,pagerank:.0043,eigenvector:.0437},{id:44,oaid:"W2586874551",doi:"10.1073/pnas.1618020114",title:"Experimental comparison of two quantum computing architectures",authors:[{name:"Norbert M. Linke",institutions:["Joint Center for Quantum Information and Computer Science","Joint Quantum Institute","University of Maryland, College Park"]},{name:"Dmitri Maslov",institutions:["U.S. National Science Foundation","Joint Center for Quantum Information and Computer Science","University of Maryland, College Park"]},{name:"Martin Roetteler",institutions:["Microsoft (United States)"]},{name:"Shantanu Debnath",institutions:["Joint Center for Quantum Information and Computer Science","Joint Quantum Institute","University of Maryland, College Park"]},{name:"Caroline Figgatt",institutions:["Joint Center for Quantum Information and Computer Science","Joint Quantum Institute","University of Maryland, College Park"]},{name:"K. A. Landsman",institutions:["Joint Center for Quantum Information and Computer Science","Joint Quantum Institute","University of Maryland, College Park"]},{name:"Kenneth Wright",institutions:["Joint Center for Quantum Information and Computer Science","Joint Quantum Institute","University of Maryland, College Park"]},{name:"C. Monroe",institutions:["Joint Center for Quantum Information and Computer Science","IonQ (United States)","Joint Quantum Institute","University of Maryland, College Park"]}],authorString:"Norbert M. Linke; Dmitri Maslov; Martin Roetteler; Shantanu Debnath; Caroline Figgatt; K. A. Landsman; Kenneth Wright; C. Monroe",institutions:["IonQ (United States)","Joint Center for Quantum Information and Computer Science","Joint Quantum Institute","Microsoft (United States)","U.S. National Science Foundation","University of Maryland, College Park"],countries:["US"],year:2017,journal:"Proceedings of the National Academy of Sciences",citations:518,abstract:"We run a selection of algorithms on two state-of-the-art 5-qubit quantum computers that are based on different technology platforms. One is a publicly accessible superconducting transmon device (www. RESEARCH: ibm.com/ibm-q) with limited connectivity, and the other is a fully connected trapped-ion system. Even though the two systems have different native quantum interactions, both can be programed in a way that is blind to the underlying hardware, thus allowing a comparison of identical quantum algorithms between different physical systems. We show that quantum algorithms and circuits that use more connectivity clearly benefit from a better-connected system of qubits. Although the quantum systems here are not yet large enough to eclipse classical computers, this experiment exposes critical factors of scaling quantum computers, such as qubit connectivity and gate expressivity. In addition, the results suggest that codesigning particular quantum applications with the hardware itself will be paramount in successfully using quantum computers in the future.",keywords:["Qubit","Transmon","Quantum computer","Quantum","Theoretical computer science","Computer engineering"],concepts:["Qubit","Transmon","Quantum computer","Quantum","Theoretical computer science","Computer engineering"],pdf_url:"https://arxiv.org/pdf/1702.01852",is_oa:!0,n_refs:44,n_refs_in_core:3,degree:19,community:3,deg_w:162,betweenness:.0013,pagerank:.00189,eigenvector:.0097},{id:45,oaid:"W3094656610",doi:"10.7566/jpsj.90.032001",title:"Hybrid Quantum-Classical Algorithms and Quantum Error Mitigation",authors:[{name:"Suguru Endo",institutions:["NTT (Japan)"]},{name:"Zhenyu Cai",institutions:["University of Oxford"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]},{name:"Xiao Yuan",institutions:["Peking University","Instituto de Física Teórica"]}],authorString:"Suguru Endo; Zhenyu Cai; Simon C. Benjamin; Xiao Yuan",institutions:["Instituto de Física Teórica","NTT (Japan)","Peking University","University of Oxford"],countries:["CN","ES","GB","JP"],year:2021,journal:"Journal of the Physical Society of Japan",citations:516,abstract:"Quantum computers can exploit a Hilbert space whose dimension increases exponentially with the number of qubits. In experiment, quantum supremacy has recently been achieved by the Google team by using a noisy intermediate-scale quantum (NISQ) device with over 50 qubits. However, the question of what can be implemented on NISQ devices is still not fully explored, and discovering useful tasks for such devices is a topic of considerable interest. Hybrid quantum-classical algorithms are regarded as well-suited for execution on NISQ devices by combining quantum computers with classical computers, and are expected to be the first useful applications for quantum computing. Meanwhile, mitigation of errors on quantum processors is also crucial to obtain reliable results. In this article, we review the basic results for hybrid quantum-classical algorithms and quantum error mitigation techniques. Since quantum computing with NISQ devices is an actively developing field, we expect this review to be a useful basis for future studies.",keywords:["Quantum computer","Quantum algorithm","Dimension","Quantum","Exploit","Hilbert space","Quantum error correction","Quantum phase estimation algorithm"],concepts:["Quantum computer","Quantum algorithm","Dimension","Quantum","Algorithm","Exploit","Hilbert space"],pdf_url:"https://arxiv.org/pdf/2011.01382",is_oa:!0,n_refs:130,n_refs_in_core:43,degree:69,community:2,deg_w:1404,betweenness:.0098,pagerank:.00991,eigenvector:.1371},{id:46,oaid:"W2092458348",doi:"10.1038/ncomms7979",title:"Demonstration of a quantum error detection code using a square lattice of four superconducting qubits",authors:[{name:"Antonio Córcoles",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Easwar Magesan",institutions:["IBM (United States)"]},{name:"Srikanth Srinivasan",institutions:["IBM (United States)"]},{name:"Andrew W. Cross",institutions:["IBM (United States)"]},{name:"Matthias Steffen",institutions:["IBM (United States)"]},{name:"Jay Gambetta",institutions:["IBM (United States)"]},{name:"Jerry M. Chow",institutions:["IBM (United States)"]}],authorString:"Antonio Córcoles; Easwar Magesan; Srikanth Srinivasan; Andrew W. Cross; Matthias Steffen; Jay Gambetta; Jerry M. Chow",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"],countries:["US"],year:2015,journal:"Nature Communications",citations:513,abstract:"The ability to detect and deal with errors when manipulating quantum systems is a fundamental requirement for fault-tolerant quantum computing. Unlike classical bits that are subject to only digital bit-flip errors, quantum bits are susceptible to a much larger spectrum of errors, for which any complete quantum error-correcting code must account. Whilst classical bit-flip detection can be realized via a linear array of qubits, a general fault-tolerant quantum error-correcting code requires extending into a higher-dimensional lattice. Here we present a quantum error detection protocol on a two-by-two planar lattice of superconducting qubits. The protocol detects an arbitrary quantum error on an encoded two-qubit entangled state via quantum non-demolition parity measurements on another pair of error syndrome qubits. This result represents a building block towards larger lattices amenable to fault-tolerant quantum error correction architectures such as the surface code.",keywords:["Quantum error correction","Qubit","Quantum convolutional code","Quantum computer","Error detection and correction","Quantum mechanics","Quantum algorithm"],concepts:["Quantum error correction","Qubit","Quantum convolutional code","Quantum computer","Error detection and correction","Quantum mechanics","Quantum algorithm"],pdf_url:"https://www.nature.com/articles/ncomms7979.pdf",is_oa:!0,n_refs:33,n_refs_in_core:2,degree:25,community:3,deg_w:238.5,betweenness:.0021,pagerank:.00254,eigenvector:.0144},{id:47,oaid:"W2736592352",doi:"10.1098/rspa.2017.0551",title:"Quantum machine learning: a classical perspective",authors:[{name:"Carlo Ciliberto",institutions:["University College London"]},{name:"Mark Herbster",institutions:["University College London"]},{name:"Alessandro Davide Ialongo",institutions:["University of Cambridge","Max Planck Institute for Intelligent Systems"]},{name:"Massimiliano Pontil",institutions:["Italian Institute of Technology","University College London"]},{name:"Andrea Rocchetto",institutions:["University of Oxford","University College London"]},{name:"Simone Severini",institutions:["Shanghai Jiao Tong University","University College London"]},{name:"Leonard Wossnig",institutions:["ETH Zurich","University of Oxford","University College London"]}],authorString:"Carlo Ciliberto; Mark Herbster; Alessandro Davide Ialongo; Massimiliano Pontil; Andrea Rocchetto; Simone Severini; Leonard Wossnig",institutions:["ETH Zurich","Italian Institute of Technology","Max Planck Institute for Intelligent Systems","Shanghai Jiao Tong University","University College London","University of Cambridge","University of Oxford"],countries:["CH","CN","DE","GB","IT"],year:2018,journal:"Proceedings of the Royal Society A Mathematical Physical and Engineering Sciences",citations:513,abstract:"Recently, increased computational power and data availability, as well as algorithmic advances, have led machine learning (ML) techniques to impressive results in regression, classification, data generation and reinforcement learning tasks. Despite these successes, the proximity to the physical limits of chip fabrication alongside the increasing size of datasets is motivating a growing number of researchers to explore the possibility of harnessing the power of quantum computation to speed up classical ML algorithms. Here we review the literature in quantum ML and discuss perspectives for a mixed readership of classical ML and quantum computation experts. Particular emphasis will be placed on clarifying the limitations of quantum algorithms, how they compare with their best classical counterparts and why quantum resources are expected to provide advantages for learning problems. Learning in the presence of noise and certain computationally hard problems in ML are identified as promising directions for the field. Practical questions, such as how to upload classical data into quantum form, will also be addressed.",keywords:["Quantum computer","Quantum","Quantum machine learning","Perspective","Reinforcement learning","Computation","Field"],concepts:["Quantum computer","Quantum","Quantum machine learning","Perspective","Reinforcement learning","Computation","Field"],pdf_url:"https://royalsocietypublishing.org/doi/pdf/10.1098/rspa.2017.0551",is_oa:!0,n_refs:218,n_refs_in_core:3,degree:30,community:0,deg_w:413,betweenness:.0017,pagerank:.00394,eigenvector:.0237},{id:48,oaid:"W3105532889",doi:"10.1103/physrevx.8.011021",title:"Computation of Molecular Spectra on a Quantum Processor with an Error-Resilient Algorithm",authors:[{name:"James Colless",institutions:["Coherent (United States)","University of California, Berkeley"]},{name:"Vinay Ramasesh",institutions:["Coherent (United States)","University of California, Berkeley"]},{name:"Dar Dahlen",institutions:["Coherent (United States)","University of California, Berkeley"]},{name:"Machiel Blok",institutions:["Coherent (United States)","University of California, Berkeley"]},{name:"Mollie E. Schwartz",institutions:["Coherent (United States)","University of California, Berkeley"]},{name:"Jarrod R. McClean",institutions:["Coherent (United States)","University of California, Berkeley"]},{name:"Jonathan Carter",institutions:["Coherent (United States)","University of California, Berkeley"]},{name:"Wibe A. de Jong",institutions:["Coherent (United States)","University of California, Berkeley"]},{name:"Irfan Siddiqi",institutions:["Coherent (United States)","University of California, Berkeley"]}],authorString:"James Colless; Vinay Ramasesh; Dar Dahlen; Machiel Blok; Mollie E. Schwartz; Jarrod R. McClean; Jonathan Carter; Wibe A. de Jong; Irfan Siddiqi",institutions:["Coherent (United States)","University of California, Berkeley"],countries:["US"],year:2018,journal:"Physical Review X",citations:482,abstract:"Harnessing the full power of nascent quantum processors requires the efficient management of a limited number of quantum bits with finite coherent lifetimes. Hybrid algorithms, such as the variational quantum eigensolver (VQE), leverage classical resources to reduce the required number of quantum gates. Experimental demonstrations of VQE have resulted in calculation of Hamiltonian ground states, and a new theoretical approach based on a quantum subspace expansion (QSE) has outlined a procedure for determining excited states that are central to dynamical processes. We use a superconducting-qubit-based processor to apply the QSE approach to the H 2 molecule, extracting both ground and excited states without the need for auxiliary qubits or additional minimization. Further, we show that this extended protocol can mitigate the effects of incoherent errors, potentially enabling larger-scale quantum simulations without the need for complex error-correction techniques.",keywords:["Quantum computer","Computation","Algorithm","Quantum","Parallel computing","Theoretical computer science","Quantum mechanics"],concepts:["Quantum computer","Computation","Algorithm","Quantum","Parallel computing","Theoretical computer science"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.8.011021",is_oa:!0,n_refs:41,n_refs_in_core:8,degree:78,community:1,deg_w:1141.5,betweenness:.0119,pagerank:.00809,eigenvector:.0913},{id:49,oaid:"W2803208764",doi:"10.22331/q-2019-07-01-156",title:"Variational Quantum Computation of Excited States",authors:[{name:"Oscar Higgott",institutions:["Riverlane (United Kingdom)","University College London"]},{name:"Daochen Wang",institutions:["Riverlane (United Kingdom)","Joint Center for Quantum Information and Computer Science","University of Maryland, College Park"]},{name:"Stephen Brierley",institutions:["Riverlane (United Kingdom)"]}],authorString:"Oscar Higgott; Daochen Wang; Stephen Brierley",institutions:["Joint Center for Quantum Information and Computer Science","Riverlane (United Kingdom)","University College London","University of Maryland, College Park"],countries:["GB","US"],year:2019,journal:"Quantum",citations:471,abstract:"The calculation of excited state energies of electronic structure Hamiltonians has many important applications, such as the calculation of optical spectra and reaction rates. While low-depth quantum algorithms, such as the variational quantum eigenvalue solver (VQE), have been used to determine ground state energies, methods for calculating excited states currently involve the implementation of high-depth controlled-unitaries or a large number of additional samples. Here we show how overlap estimation can be used to deflate eigenstates once they are found, enabling the calculation of excited state energies and their degeneracies. We propose an implementation that requires the same number of qubits as VQE and at most twice the circuit depth. Our method is robust to control errors, is compatible with error-mitigation strategies and can be implemented on near-term quantum computers.",keywords:["Excited state","Qubit","Eigenvalues and eigenvectors","Quantum computer","Quantum","Computation","Solver"],concepts:["Excited state","Qubit","Eigenvalues and eigenvectors","Quantum computer","Quantum","Computation","Solver"],pdf_url:"https://quantum-journal.org/papers/q-2019-07-01-156/pdf/",is_oa:!0,n_refs:55,n_refs_in_core:17,degree:57,community:2,deg_w:993.5,betweenness:.0045,pagerank:.00708,eigenvector:.0922},{id:50,oaid:"W2895777514",doi:"10.1021/acs.jctc.8b01004",title:"Generalized Unitary Coupled Cluster Wave functions for Quantum Computation",authors:[{name:"Joonho Lee",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"William J. Huggins",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"Martin Head‐Gordon",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"K. Birgitta Whaley",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]}],authorString:"Joonho Lee; William J. Huggins; Martin Head‐Gordon; K. Birgitta Whaley",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"],countries:["US"],year:2018,journal:"Journal of Chemical Theory and Computation",citations:465,abstract:"We introduce a unitary coupled-cluster (UCC) ansatz termed k-UpCCGSD that is based on a family of sparse generalized doubles operators, which provides an affordable and systematically improvable unitary coupled-cluster wave function suitable for implementation on a near-term quantum computer. k-UpCCGSD employs k products of the exponential of pair coupled-cluster double excitation operators (pCCD), together with generalized single excitation operators. We compare its performance in both efficiency of implementation and accuracy with that of the generalized UCC ansatz employing the full generalized single and double excitation operators (UCCGSD), as well as with the standard ansatz employing only single and double excitations (UCCSD). k-UpCCGSD is found to show the best scaling for quantum computing applications, requiring a circuit depth of O(kN), compared with O(N3) for UCCGSD, and O((N−η)2η) for UCCSD, where N is the number of spin orbitals and η is the number of electrons. We analyzed the accuracy of these three ansätze by making classical benchmark calculations on the ground state and the first excited state of H4 (STO-3G, 6-31G), H2O (STO-3G), and N2 (STO-3G), making additional comparisons to conventional coupled cluster methods. The results for ground states show that k-UpCCGSD offers a good trade-off between accuracy and cost, achieving chemical accuracy for lower cost of implementation on quantum computers than both UCCGSD and UCCSD. UCCGSD is also found to be more accurate than UCCSD but at a greater cost for implementation. Excited states are calculated with an orthogonally constrained variational quantum eigensolver approach. This is seen to generally yield less accurate energies than for the corresponding ground states. We demonstrate that using a specialized multideterminantal reference state constructed from classical linear response calculations allows these excited state energetics to be improved.",keywords:["Ansatz","Coupled cluster","Wave function","Excited state","Quantum computer","Unitary state","Unitary group","Quantum mechanics"],concepts:["Ansatz","Coupled cluster","Wave function","Excited state","Quantum computer","Unitary state","Unitary group","Quantum mechanics"],pdf_url:"https://arxiv.org/pdf/1810.02327",is_oa:!0,n_refs:112,n_refs_in_core:12,degree:50,community:1,deg_w:975,betweenness:.0024,pagerank:.00696,eigenvector:.0884},{id:51,oaid:"W3128504623",doi:null,title:"Hybrid quantum-classical algorithms and quantum error mitigation",authors:[{name:"Cai, Z",institutions:["NTT (Japan)"]},{name:"Benjamin, SC",institutions:["University of Oxford"]},{name:"Endo, S",institutions:["University of Oxford"]},{name:"Xiao Yuan",institutions:["Peking University","Instituto de Física Teórica"]}],authorString:"Cai, Z; Benjamin, SC; Endo, S; Xiao Yuan",institutions:["Instituto de Física Teórica","NTT (Japan)","Peking University","University of Oxford"],countries:["CN","ES","GB","JP"],year:2021,journal:"Oxford University Research Archive (ORA) (University of Oxford)",citations:457,abstract:"Quantum computers can exploit a Hilbert space whose dimension increases exponentially with the number of qubits. In experiment, quantum supremacy has recently been achieved by the Google team by using a noisy intermediate-scale quantum (NISQ) device with over 50 qubits. However, the question of what can be implemented on NISQ devices is still not fully explored, and discovering useful tasks for such devices is a topic of considerable interest. Hybrid quantum-classical algorithms are regarded as well-suited for execution on NISQ devices by combining quantum computers with classical computers, and are expected to be the first useful applications for quantum computing. Meanwhile, mitigation of errors on quantum processors is also crucial to obtain reliable results. In this article, we review the basic results for hybrid quantum-classical algorithms and quantum error mitigation techniques. Since quantum computing with NISQ devices is an actively developing field, we expect this review to be a useful basis for future studies.",keywords:["Quantum computer","Quantum algorithm","Qubit","Quantum sort","Quantum error correction","Algorithm","Quantum"],concepts:["Quantum computer","Quantum algorithm","Qubit","Quantum sort","Quantum error correction","Algorithm","Quantum"],pdf_url:null,is_oa:!1,n_refs:151,n_refs_in_core:22,degree:49,community:2,deg_w:1121,betweenness:.0044,pagerank:.0079,eigenvector:.1297},{id:52,oaid:"W3211718387",doi:"10.1038/s41467-022-32550-3",title:"Generalization in quantum machine learning from few training data",authors:[{name:"Matthias C. Caro",institutions:["Munich Center for Quantum Science and Technology","Technical University of Munich"]},{name:"Hsin-Yuan Huang",institutions:["California Institute of Technology"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory"]},{name:"Kunal Sharma",institutions:["Joint Center for Quantum Information and Computer Science","University of Maryland, College Park"]},{name:"Andrew Sornborger",institutions:["Los Alamos National Laboratory","Quantum Science Center"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Matthias C. Caro; Hsin-Yuan Huang; M. Cerezo; Kunal Sharma; Andrew Sornborger; Łukasz Cincio; Patrick J. Coles",institutions:["California Institute of Technology","Joint Center for Quantum Information and Computer Science","Los Alamos National Laboratory","Munich Center for Quantum Science and Technology","Quantum Science Center","Technical University of Munich","University of Maryland, College Park"],countries:["DE","US"],year:2022,journal:"Nature Communications",citations:456,abstract:"Modern quantum machine learning (QML) methods involve variationally optimizing a parameterized quantum circuit on a training data set, and subsequently making predictions on a testing data set (i.e., generalizing). In this work, we provide a comprehensive study of generalization performance in QML after training on a limited number N of training data points. We show that the generalization error of a quantum machine learning model with T trainable gates scales at worst as [Formula: see text]. When only K ≪ T gates have undergone substantial change in the optimization process, we prove that the generalization error improves to [Formula: see text]. Our results imply that the compiling of unitaries into a polynomial number of native gates, a crucial application for the quantum computing industry that typically uses exponential-size training data, can be sped up significantly. We also show that classification of quantum states across a phase transition with a quantum convolutional neural network requires only a very small training data set. Other potential applications include learning quantum error correcting codes or quantum dynamical simulation. Our work injects new hope into the field of QML, as good generalization is guaranteed from few training data.",keywords:["Generalization","Quantum","Convolutional neural network","Quantum computer","Parameterized complexity","Quantum circuit","Quantum machine learning"],concepts:["Generalization","Quantum","Convolutional neural network","Quantum computer","Parameterized complexity","Quantum circuit","Quantum machine learning"],pdf_url:"https://www.nature.com/articles/s41467-022-32550-3.pdf",is_oa:!0,n_refs:154,n_refs_in_core:22,degree:39,community:0,deg_w:764.5,betweenness:.0025,pagerank:.00593,eigenvector:.0677},{id:53,oaid:"W2972032089",doi:"10.22331/q-2020-05-25-269",title:"Quantum Natural Gradient",authors:[{name:"James Stokes",institutions:["Flatiron Health (United States)","Flatiron Institute"]},{name:"Josh Izaac",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Giuseppe Carleo",institutions:["Flatiron Health (United States)","Flatiron Institute"]}],authorString:"James Stokes; Josh Izaac; Nathan Killoran; Giuseppe Carleo",institutions:["Flatiron Health (United States)","Flatiron Institute","Xanadu Quantum Technologies (Canada)"],countries:["CA","US"],year:2020,journal:"Quantum",citations:449,abstract:"A quantum generalization of Natural Gradient Descent is presented as part of a general-purpose optimization framework for variational quantum circuits. The optimization dynamics is interpreted as moving in the steepest descent direction with respect to the Quantum Information Geometry, corresponding to the real part of the Quantum Geometric Tensor (QGT), also known as the Fubini-Study metric tensor. An efficient algorithm is presented for computing a block-diagonal approximation to the Fubini-Study metric tensor for parametrized quantum circuits, which may be of independent interest.",keywords:["Tensor","Diagonal","Quantum","Quantum algorithm","Generalization","Metric","Gradient descent"],concepts:["Tensor","Diagonal","Quantum","Quantum algorithm","Generalization","Metric","Gradient descent"],pdf_url:"https://quantum-journal.org/papers/q-2020-05-25-269/pdf/",is_oa:!0,n_refs:49,n_refs_in_core:12,degree:47,community:0,deg_w:627,betweenness:.0033,pagerank:.00507,eigenvector:.0536},{id:54,oaid:"W2903627855",doi:"10.22331/q-2019-10-07-191",title:"Theory of variational quantum simulation",authors:[{name:"Xiao Yuan",institutions:["University of Oxford"]},{name:"Suguru Endo",institutions:["University of Oxford"]},{name:"Qi Zhao",institutions:["Tsinghua University"]},{name:"Ying Li",institutions:["China Academy of Engineering Physics"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]}],authorString:"Xiao Yuan; Suguru Endo; Qi Zhao; Ying Li; Simon C. Benjamin",institutions:["China Academy of Engineering Physics","Tsinghua University","University of Oxford"],countries:["CN","GB"],year:2019,journal:"Quantum",citations:438,abstract:"The variational method is a versatile tool for classical simulation of a variety of quantum systems. Great efforts have recently been devoted to its extension to quantum computing for efficiently solving static many-body problems and simulating real and imaginary time dynamics. In this work, we first review the conventional variational principles, including the Rayleigh-Ritz method for solving static problems, and the Dirac and Frenkel variational principle, the McLachlan's variational principle, and the time-dependent variational principle, for simulating real time dynamics. We focus on the simulation of dynamics and discuss the connections of the three variational principles. Previous works mainly focus on the unitary evolution of pure states. In this work, we introduce variational quantum simulation of mixed states under general stochastic evolution. We show how the results can be reduced to the pure state case with a correction term that takes accounts of global phase alignment. For variational simulation of imaginary time evolution, we also extend it to the mixed state scenario and discuss variational Gibbs state preparation. We further elaborate on the design of ansatz that is compatible with post-selection measurement and the implementation of the generalised variational algorithms with quantum circuits. Our work completes the theory of variational quantum simulation of general real and imaginary time evolution and it is applicable to near-term quantum hardware.",keywords:["Ansatz","Variational method","Focus","Quantum","Imaginary time","Quantum simulator","Quantum computer","Luke's variational principle"],concepts:["Ansatz","Variational method","Focus","Quantum","Imaginary time","Statistical physics","Quantum simulator","Quantum computer"],pdf_url:"https://quantum-journal.org/papers/q-2019-10-07-191/pdf/",is_oa:!0,n_refs:61,n_refs_in_core:12,degree:54,community:2,deg_w:951.5,betweenness:.0044,pagerank:.00685,eigenvector:.092},{id:55,oaid:"W2794503138",doi:"10.1103/physrevx.8.031022",title:"Quantum Chemistry Calculations on a Trapped-Ion Quantum Simulator",authors:[{name:"Cornelius Hempel",institutions:["The University of Sydney","Austrian Academy of Sciences","Institute for Quantum Optics and Quantum Information Innsbruck","ARC Centre of Excellence for Engineered Quantum Systems"]},{name:"Christine Maier",institutions:["Austrian Academy of Sciences","Universität Innsbruck","Institute for Quantum Optics and Quantum Information Innsbruck"]},{name:"Jonathan Romero",institutions:["Harvard University"]},{name:"Jarrod McClean",institutions:["Google (United States)"]},{name:"Thomas Monz",institutions:["Universität Innsbruck"]},{name:"Heng Shen",institutions:["Austrian Academy of Sciences","Universität Innsbruck","Institute for Quantum Optics and Quantum Information Innsbruck"]},{name:"Petar Jurcevic",institutions:["Austrian Academy of Sciences","Universität Innsbruck","Institute for Quantum Optics and Quantum Information Innsbruck"]},{name:"Ben P. Lanyon",institutions:["Austrian Academy of Sciences","Universität Innsbruck","Institute for Quantum Optics and Quantum Information Innsbruck"]},{name:"Peter Love",institutions:["Tufts University"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Alán Aspuru-Guzik",institutions:["Harvard University"]},{name:"Rainer Blatt",institutions:["Austrian Academy of Sciences","Universität Innsbruck","Institute for Quantum Optics and Quantum Information Innsbruck"]},{name:"Christian F. Roos",institutions:["Austrian Academy of Sciences","Universität Innsbruck","Institute for Quantum Optics and Quantum Information Innsbruck"]}],authorString:"Cornelius Hempel; Christine Maier; Jonathan Romero; Jarrod McClean; Thomas Monz; Heng Shen; Petar Jurcevic; Ben P. Lanyon; Peter Love; Ryan Babbush; Alán Aspuru-Guzik; Rainer Blatt et al.",institutions:["ARC Centre of Excellence for Engineered Quantum Systems","Austrian Academy of Sciences","Google (United States)","Harvard University","Institute for Quantum Optics and Quantum Information Innsbruck","The University of Sydney","Tufts University","Universität Innsbruck"],countries:["AT","AU","US"],year:2018,journal:"Physical Review X",citations:435,abstract:"Quantum-classical hybrid algorithms are a promising approach for near-term practical applications of quantum computers. A new experiment demonstrates how a trapped-ion implementation of one such algorithm solves a quantum chemistry problem.",keywords:["Quantum","Quantum simulator","Quantum chemistry","Quantum computer","Quantum algorithm","Quantum chemical","Quantum dynamics"],concepts:["Quantum","Quantum simulator","Quantum chemistry","Quantum computer","Statistical physics","Quantum algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.8.031022",is_oa:!0,n_refs:106,n_refs_in_core:14,degree:59,community:1,deg_w:1291.5,betweenness:.0065,pagerank:.00912,eigenvector:.0872},{id:56,oaid:"W3199543116",doi:"10.1103/physrevlett.127.120502",title:"Training Variational Quantum Algorithms Is NP-Hard",authors:[{name:"Lennart Bittel",institutions:["Heinrich Heine University Düsseldorf"]},{name:"Martin Kliesch",institutions:["Heinrich Heine University Düsseldorf"]}],authorString:"Lennart Bittel; Martin Kliesch",institutions:["Heinrich Heine University Düsseldorf"],countries:["DE"],year:2021,journal:"Physical Review Letters",citations:423,abstract:"Variational quantum algorithms are proposed to solve relevant computational problems on near term quantum devices. Popular versions are variational quantum eigensolvers and quantum approximate optimization algorithms that solve ground state problems from quantum chemistry and binary optimization problems, respectively. They are based on the idea of using a classical computer to train a parametrized quantum circuit. We show that the corresponding classical optimization problems are NP-hard. Moreover, the hardness is robust in the sense that, for every polynomial time algorithm, there are instances for which the relative error resulting from the classical optimization problem can be arbitrarily large assuming that P≠NP. Even for classically tractable systems composed of only logarithmically many qubits or free fermions, we show the optimization to be NP-hard. This elucidates that the classical optimization is intrinsically hard and does not merely inherit the hardness from the ground state problem. Our analysis shows that the training landscape can have many far from optimal persistent local minima This means gradient and higher order descent algorithms will generally converge to far from optimal solutions.",keywords:["Maxima and minima","Quantum","Qubit","Quantum computer","Optimization problem","Quantum algorithm","Ground state"],concepts:["Maxima and minima","Quantum","Qubit","Quantum computer","Optimization problem","Quantum algorithm","Ground state"],pdf_url:"https://arxiv.org/pdf/2101.07267",is_oa:!0,n_refs:23,n_refs_in_core:7,degree:31,community:0,deg_w:282.5,betweenness:.0016,pagerank:.00275,eigenvector:.0276},{id:57,oaid:"W2784059933",doi:"10.1103/physrevlett.120.210501",title:"Cloud Quantum Computing of an Atomic Nucleus",authors:[{name:"Eugene Dumitrescu",institutions:["Oak Ridge National Laboratory"]},{name:"Alex McCaskey",institutions:["Oak Ridge National Laboratory"]},{name:"G. Hagen",institutions:["Oak Ridge National Laboratory","University of Tennessee at Knoxville"]},{name:"G. R. Jansen",institutions:["Oak Ridge National Laboratory"]},{name:"Titus Morris",institutions:["Oak Ridge National Laboratory","University of Tennessee at Knoxville"]},{name:"T. Papenbrock",institutions:["Oak Ridge National Laboratory","University of Tennessee at Knoxville"]},{name:"Raphael C. Pooser",institutions:["Oak Ridge National Laboratory","University of Tennessee at Knoxville"]},{name:"D. J. Dean",institutions:["Oak Ridge National Laboratory"]},{name:"Pavel Lougovski",institutions:["Oak Ridge National Laboratory"]}],authorString:"Eugene Dumitrescu; Alex McCaskey; G. Hagen; G. R. Jansen; Titus Morris; T. Papenbrock; Raphael C. Pooser; D. J. Dean; Pavel Lougovski",institutions:["Oak Ridge National Laboratory","University of Tennessee at Knoxville"],countries:["US"],year:2018,journal:"Physical Review Letters",citations:416,abstract:"We report a quantum simulation of the deuteron binding energy on quantum processors accessed via cloud servers. We use a Hamiltonian from pionless effective field theory at leading order. We design a low-depth version of the unitary coupled-cluster ansatz, use the variational quantum eigensolver algorithm, and compute the binding energy to within a few percent. Our work is the first step towards scalable nuclear structure computations on a quantum processor via the cloud, and it sheds light on how to map scientific computing applications onto nascent quantum devices.",keywords:["Cloud computing","Nucleus","Atomic nucleus","Quantum computer","Quantum","Quantum mechanics"],concepts:["Cloud computing","Nucleus","Atomic nucleus","Quantum computer","Quantum","Quantum mechanics"],pdf_url:"https://arxiv.org/pdf/1801.03897",is_oa:!0,n_refs:43,n_refs_in_core:6,degree:41,community:1,deg_w:481,betweenness:.0027,pagerank:.00383,eigenvector:.0465},{id:58,oaid:"W2990112601",doi:"10.1103/prxquantum.2.020310",title:"Qubit-ADAPT-VQE: An Adaptive Algorithm for Constructing Hardware-Efficient Ansätze on a Quantum Processor",authors:[{name:"Ho Lun Tang",institutions:["Virginia Tech"]},{name:"V.O. Shkolnikov",institutions:["Virginia Tech"]},{name:"George S. Barron",institutions:["Virginia Tech"]},{name:"Harper R. Grimsley",institutions:["Virginia Tech"]},{name:"Nicholas J. Mayhall",institutions:["Virginia Tech"]},{name:"Edwin Barnes",institutions:["Virginia Tech"]},{name:"Sophia E. Economou",institutions:["Virginia Tech"]}],authorString:"Ho Lun Tang; V.O. Shkolnikov; George S. Barron; Harper R. Grimsley; Nicholas J. Mayhall; Edwin Barnes; Sophia E. Economou",institutions:["Virginia Tech"],countries:["US"],year:2021,journal:"PRX Quantum",citations:390,abstract:"The resources required to run a high-accuracy variational quantum eigensolver algorithm with a dynamically created ansatz are quantified and reduced significantly, easing the quantum simulation of many-body systems.",keywords:["Ansatz","Quantum computer","Quantum","Quantum algorithm","Quantum phase estimation algorithm","Adaptive algorithm","Convergence"],concepts:["Ansatz","Quantum computer","Quantum","Quantum algorithm","Algorithm","Quantum phase estimation algorithm","Parallel computing"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.020310",is_oa:!0,n_refs:40,n_refs_in_core:15,degree:40,community:1,deg_w:570.5,betweenness:.0024,pagerank:.00446,eigenvector:.0472},{id:59,oaid:"W2803086154",doi:"10.1103/physreva.98.022322",title:"Quantum algorithms for electronic structure calculations: Particle-hole Hamiltonian and optimized wave-function expansions",authors:[{name:"Panagiotis Kl. Barkoutsos",institutions:["ETH Zurich","IBM Research - Zurich"]},{name:"Jérôme F. Gonthier",institutions:["University of California, Berkeley"]},{name:"Igor O. Sokolov",institutions:["ETH Zurich","IBM Research - Zurich"]},{name:"Nikolaj Moll",institutions:["IBM Research - Zurich"]},{name:"Gian Salis",institutions:["IBM Research - Zurich"]},{name:"Andreas Fuhrer",institutions:["IBM Research - Zurich"]},{name:"Marc Ganzhorn",institutions:["IBM Research - Zurich"]},{name:"Daniel J. Egger",institutions:["IBM Research - Zurich"]},{name:"Matthias Troyer",institutions:["Microsoft (United States)","ETH Zurich"]},{name:"Antonio Mezzacapo",institutions:[]},{name:"Stefan Filipp",institutions:["IBM Research - Zurich"]},{name:"Ivano Tavernelli",institutions:["IBM Research - Zurich"]}],authorString:"Panagiotis Kl. Barkoutsos; Jérôme F. Gonthier; Igor O. Sokolov; Nikolaj Moll; Gian Salis; Andreas Fuhrer; Marc Ganzhorn; Daniel J. Egger; Matthias Troyer; Antonio Mezzacapo; Stefan Filipp; Ivano Tavernelli",institutions:["ETH Zurich","IBM Research - Zurich","Microsoft (United States)","University of California, Berkeley"],countries:["CH","US"],year:2018,journal:"Physical review. A/Physical review, A",citations:383,abstract:"In this work we investigate methods to improve the efficiency and scalability of quantum algorithms for quantum chemistry applications. We propose a transformation of the electronic structure Hamiltonian in the second quantization framework into the particle-hole picture, which offers a better starting point for the expansion of the system wave function. The state of the molecular system at study is parametrized so as to constrain the sampling of the corresponding wave function within the sector of the molecular Fock space that contains the desired solution. To this end, we explore different mapping schemes to encode the molecular ground state wave function in a quantum register. Taking advantage of known post-Hartree-Fock quantum chemistry approaches and heuristic Hilbert space search quantum algorithms, we propose a new family of quantum circuits based on exchange-type gates that enable accurate calculations while keeping the gate count (i.e., the circuit depth) low. The particle-hole implementation of the unitary coupled-cluster (UCC) method within the variational quantum eigensolver approach gives rise to an efficient quantum algorithm, named q-UCC, with important advantages compared to the straightforward translation of the classical coupled-cluster counterpart. In particular, we show how a single Trotter step in the expansion of the system wave function can accurately and efficiently reproduce the ground-state energy of simple molecular systems.",keywords:["Hamiltonian","Wave function","Electronic structure","Quantum","Quantum mechanics","Algorithm"],concepts:["Hamiltonian","Wave function","Electronic structure","Quantum","Quantum mechanics","Algorithm"],pdf_url:"https://arxiv.org/pdf/1805.04340",is_oa:!0,n_refs:66,n_refs_in_core:9,degree:49,community:1,deg_w:952.5,betweenness:.0028,pagerank:.00679,eigenvector:.079},{id:60,oaid:"W2808979145",doi:"10.1103/physrevresearch.1.033063",title:"Continuous-variable quantum neural networks",authors:[{name:"Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Thomas R. Bromley",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Juan Miguel Arrazola",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Maria Schuld",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Nicolás Quesada",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Seth Lloyd",institutions:["Massachusetts Institute of Technology"]}],authorString:"Nathan Killoran; Thomas R. Bromley; Juan Miguel Arrazola; Maria Schuld; Nicolás Quesada; Seth Lloyd",institutions:["Massachusetts Institute of Technology","Xanadu Quantum Technologies (Canada)"],countries:["CA","US"],year:2019,journal:"Physical Review Research",citations:381,abstract:"Neural networks and quantum computers are both key technologies for the next generation of computing. This paper demonstrates that these two types of computation can be executed with the same physical platform, based on photonics. This provides a natural extension of classical machine learning algorithms into the quantum realm.",keywords:["Artificial neural network","Quantum computer","Quantum","Key","Extension","Computation","Quantum information","Quantum network"],concepts:["Artificial neural network","Quantum computer","Quantum","Key","Extension","Computation"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.1.033063",is_oa:!0,n_refs:87,n_refs_in_core:9,degree:30,community:0,deg_w:360.5,betweenness:.0013,pagerank:.00357,eigenvector:.0141},{id:61,oaid:"W2811032035",doi:"10.22331/q-2019-05-13-140",title:"Quantum-assisted quantum compiling",authors:[{name:"Sumeet Khatri",institutions:["Louisiana State University","Los Alamos National Laboratory"]},{name:"Ryan LaRose",institutions:["Los Alamos National Laboratory","Michigan State University"]},{name:"Alexander Poremba",institutions:["California Institute of Technology","Los Alamos National Laboratory"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Andrew Sornborger",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Sumeet Khatri; Ryan LaRose; Alexander Poremba; Łukasz Cincio; Andrew Sornborger; Patrick J. Coles",institutions:["California Institute of Technology","Los Alamos National Laboratory","Louisiana State University","Michigan State University"],countries:["US"],year:2019,journal:"Quantum",citations:378,abstract:`Compiling quantum algorithms for near-term quantum computers (accounting for connectivity and native gate alphabets) is a major challenge that has received significant attention both by industry and academia. Avoiding the exponential overhead of classical simulation of quantum dynamics will allow compilation of larger algorithms, and a strategy for this is to evaluate an algorithm's cost on a quantum computer. To this end, we propose a variational hybrid quantum-classical algorithm called quantum-assisted quantum compiling (QAQC). In QAQC, we use the overlap between a target unitary<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>U</mml:mi></mml:math>and a trainable unitary<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>V</mml:mi></mml:math>as the cost function to be evaluated on the quantum computer. More precisely, to ensure that QAQC scales well with problem size, our cost involves not only the global overlap<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi mathvariant="normal">T</mml:mi><mml:mi mathvariant="normal">r</mml:mi></mml:mrow><mml:mo stretchy="false">(</mml:mo><mml:msup><mml:mi>V</mml:mi><mml:mo>†</mml:mo></mml:msup><mml:mi>U</mml:mi><mml:mo stretchy="false">)</mml:mo></mml:math>but also the local overlaps with respect to individual qubits. We introduce novel short-depth quantum circuits to quantify the terms in our cost function, and we prove that our cost cannot be efficiently approximated with a classical algorithm under reasonable complexity assumptions. We present both gradient-free and gradient-based approaches to minimizing this cost. As a demonstration of QAQC, we compile various one-qubit gates on IBM's and Rigetti's quantum computers into their respective native gate alphabets. Furthermore, we successfully simulate QAQC up to a problem size of 9 qubits, and these simulations highlight both the scalability of our cost function as well as the noise resilience of QAQC. Future applications of QAQC include algorithm depth compression, black-box compiling, noise mitigation, and benchmarking.`,keywords:["Algorithm","Quantum computer","Quantum algorithm","Function","Quantum","Quantum mechanics"],concepts:["Algorithm","Quantum computer","Quantum algorithm","Function","Quantum"],pdf_url:"https://quantum-journal.org/papers/q-2019-05-13-140/pdf/",is_oa:!0,n_refs:80,n_refs_in_core:6,degree:47,community:0,deg_w:721,betweenness:.0033,pagerank:.0056,eigenvector:.0576},{id:62,oaid:"W2921920881",doi:"10.22331/q-2019-12-09-214",title:"An initialization strategy for addressing barren plateaus in parametrized quantum circuits",authors:[{name:"Edward Grant",institutions:["Rahko (United Kingdom)","University College London"]},{name:"Leonard Wossnig",institutions:["Rahko (United Kingdom)","University College London"]},{name:"Mateusz Ostaszewski",institutions:["Institute of Theoretical and Applied Informatics","Polish Academy of Sciences"]},{name:"Marcello Benedetti",institutions:["Cambridge Quantum Computing (United Kingdom)","University College London"]}],authorString:"Edward Grant; Leonard Wossnig; Mateusz Ostaszewski; Marcello Benedetti",institutions:["Cambridge Quantum Computing (United Kingdom)","Institute of Theoretical and Applied Informatics","Polish Academy of Sciences","Rahko (United Kingdom)","University College London"],countries:["GB","PL"],year:2019,journal:"Quantum",citations:374,abstract:"Parametrized quantum circuits initialized with random initial parameter values are characterized by barren plateaus where the gradient becomes exponentially small in the number of qubits. In this technical note we theoretically motivate and empirically validate an initialization strategy which can resolve the barren plateau problem for practical applications. The technique involves randomly selecting some of the initial parameter values, then choosing the remaining values so that the circuit is a sequence of shallow blocks that each evaluates to the identity. This initialization limits the effective depth of the circuits used to calculate the first parameter update so that they cannot be stuck in a barren plateau at the start of training. In turn, this makes some of the most compact ansätze usable in practice, which was not possible before even for rather basic problems. We show empirically that variational quantum eigensolvers and quantum neural networks initialized using this strategy can be trained using a gradient based method.",keywords:["Initialization","USable","Electronic circuit","Quantum","Plateau","Sequence","Quantum circuit","Exponential growth"],concepts:["Initialization","USable","Electronic circuit","Quantum","Plateau","Sequence"],pdf_url:"https://quantum-journal.org/papers/q-2019-12-09-214/pdf/",is_oa:!0,n_refs:6,n_refs_in_core:3,degree:45,community:0,deg_w:390.5,betweenness:.0032,pagerank:.00344,eigenvector:.0327},{id:63,oaid:"W2784994528",doi:"10.1038/s41534-019-0157-8",title:"A generative modeling approach for benchmarking and training shallow quantum circuits",authors:[{name:"Marcello Benedetti",institutions:["Cambridge Quantum Computing (United Kingdom)","University College London"]},{name:"Delfina Garcia-Pintos",institutions:[]},{name:"Óscar Perdomo",institutions:["Central Connecticut State University","Rigetti Computing (United States)"]},{name:"Vicente Leyton‐Ortega",institutions:["Rigetti Computing (United States)"]},{name:"Yunseong Nam",institutions:["IonQ (United States)"]},{name:"Alejandro Perdomo‐Ortiz",institutions:["Ames Research Center","NASA Research Park","Zapata (United States)","Rigetti Computing (United States)","University College London"]}],authorString:"Marcello Benedetti; Delfina Garcia-Pintos; Óscar Perdomo; Vicente Leyton‐Ortega; Yunseong Nam; Alejandro Perdomo‐Ortiz",institutions:["Ames Research Center","Cambridge Quantum Computing (United Kingdom)","Central Connecticut State University","IonQ (United States)","NASA Research Park","Rigetti Computing (United States)","University College London","Zapata (United States)"],countries:["GB","US"],year:2019,journal:"npj Quantum Information",citations:373,abstract:"Abstract Hybrid quantum-classical algorithms provide ways to use noisy intermediate-scale quantum computers for practical applications. Expanding the portfolio of such techniques, we propose a quantum circuit learning algorithm that can be used to assist the characterization of quantum devices and to train shallow circuits for generative tasks. The procedure leverages quantum hardware capabilities to its fullest extent by using native gates and their qubit connectivity. We demonstrate that our approach can learn an optimal preparation of the Greenberger-Horne-Zeilinger states, also known as “cat states”. We further demonstrate that our approach can efficiently prepare approximate representations of coherent thermal states, wave functions that encode Boltzmann probabilities in their amplitudes. Finally, complementing proposals to characterize the power or usefulness of near-term quantum devices, such as IBM’s quantum volume, we provide a new hardware-independent metric called the qBAS score. It is based on the performance yield in a specific sampling task on one of the canonical machine learning data sets known as Bars and Stripes. We show how entanglement is a key ingredient in encoding the patterns of this data set; an ideal benchmark for testing hardware starting at four qubits and up. We provide experimental results and evaluation of this metric to probe the trade off between several architectural circuit designs and circuit depths on an ion-trap quantum computer.",keywords:["Quantum computer","Qubit","Quantum circuit","Metric","Quantum","Quantum algorithm","Computer engineering"],concepts:["Quantum computer","Qubit","Quantum circuit","Metric","Quantum","Quantum algorithm","Computer engineering"],pdf_url:"https://www.nature.com/articles/s41534-019-0157-8.pdf",is_oa:!0,n_refs:85,n_refs_in_core:9,degree:37,community:0,deg_w:528,betweenness:.0026,pagerank:.00446,eigenvector:.0464},{id:64,oaid:"W2801305581",doi:"10.1103/physrevx.8.041015",title:"Encoding Electronic Spectra in Quantum Circuits with Linear T Complexity",authors:[{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Craig Gidney",institutions:["Google (United States)"]},{name:"Dominic W. Berry",institutions:["Macquarie University"]},{name:"Nathan Wiebe",institutions:["Microsoft (United States)"]},{name:"Jarrod R. McClean",institutions:["Google (United States)"]},{name:"Alexandru Paler",institutions:["Linz Center of Mechatronics (Austria)"]},{name:"Austin G. Fowler",institutions:["Google (United States)"]},{name:"Hartmut Neven",institutions:["Google (United States)"]}],authorString:"Ryan Babbush; Craig Gidney; Dominic W. Berry; Nathan Wiebe; Jarrod R. McClean; Alexandru Paler; Austin G. Fowler; Hartmut Neven",institutions:["Google (United States)","Linz Center of Mechatronics (Austria)","Macquarie University","Microsoft (United States)"],countries:["AT","AU","US"],year:2018,journal:"Physical Review X",citations:365,abstract:'We construct quantum circuits that exactly encode the spectra of correlated electron models up to errors from rotation synthesis. By invoking these circuits as oracles within the recently introduced "qubitization" framework, one can use quantum phase estimation to sample states in the Hamiltonian eigenbasis with optimal query complexity O=, where is an absolute sum of Hamiltonian coefficients and is the target precision. For both the Hubbard model and electronic structure Hamiltonian in a second quantized basis diagonalizing the Coulomb operator, our circuits have T-gate complexity O(N log1=), where N is the number of orbitals in the basis. This scenario enables sampling in the eigenbasis of electronic structure Hamiltonians with T complexity O(N 3 = N 2 log1==). Compared to prior approaches, our algorithms are asymptotically more efficient in gate complexity and require fewer T gates near the classically intractable regime. Compiling to surface code fault-tolerant gates and assuming per-gate error rates of one part in a thousand reveals that one can error correct phase estimation on interesting instances of these problems beyond the current capabilities of classical methods using only about a million superconducting qubits in a matter of hours.',keywords:["Hamiltonian","Qubit","Quantum computer","Quantum","Quantum mechanics","Algorithm"],concepts:["Hamiltonian","Qubit","Quantum computer","Quantum","Quantum mechanics","Algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.8.041015",is_oa:!0,n_refs:136,n_refs_in_core:12,degree:37,community:1,deg_w:864,betweenness:.0015,pagerank:.00629,eigenvector:.0723},{id:65,oaid:"W3014386333",doi:"10.1038/s41534-020-0259-3",title:"Ground-state energy estimation of the water molecule on a trapped-ion quantum computer",authors:[{name:"Yunseong Nam",institutions:["IonQ (United States)"]},{name:"Jwo-Sy Chen",institutions:["IonQ (United States)"]},{name:"Neal C. Pisenti",institutions:["IonQ (United States)"]},{name:"Kenneth Wright",institutions:["IonQ (United States)"]},{name:"Conor P. Delaney",institutions:["IonQ (United States)"]},{name:"Dmitri Maslov",institutions:["U.S. National Science Foundation"]},{name:"Kenneth R. Brown",institutions:["Duke University","IonQ (United States)"]},{name:"Stewart Allen",institutions:["IonQ (United States)"]},{name:"Jason Amini",institutions:["IonQ (United States)"]},{name:"Joel Apisdorf",institutions:["IonQ (United States)"]},{name:"Kristin M. Beck",institutions:["IonQ (United States)"]},{name:"Aleksey Blinov",institutions:["IonQ (United States)"]},{name:"V. Chaplin",institutions:["IonQ (United States)"]},{name:"Mika Chmielewski",institutions:["IonQ (United States)","Joint Quantum Institute","University of Maryland, College Park"]},{name:"Coleman Collins",institutions:["IonQ (United States)"]},{name:"Shantanu Debnath",institutions:["IonQ (United States)"]},{name:"Kai Hudek",institutions:["IonQ (United States)"]},{name:"Andrew M. Ducore",institutions:["IonQ (United States)"]},{name:"Matthew Keesan",institutions:["IonQ (United States)"]},{name:"Sarah M. Kreikemeier",institutions:["IonQ (United States)"]},{name:"Jonathan Mizrahi",institutions:["IonQ (United States)"]},{name:"Professor Allan Solomon",institutions:["IonQ (United States)"]},{name:"M. Williams",institutions:["IonQ (United States)"]},{name:"J. David Wong-Campos",institutions:["IonQ (United States)"]},{name:"D. L. Moehring",institutions:["IonQ (United States)"]},{name:"C. Monroe",institutions:["IonQ (United States)","Joint Quantum Institute","University of Maryland, College Park"]},{name:"Jungsang Kim",institutions:["Duke University","IonQ (United States)"]}],authorString:"Yunseong Nam; Jwo-Sy Chen; Neal C. Pisenti; Kenneth Wright; Conor P. Delaney; Dmitri Maslov; Kenneth R. Brown; Stewart Allen; Jason Amini; Joel Apisdorf; Kristin M. Beck; Aleksey Blinov et al.",institutions:["Duke University","IonQ (United States)","Joint Quantum Institute","U.S. National Science Foundation","University of Maryland, College Park"],countries:["US"],year:2020,journal:"npj Quantum Information",citations:352,abstract:"Abstract Quantum computing leverages the quantum resources of superposition and entanglement to efficiently solve computational problems considered intractable for classical computers. Examples include calculating molecular and nuclear structure, simulating strongly interacting electron systems, and modeling aspects of material function. While substantial theoretical advances have been made in mapping these problems to quantum algorithms, there remains a large gap between the resource requirements for solving such problems and the capabilities of currently available quantum hardware. Bridging this gap will require a co-design approach, where the expression of algorithms is developed in conjunction with the hardware itself to optimize execution. Here we describe an extensible co-design framework for solving chemistry problems on a trapped-ion quantum computer and apply it to estimating the ground-state energy of the water molecule using the variational quantum eigensolver (VQE) method. The controllability of the trapped-ion quantum computer enables robust energy estimates using the prepared VQE ansatz states. The systematic and statistical errors are comparable to the chemical accuracy, which is the target threshold necessary for predicting the rates of chemical reaction dynamics, without resorting to any error mitigation techniques based on Richardson extrapolation.",keywords:["Quantum computer","Quantum algorithm","Computational science","Ansatz","Quantum","Quantum entanglement","Statistical physics"],concepts:["Quantum computer","Quantum algorithm","Computational science","Ansatz","Quantum","Quantum entanglement","Statistical physics"],pdf_url:"https://www.nature.com/articles/s41534-020-0259-3.pdf",is_oa:!0,n_refs:52,n_refs_in_core:5,degree:36,community:1,deg_w:428,betweenness:.0024,pagerank:.00356,eigenvector:.0409},{id:66,oaid:"W1870671750",doi:"10.1038/ncomms8654",title:"Digital quantum simulation of fermionic models with a superconducting circuit",authors:[{name:"R. Barends",institutions:["Google (United States)"]},{name:"Lucas Lamata",institutions:["University of the Basque Country"]},{name:"J. Kelly",institutions:["Google (United States)","University of California, Santa Barbara"]},{name:"Laura García-Álvarez",institutions:["University of the Basque Country"]},{name:"Austin G. Fowler",institutions:["Google (United States)"]},{name:"A. Megrant",institutions:["University of California, Santa Barbara"]},{name:"E. Jeffrey",institutions:["Google (United States)"]},{name:"T. White",institutions:["University of California, Santa Barbara"]},{name:"D. Sank",institutions:["Google (United States)"]},{name:"J. Mutus",institutions:["Google (United States)"]},{name:"B. Campbell",institutions:["University of California, Santa Barbara"]},{name:"Yu Chen",institutions:["Google (United States)"]},{name:"Z. Chen",institutions:["University of California, Santa Barbara"]},{name:"B. Chiaro",institutions:["University of California, Santa Barbara"]},{name:"A. Dunsworth",institutions:["University of California, Santa Barbara"]},{name:"I.-C. Hoi",institutions:["University of California, Santa Barbara"]},{name:"C. Neill",institutions:["University of California, Santa Barbara"]},{name:"P. O’Malley",institutions:["University of California, Santa Barbara"]},{name:"Chris Quintana",institutions:["University of California, Santa Barbara"]},{name:"P. Roushan",institutions:["Google (United States)"]},{name:"A. Vainsencher",institutions:["University of California, Santa Barbara"]},{name:"J. Wenner",institutions:["University of California, Santa Barbara"]},{name:"E. Solano",institutions:["Ikerbasque","University of the Basque Country"]},{name:"John M. Martinis",institutions:["Google (United States)","University of California, Santa Barbara"]}],authorString:"R. Barends; Lucas Lamata; J. Kelly; Laura García-Álvarez; Austin G. Fowler; A. Megrant; E. Jeffrey; T. White; D. Sank; J. Mutus; B. Campbell; Yu Chen et al.",institutions:["Google (United States)","Ikerbasque","University of California, Santa Barbara","University of the Basque Country"],countries:["ES","US"],year:2015,journal:"Nature Communications",citations:348,abstract:"One of the key applications of quantum information is simulating nature. Fermions are ubiquitous in nature, appearing in condensed matter systems, chemistry and high energy physics. However, universally simulating their interactions is arguably one of the largest challenges, because of the difficulties arising from anticommutativity. Here we use digital methods to construct the required arbitrary interactions, and perform quantum simulation of up to four fermionic modes with a superconducting quantum circuit. We employ in excess of 300 quantum logic gates, and reach fidelities that are consistent with a simple model of uncorrelated errors. The presented approach is in principle scalable to a larger number of modes, and arbitrary spatial dimensions.",keywords:["Quantum simulator","Quantum","Scalability","Quantum computer","Uncorrelated","Superconductivity","Fermion"],concepts:["Quantum simulator","Quantum","Scalability","Quantum computer","Uncorrelated","Superconductivity","Fermion"],pdf_url:"https://www.nature.com/articles/ncomms8654.pdf",is_oa:!0,n_refs:35,n_refs_in_core:0,degree:25,community:3,deg_w:215,betweenness:.002,pagerank:.00222,eigenvector:.0155},{id:67,oaid:"W2234450295",doi:"10.1103/physrevx.8.021050",title:"Quantum Boltzmann Machine",authors:[{name:"Mohammad H. Amin",institutions:["D-Wave Systems (Canada)","Simon Fraser University"]},{name:"Evgeny Andriyash",institutions:["D-Wave Systems (Canada)"]},{name:"Jason Rolfe",institutions:["D-Wave Systems (Canada)"]},{name:"Bohdan Kulchytskyy",institutions:["University of Waterloo","Perimeter Institute"]},{name:"Roger Melko",institutions:["University of Waterloo","Perimeter Institute"]}],authorString:"Mohammad H. Amin; Evgeny Andriyash; Jason Rolfe; Bohdan Kulchytskyy; Roger Melko",institutions:["D-Wave Systems (Canada)","Perimeter Institute","Simon Fraser University","University of Waterloo"],countries:["CA"],year:2018,journal:"Physical Review X",citations:348,abstract:"A new machine-learning algorithm demonstrates the performance of a quantum Boltzmann machine, a quantum extension of a popular classical neural network, paving the way for quantum approaches to machine learning.",keywords:["Quantum","Boltzmann machine","Quantum algorithm","Restricted Boltzmann machine","Boltzmann constant","Open quantum system","Quantum computer","Quantum network"],concepts:["Quantum","Boltzmann machine","Statistical physics","Quantum algorithm","Restricted Boltzmann machine","Boltzmann constant"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.8.021050",is_oa:!0,n_refs:24,n_refs_in_core:1,degree:22,community:0,deg_w:129.5,betweenness:8e-4,pagerank:.0018,eigenvector:.0056},{id:68,oaid:"W2963198496",doi:"10.1103/physreva.101.010301",title:"Variational quantum algorithms for nonlinear problems",authors:[{name:"Michael Lubasch",institutions:["University of Oxford"]},{name:"Jaewoo Joo",institutions:["University of Oxford"]},{name:"Pierre Moinier",institutions:["BAE Systems (United Kingdom)"]},{name:"Martin Kiffner",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Oxford","Université Bourgogne Franche-Comté"]},{name:"Dieter Jaksch",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Oxford","Université Bourgogne Franche-Comté"]}],authorString:"Michael Lubasch; Jaewoo Joo; Pierre Moinier; Martin Kiffner; Dieter Jaksch",institutions:["BAE Systems (United Kingdom)","Centre for Quantum Technologies","National University of Singapore","University of Oxford","Université Bourgogne Franche-Comté"],countries:["FR","GB","SG"],year:2020,journal:"Physical review. A/Physical review, A",citations:345,abstract:'We show that nonlinear problems including nonlinear partial differential equations can be efficiently solved by variational quantum computing. We achieve this by utilizing multiple copies of variational quantum states to treat nonlinearities efficiently and by introducing tensor networks as a programming paradigm. The key concepts of the algorithm are demonstrated for the nonlinear Schr\\"odinger equation as a canonical example. We numerically show that the variational quantum ansatz can be exponentially more efficient than matrix product states and present experimental proof-of-principle results obtained on an IBM Q device.',keywords:["Nonlinear system","Quantum","Algorithm","Quantum algorithm","Quantum mechanics"],concepts:["Nonlinear system","Quantum","Algorithm","Quantum algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.101.010301",is_oa:!0,n_refs:86,n_refs_in_core:13,degree:36,community:2,deg_w:520.5,betweenness:.0015,pagerank:.00411,eigenvector:.0541},{id:69,oaid:"W4307283983",doi:"10.1063/5.0082975",title:"The future of quantum computing with superconducting qubits",authors:[{name:"Sergey Bravyi",institutions:["IBM (United States)"]},{name:"Oliver Dial",institutions:["IBM (United States)"]},{name:"Jay Gambetta",institutions:["IBM (United States)"]},{name:"Darı́o Gil",institutions:["IBM (United States)"]},{name:"Zaira Nazario",institutions:["IBM (United States)"]}],authorString:"Sergey Bravyi; Oliver Dial; Jay Gambetta; Darı́o Gil; Zaira Nazario",institutions:["IBM (United States)"],countries:["US"],year:2022,journal:"Journal of Applied Physics",citations:337,abstract:"For the first time in history, we are seeing a branching point in computing paradigms with the emergence of quantum processing units (QPUs). Extracting the full potential of computation and realizing quantum algorithms with a super-polynomial speedup will most likely require major advances in quantum error correction technology. Meanwhile, achieving a computational advantage in the near term may be possible by combining multiple QPUs through circuit knitting techniques, improving the quality of solutions through error suppression and mitigation, and focusing on heuristic versions of quantum algorithms with asymptotic speedups. For this to happen, the performance of quantum computing hardware needs to improve and software needs to seamlessly integrate quantum and classical processors together to form a new architecture that we are calling quantum-centric supercomputing. In the long term, we see hardware that exploits qubit connectivity in higher than 2D topologies to realize more efficient quantum error correcting codes, modular architectures for scaling QPUs and parallelizing workloads, and software that evolves to make the intricacies of the technology invisible to the users and realize the goal of ubiquitous, frictionless quantum computing.",keywords:["Superconducting quantum computing","Qubit","Superconductivity","Quantum computer","Quantum","Quantum mechanics"],concepts:["Superconducting quantum computing","Qubit","Superconductivity","Quantum computer","Quantum","Quantum mechanics"],pdf_url:"https://aip.scitation.org/doi/pdf/10.1063/5.0082975",is_oa:!0,n_refs:159,n_refs_in_core:13,degree:27,community:2,deg_w:267,betweenness:.0022,pagerank:.00267,eigenvector:.0148},{id:70,oaid:"W3004252283",doi:"10.1007/s42484-020-00036-4",title:"Layerwise learning for quantum neural networks",authors:[{name:"Andrea Skolik",institutions:["Leiden University","University of Applied Sciences Leiden","Ludwig-Maximilians-Universität München"]},{name:"Jarrod R. McClean",institutions:["Google (United States)"]},{name:"Masoud Mohseni",institutions:["Google (United States)"]},{name:"Patrick van der Smagt",institutions:["Eötvös Loránd University","Volkswagen Group (Germany)"]},{name:"Martin Leib",institutions:[]}],authorString:"Andrea Skolik; Jarrod R. McClean; Masoud Mohseni; Patrick van der Smagt; Martin Leib",institutions:["Eötvös Loránd University","Google (United States)","Leiden University","Ludwig-Maximilians-Universität München","University of Applied Sciences Leiden","Volkswagen Group (Germany)"],countries:["DE","HU","NL","US"],year:2021,journal:"Quantum Machine Intelligence",citations:334,abstract:"Abstract With the increased focus on quantum circuit learning for near-term applications on quantum devices, in conjunction with unique challenges presented by cost function landscapes of parametrized quantum circuits, strategies for effective training are becoming increasingly important. In order to ameliorate some of these challenges, we investigate a layerwise learning strategy for parametrized quantum circuits. The circuit depth is incrementally grown during optimization, and only subsets of parameters are updated in each training step. We show that when considering sampling noise, this strategy can help avoid the problem of barren plateaus of the error surface due to the low depth of circuits, low number of parameters trained in one step, and larger magnitude of gradients compared to training the full circuit. These properties make our algorithm preferable for execution on noisy intermediate-scale quantum devices. We demonstrate our approach on an image-classification task on handwritten digits, and show that layerwise learning attains an 8% lower generalization error on average in comparison to standard learning schemes for training quantum circuits of the same size. Additionally, the percentage of runs that reach lower test errors is up to 40% larger compared to training the full circuit, which is susceptible to creeping onto a plateau during training.",keywords:["Quantum","Electronic circuit","Generalization","Artificial neural network","Function","Training","Deep learning"],concepts:["Quantum","Electronic circuit","Generalization","Artificial neural network","Function","Training","Deep learning"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s42484-020-00036-4.pdf",is_oa:!0,n_refs:80,n_refs_in_core:24,degree:52,community:0,deg_w:870,betweenness:.0051,pagerank:.0065,eigenvector:.076},{id:71,oaid:"W2796615720",doi:"10.22331/q-2019-03-11-129",title:"Strawberry Fields: A Software Platform for Photonic Quantum Computing",authors:[{name:"Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Josh Izaac",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Nicolás Quesada",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Ville Bergholm",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Matthew Amy",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Christian Weedbrook",institutions:["Xanadu Quantum Technologies (Canada)"]}],authorString:"Nathan Killoran; Josh Izaac; Nicolás Quesada; Ville Bergholm; Matthew Amy; Christian Weedbrook",institutions:["Xanadu Quantum Technologies (Canada)"],countries:["CA"],year:2019,journal:"Quantum",citations:316,abstract:"We introduce Strawberry Fields, an open-source quantum programming architecture for light-based quantum computers, and detail its key features. Built in Python, Strawberry Fields is a full-stack library for design, simulation, optimization, and quantum machine learning of continuous-variable circuits. The platform consists of three main components: (i) an API for quantum programming based on an easy-to-use language named Blackbird; (ii) a suite of three virtual quantum computer backends, built in NumPy and TensorFlow, each targeting specialized uses; and (iii) an engine which can compile Blackbird programs on various backends, including the three built-in simulators, and - in the near future - photonic quantum information processors. The library also contains examples of several paradigmatic algorithms, including teleportation, (Gaussian) boson sampling, instantaneous quantum polynomial, Hamiltonian simulation, and variational quantum circuit optimization.",keywords:["Quantum computer","Quantum","Compiler","Quantum machine learning","Quantum circuit","Computational science","Quantum simulator"],concepts:["Quantum computer","Quantum","Compiler","Quantum machine learning","Quantum circuit","Computational science","Quantum simulator"],pdf_url:"https://quantum-journal.org/papers/q-2019-03-11-129/pdf/",is_oa:!0,n_refs:121,n_refs_in_core:9,degree:28,community:0,deg_w:366,betweenness:.0017,pagerank:.00331,eigenvector:.0319},{id:72,oaid:"W4367841521",doi:"10.1103/prxquantum.4.027001",title:"Quantum Simulation for High-Energy Physics",authors:[{name:"C. Bauer",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Zohreh Davoudi",institutions:["Joint Quantum Institute","University of Maryland, College Park"]},{name:"A. Baha Balantekin",institutions:["University of Wisconsin–Madison"]},{name:"Tanmoy Bhattacharya",institutions:["Los Alamos National Laboratory"]},{name:"Marcela Carena",institutions:["Fermi National Accelerator Laboratory","University of Chicago"]},{name:"Wibe A. de Jong",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Patrick Draper",institutions:["University of Illinois Urbana-Champaign"]},{name:"A. X. El-Khadra",institutions:["University of Illinois Urbana-Champaign"]},{name:"Nate Gemelke",institutions:["QuEra Computing (United States)"]},{name:"Masanori Hanada",institutions:["University of Surrey"]},{name:"Dmitri E. Kharzeev",institutions:["Brookhaven National Laboratory","Stony Brook University"]},{name:"Henry Lamm",institutions:["Fermi National Accelerator Laboratory"]},{name:"Yingying Li",institutions:["University of Science and Technology of China","Peng Huanwu Center for Fundamental Theory"]},{name:"Junyu Liu",institutions:["University of Chicago"]},{name:"Mikhail D. Lukin",institutions:["Harvard University"]},{name:"Yannick Meurice",institutions:["University of Iowa"]},{name:"C. Monroe",institutions:["Duke University","IonQ (United States)"]},{name:"Benjamin Nachman",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Guido Pagano",institutions:["Rice University"]},{name:"John Preskill",institutions:["California Institute of Technology"]},{name:"Enrico Rinaldi",institutions:["University of Michigan","RIKEN"]},{name:"Alessandro Roggero",institutions:["University of Trento","Istituto Nazionale di Fisica Nucleare, Trento Institute for Fundamental Physics And Applications"]},{name:"David Santiago",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Martin J. Savage",institutions:["University of Washington"]},{name:"Irfan Siddiqi",institutions:["Lawrence Berkeley National Laboratory"]},{name:"George Siopsis",institutions:["University of Tennessee at Knoxville"]},{name:"David Van Zanten",institutions:["Fermi National Accelerator Laboratory"]},{name:"Nathan Wiebe",institutions:["Pacific Northwest National Laboratory","University of Toronto"]},{name:"Yukari Yamauchi",institutions:["Joint Quantum Institute","University of Maryland, College Park"]},{name:"Kübra Yeter‐Aydeniz",institutions:["Physical Sciences (United States)","Mitre (United States)"]},{name:"Silvia Zorzetti",institutions:["Fermi National Accelerator Laboratory","University of Chicago"]}],authorString:"C. Bauer; Zohreh Davoudi; A. Baha Balantekin; Tanmoy Bhattacharya; Marcela Carena; Wibe A. de Jong; Patrick Draper; A. X. El-Khadra; Nate Gemelke; Masanori Hanada; Dmitri E. Kharzeev; Henry Lamm et al.",institutions:["Brookhaven National Laboratory","California Institute of Technology","Duke University","Fermi National Accelerator Laboratory","Harvard University","IonQ (United States)","Istituto Nazionale di Fisica Nucleare, Trento Institute for Fundamental Physics And Applications","Joint Quantum Institute","Lawrence Berkeley National Laboratory","Los Alamos National Laboratory","Mitre (United States)","Pacific Northwest National Laboratory","Peng Huanwu Center for Fundamental Theory","Physical Sciences (United States)","QuEra Computing (United States)","RIKEN","Rice University","Stony Brook University","University of Chicago","University of Illinois Urbana-Champaign","University of Iowa","University of Maryland, College Park","University of Michigan","University of Science and Technology of China","University of Surrey","University of Tennessee at Knoxville","University of Toronto","University of Trento","University of Washington","University of Wisconsin–Madison"],countries:["CA","CN","GB","IT","JP","US"],year:2023,journal:"PRX Quantum",citations:314,abstract:"It is for the first time that quantum simulation for high-energy physics (HEP) is studied in the U.S. decadal particle-physics community planning, and in fact until recently, this was not considered a mainstream topic in the community. This fact speaks of a remarkable rate of growth of this subfield over the past few years, stimulated by the impressive advancements in quantum information sciences (QIS) and associated technologies over the past decade, and the significant investment in this area by the government and private sectors in the U.S. and other countries. High-energy physicists have quickly identified problems of importance to our understanding of nature at the most fundamental level, from tiniest distances to cosmological extents, that are intractable with classical computers but may benefit from quantum advantage. They have initiated, and continue to carry out, a vigorous program in theory, algorithm, and hardware co-design for simulations of relevance to the HEP mission. This Roadmap is an attempt to bring this exciting and yet challenging area of research to the spotlight, and to elaborate on what the promises, requirements, challenges, and potential solutions are over the next decade and beyond.",keywords:["Mainstream","Government","License","Citation","Relevance","Outreach"],concepts:["Mainstream","Government","License","Citation","Relevance","Outreach"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.4.027001",is_oa:!0,n_refs:501,n_refs_in_core:23,degree:39,community:3,deg_w:1019,betweenness:.0031,pagerank:.00744,eigenvector:.1122},{id:73,oaid:"W2797105324",doi:"10.1038/s41534-018-0116-9",title:"Hierarchical quantum classifiers",authors:[{name:"Edward Grant",institutions:["Rahko (United Kingdom)","University College London"]},{name:"Marcello Benedetti",institutions:["Cambridge Quantum Computing (United Kingdom)","University College London"]},{name:"Shuxiang Cao",institutions:["University of Oxford","Zhejiang University"]},{name:"Andrew Hallam",institutions:["London Centre for Nanotechnology","University College London"]},{name:"Joshua Lockhart",institutions:["University College London"]},{name:"Vid Stojevic",institutions:[]},{name:"Andrew G. Green",institutions:["London Centre for Nanotechnology"]},{name:"Simone Severini",institutions:["University College London"]}],authorString:"Edward Grant; Marcello Benedetti; Shuxiang Cao; Andrew Hallam; Joshua Lockhart; Vid Stojevic; Andrew G. Green; Simone Severini",institutions:["Cambridge Quantum Computing (United Kingdom)","London Centre for Nanotechnology","Rahko (United Kingdom)","University College London","University of Oxford","Zhejiang University"],countries:["CN","GB"],year:2018,journal:"npj Quantum Information",citations:307,abstract:"Abstract Quantum circuits with hierarchical structure have been used to perform binary classification of classical data encoded in a quantum state. We demonstrate that more expressive circuits in the same family achieve better accuracy and can be used to classify highly entangled quantum states, for which there is no known efficient classical method. We compare performance for several different parameterizations on two classical machine learning datasets, Iris and MNIST, and on a synthetic dataset of quantum states. Finally, we demonstrate that performance is robust to noise and deploy an Iris dataset classifier on the ibmqx4 quantum computer.",keywords:["Quantum","Binary number","Classifier","Quantum computer","Quantum circuit","Electronic circuit","Noise","Quantum algorithm"],concepts:["Quantum","Binary number","Classifier","Quantum computer","Quantum circuit","Algorithm"],pdf_url:"https://www.nature.com/articles/s41534-018-0116-9.pdf",is_oa:!0,n_refs:26,n_refs_in_core:5,degree:22,community:0,deg_w:175.5,betweenness:7e-4,pagerank:.0022,eigenvector:.0055},{id:74,oaid:"W2898401615",doi:"10.1103/physrevresearch.2.033125",title:"Expressive power of parametrized quantum circuits",authors:[{name:"Yuxuan Du",institutions:["The University of Sydney"]},{name:"Min-Hsiu Hsieh",institutions:["University of Technology Sydney","Centre for Quantum Computation and Communication Technology"]},{name:"Tongliang Liu",institutions:["The University of Sydney"]},{name:"Dacheng Tao",institutions:["The University of Sydney"]}],authorString:"Yuxuan Du; Min-Hsiu Hsieh; Tongliang Liu; Dacheng Tao",institutions:["Centre for Quantum Computation and Communication Technology","The University of Sydney","University of Technology Sydney"],countries:["AU"],year:2020,journal:"Physical Review Research",citations:304,abstract:"The authors demonstrate that parametrized quantum circuits possess a better expressive power than classical neural networks, such as restricted and deep Boltzmann machines. Based on the advanced expressive power, the authors propose a Bayesian quantum circuit that enables parametrized quantum circuits to perform machine learning tasks",keywords:["Quantum","Electronic circuit","Boltzmann machine","Quantum circuit","Power","Quantum computer","Artificial neural network","Quantum algorithm"],concepts:["Quantum","Electronic circuit","Boltzmann machine","Quantum circuit","Power","Quantum computer","Theoretical computer science"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.2.033125",is_oa:!0,n_refs:44,n_refs_in_core:9,degree:33,community:0,deg_w:339.5,betweenness:.0019,pagerank:.0034,eigenvector:.0198},{id:75,oaid:"W2794602324",doi:"10.1088/2058-9565/aaea94",title:"Towards quantum machine learning with tensor networks",authors:[{name:"William Huggins",institutions:["University of California, Berkeley"]},{name:"Piyush Patil",institutions:["University of California, Berkeley"]},{name:"Bradley Mitchell",institutions:["University of California, Berkeley"]},{name:"K Birgitta Whaley",institutions:["University of California, Berkeley"]},{name:"E Miles Stoudenmire",institutions:["Flatiron Health (United States)","Flatiron Institute"]}],authorString:"William Huggins; Piyush Patil; Bradley Mitchell; K Birgitta Whaley; E Miles Stoudenmire",institutions:["Flatiron Health (United States)","Flatiron Institute","University of California, Berkeley"],countries:["US"],year:2018,journal:"Quantum Science and Technology",citations:304,abstract:"Abstract Machine learning is a promising application of quantum computing, but challenges remain for implementation today because near-term devices have a limited number of physical qubits and high error rates. Motivated by the usefulness of tensor networks for machine learning in the classical context, we propose quantum computing approaches to both discriminative and generative learning, with circuits based on tree and matrix product state tensor networks, that could already have benefits with such near-term devices. The result is a unified framework in which classical and quantum computing can benefit from the same theoretical and algorithmic developments, and the same model can be trained classically then transferred to the quantum setting for additional optimization. Tensor network circuits can also provide qubit-efficient schemes in which, depending on the architecture, the number of physical qubits required scales only logarithmically with, or independently of the input or output data sizes. We demonstrate our proposals with numerical experiments, training a discriminative model to perform handwriting recognition using a hybrid quantum-classical optimization procedure that could be carried out on quantum hardware today, and testing the noise resilience of the trained model.",keywords:["Tensor","Qubit","Quantum computer","Discriminative model","Tensor product","Quantum","Quantum information","Quantum state"],concepts:["Tensor","Qubit","Quantum computer","Discriminative model","Tensor product","Quantum"],pdf_url:"https://arxiv.org/pdf/1803.11537",is_oa:!0,n_refs:24,n_refs_in_core:3,degree:21,community:0,deg_w:143,betweenness:8e-4,pagerank:.00185,eigenvector:.0081},{id:76,oaid:"W2907827190",doi:"10.1103/physrevlett.122.230401",title:"Quantum Computation of Electronic Transitions Using a Variational Quantum Eigensolver",authors:[{name:"Robert M. Parrish",institutions:["SLAC National Accelerator Laboratory","Stanford University"]},{name:"Edward G. Hohenstein",institutions:["SLAC National Accelerator Laboratory","Stanford University"]},{name:"Peter L. McMahon",institutions:["Stanford University"]},{name:"Todd J. Martı́nez",institutions:["SLAC National Accelerator Laboratory","Stanford University"]}],authorString:"Robert M. Parrish; Edward G. Hohenstein; Peter L. McMahon; Todd J. Martı́nez",institutions:["SLAC National Accelerator Laboratory","Stanford University"],countries:["US"],year:2019,journal:"Physical Review Letters",citations:301,abstract:"We develop an extension of the variational quantum eigensolver (VQE) algorithm-multistate contracted VQE (MC-VQE)-that allows for the efficient computation of the transition energies between the ground state and several low-lying excited states of a molecule, as well as the oscillator strengths associated with these transitions. We numerically simulate MC-VQE by computing the absorption spectrum of an ab initio exciton model of an 18-chromophore light-harvesting complex from purple photosynthetic bacteria.",keywords:["Computation","Quantum computer","Quantum","Electronic structure","Quantum algorithm","Quantum mechanics"],concepts:["Computation","Quantum computer","Quantum","Electronic structure","Quantum algorithm","Quantum mechanics"],pdf_url:"https://arxiv.org/pdf/1901.01234",is_oa:!0,n_refs:84,n_refs_in_core:10,degree:42,community:1,deg_w:773.5,betweenness:.0013,pagerank:.00555,eigenvector:.0768},{id:77,oaid:"W2895995157",doi:"10.1103/physrevresearch.1.033062",title:"Subspace-search variational quantum eigensolver for excited states",authors:[{name:"Ken M. Nakanishi",institutions:["The University of Tokyo"]},{name:"Kosuke Mitarai",institutions:["The University of Osaka"]},{name:"Keisuke Fujii",institutions:["Japan Science and Technology Agency","The University of Osaka"]}],authorString:"Ken M. Nakanishi; Kosuke Mitarai; Keisuke Fujii",institutions:["Japan Science and Technology Agency","The University of Osaka","The University of Tokyo"],countries:["JP"],year:2019,journal:"Physical Review Research",citations:298,abstract:"The authors propose an algorithm, the subspace-search variational quantum eigensolver (SSVQE) that searches a low energy subspace by supplying orthogonal input states to the variational ansatz and relies on the unitarity of transformations to ensure the orthogonality of output states. This work extends the applicable domain of the Variational Quantum Eigensolver to excited states and their related properties.",keywords:["Ansatz","Unitarity","Excited state","Subspace topology","Orthogonality","Quantum","Domain","Work"],concepts:["Ansatz","Unitarity","Excited state","Subspace topology","Orthogonality","Quantum","Quantum mechanics"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.1.033062",is_oa:!0,n_refs:14,n_refs_in_core:8,degree:38,community:2,deg_w:318.5,betweenness:.003,pagerank:.00289,eigenvector:.0293},{id:78,oaid:"W2578080479",doi:"10.1103/physrevlett.118.150503",title:"Hybrid Quantum-Classical Approach to Quantum Optimal Control",authors:[{name:"Jun Li",institutions:["Beijing Computational Science Research Center"]},{name:"Xiaodong Yang",institutions:["University of Science and Technology of China"]},{name:"Xinhua Peng",institutions:["University of Science and Technology of China"]},{name:"Chang-Pu Sun",institutions:["Beijing Computational Science Research Center"]}],authorString:"Jun Li; Xiaodong Yang; Xinhua Peng; Chang-Pu Sun",institutions:["Beijing Computational Science Research Center","University of Science and Technology of China"],countries:["CN"],year:2017,journal:"Physical Review Letters",citations:287,abstract:"A central challenge in quantum computing is to identify more computational problems for which utilization of quantum resources can offer significant speedup. Here, we propose a hybrid quantum-classical scheme to tackle the quantum optimal control problem. We show that the most computationally demanding part of gradient-based algorithms, namely, computing the fitness function and its gradient for a control input, can be accomplished by the process of evolution and measurement on a quantum simulator. By posing queries to and receiving answers from the quantum simulator, classical computing devices update the control parameters until an optimal control solution is found. To demonstrate the quantum-classical scheme in experiment, we use a seven-qubit nuclear magnetic resonance system, on which we have succeeded in optimizing state preparation without involving classical computation of the large Hilbert space evolution.",keywords:["Quantum computer","Quantum algorithm","Speedup","Quantum phase estimation algorithm","Quantum","Qubit","Hilbert space"],concepts:["Quantum computer","Quantum algorithm","Speedup","Quantum phase estimation algorithm","Quantum","Qubit","Hilbert space"],pdf_url:"https://arxiv.org/pdf/1608.00677",is_oa:!0,n_refs:45,n_refs_in_core:5,degree:38,community:1,deg_w:274.5,betweenness:.0043,pagerank:.00272,eigenvector:.0187},{id:79,oaid:"W2074229736",doi:"10.1038/ncomms7983",title:"Detecting bit-flip errors in a logical qubit using stabilizer measurements",authors:[{name:"Diego Ristè",institutions:["QuTech","Delft University of Technology"]},{name:"Stefano Poletto",institutions:["QuTech","Delft University of Technology"]},{name:"M.-Z. Huang",institutions:["Leiden University","Huygens Institute for History and Culture of the Netherlands","QuTech","Delft University of Technology"]},{name:"Alessandro Bruno",institutions:["QuTech","Delft University of Technology"]},{name:"Visa Vesterinen",institutions:["QuTech","VTT Technical Research Centre of Finland","Delft University of Technology"]},{name:"O.-P. Saira",institutions:["QuTech","Delft University of Technology","Aalto University"]},{name:"L. DiCarlo",institutions:["QuTech","Delft University of Technology"]}],authorString:"Diego Ristè; Stefano Poletto; M.-Z. Huang; Alessandro Bruno; Visa Vesterinen; O.-P. Saira; L. DiCarlo",institutions:["Aalto University","Delft University of Technology","Huygens Institute for History and Culture of the Netherlands","Leiden University","QuTech","VTT Technical Research Centre of Finland"],countries:["FI","NL"],year:2015,journal:"Nature Communications",citations:276,abstract:"Quantum data are susceptible to decoherence induced by the environment and to errors in the hardware processing it. A future fault-tolerant quantum computer will use quantum error correction to actively protect against both. In the smallest error correction codes, the information in one logical qubit is encoded in a two-dimensional subspace of a larger Hilbert space of multiple physical qubits. For each code, a set of non-demolition multi-qubit measurements, termed stabilizers, can discretize and signal physical qubit errors without collapsing the encoded information. Here using a five-qubit superconducting processor, we realize the two parity measurements comprising the stabilizers of the three-qubit repetition code protecting one logical qubit from physical bit-flip errors. While increased physical qubit coherence times and shorter quantum error correction blocks are required to actively safeguard the quantum information, this demonstration is a critical step towards larger codes based on multiple parity measurements.",keywords:["Qubit","Quantum error correction","Error detection and correction","Quantum decoherence","Quantum convolutional code","Quantum computer","Algorithm"],concepts:["Qubit","Quantum error correction","Error detection and correction","Quantum decoherence","Quantum convolutional code","Quantum computer","Algorithm"],pdf_url:"https://www.nature.com/articles/ncomms7983.pdf",is_oa:!0,n_refs:34,n_refs_in_core:3,degree:17,community:3,deg_w:183.5,betweenness:6e-4,pagerank:.00212,eigenvector:.0096},{id:80,oaid:"W2810721533",doi:"10.1103/physreva.99.062304",title:"Variational quantum algorithms for discovering Hamiltonian spectra",authors:[{name:"Tyson Jones",institutions:["University of Oxford"]},{name:"Suguru Endo",institutions:["University of Oxford"]},{name:"Sam McArdle",institutions:["University of Oxford"]},{name:"Xiao Yuan",institutions:["University of Oxford"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]}],authorString:"Tyson Jones; Suguru Endo; Sam McArdle; Xiao Yuan; Simon C. Benjamin",institutions:["University of Oxford"],countries:["GB"],year:2019,journal:"Physical review. A/Physical review, A",citations:275,abstract:"Calculating the energy spectrum of a quantum system is an important task, for example to analyze reaction rates in drug discovery and catalysis. There has been significant progress in developing algorithms to calculate the ground state energy of molecules on near-term quantum computers. However, calculating excited state energies has attracted comparatively less attention, and it is currently unclear what the optimal method is. We introduce a low depth, variational quantum algorithm to sequentially calculate the excited states of general Hamiltonians. Incorporating a recently proposed technique [O. Higgott, D. Wang, and S. Brierley, arXiv:1805.08138], we employ the low depth swap test to energetically penalize the ground state, and transform excited states into ground states of modified Hamiltonians. We use variational imaginary time evolution as a subroutine, which deterministically propagates toward the target eigenstate. We discuss how symmetry measurements can mitigate errors in the swap test step. We numerically test our algorithm on Hamiltonians which encode 3SAT optimization problems of up to 18 qubits, and the electronic structure of the lithium hydride molecule. As our algorithm uses only low depth circuits and variational algorithms, it is suitable for use on near-term quantum hardware.",keywords:["Excited state","Qubit","Hamiltonian","Quantum","Quantum computer","Algorithm","Quantum algorithm","Ground state"],concepts:["Excited state","Qubit","Hamiltonian","Quantum","Quantum computer","Algorithm","Quantum algorithm","Ground state"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.99.062304",is_oa:!0,n_refs:39,n_refs_in_core:10,degree:54,community:2,deg_w:875,betweenness:.0039,pagerank:.00631,eigenvector:.0788},{id:81,oaid:"W2954292307",doi:"10.1063/1.5141458",title:"Measurement optimization in the variational quantum eigensolver using a minimum clique cover",authors:[{name:"Vladyslav Verteletskyi",institutions:["University of Toronto","Taras Shevchenko National University of Kyiv","The Scarborough Hospital"]},{name:"Tzu-Ching Yen",institutions:["University of Toronto"]},{name:"Artur F. Izmaylov",institutions:["University of Toronto","The Scarborough Hospital"]}],authorString:"Vladyslav Verteletskyi; Tzu-Ching Yen; Artur F. Izmaylov",institutions:["Taras Shevchenko National University of Kyiv","The Scarborough Hospital","University of Toronto"],countries:["CA","UA"],year:2020,journal:"The Journal of Chemical Physics",citations:272,abstract:"Solving the electronic structure problem using the Variational Quantum Eigensolver (VQE) technique involves the measurement of the Hamiltonian expectation value. The current hardware can perform only projective single-qubit measurements, and thus, the Hamiltonian expectation value is obtained by measuring parts of the Hamiltonian rather than the full Hamiltonian. This restriction makes the measurement process inefficient because the number of terms in the Hamiltonian grows as O(N4) with the size of the system, N. To optimize the VQE measurement, one can try to group as many Hamiltonian terms as possible for their simultaneous measurement. Single-qubit measurements allow one to group only the terms commuting within the corresponding single-qubit subspaces or qubit-wise commuting. We found that the qubit-wise commutativity between the Hamiltonian terms can be expressed as a graph and the problem of the optimal grouping is equivalent to finding a minimum clique cover (MCC) for the Hamiltonian graph. The MCC problem is NP-hard, but there exist several polynomial heuristic algorithms to solve it approximately. Several of these heuristics were tested in this work for a set of molecular electronic Hamiltonians. On average, grouping qubit-wise commuting terms reduced the number of operators to measure three times less compared to the total number of terms in the considered Hamiltonians.",keywords:["Hamiltonian","Qubit","Hamiltonian path","Hamiltonian path problem","Quantum","Heuristics","Discrete mathematics"],concepts:["Hamiltonian","Qubit","Hamiltonian path","Hamiltonian path problem","Quantum","Heuristics","Discrete mathematics"],pdf_url:"https://arxiv.org/pdf/1907.03358",is_oa:!0,n_refs:38,n_refs_in_core:4,degree:35,community:1,deg_w:415.5,betweenness:.0021,pagerank:.00347,eigenvector:.0398},{id:82,oaid:"W2888094667",doi:"10.1103/physrevlett.122.180501",title:"Error-Mitigated Digital Quantum Simulation",authors:[{name:"Sam McArdle",institutions:["University of Oxford"]},{name:"Xiao Yuan",institutions:["University of Oxford"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]}],authorString:"Sam McArdle; Xiao Yuan; Simon C. Benjamin",institutions:["University of Oxford"],countries:["GB"],year:2019,journal:"Physical Review Letters",citations:271,abstract:"Variational algorithms may enable classically intractable simulations on near-future quantum computers. However, their potential is limited by hardware errors. It is therefore crucial to develop efficient ways to mitigate these errors. Here, we propose a stabilizerlike method which enables the detection of up to 60%-80% of depolarizing errors. Our method is suitable for near-term quantum hardware. Simulations show that our method can significantly benefit calculations subject to both stochastic and correlated noise, especially when combined with existing error mitigation techniques.",keywords:["Quantum","Noise","Error detection and correction","Quantum computer","Quantum error correction","Algorithm","Computer engineering"],concepts:["Quantum","Noise","Error detection and correction","Quantum computer","Quantum error correction","Algorithm","Computer engineering"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevLett.122.180501",is_oa:!0,n_refs:62,n_refs_in_core:18,degree:57,community:2,deg_w:1233,betweenness:.0037,pagerank:.00856,eigenvector:.1112},{id:83,oaid:"W2949480218",doi:"10.1038/s41534-019-0217-0",title:"Simulating quantum many-body dynamics on a current digital quantum computer",authors:[{name:"Adam Smith",institutions:["Imperial College London","Technical University of Munich"]},{name:"M. S. Kim",institutions:["Imperial College London"]},{name:"Frank Pollmann",institutions:["Technical University of Munich"]},{name:"Johannes Knolle",institutions:["Imperial College London"]}],authorString:"Adam Smith; M. S. Kim; Frank Pollmann; Johannes Knolle",institutions:["Imperial College London","Technical University of Munich"],countries:["DE","GB"],year:2019,journal:"npj Quantum Information",citations:270,abstract:"Abstract Universal quantum computers are potentially an ideal setting for simulating many-body quantum dynamics that is out of reach for classical digital computers. We use state-of-the-art IBM quantum computers to study paradigmatic examples of condensed matter physics—we simulate the effects of disorder and interactions on quantum particle transport, as well as correlation and entanglement spreading. Our benchmark results show that the quality of the current machines is below what is necessary for quantitatively accurate continuous-time dynamics of observables and reachable system sizes are small comparable to exact diagonalization. Despite this, we are successfully able to demonstrate clear qualitative behaviour associated with localization physics and many-body interaction effects.",keywords:["Quantum entanglement","Observable","Quantum computer","Quantum","Quantum dynamics","Current","IBM","Quantum simulator"],concepts:["Quantum entanglement","Observable","Quantum computer","Statistical physics","Quantum","Quantum dynamics","Current"],pdf_url:"https://www.nature.com/articles/s41534-019-0217-0.pdf",is_oa:!0,n_refs:75,n_refs_in_core:5,degree:27,community:3,deg_w:240,betweenness:.003,pagerank:.00247,eigenvector:.0201},{id:84,oaid:"W3119636101",doi:"10.1103/physrevlett.126.190505",title:"Information-Theoretic Bounds on Quantum Advantage in Machine Learning",authors:[{name:"Hsin-Yuan Huang",institutions:["California Institute of Technology"]},{name:"Richard Kueng",institutions:["Johannes Kepler University of Linz"]},{name:"John Preskill",institutions:["California Institute of Technology"]}],authorString:"Hsin-Yuan Huang; Richard Kueng; John Preskill",institutions:["California Institute of Technology","Johannes Kepler University of Linz"],countries:["AT","US"],year:2021,journal:"Physical Review Letters",citations:264,abstract:"We study the performance of classical and quantum machine learning (ML) models in predicting outcomes of physical experiments. The experiments depend on an input parameter x and involve execution of a (possibly unknown) quantum process E. Our figure of merit is the number of runs of E required to achieve a desired prediction performance. We consider classical ML models that perform a measurement and record the classical outcome after each run of E, and quantum ML models that can access E coherently to acquire quantum data; the classical or quantum data are then used to predict the outcomes of future experiments. We prove that for any input distribution D(x), a classical ML model can provide accurate predictions on average by accessing E a number of times comparable to the optimal quantum ML model. In contrast, for achieving an accurate prediction on all inputs, we prove that the exponential quantum advantage is possible. For example, to predict the expectations of all Pauli observables in an n-qubit system ρ, classical ML models require 2^{Ω(n)} copies of ρ, but we present a quantum ML model using only O(n) copies. Our results clarify where the quantum advantage is possible and highlight the potential for classical ML models to address challenging quantum problems in physics and chemistry.",keywords:["Pauli exclusion principle","Quantum","Observable","Quantum machine learning","Quantum algorithm","Qubit","Quantum information"],concepts:["Pauli exclusion principle","Quantum","Observable","Quantum machine learning","Quantum algorithm","Qubit","Quantum information"],pdf_url:"https://arxiv.org/pdf/2101.02464",is_oa:!0,n_refs:98,n_refs_in_core:9,degree:30,community:0,deg_w:355.5,betweenness:.003,pagerank:.00342,eigenvector:.0169},{id:85,oaid:"W2949453985",doi:"10.1103/physreva.98.062339",title:"Low-cost error mitigation by symmetry verification",authors:[{name:"Xavier Bonet-Monroig",institutions:["Leiden University"]},{name:"Ramiro Sagastizabal",institutions:["QuTech","Delft University of Technology"]},{name:"Meenakshi Singh",institutions:["QuTech","Delft University of Technology"]},{name:"Thomas E. O’Brien",institutions:["Leiden University"]}],authorString:"Xavier Bonet-Monroig; Ramiro Sagastizabal; Meenakshi Singh; Thomas E. O’Brien",institutions:["Delft University of Technology","Leiden University","QuTech"],countries:["NL"],year:2018,journal:"Physical review. A/Physical review, A",citations:260,abstract:"We investigate the performance of error mitigation via measurement of conserved symmetries on near-term devices. We present two protocols to measure conserved symmetries during the bulk of an experiment, and develop a third, zero-cost, post-processing protocol which is equivalent to a variant of the quantum subspace expansion. We develop methods for inserting global and local symmetries into quantum algorithms, and for adjusting natural symmetries of the problem to boost the mitigation of errors produced by different noise channels. We demonstrate these techniques on two- and four-qubit simulations of the hydrogen molecule (using a classical density-matrix simulator), finding up to an order of magnitude reduction of the error in obtaining the ground-state dissociation curve.",keywords:["Homogeneous space","Subspace topology","Qubit","Measure","Quantum","Offset","Algorithm"],concepts:["Homogeneous space","Subspace topology","Qubit","Measure","Quantum","Offset","Algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.98.062339",is_oa:!0,n_refs:41,n_refs_in_core:12,degree:52,community:2,deg_w:885.5,betweenness:.0038,pagerank:.00639,eigenvector:.0818},{id:86,oaid:"W2620582212",doi:"10.1103/physrevx.8.011044",title:"Low-Depth Quantum Simulation of Materials",authors:[{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Nathan Wiebe",institutions:["Microsoft (United States)"]},{name:"Jarrod McClean",institutions:["Google (United States)"]},{name:"James McClain",institutions:["California Institute of Technology"]},{name:"Hartmut Neven",institutions:["Google (United States)"]},{name:"Garnet Kin-Lic Chan",institutions:["California Institute of Technology"]}],authorString:"Ryan Babbush; Nathan Wiebe; Jarrod McClean; James McClain; Hartmut Neven; Garnet Kin-Lic Chan",institutions:["California Institute of Technology","Google (United States)","Microsoft (United States)"],countries:["US"],year:2018,journal:"Physical Review X",citations:257,abstract:"A proposed quantum algorithm for simulating the electronic structure of materials improves on the efficiency of current approaches, offering a path towards demonstrating quantum supremacy in physical applications.",keywords:["Quantum","Path","Quantum simulator","Current","Quantum computer","Quantum dot","Quantum sensor","Electronic structure"],concepts:["Quantum","Path","Quantum simulator","Statistical physics","Current","Quantum computer"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.8.011044",is_oa:!0,n_refs:110,n_refs_in_core:9,degree:47,community:1,deg_w:913.5,betweenness:.0034,pagerank:.0066,eigenvector:.0662},{id:87,oaid:"W2905003072",doi:"10.1103/physrevlett.125.010501",title:"Variational Quantum Simulation of General Processes",authors:[{name:"Suguru Endo",institutions:["NTT (Japan)","University of Oxford"]},{name:"Jinzhao Sun",institutions:["University of Oxford"]},{name:"Ying Li",institutions:["China Academy of Engineering Physics"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]},{name:"Xiao Yuan",institutions:["University of Oxford"]}],authorString:"Suguru Endo; Jinzhao Sun; Ying Li; Simon C. Benjamin; Xiao Yuan",institutions:["China Academy of Engineering Physics","NTT (Japan)","University of Oxford"],countries:["CN","GB","JP"],year:2020,journal:"Physical Review Letters",citations:256,abstract:"Variational quantum algorithms have been proposed to solve static and dynamic problems of closed many-body quantum systems. Here we investigate variational quantum simulation of three general types of tasks-generalized time evolution with a non-Hermitian Hamiltonian, linear algebra problems, and open quantum system dynamics. The algorithm for generalized time evolution provides a unified framework for variational quantum simulation. In particular, we show its application in solving linear systems of equations and matrix-vector multiplications by converting these algebraic problems into generalized time evolution. Meanwhile, assuming a tensor product structure of the matrices, we also propose another variational approach for these two tasks by combining variational real and imaginary time evolution. Finally, we introduce variational quantum simulation for open system dynamics. We variationally implement the stochastic Schrödinger equation, which consists of dissipative evolution and stochastic jump processes. We numerically test the algorithm with a 6-qubit 2D transverse field Ising model under dissipation.",keywords:["Quantum","Statistical physics","Quantum mechanics","Theoretical physics"],concepts:["Quantum","Statistical physics","Quantum mechanics","Theoretical physics"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevLett.125.010501",is_oa:!0,n_refs:97,n_refs_in_core:24,degree:53,community:2,deg_w:1082.5,betweenness:.0038,pagerank:.00767,eigenvector:.0982},{id:88,oaid:"W2964421692",doi:"10.1038/s41534-020-00341-7",title:"Efficient and noise resilient measurements for quantum chemistry on near-term quantum computers",authors:[{name:"William J. Huggins",institutions:["Google (United States)","University of California, Berkeley"]},{name:"Jarrod R. McClean",institutions:["Google (United States)"]},{name:"Nicholas C. Rubin",institutions:["Google (United States)"]},{name:"Jiang Zhang",institutions:["Google (United States)"]},{name:"Nathan Wiebe",institutions:["Google (United States)","Pacific Northwest National Laboratory","University of Washington"]},{name:"K. Birgitta Whaley",institutions:["University of California, Berkeley"]},{name:"Ryan Babbush",institutions:["Google (United States)"]}],authorString:"William J. Huggins; Jarrod R. McClean; Nicholas C. Rubin; Jiang Zhang; Nathan Wiebe; K. Birgitta Whaley; Ryan Babbush",institutions:["Google (United States)","Pacific Northwest National Laboratory","University of California, Berkeley","University of Washington"],countries:["US"],year:2021,journal:"npj Quantum Information",citations:256,abstract:"Abstract Variational algorithms are a promising paradigm for utilizing near-term quantum devices for modeling electronic states of molecular systems. However, previous bounds on the measurement time required have suggested that the application of these techniques to larger molecules might be infeasible. We present a measurement strategy based on a low-rank factorization of the two-electron integral tensor. Our approach provides a cubic reduction in term groupings over prior state-of-the-art and enables measurement times three orders of magnitude smaller than those suggested by commonly referenced bounds for the largest systems we consider. Although our technique requires execution of a linear-depth circuit prior to measurement, this is compensated for by eliminating challenges associated with sampling nonlocal Jordan–Wigner transformed operators in the presence of measurement error, while enabling a powerful form of error mitigation based on efficient postselection. We numerically characterize these benefits with noisy quantum circuit simulations for ground-state energies of strongly correlated electronic systems.",keywords:["Postselection","Term","Quantum computer","Noise","Quantum","Tensor","Factorization"],concepts:["Postselection","Term","Quantum computer","Noise","Quantum","Tensor","Factorization"],pdf_url:"https://www.nature.com/articles/s41534-020-00341-7.pdf",is_oa:!0,n_refs:70,n_refs_in_core:19,degree:45,community:1,deg_w:722.5,betweenness:.0037,pagerank:.00548,eigenvector:.0602},{id:89,oaid:"W2176839111",doi:"10.1103/physrevx.6.031045",title:"Hybrid Quantum-Classical Approach to Correlated Materials",authors:[{name:"Bela Bauer",institutions:["Microsoft (United States)"]},{name:"Dave Wecker",institutions:["Microsoft (United States)"]},{name:"Andrew J. Millis",institutions:["Columbia University"]},{name:"Matthew B. Hastings",institutions:["Microsoft (United States)"]},{name:"Matthias Troyer",institutions:["Microsoft (United States)","ETH Zurich"]}],authorString:"Bela Bauer; Dave Wecker; Andrew J. Millis; Matthew B. Hastings; Matthias Troyer",institutions:["Columbia University","ETH Zurich","Microsoft (United States)"],countries:["CH","US"],year:2016,journal:"Physical Review X",citations:248,abstract:"Quantum computers promise to shed light on many areas of research that have proven too computationally expensive even for current supercomputers. Researchers show how a hybrid quantum-classical approach can be used to simulate strongly correlated materials, such as high-temperature superconductors and transition-metal oxides.",keywords:["Quantum","Statistical physics","Quantum mechanics"],concepts:["Quantum","Statistical physics","Quantum mechanics"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.6.031045",is_oa:!0,n_refs:67,n_refs_in_core:2,degree:30,community:1,deg_w:315,betweenness:.0019,pagerank:.00285,eigenvector:.0253},{id:90,oaid:"W2996023926",doi:"10.1103/prxquantum.2.017001",title:"Quantum Computer Systems for Scientific Discovery",authors:[{name:"Yuri Alexeev",institutions:["Argonne National Laboratory"]},{name:"Dave Bacon",institutions:["Google (United States)"]},{name:"Kenneth R. Brown",institutions:["Duke University"]},{name:"Robert Calderbank",institutions:["Duke University"]},{name:"Lincoln D. Carr",institutions:["Colorado School of Mines"]},{name:"Frederic T. Chong",institutions:["University of Chicago"]},{name:"Brian DeMarco",institutions:["University of Illinois Urbana-Champaign"]},{name:"Dirk Englund",institutions:["Massachusetts Institute of Technology"]},{name:"Edward Farhi",institutions:["Google (United States)","Massachusetts Institute of Technology"]},{name:"Bill Fefferman",institutions:["University of Chicago"]},{name:"Alexey V. Gorshkov",institutions:["National Institute of Standards and Technology","Joint Center for Quantum Information and Computer Science","Joint Quantum Institute","University of Maryland, College Park"]},{name:"Andrew Houck",institutions:["Princeton University"]},{name:"Jungsang Kim",institutions:["Duke University","IonQ (United States)"]},{name:"Shelby Kimmel",institutions:["Middlebury College"]},{name:"Michael Lange",institutions:["L3Harris (United States)"]},{name:"Seth Lloyd",institutions:["Massachusetts Institute of Technology"]},{name:"Mikhail D. Lukin",institutions:["Harvard University"]},{name:"Dmitri Maslov",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Peter Maunz",institutions:["Sandia National Laboratories"]},{name:"Christopher Monroe",institutions:["Joint Center for Quantum Information and Computer Science","IonQ (United States)","Joint Quantum Institute","University of Maryland, College Park"]},{name:"John Preskill",institutions:["California Institute of Technology"]},{name:"Martin Roetteler",institutions:["Microsoft (United States)"]},{name:"Martin J. Savage",institutions:["University of Washington"]},{name:"Jeff Thompson",institutions:["Princeton University"]}],authorString:"Yuri Alexeev; Dave Bacon; Kenneth R. Brown; Robert Calderbank; Lincoln D. Carr; Frederic T. Chong; Brian DeMarco; Dirk Englund; Edward Farhi; Bill Fefferman; Alexey V. Gorshkov; Andrew Houck et al.",institutions:["Argonne National Laboratory","California Institute of Technology","Colorado School of Mines","Duke University","Google (United States)","Harvard University","IBM Research - Thomas J. Watson Research Center","IonQ (United States)","Joint Center for Quantum Information and Computer Science","Joint Quantum Institute","L3Harris (United States)","Massachusetts Institute of Technology","Microsoft (United States)","Middlebury College","National Institute of Standards and Technology","Princeton University","Sandia National Laboratories","University of Chicago","University of Illinois Urbana-Champaign","University of Maryland, College Park","University of Washington"],countries:["US"],year:2021,journal:"PRX Quantum",citations:243,abstract:"The great promise of quantum computers comes with the dual challenges of building them and finding their useful applications. We argue that these two challenges should be considered together, by codesigning full-stack quantum computer systems along with their applications in order to hasten their development and potential for scientific discovery. In this context, we identify scientific and community needs, opportunities, a sampling of a few use case studies, and significant challenges for the development of quantum computers for science over the next 2-10 years.",keywords:["Scientific discovery","Quantum computer","Quantum","Order","Dual","Quantum information"],concepts:["Scientific discovery","Quantum computer","Quantum","Order","Dual","Quantum information","Data science"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.017001",is_oa:!0,n_refs:102,n_refs_in_core:18,degree:36,community:3,deg_w:495.5,betweenness:.0033,pagerank:.00418,eigenvector:.0333},{id:91,oaid:"W2923481626",doi:"10.1103/physrevlett.122.140504",title:"Accelerated Variational Quantum Eigensolver",authors:[{name:"Daochen Wang",institutions:["Riverlane (United Kingdom)"]},{name:"Oscar Higgott",institutions:["Riverlane (United Kingdom)"]},{name:"Stephen Brierley",institutions:["Riverlane (United Kingdom)"]}],authorString:"Daochen Wang; Oscar Higgott; Stephen Brierley",institutions:["Riverlane (United Kingdom)"],countries:["GB"],year:2019,journal:"Physical Review Letters",citations:243,abstract:"The problem of finding the ground state energy of a Hamiltonian using a quantum computer is currently solved using either the quantum phase estimation (QPE) or variational quantum eigensolver (VQE) algorithms. For precision $\\ensuremath{\\epsilon}$, QPE requires $O(1)$ repetitions of circuits with depth $O(1/\\ensuremath{\\epsilon})$, whereas each expectation estimation subroutine within VQE requires $O(1/{\\ensuremath{\\epsilon}}^{2})$ samples from circuits with depth $O(1)$. We propose a generalized VQE algorithm that interpolates between these two regimes via a free parameter $\\ensuremath{\\alpha}\\ensuremath{\\in}[0,1]$, which can exploit quantum coherence over a circuit depth of $O(1/{\\ensuremath{\\epsilon}}^{\\ensuremath{\\alpha}})$ to reduce the number of samples to $O(1/{\\ensuremath{\\epsilon}}^{2(1\\ensuremath{-}\\ensuremath{\\alpha})})$. Along the way, we give a new routine for expectation estimation under limited quantum resources that is of independent interest.",keywords:["Quantum computer","Quantum","Hamiltonian","Subroutine","Quantum algorithm","Quantum circuit","Quantum mechanics"],concepts:["Quantum computer","Quantum","Hamiltonian","Subroutine","Quantum algorithm","Quantum circuit","Quantum mechanics"],pdf_url:"https://arxiv.org/pdf/1802.00171",is_oa:!0,n_refs:25,n_refs_in_core:5,degree:35,community:1,deg_w:392.5,betweenness:.0015,pagerank:.00328,eigenvector:.0346},{id:92,oaid:"W2157120748",doi:"10.1038/srep03589",title:"From transistor to trapped-ion computers for quantum chemistry",authors:[{name:"Man‐Hong Yung",institutions:["Beijing Academy of Quantum Information Sciences","Tsinghua University"]},{name:"J. Casanova",institutions:["University of the Basque Country"]},{name:"Antonio Mezzacapo",institutions:["University of the Basque Country"]},{name:"Jarrod R. McClean",institutions:["Harvard University"]},{name:"Lucas Lamata",institutions:["University of the Basque Country"]},{name:"Alán Aspuru‐Guzik",institutions:["Harvard University"]},{name:"E. Solano",institutions:["Ikerbasque","University of the Basque Country"]}],authorString:"Man‐Hong Yung; J. Casanova; Antonio Mezzacapo; Jarrod R. McClean; Lucas Lamata; Alán Aspuru‐Guzik; E. Solano",institutions:["Beijing Academy of Quantum Information Sciences","Harvard University","Ikerbasque","Tsinghua University","University of the Basque Country"],countries:["CN","ES","US"],year:2014,journal:"Scientific Reports",citations:237,abstract:"Over the last few decades, quantum chemistry has progressed through the development of computational methods based on modern digital computers. However, these methods can hardly fulfill the exponentially-growing resource requirements when applied to large quantum systems. As pointed out by Feynman, this restriction is intrinsic to all computational models based on classical physics. Recently, the rapid advancement of trapped-ion technologies has opened new possibilities for quantum control and quantum simulations. Here, we present an efficient toolkit that exploits both the internal and motional degrees of freedom of trapped ions for solving problems in quantum chemistry, including molecular electronic structure, molecular dynamics, and vibronic coupling. We focus on applications that go beyond the capacity of classical computers, but may be realizable on state-of-the-art trapped-ion systems. These results allow us to envision a new paradigm of quantum chemistry that shifts from the current transistor to a near-future trapped-ion-based technology.",keywords:["Quantum computer","Quantum chemistry","Quantum","Trapped ion quantum computer","Ion","Quantum technology","Quantum simulator"],concepts:["Quantum computer","Quantum chemistry","Quantum","Trapped ion quantum computer","Ion","Quantum technology","Quantum simulator"],pdf_url:"https://www.nature.com/articles/srep03589.pdf",is_oa:!0,n_refs:55,n_refs_in_core:1,degree:39,community:1,deg_w:412.5,betweenness:.0034,pagerank:.00346,eigenvector:.0342},{id:93,oaid:"W2979788593",doi:"10.1038/s41534-020-00302-0",title:"Variational fast forwarding for quantum simulation beyond the coherence time",authors:[{name:"Cristina Cîrstoiu",institutions:["Los Alamos National Laboratory","University of Oxford","Science Oxford"]},{name:"Zoë Holmes",institutions:["Los Alamos National Laboratory","Imperial College London"]},{name:"Joseph T. Iosue",institutions:["Los Alamos National Laboratory","Palo Alto Institute"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]},{name:"Andrew Sornborger",institutions:["Los Alamos National Laboratory"]}],authorString:"Cristina Cîrstoiu; Zoë Holmes; Joseph T. Iosue; Łukasz Cincio; Patrick J. Coles; Andrew Sornborger",institutions:["Imperial College London","Los Alamos National Laboratory","Palo Alto Institute","Science Oxford","University of Oxford"],countries:["GB","US"],year:2020,journal:"npj Quantum Information",citations:233,abstract:"Abstract Trotterization-based, iterative approaches to quantum simulation (QS) are restricted to simulation times less than the coherence time of the quantum computer (QC), which limits their utility in the near term. Here, we present a hybrid quantum-classical algorithm, called variational fast forwarding (VFF), for decreasing the quantum circuit depth of QSs. VFF seeks an approximate diagonalization of a short-time simulation to enable longer-time simulations using a constant number of gates. Our error analysis provides two results: (1) the simulation error of VFF scales at worst linearly in the fast-forwarded simulation time, and (2) our cost function’s operational meaning as an upper bound on average-case simulation error provides a natural termination condition for VFF. We implement VFF for the Hubbard, Ising, and Heisenberg models on a simulator. In addition, we implement VFF on Rigetti’s QC to demonstrate simulation beyond the coherence time. Finally, we show how to estimate energy eigenvalues using VFF.",keywords:["Coherence","Quantum computer","Quantum","Quantum algorithm","Upper and lower bounds","Ising model","Eigenvalues and eigenvectors"],concepts:["Coherence","Quantum computer","Quantum","Quantum algorithm","Upper and lower bounds","Ising model","Eigenvalues and eigenvectors"],pdf_url:"https://www.nature.com/articles/s41534-020-00302-0.pdf",is_oa:!0,n_refs:78,n_refs_in_core:17,degree:49,community:0,deg_w:803.5,betweenness:.0038,pagerank:.00604,eigenvector:.071},{id:94,oaid:"W2942327165",doi:"10.1038/s41534-019-0240-1",title:"Efficient symmetry-preserving state preparation circuits for the variational quantum eigensolver algorithm",authors:[{name:"Bryan T. Gard",institutions:["Virginia Tech"]},{name:"Linghua Zhu",institutions:["Virginia Tech"]},{name:"George S. Barron",institutions:["Virginia Tech"]},{name:"Nicholas J. Mayhall",institutions:["Virginia Tech"]},{name:"Sophia E. Economou",institutions:["Virginia Tech"]},{name:"Edwin Barnes",institutions:["Virginia Tech"]}],authorString:"Bryan T. Gard; Linghua Zhu; George S. Barron; Nicholas J. Mayhall; Sophia E. Economou; Edwin Barnes",institutions:["Virginia Tech"],countries:["US"],year:2020,journal:"npj Quantum Information",citations:231,abstract:'Abstract The variational quantum eigensolver is one of the most promising approaches for performing chemistry simulations using noisy intermediate-scale quantum (NISQ) processors. The efficiency of this algorithm depends crucially on the ability to prepare multi-qubit trial states on the quantum processor that either include, or at least closely approximate, the actual energy eigenstates of the problem being simulated while avoiding states that have little overlap with them. Symmetries play a central role in determining the best trial states. Here, we present efficient state preparation circuits that respect particle number, total spin, spin projection, and time-reversal symmetries. These circuits contain the minimal number of variational parameters needed to fully span the appropriate symmetry subspace dictated by the chemistry problem while avoiding all irrelevant sectors of Hilbert space. We show how to construct these circuits for arbitrary numbers of orbitals, electrons, and spin quantum numbers, and we provide explicit decompositions and gate counts in terms of standard gate sets in each case. We test our circuits in quantum simulations of the $${H}_{2}$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"> <mml:msub> <mml:mrow> <mml:mi>H</mml:mi> </mml:mrow> <mml:mrow> <mml:mn>2</mml:mn> </mml:mrow> </mml:msub> </mml:math> and $$LiH$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"> <mml:mrow> <mml:mi>L</mml:mi> <mml:mi>i</mml:mi> <mml:mi>H</mml:mi> </mml:mrow> </mml:math> molecules and find that they outperform standard state preparation methods in terms of both accuracy and circuit depth.',keywords:["Quantum computer","Electronic circuit","Quantum algorithm","Quantum gate","Quantum","Quantum circuit","Eigenvalues and eigenvectors","State"],concepts:["Quantum computer","Electronic circuit","Quantum algorithm","Quantum gate","Quantum","Algorithm","Quantum circuit","Eigenvalues and eigenvectors"],pdf_url:"https://www.nature.com/articles/s41534-019-0240-1.pdf",is_oa:!0,n_refs:35,n_refs_in_core:13,degree:42,community:1,deg_w:608,betweenness:.0018,pagerank:.00461,eigenvector:.0581},{id:95,oaid:"W4312224136",doi:"10.1038/s41467-022-35364-5",title:"Quantum variational algorithms are swamped with traps",authors:[{name:"Eric R. Anschuetz",institutions:["IIT@MIT"]},{name:"Bobak T. Kiani",institutions:["IIT@MIT"]}],authorString:"Eric R. Anschuetz; Bobak T. Kiani",institutions:["IIT@MIT"],countries:["US"],year:2022,journal:"Nature Communications",citations:227,abstract:"One of the most important properties of classical neural networks is how surprisingly trainable they are, though their training algorithms typically rely on optimizing complicated, nonconvex loss functions. Previous results have shown that unlike the case in classical neural networks, variational quantum models are often not trainable. The most studied phenomenon is the onset of barren plateaus in the training landscape of these quantum models, typically when the models are very deep. This focus on barren plateaus has made the phenomenon almost synonymous with the trainability of quantum models. Here, we show that barren plateaus are only a part of the story. We prove that a wide class of variational quantum models-which are shallow, and exhibit no barren plateaus-have only a superpolynomially small fraction of local minima within any constant energy from the global minimum, rendering these models untrainable if no good initial guess of the optimal parameters is known. We also study the trainability of variational quantum algorithms from a statistical query framework, and show that noisy optimization of a wide variety of quantum models is impossible with a sub-exponential number of queries. Finally, we numerically confirm our results on a variety of problem instances. Though we exclude a wide variety of quantum algorithms here, we give reason for optimism for certain classes of variational algorithms and discuss potential ways forward in showing the practical utility of such algorithms.",keywords:["Quantum","Algorithm","Quantum mechanics"],concepts:["Quantum","Algorithm"],pdf_url:"https://www.nature.com/articles/s41467-022-35364-5.pdf",is_oa:!0,n_refs:49,n_refs_in_core:12,degree:28,community:0,deg_w:262,betweenness:.001,pagerank:.00269,eigenvector:.0147},{id:96,oaid:"W3047776431",doi:"10.1103/prxquantum.1.020319",title:"Exploring Entanglement and Optimization within the Hamiltonian Variational Ansatz",authors:[{name:"Roeland Wiersema",institutions:["University of Waterloo","Vector Institute"]},{name:"Cunlu Zhou",institutions:["University of Toronto","Vector Institute"]},{name:"Yvette de Sereville",institutions:["University of Waterloo"]},{name:"Juan Felipe Carrasquilla",institutions:["University of Waterloo","Vector Institute"]},{name:"Yong Baek Kim",institutions:["University of Toronto"]},{name:"Henry Yuen",institutions:["University of Toronto"]}],authorString:"Roeland Wiersema; Cunlu Zhou; Yvette de Sereville; Juan Felipe Carrasquilla; Yong Baek Kim; Henry Yuen",institutions:["University of Toronto","University of Waterloo","Vector Institute"],countries:["CA"],year:2020,journal:"PRX Quantum",citations:227,abstract:'Quantum variational algorithms are one of the most promising applications of near-term quantum computers; however, recent studies have demonstrated that unless the variational quantum circuits are configured in a problem-specific manner, optimization of such circuits will most likely fail. In this paper, we focus on a special family of quantum circuits called the Hamiltonian variational ansatz (HVA), which its takes inspiration from the quantum approximate optimization algorithm and adiabatic quantum computation. Through the study of its entanglement spectrum and energy-gradient statistics, we find that the HVA exhibits favorable structural properties such as mild or entirely absent barren plateaus and a restricted state space that eases their optimization in comparison to the well-studied "hardware-efficient ansatz." We also numerically observe that the optimization landscape of the HVA becomes almost trap free, i.e., there are no suboptimal minima, when the ansatz is overparametrized. We observe a size-dependent "computational phase transition" as the number of layers in the HVA circuit is increased where the optimization crosses over from a hard to an easy region in terms of the quality of the approximations and the speed of convergence to a good solution. In contrast to the analogous transitions observed in the learning of random unitaries, which occur at a number of layers that grows exponentially with the number of qubits, our variational-quantum-eigensolver experiments suggest that the threshold to achieve the overparametrization phenomenon scales at most polynomially in the number of qubits for the transverse-field Ising and XXZ models. Lastly, as a demonstration of its entangling power and effectiveness, we show that the HVA can find accurate approximations to the ground states of a modified Haldane-Shastry Hamiltonian on a ring, which has long-range interactions and has a power-law entanglement scaling.',keywords:["Ansatz","Hamiltonian","Quantum entanglement","Quantum","Qubit","Adiabatic quantum computation","Quantum computer","Quantum algorithm"],concepts:["Ansatz","Hamiltonian","Quantum entanglement","Quantum","Statistical physics","Qubit","Adiabatic quantum computation"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.1.020319",is_oa:!0,n_refs:38,n_refs_in_core:7,degree:24,community:0,deg_w:188.5,betweenness:.0012,pagerank:.00213,eigenvector:.0159},{id:97,oaid:"W4206745400",doi:"10.1186/s41313-021-00032-6",title:"VQE method: a short survey and recent developments",authors:[{name:"Dmitry A. Fedorov",institutions:["Oak Ridge Associated Universities","Argonne National Laboratory"]},{name:"Bo Peng",institutions:["Pacific Northwest National Laboratory"]},{name:"Niranjan Govind",institutions:["Pacific Northwest National Laboratory"]},{name:"Yuri Alexeev",institutions:["Argonne National Laboratory"]}],authorString:"Dmitry A. Fedorov; Bo Peng; Niranjan Govind; Yuri Alexeev",institutions:["Argonne National Laboratory","Oak Ridge Associated Universities","Pacific Northwest National Laboratory"],countries:["US"],year:2022,journal:"Materials Theory",citations:225,abstract:"Abstract The variational quantum eigensolver (VQE) is a method that uses a hybrid quantum-classical computational approach to find eigenvalues of a Hamiltonian. VQE has been proposed as an alternative to fully quantum algorithms such as quantum phase estimation (QPE) because fully quantum algorithms require quantum hardware that will not be accessible in the near future. VQE has been successfully applied to solve the electronic Schrödinger equation for a variety of small molecules. However, the scalability of this method is limited by two factors: the complexity of the quantum circuits and the complexity of the classical optimization problem. Both of these factors are affected by the choice of the variational ansatz used to represent the trial wave function. Hence, the construction of an efficient ansatz is an active area of research. Put another way, modern quantum computers are not capable of executing deep quantum circuits produced by using currently available ansatzes for problems that map onto more than several qubits. In this review, we present recent developments in the field of designing efficient ansatzes that fall into two categories—chemistry–inspired and hardware–efficient—that produce quantum circuits that are easier to run on modern hardware. We discuss the shortfalls of ansatzes originally formulated for VQE simulations, how they are addressed in more sophisticated methods, and the potential ways for further improvements.",keywords:["Ansatz","Quantum computer","Quantum","Quantum algorithm","Scalability","Hamiltonian","Qubit"],concepts:["Ansatz","Quantum computer","Quantum","Quantum algorithm","Scalability","Hamiltonian","Qubit"],pdf_url:"https://materialstheory.springeropen.com/counter/pdf/10.1186/s41313-021-00032-6",is_oa:!0,n_refs:120,n_refs_in_core:30,degree:45,community:1,deg_w:985.5,betweenness:.002,pagerank:.00696,eigenvector:.1039},{id:98,oaid:"W3108496771",doi:"10.22331/q-2021-10-05-558",title:"Effect of barren plateaus on gradient-free optimization",authors:[{name:"Andrew Arrasmith",institutions:["Los Alamos National Laboratory"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory"]},{name:"Piotr Czarnik",institutions:["Los Alamos National Laboratory"]},{name:"Lukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Andrew Arrasmith; M. Cerezo; Piotr Czarnik; Lukasz Cincio; Patrick J. Coles",institutions:["Los Alamos National Laboratory"],countries:["US"],year:2021,journal:"Quantum",citations:223,abstract:"Barren plateau landscapes correspond to gradients that vanish exponentially in the number of qubits. Such landscapes have been demonstrated for variational quantum algorithms and quantum neural networks with either deep circuits or global cost functions. For obvious reasons, it is expected that gradient-based optimizers will be significantly affected by barren plateaus. However, whether or not gradient-free optimizers are impacted is a topic of debate, with some arguing that gradient-free approaches are unaffected by barren plateaus. Here we show that, indeed, gradient-free optimizers do not solve the barren plateau problem. Our main result proves that cost function differences, which are the basis for making decisions in a gradient-free optimization, are exponentially suppressed in a barren plateau. Hence, without exponential precision, gradient-free optimizers will not make progress in the optimization. We numerically confirm this by training in a barren plateau with several gradient-free optimizers (Nelder-Mead, Powell, and COBYLA algorithms), and show that the numbers of shots required in the optimization grows exponentially with the number of qubits.",keywords:["Exponential growth","Plateau","Exponential function","Function","Quantum","Artificial neural network","Basis"],concepts:["Exponential growth","Plateau","Exponential function","Function","Quantum","Artificial neural network","Statistical physics"],pdf_url:"https://quantum-journal.org/papers/q-2021-10-05-558/pdf/",is_oa:!0,n_refs:43,n_refs_in_core:16,degree:39,community:0,deg_w:516.5,betweenness:.002,pagerank:.00423,eigenvector:.0438},{id:99,oaid:"W3166275705",doi:"10.22331/q-2022-09-29-824",title:"Diagnosing Barren Plateaus with Tools from Quantum Optimal Control",authors:[{name:"Martín Larocca",institutions:["Los Alamos National Laboratory","Universidad de Buenos Aires"]},{name:"Piotr Czarnik",institutions:["Los Alamos National Laboratory"]},{name:"Kunal Sharma",institutions:["Louisiana State University","Los Alamos National Laboratory"]},{name:"Gopikrishnan Muraleedharan",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory"]}],authorString:"Martín Larocca; Piotr Czarnik; Kunal Sharma; Gopikrishnan Muraleedharan; Patrick J. Coles; M. Cerezo",institutions:["Los Alamos National Laboratory","Louisiana State University","Universidad de Buenos Aires"],countries:["AR","US"],year:2022,journal:"Quantum",citations:221,abstract:'Variational Quantum Algorithms (VQAs) have received considerable attention due to their potential for achieving near-term quantum advantage. However, more work is needed to understand their scalability. One known scaling result for VQAs is barren plateaus, where certain circumstances lead to exponentially vanishing gradients. It is common folklore that problem-inspired ansatzes avoid barren plateaus, but in fact, very little is known about their gradient scaling. In this work we employ tools from quantum optimal control to develop a framework that can diagnose the presence or absence of barren plateaus for problem-inspired ansatzes. Such ansatzes include the Quantum Alternating Operator Ansatz (QAOA), the Hamiltonian Variational Ansatz (HVA), and others. With our framework, we prove that avoiding barren plateaus for these ansatzes is not always guaranteed. Specifically, we show that the gradient scaling of the VQA depends on the degree of controllability of the system, and hence can be diagnosed through the dynamical Lie algebra<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi mathvariant="fraktur">g</mml:mi></mml:mrow></mml:math>obtained from the generators of the ansatz. We analyze the existence of barren plateaus in QAOA and HVA ansatzes, and we highlight the role of the input state, as different initial states can lead to the presence or absence of barren plateaus. Taken together, our results provide a framework for trainability-aware ansatz design strategies that do not come at the cost of extra quantum resources. Moreover, we prove no-go results for obtaining ground states with variational ansatzes for controllable system such as spin glasses. Our work establishes a link between the existence of barren plateaus and the scaling of the dimension of<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi mathvariant="fraktur">g</mml:mi></mml:mrow></mml:math>.',keywords:["Ansatz","Scalability","Scaling","Quantum","Hamiltonian","Quantum computer","Controllability"],concepts:["Ansatz","Scalability","Scaling","Quantum","Hamiltonian","Quantum computer","Controllability"],pdf_url:"https://quantum-journal.org/papers/q-2022-09-29-824/pdf/",is_oa:!0,n_refs:166,n_refs_in_core:38,degree:55,community:0,deg_w:1326,betweenness:.0043,pagerank:.00945,eigenvector:.1319},{id:100,oaid:"W2760696651",doi:"10.1126/sciadv.aap9646",title:"Witnessing eigenstates for quantum simulation of Hamiltonian spectra",authors:[{name:"Raffaele Santagati",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Jianwei Wang",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Antonio A. Gentile",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Stefano Paesani",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Nathan Wiebe",institutions:["Microsoft (United States)"]},{name:"Jarrod R. McClean",institutions:["Google (United States)","Lawrence Berkeley National Laboratory"]},{name:"Sam Morley-Short",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Peter Shadbolt",institutions:["Imperial College London"]},{name:"Damien Bonneau",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Joshua W. Silverstone",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"David P. Tew",institutions:["University of Bristol","Max Planck Institute for Solid State Research"]},{name:"Xiaoqi Zhou",institutions:["Sun Yat-sen University"]},{name:"Jeremy L. O’Brien",institutions:["University of Bristol","Bristol Robotics Laboratory"]},{name:"Mark G. Thompson",institutions:["University of Bristol","Bristol Robotics Laboratory"]}],authorString:"Raffaele Santagati; Jianwei Wang; Antonio A. Gentile; Stefano Paesani; Nathan Wiebe; Jarrod R. McClean; Sam Morley-Short; Peter Shadbolt; Damien Bonneau; Joshua W. Silverstone; David P. Tew; Xiaoqi Zhou et al.",institutions:["Bristol Robotics Laboratory","Google (United States)","Imperial College London","Lawrence Berkeley National Laboratory","Max Planck Institute for Solid State Research","Microsoft (United States)","Sun Yat-sen University","University of Bristol"],countries:["CN","DE","GB","US"],year:2018,journal:"Science Advances",citations:219,abstract:'The efficient calculation of Hamiltonian spectra, a problem often intractable on classical machines, can find application in many fields, from physics to chemistry. We introduce the concept of an "eigenstate witness" and, through it, provide a new quantum approach that combines variational methods and phase estimation to approximate eigenvalues for both ground and excited states. This protocol is experimentally verified on a programmable silicon quantum photonic chip, a mass-manufacturable platform, which embeds entangled state generation, arbitrary controlled unitary operations, and projective measurements. Both ground and excited states are experimentally found with fidelities >99%, and their eigenvalues are estimated with 32 bits of precision. We also investigate and discuss the scalability of the approach and study its performance through numerical simulations of more complex Hamiltonians. This result shows promising progress toward quantum chemistry on quantum computers.',keywords:["Hamiltonian","Eigenvalues and eigenvectors","Spectral line","Quantum","Quantum mechanics","Statistical physics","Theoretical physics"],concepts:["Hamiltonian","Eigenvalues and eigenvectors","Spectral line","Quantum","Quantum mechanics","Statistical physics","Theoretical physics"],pdf_url:"https://advances.sciencemag.org/content/advances/4/1/eaap9646.full.pdf",is_oa:!0,n_refs:64,n_refs_in_core:5,degree:47,community:1,deg_w:765,betweenness:.0021,pagerank:.00554,eigenvector:.0719},{id:101,oaid:"W2981325086",doi:"10.1063/1.5133059",title:"Exact parameterization of fermionic wave functions via unitary coupled cluster theory",authors:[{name:"Francesco A. Evangelista",institutions:["Emory University","Atlanta University Center"]},{name:"Garnet Kin-Lic Chan",institutions:["California Institute of Technology"]},{name:"Gustavo E. Scuseria",institutions:["Rice University"]}],authorString:"Francesco A. Evangelista; Garnet Kin-Lic Chan; Gustavo E. Scuseria",institutions:["Atlanta University Center","California Institute of Technology","Emory University","Rice University"],countries:["US"],year:2019,journal:"The Journal of Chemical Physics",citations:219,abstract:'A formal analysis is conducted on the exactness of various forms of unitary coupled cluster (UCC) theory based on particle-hole excitation and de-excitation operators. Both the conventional single exponential UCC parameterization and a factorized (referred to here as "disentangled") version are considered. We formulate a differential cluster analysis to determine the UCC amplitudes corresponding to a general quantum state. The exactness of conventional UCC (ability to represent any state) is explored numerically, and it is formally shown to be determined by the structure of the critical points of the UCC exponential mapping. A family of disentangled UCC wave functions is proven to exactly parameterize any state, thus showing how to construct Trotter-error-free parameterizations of UCC for applications in quantum computing. From these results, we construct an exact disentangled UCC parameterization that employs an infinite sequence of particle-hole or general one- and two-body substitution operators.',keywords:["Unitary state","Construct","Quantum","Exponential function","Coupled cluster","Cluster","Sequence"],concepts:["Unitary state","Construct","Quantum","Exponential function","Coupled cluster","Cluster","Sequence"],pdf_url:"https://aip.scitation.org/doi/pdf/10.1063/1.5133059",is_oa:!0,n_refs:54,n_refs_in_core:8,degree:30,community:1,deg_w:428,betweenness:6e-4,pagerank:.00351,eigenvector:.0376},{id:102,oaid:"W2990442724",doi:"10.22331/q-2019-12-02-208",title:"Qubitization of Arbitrary Basis Quantum Chemistry Leveraging Sparsity and Low Rank Factorization",authors:[{name:"Dominic W. Berry",institutions:["Macquarie University"]},{name:"Craig Gidney",institutions:["Google (United States)"]},{name:"Mário Motta",institutions:["California Institute of Technology"]},{name:"Jarrod R. McClean",institutions:["Google (United States)"]},{name:"Ryan Babbush",institutions:["Google (United States)"]}],authorString:"Dominic W. Berry; Craig Gidney; Mário Motta; Jarrod R. McClean; Ryan Babbush",institutions:["California Institute of Technology","Google (United States)","Macquarie University"],countries:["AU","US"],year:2019,journal:"Quantum",citations:219,abstract:'Recent work has dramatically reduced the gate complexity required to quantum simulate chemistry by using linear combinations of unitaries based methods to exploit structure in the plane wave basis Coulomb operator. Here, we show that one can achieve similar scaling even for arbitrary basis sets (which can be hundreds of times more compact than plane waves) by using qubitized quantum walks in a fashion that takes advantage of structure in the Coulomb operator, either by directly exploiting sparseness, or via a low rank tensor factorization. We provide circuits for several variants of our algorithm (which all improve over the scaling of prior methods) including one with <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mover><mml:mi class="MJX-tex-caligraphic" mathvariant="script">O</mml:mi><mml:mo>~</mml:mo></mml:mover></mml:mrow><mml:mo stretchy="false">(</mml:mo><mml:msup><mml:mi>N</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mn>3</mml:mn><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo>/</mml:mo></mml:mrow><mml:mn>2</mml:mn></mml:mrow></mml:msup><mml:mi>λ</mml:mi><mml:mo stretchy="false">)</mml:mo></mml:math> T complexity, where <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>N</mml:mi></mml:math> is number of orbitals and <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>λ</mml:mi></mml:math> is the 1-norm of the chemistry Hamiltonian. We deploy our algorithms to simulate the FeMoco molecule (relevant to Nitrogen fixation) and obtain circuits requiring about seven hundred times less surface code spacetime volume than prior quantum algorithms for this system, despite us using a larger and more accurate active space.',keywords:["Algorithm","Basis"],concepts:["Algorithm","Basis"],pdf_url:"https://quantum-journal.org/papers/q-2019-12-02-208/pdf/",is_oa:!0,n_refs:85,n_refs_in_core:6,degree:28,community:1,deg_w:469,betweenness:.0014,pagerank:.00382,eigenvector:.041},{id:103,oaid:"W3121383614",doi:"10.22331/q-2021-01-28-391",title:"Structure optimization for parameterized quantum circuits",authors:[{name:"Mateusz Ostaszewski",institutions:["Institute of Theoretical and Applied Informatics","University College London","Polish Academy of Sciences"]},{name:"Edward Grant",institutions:["Rahko (United Kingdom)","University College London"]},{name:"Marcello Benedetti",institutions:["Cambridge Quantum Computing (United Kingdom)","University College London"]}],authorString:"Mateusz Ostaszewski; Edward Grant; Marcello Benedetti",institutions:["Cambridge Quantum Computing (United Kingdom)","Institute of Theoretical and Applied Informatics","Polish Academy of Sciences","Rahko (United Kingdom)","University College London"],countries:["GB","PL"],year:2021,journal:"Quantum",citations:210,abstract:"We propose an efficient method for simultaneously optimizing both the structure and parameter values of quantum circuits with only a small computational overhead. Shallow circuits that use structure optimization perform significantly better than circuits that use parameter updates alone, making this method particularly suitable for noisy intermediate-scale quantum computers. We demonstrate the method for optimizing a variational quantum eigensolver for finding the ground states of Lithium Hydride and the Heisenberg model in simulation, and for finding the ground state of Hydrogen gas on the IBM Melbourne quantum computer.",keywords:["Parameterized complexity","Quantum computer","Electronic circuit","Quantum","Quantum circuit","Overhead","IBM"],concepts:["Parameterized complexity","Quantum computer","Electronic circuit","Quantum","Quantum circuit","Overhead","IBM"],pdf_url:"https://quantum-journal.org/papers/q-2021-01-28-391/pdf/",is_oa:!0,n_refs:41,n_refs_in_core:11,degree:31,community:0,deg_w:268.5,betweenness:.003,pagerank:.00278,eigenvector:.0173},{id:104,oaid:"W2897217696",doi:"10.1038/s41534-019-0167-6",title:"Variational quantum state diagonalization",authors:[{name:"Ryan LaRose",institutions:["Los Alamos National Laboratory","Michigan State University"]},{name:"Arkin Tikku",institutions:["Los Alamos National Laboratory","Imperial College London"]},{name:"Étude O’Neel-Judy",institutions:["Los Alamos National Laboratory"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Ryan LaRose; Arkin Tikku; Étude O’Neel-Judy; Łukasz Cincio; Patrick J. Coles",institutions:["Imperial College London","Los Alamos National Laboratory","Michigan State University"],countries:["GB","US"],year:2019,journal:"npj Quantum Information",citations:206,abstract:'Abstract Variational hybrid quantum-classical algorithms are promising candidates for near-term implementation on quantum computers. In these algorithms, a quantum computer evaluates the cost of a gate sequence (with speedup over classical cost evaluation), and a classical computer uses this information to adjust the parameters of the gate sequence. Here we present such an algorithm for quantum state diagonalization. State diagonalization has applications in condensed matter physics (e.g., entanglement spectroscopy) as well as in machine learning (e.g., principal component analysis). For a quantum state ρ and gate sequence U , our cost function quantifies how far $$U\\rho U^\\dagger$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"> <mml:mrow> <mml:mi>U</mml:mi> <mml:mi>ρ</mml:mi> <mml:msup> <mml:mrow> <mml:mi>U</mml:mi> </mml:mrow> <mml:mrow> <mml:mo>†</mml:mo> </mml:mrow> </mml:msup> </mml:mrow> </mml:math> is from being diagonal. We introduce short-depth quantum circuits to quantify our cost. Minimizing this cost returns a gate sequence that approximately diagonalizes ρ . One can then read out approximations of the largest eigenvalues, and the associated eigenvectors, of ρ . As a proof-of-principle, we implement our algorithm on Rigetti’s quantum computer to diagonalize one-qubit states and on a simulator to find the entanglement spectrum of the Heisenberg model ground state.',keywords:["Algorithm","Quantum computer","Quantum algorithm","Quantum machine learning","Quantum entanglement","Eigenvalues and eigenvectors","Quantum simulator"],concepts:["Algorithm","Quantum computer","Quantum algorithm","Quantum machine learning","Quantum entanglement","Eigenvalues and eigenvectors","Quantum simulator"],pdf_url:"https://www.nature.com/articles/s41534-019-0167-6.pdf",is_oa:!0,n_refs:66,n_refs_in_core:10,degree:47,community:0,deg_w:708.5,betweenness:.003,pagerank:.00547,eigenvector:.0598},{id:105,oaid:"W2978899725",doi:"10.22331/q-2020-08-31-314",title:"Stochastic gradient descent for hybrid quantum-classical optimization",authors:[{name:"Ryan Sweke",institutions:["Freie Universität Berlin"]},{name:"Frederik Wilde",institutions:["Freie Universität Berlin"]},{name:"Johannes Meyer",institutions:["Freie Universität Berlin"]},{name:"Maria Schuld",institutions:["Xanadu Quantum Technologies (Canada)","University of KwaZulu-Natal"]},{name:"Paul K. Faehrmann",institutions:["Freie Universität Berlin"]},{name:"Barthélémy Meynard-Piganeau",institutions:["École Polytechnique"]},{name:"Jens Eisert",institutions:["Helmholtz-Zentrum Berlin für Materialien und Energie","Freie Universität Berlin"]}],authorString:"Ryan Sweke; Frederik Wilde; Johannes Meyer; Maria Schuld; Paul K. Faehrmann; Barthélémy Meynard-Piganeau; Jens Eisert",institutions:["Freie Universität Berlin","Helmholtz-Zentrum Berlin für Materialien und Energie","University of KwaZulu-Natal","Xanadu Quantum Technologies (Canada)","École Polytechnique"],countries:["CA","DE","FR","ZA"],year:2020,journal:"Quantum",citations:206,abstract:'Within the context of hybrid quantum-classical optimization, gradient descent based optimizers typically require the evaluation of expectation values with respect to the outcome of parameterized quantum circuits. In this work, we explore the consequences of the prior observation that estimation of these quantities on quantum hardware results in a form of<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>s</mml:mi><mml:mi>t</mml:mi><mml:mi>o</mml:mi><mml:mi>c</mml:mi><mml:mi>h</mml:mi><mml:mi>a</mml:mi><mml:mi>s</mml:mi><mml:mi>t</mml:mi><mml:mi>i</mml:mi><mml:mi>c</mml:mi></mml:math>gradient descent optimization. We formalize this notion, which allows us to show that in many relevant cases, including VQE, QAOA and certain quantum classifiers, estimating expectation values with<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>k</mml:mi></mml:math>measurement outcomes results in optimization algorithms whose convergence properties can be rigorously well understood, for any value of<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>k</mml:mi></mml:math>. In fact, even using single measurement outcomes for the estimation of expectation values is sufficient. Moreover, in many settings the required gradients can be expressed as linear combinations of expectation values -- originating, e.g., from a sum over local terms of a Hamiltonian, a parameter shift rule, or a sum over data-set instances -- and we show that in these cases<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>k</mml:mi></mml:math>-shot expectation value estimation can be combined with sampling over terms of the linear combination, to obtain ``doubly stochastic\'\' gradient descent optimizers. For all algorithms we prove convergence guarantees, providing a framework for the derivation of rigorous optimization results in the context of near-term quantum devices. Additionally, we explore numerically these methods on benchmark VQE, QAOA and quantum-enhanced machine learning tasks and show that treating the stochastic settings as hyper-parameters allows for state-of-the-art results with significantly fewer circuit executions and measurements.',keywords:["Stochastic gradient descent","Convergence","Gradient descent","Benchmark","Parameterized complexity","Context","Quantum","Stochastic optimization"],concepts:["Stochastic gradient descent","Convergence","Gradient descent","Benchmark","Parameterized complexity","Context","Mathematical optimization"],pdf_url:"https://quantum-journal.org/papers/q-2020-08-31-314/pdf/",is_oa:!0,n_refs:42,n_refs_in_core:9,degree:34,community:0,deg_w:379.5,betweenness:.0014,pagerank:.00343,eigenvector:.0279},{id:106,oaid:"W3028293372",doi:"10.1002/wcms.1481",title:"The prospects of quantum computing in computational molecular biology",authors:[{name:"Carlos Outeiral",institutions:["University of Oxford"]},{name:"Martin Strahm",institutions:["Roche (Switzerland)"]},{name:"Jiye Shi",institutions:["UCB Pharma (United Kingdom)"]},{name:"Garrett M. Morris",institutions:["University of Oxford"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]},{name:"Charlotte M. Deane",institutions:["University of Oxford"]}],authorString:"Carlos Outeiral; Martin Strahm; Jiye Shi; Garrett M. Morris; Simon C. Benjamin; Charlotte M. Deane",institutions:["Roche (Switzerland)","UCB Pharma (United Kingdom)","University of Oxford"],countries:["CH","GB"],year:2020,journal:"Wiley Interdisciplinary Reviews Computational Molecular Science",citations:206,abstract:"Abstract Quantum computers can in principle solve certain problems exponentially more quickly than their classical counterparts. We have not yet reached the advent of useful quantum computation, but when we do, it will affect nearly all scientific disciplines. In this review, we examine how current quantum algorithms could revolutionize computational biology and bioinformatics. There are potential benefits across the entire field, from the ability to process vast amounts of information and run machine learning algorithms far more efficiently, to algorithms for quantum simulation that are poised to improve computational calculations in drug discovery, to quantum algorithms for optimization that may advance fields from protein structure prediction to network analysis. However, these exciting prospects are susceptible to “hype,” and it is also important to recognize the caveats and challenges in this new technology. Our aim is to introduce the promise and limitations of emerging quantum computing technologies in the areas of computational molecular biology and bioinformatics. This article is categorized under: Structure and Mechanism &gt; Computational Biochemistry and Biophysics Data Science &gt; Computer Algorithms and Programming Electronic Structure Theory &gt; Ab Initio Electronic Structure Methods",keywords:["Quantum computer","Quantum","Computational complexity theory","Computational model","Process","Modelling biological systems","Computational problem","Quantum algorithm"],concepts:["Quantum computer","Quantum","Theoretical computer science","Computational complexity theory","Computational model","Process","Modelling biological systems"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/wcms.1481",is_oa:!0,n_refs:163,n_refs_in_core:21,degree:35,community:0,deg_w:592,betweenness:.0031,pagerank:.00484,eigenvector:.0439},{id:107,oaid:"W3104428150",doi:"10.17169/refubium-28427",title:"Stochastic gradient descent for hybrid quantum-classical optimization",authors:[{name:"Ryan Sweke",institutions:["Freie Universität Berlin"]},{name:"Ryan Sweke",institutions:["Freie Universität Berlin"]},{name:"Johannes Jakob Meyer",institutions:["Freie Universität Berlin"]},{name:"Johannes Jakob Meyer",institutions:["Xanadu Quantum Technologies (Canada)","University of KwaZulu-Natal"]},{name:"Paul K. Faehrmann",institutions:["Freie Universität Berlin"]},{name:"Barthélémy Meynard-Piganeau",institutions:["École Polytechnique"]},{name:"Jens Eisert",institutions:["Helmholtz-Zentrum Berlin für Materialien und Energie","Freie Universität Berlin"]}],authorString:"Ryan Sweke; Ryan Sweke; Johannes Jakob Meyer; Johannes Jakob Meyer; Paul K. Faehrmann; Barthélémy Meynard-Piganeau; Jens Eisert",institutions:["Freie Universität Berlin","Helmholtz-Zentrum Berlin für Materialien und Energie","University of KwaZulu-Natal","Xanadu Quantum Technologies (Canada)","École Polytechnique"],countries:["CA","DE","FR","ZA"],year:2020,journal:"Refubium (Universitätsbibliothek der Freien Universität Berlin)",citations:204,abstract:'Within the context of hybrid quantum-classical optimization, gradient descent based optimizers typically require the evaluation of expectation values with respect to the outcome of parameterized quantum circuits. In this work, we explore the consequences of the prior observation that estimation of these quantities on quantum hardware results in a form of stochastic gradient descent optimization. We formalize this notion, which allows us to show that in many relevant cases, including VQE, QAOA and certain quantum classifiers, estimating expectation values with k measurement outcomes results in optimization algorithms whose convergence properties can be rigorously well understood, for any value of k. In fact, even using single measurement outcomes for the estimation of expectation values is sufficient. Moreover, in many settings the required gradients can be expressed as linear combinations of expectation values - originating, e.g., from a sum over local terms of a Hamiltonian, a parameter shift rule, or a sum over data-set instances - and we show that in these cases k-shot expectation value estimation can be combined with sampling over terms of the linear combination, to obtain "doubly stochastic" gradient descent optimizers. For all algorithms we prove convergence guarantees, providing a framework for the derivation of rigorous optimization results in the context of near-term quantum devices. Additionally, we explore numerically these methods on benchmark VQE, QAOA and quantum-enhanced machine learning tasks and show that treating the stochastic settings as hyper-parameters allows for state-of-the-art results with significantly fewer circuit executions and measurements.',keywords:["Stochastic gradient descent","Gradient descent","Stochastic optimization","Quantum circuit","Parameterized complexity","Quantum","Mathematical optimization"],concepts:["Stochastic gradient descent","Gradient descent","Stochastic optimization","Quantum circuit","Parameterized complexity","Quantum","Mathematical optimization"],pdf_url:"https://refubium.fu-berlin.de/handle/fub188/28679",is_oa:!0,n_refs:64,n_refs_in_core:7,degree:29,community:0,deg_w:386,betweenness:.001,pagerank:.00338,eigenvector:.0318},{id:108,oaid:"W4285390635",doi:"10.1103/prxquantum.3.030101",title:"Is Quantum Advantage the Right Goal for Quantum Machine Learning?",authors:[{name:"Maria Schuld",institutions:["Xanadu Quantum Technologies (Canada)"]},{name:"Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"]}],authorString:"Maria Schuld; Nathan Killoran",institutions:["Xanadu Quantum Technologies (Canada)"],countries:["CA"],year:2022,journal:"PRX Quantum",citations:204,abstract:'Machine learning is frequently listed among the most promising applications for quantum computing. This is in fact a curious choice: the machine-learning algorithms of today are notoriously powerful in practice but remain theoretically difficult to study. Quantum computing, in contrast, does not offer practical benchmarks on realistic scales and theory is the main tool we have to judge whether it could become relevant for a problem. In this perspective, we explain why it is so difficult to say something about the practical power of quantum computers for machine learning with the tools we are currently using. We argue that these challenges call for a critical debate on whether quantum advantage and that the narrative of "beating" classical machine learning should continue to dominate the literature in the way it does, and highlight examples for how other perspectives in existing research provide an important alternative to the focus on advantage.',keywords:["Perspective","Quantum machine learning","Quantum","Narrative","Focus"],concepts:["Perspective","Quantum machine learning","Quantum","Narrative","Focus"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.3.030101",is_oa:!0,n_refs:97,n_refs_in_core:17,degree:32,community:0,deg_w:438,betweenness:.0015,pagerank:.0041,eigenvector:.0215},{id:109,oaid:"W3080410339",doi:"10.1103/prxquantum.2.010342",title:"Real- and Imaginary-Time Evolution with Compressed Quantum Circuits",authors:[{name:"Sheng-Hsuan Lin",institutions:["Technical University of Munich"]},{name:"Rohit Dilip",institutions:["Munich Center for Quantum Science and Technology","Technical University of Munich"]},{name:"Andrew G. Green",institutions:["London Centre for Nanotechnology","University College London"]},{name:"Adam Smith",institutions:["Technical University of Munich"]},{name:"Frank Pollmann",institutions:["Munich Center for Quantum Science and Technology","Technical University of Munich"]}],authorString:"Sheng-Hsuan Lin; Rohit Dilip; Andrew G. Green; Adam Smith; Frank Pollmann",institutions:["London Centre for Nanotechnology","Munich Center for Quantum Science and Technology","Technical University of Munich","University College London"],countries:["DE","GB"],year:2021,journal:"PRX Quantum",citations:201,abstract:"The current generation of noisy intermediate-scale quantum computers introduces new opportunities to study quantum many-body systems. In this paper, we show that quantum circuits can provide a dramatically more efficient representation than current classical numerics of the quantum states generated under nonequilibrium quantum dynamics. For quantum circuits, we perform both real-and imaginary-time evolution using an optimization algorithm that is feasible on near-term quantum computers. We benchmark the algorithms by finding the ground state and simulating a global quench of the transverse-field Ising model with a longitudinal field on a classical computer. Furthermore, we implement (classically optimized) gates on a quantum processing unit and demonstrate that our algorithm effectively captures real-time evolution.",keywords:["Quantum algorithm","Quantum computer","Quantum","Quantum error correction","Quantum phase estimation algorithm","Quantum gate","Quantum annealing","Quantum circuit"],concepts:["Quantum algorithm","Quantum computer","Quantum","Quantum error correction","Quantum phase estimation algorithm","Quantum gate","Quantum annealing"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.010342",is_oa:!0,n_refs:48,n_refs_in_core:11,degree:31,community:2,deg_w:264,betweenness:.0017,pagerank:.0027,eigenvector:.0175},{id:110,oaid:"W3106887093",doi:"10.1109/access.2020.3041719",title:"Machine Learning: Quantum vs Classical",authors:[{name:"Tariq M. Khan",institutions:["Deakin University"]},{name:"Antonio Robles‐Kelly",institutions:["Deakin University"]}],authorString:"Tariq M. Khan; Antonio Robles‐Kelly",institutions:["Deakin University"],countries:["AU"],year:2020,journal:"IEEE Access",citations:201,abstract:"Encouraged by growing computing power and algorithmic development, machine learning technologies have become powerful tools for a wide variety of application areas, spanning from agriculture to chemistry and natural language processing. The use of quantum systems to process classical data using machine learning algorithms has given rise to an emerging research area, i.e. quantum machine learning. Despite its origins in the processing of classical data, quantum machine learning also explores the use of quantum phenomena for learning systems, the use of quantum computers for learning on quantum data and how machine learning algorithms and software can be formulated and implemented on quantum computers. Quantum machine learning can have a transformational effect on computer science. It may speed up the processing of information well beyond the existing classical speeds. Recent work has seen the development of quantum algorithms that could serve as foundations for machine learning applications. Despite its great promise, there are still significant hardware and software challenges that need to be resolved before quantum machine learning becomes practical. In this paper, we present an overview of quantum machine learning in the light of classical approaches. Departing from foundational concepts of machine learning and quantum computing, we discuss various technical contributions, strengths and similarities of the research work in this domain. We also elaborate upon the recent progress of different quantum machine learning approaches, their complexity, and applications in various fields such as physics, chemistry and natural language processing.",keywords:["Quantum machine learning","Computational learning theory","Quantum computer","Algorithmic learning theory","Quantum"],concepts:["Quantum machine learning","Computational learning theory","Quantum computer","Algorithmic learning theory","Quantum"],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/6514899/09274431.pdf",is_oa:!0,n_refs:160,n_refs_in_core:14,degree:28,community:0,deg_w:459,betweenness:.001,pagerank:.00413,eigenvector:.0246},{id:111,oaid:"W2053275122",doi:"10.1038/srep06603",title:"Adiabatic Quantum Simulation of Quantum Chemistry",authors:[{name:"Ryan Babbush",institutions:["Harvard University"]},{name:"Peter J. Love",institutions:["Haverford College"]},{name:"Alán Aspuru‐Guzik",institutions:["Harvard University"]}],authorString:"Ryan Babbush; Peter J. Love; Alán Aspuru‐Guzik",institutions:["Harvard University","Haverford College"],countries:["US"],year:2014,journal:"Scientific Reports",citations:199,abstract:"We show how to apply the quantum adiabatic algorithm directly to the quantum computation of molecular properties. We describe a procedure to map electronic structure Hamiltonians to 2-body qubit Hamiltonians with a small set of physically realizable couplings. By combining the Bravyi-Kitaev construction to map fermions to qubits with perturbative gadgets to reduce the Hamiltonian to 2-body, we obtain precision requirements on the coupling strengths and a number of ancilla qubits that scale polynomially in the problem size. Hence our mapping is efficient. The required set of controllable interactions includes only two types of interaction beyond the Ising interactions required to apply the quantum adiabatic algorithm to combinatorial optimization problems. Our mapping may also be of interest to chemists directly as it defines a dictionary from electronic structure to spin Hamiltonians with physical interactions.",keywords:["Adiabatic process","Quantum","Quantum chemistry","Quantum computer","Statistical physics","Quantum mechanics"],concepts:["Adiabatic process","Quantum","Quantum chemistry","Quantum computer","Statistical physics"],pdf_url:"https://www.nature.com/articles/srep06603.pdf",is_oa:!0,n_refs:155,n_refs_in_core:2,degree:27,community:1,deg_w:465,betweenness:.0015,pagerank:.0038,eigenvector:.0382},{id:112,oaid:"W3209237089",doi:"10.1038/s41467-023-36159-y",title:"Quantum machine learning beyond kernel methods",authors:[{name:"Sofiène Jerbi",institutions:["Universität Innsbruck"]},{name:"Lukas J. Fiderer",institutions:["Universität Innsbruck"]},{name:"Hendrik Poulsen Nautrup",institutions:["Universität Innsbruck"]},{name:"Jonas M. Kübler",institutions:["Max Planck Institute for Intelligent Systems"]},{name:"Hans J. Briegel",institutions:["Universität Innsbruck"]},{name:"Vedran Dunjko",institutions:["Leiden University"]}],authorString:"Sofiène Jerbi; Lukas J. Fiderer; Hendrik Poulsen Nautrup; Jonas M. Kübler; Hans J. Briegel; Vedran Dunjko",institutions:["Leiden University","Max Planck Institute for Intelligent Systems","Universität Innsbruck"],countries:["AT","DE","NL"],year:2023,journal:"Nature Communications",citations:198,abstract:"Machine learning algorithms based on parametrized quantum circuits are prime candidates for near-term applications on noisy quantum computers. In this direction, various types of quantum machine learning models have been introduced and studied extensively. Yet, our understanding of how these models compare, both mutually and to classical models, remains limited. In this work, we identify a constructive framework that captures all standard models based on parametrized quantum circuits: that of linear quantum models. In particular, we show using tools from quantum information theory how data re-uploading circuits, an apparent outlier of this framework, can be efficiently mapped into the simpler picture of linear models in quantum Hilbert spaces. Furthermore, we analyze the experimentally-relevant resource requirements of these models in terms of qubit number and amount of data needed to learn. Based on recent results from classical machine learning, we prove that linear quantum models must utilize exponentially more qubits than data re-uploading models in order to solve certain learning tasks, while kernel methods additionally require exponentially more data points. Our results provide a more comprehensive view of quantum machine learning models as well as insights on the compatibility of different models with NISQ constraints.",keywords:["Quantum machine learning","Theoretical computer science","Qubit","Quantum algorithm","Quantum circuit","Quantum","Quantum computer"],concepts:["Quantum machine learning","Theoretical computer science","Qubit","Quantum algorithm","Quantum circuit","Quantum","Quantum computer"],pdf_url:"https://www.nature.com/articles/s41467-023-36159-y.pdf",is_oa:!0,n_refs:63,n_refs_in_core:13,degree:27,community:0,deg_w:301,betweenness:9e-4,pagerank:.00306,eigenvector:.0191},{id:113,oaid:"W2982420674",doi:"10.1103/physrevresearch.2.043140",title:"Quantum equation of motion for computing molecular excitation energies on a noisy quantum processor",authors:[{name:"Pauline J. Ollitrault",institutions:["ETH Zurich","IBM Research - Zurich"]},{name:"Abhinav Kandala",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Chun-Fu Chen",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Panagiotis Kl. Barkoutsos",institutions:["IBM Research - Zurich"]},{name:"Antonio Mezzacapo",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Marco Pistoia",institutions:["JPMorgan Chase & Co (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Sarah Sheldon",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Stefan Woerner",institutions:["IBM Research - Zurich"]},{name:"Jay M. Gambetta",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Ivano Tavernelli",institutions:["IBM Research - Zurich"]}],authorString:"Pauline J. Ollitrault; Abhinav Kandala; Chun-Fu Chen; Panagiotis Kl. Barkoutsos; Antonio Mezzacapo; Marco Pistoia; Sarah Sheldon; Stefan Woerner; Jay M. Gambetta; Ivano Tavernelli",institutions:["ETH Zurich","IBM Research - Thomas J. Watson Research Center","IBM Research - Zurich","JPMorgan Chase & Co (United States)"],countries:["CH","US"],year:2020,journal:"Physical Review Research",citations:197,abstract:"The computation of molecular excitation energies is essential for predicting photo-induced reactions of chemical and technological interest. While the classical computing resources needed for this task scale poorly, quantum algorithms emerge as promising alternatives. In particular, the extension of the variational quantum eigensolver algorithm to the computation of the excitation energies is an attractive option. However, there is currently a lack of such algorithms for correlated molecular systems that is amenable to near-term, noisy hardware. In this work, we propose an extension of the well-established classical equation of motion approach to a quantum algorithm for the calculation of molecular excitation energies on noisy quantum computers. In particular, we demonstrate the efficiency of this approach in the calculation of the excitation energies of the LiH molecule on an IBM Quantum computer.",keywords:["Excitation","Quantum computer","Quantum","Computation","Quantum algorithm","IBM","Equations of motion","Motion"],concepts:["Excitation","Quantum computer","Quantum","Computation","Quantum algorithm","IBM","Quantum mechanics"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.2.043140",is_oa:!0,n_refs:38,n_refs_in_core:15,degree:35,community:1,deg_w:387,betweenness:.0017,pagerank:.00332,eigenvector:.0307},{id:114,oaid:"W3101678819",doi:null,title:"Noise resilience of variational quantum compiling",authors:[{name:"Kunal Sharma",institutions:["Louisiana State University","Los Alamos National Laboratory"]},{name:"Khatri, Sumeet",institutions:["Louisiana State University"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Kunal Sharma; Khatri, Sumeet; M. Cerezo; Patrick J. Coles",institutions:["Los Alamos National Laboratory","Louisiana State University"],countries:["US"],year:2020,journal:"Civil War Book Review",citations:194,abstract:"Variational hybrid quantum-classical algorithms (VHQCAs) are near-term algorithms that leverage classical optimization to minimize a cost function, which is efficiently evaluated on a quantum computer. Recently VHQCAs have been proposed for quantum compiling, where a target unitary U is compiled into a short-depth gate sequence V. In this work, we report on a surprising form of noise resilience for these algorithms. Namely, we find one often learns the correct gate sequence V (i.e. the correct variational parameters) despite various sources of incoherent noise acting during the cost-evaluation circuit. Our main results are rigorous theorems stating that the optimal variational parameters are unaffected by a broad class of noise models, such as measurement noise, gate noise, and Pauli channel noise. Furthermore, our numerical implementations on IBM's noisy simulator demonstrate resilience when compiling the quantum Fourier transform, Toffoli gate, and W-state preparation. Hence, variational quantum compiling, due to its robustness, could be practically useful for noisy intermediate-scale quantum devices. Finally, we speculate that this noise resilience may be a general phenomenon that applies to other VHQCAs such as the variational quantum eigensolver.",keywords:["Resilience","Noise","Quantum","Statistical physics","Quantum mechanics"],concepts:["Resilience","Noise","Quantum","Statistical physics","Quantum mechanics"],pdf_url:"https://digitalcommons.lsu.edu/libraries_pubs/87",is_oa:!0,n_refs:64,n_refs_in_core:7,degree:32,community:0,deg_w:558.5,betweenness:9e-4,pagerank:.00439,eigenvector:.0443},{id:115,oaid:"W4401331420",doi:"10.1103/prxquantum.5.037001",title:"Quantum Computing for High-Energy Physics: State of the Art and Challenges",authors:[{name:"Alberto Di Meglio",institutions:["European Organization for Nuclear Research"]},{name:"Karl Jansen",institutions:["Cyprus Institute","Deutsches Elektronen-Synchrotron DESY"]},{name:"Ivano Tavernelli",institutions:["IBM Research - Zurich"]},{name:"Constantia Alexandrou",institutions:["Cyprus Institute","University of Cyprus"]},{name:"Srinivasan Arunachalam",institutions:["IBM (United States)"]},{name:"C. Bauer",institutions:["Lawrence Berkeley National Laboratory"]},{name:"K. Borras",institutions:["Deutsches Elektronen-Synchrotron DESY","RWTH Aachen University"]},{name:"Stefano Carrazza",institutions:["University of Milan","Istituto Nazionale di Fisica Nucleare, Sezione di Milano","European Organization for Nuclear Research"]},{name:"Arianna Crippa",institutions:["Deutsches Elektronen-Synchrotron DESY","Humboldt-Universität zu Berlin"]},{name:"V. Croft",institutions:[]},{name:"Roland de Putter",institutions:["IBM (United States)"]},{name:"Andrea Delgado",institutions:["Oak Ridge National Laboratory"]},{name:"Vedran Dunjko",institutions:[]},{name:"Daniel J. Egger",institutions:["IBM Research - Zurich"]},{name:"Elías F. Combarro",institutions:["Universidad de Oviedo"]},{name:"Elina Fuchs",institutions:["Leibniz University Hannover","Physikalisch-Technische Bundesanstalt","European Organization for Nuclear Research"]},{name:"Lena Funcke",institutions:["University of Bonn"]},{name:"Daniel González-Cuadra",institutions:["Austrian Academy of Sciences","Universität Innsbruck"]},{name:"Michele Grossi",institutions:["European Organization for Nuclear Research"]},{name:"Jad C. Halimeh",institutions:["Munich Center for Quantum Science and Technology","Ludwig-Maximilians-Universität München"]},{name:"Zoë Holmes",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Stefan Kühn",institutions:["Deutsches Elektronen-Synchrotron DESY"]},{name:"Denis Lacroix",institutions:["Centre National de la Recherche Scientifique","Université Paris-Saclay","Institut National de Physique Nucléaire et de Physique des Particules","Laboratoire de Physique des 2 Infinis Irène Joliot-Curie"]},{name:"Randy Lewis",institutions:["York University"]},{name:"D. Lucchesi",institutions:["Istituto Nazionale di Fisica Nucleare, Sezione di Padova","European Organization for Nuclear Research"]},{name:"Miriam Lucio Martínez",institutions:["Maastricht University","National Institute for Subatomic Physics"]},{name:"F. Meloni",institutions:["Deutsches Elektronen-Synchrotron DESY"]},{name:"Antonio Mezzacapo",institutions:["IBM (United States)"]},{name:"Simone Montangero",institutions:["Istituto Nazionale di Fisica Nucleare, Sezione di Padova","European Organization for Nuclear Research"]},{name:"Lento Nagano",institutions:["The University of Tokyo"]},{name:"V. R. Pascuzzi",institutions:["IBM (United States)"]},{name:"V. Radescu",institutions:[]},{name:"E. Rico",institutions:["Ikerbasque","University of the Basque Country","Donostia International Physics Center"]},{name:"Alessandro Roggero",institutions:["University of Trento","Istituto Nazionale di Fisica Nucleare, Trento Institute for Fundamental Physics And Applications"]},{name:"Julian Schuhmacher",institutions:["IBM Research - Zurich"]},{name:"Joao Seixas",institutions:["Advanced Materials and Technologies (Slovenia)","Instituto Superior Técnico"]},{name:"Pietro Silvi",institutions:["Istituto Nazionale di Fisica Nucleare, Sezione di Padova","European Organization for Nuclear Research"]},{name:"Panagiotis Spentzouris",institutions:["Fermi National Accelerator Laboratory"]},{name:"Francesco Tacchino",institutions:["IBM Research - Zurich"]},{name:"Kristan Temme",institutions:["IBM (United States)"]},{name:"K. Terashi",institutions:["The University of Tokyo"]},{name:"Jordi Tura",institutions:["Leiden University"]},{name:"Cenk Tüysüz",institutions:["Deutsches Elektronen-Synchrotron DESY","Humboldt-Universität zu Berlin"]},{name:"S. Vallecorsa",institutions:["European Organization for Nuclear Research"]},{name:"U.‐J. Wiese",institutions:["University of Bern"]},{name:"Shinjae Yoo",institutions:["Brookhaven National Laboratory"]},{name:"Jinglei Zhang",institutions:["University of Waterloo"]}],authorString:"Alberto Di Meglio; Karl Jansen; Ivano Tavernelli; Constantia Alexandrou; Srinivasan Arunachalam; C. Bauer; K. Borras; Stefano Carrazza; Arianna Crippa; V. Croft; Roland de Putter; Andrea Delgado et al.",institutions:["Advanced Materials and Technologies (Slovenia)","Austrian Academy of Sciences","Brookhaven National Laboratory","Centre National de la Recherche Scientifique","Cyprus Institute","Deutsches Elektronen-Synchrotron DESY","Donostia International Physics Center","European Organization for Nuclear Research","Fermi National Accelerator Laboratory","Humboldt-Universität zu Berlin","IBM (United States)","IBM Research - Zurich","Ikerbasque","Institut National de Physique Nucléaire et de Physique des Particules","Instituto Superior Técnico","Istituto Nazionale di Fisica Nucleare, Sezione di Milano","Istituto Nazionale di Fisica Nucleare, Sezione di Padova","Istituto Nazionale di Fisica Nucleare, Trento Institute for Fundamental Physics And Applications","Laboratoire de Physique des 2 Infinis Irène Joliot-Curie","Lawrence Berkeley National Laboratory","Leibniz University Hannover","Leiden University","Ludwig-Maximilians-Universität München","Maastricht University","Munich Center for Quantum Science and Technology","National Institute for Subatomic Physics","Oak Ridge National Laboratory","Physikalisch-Technische Bundesanstalt","RWTH Aachen University","The University of Tokyo","Universidad de Oviedo","University of Bern","University of Bonn","University of Cyprus","University of Milan","University of Trento","University of Waterloo","University of the Basque Country","Universität Innsbruck","Université Paris-Saclay","York University","École Polytechnique Fédérale de Lausanne"],countries:["AT","CA","CH","CY","DE","ES","FR","IT","JP","NL","PT","SI","US"],year:2024,journal:"PRX Quantum",citations:193,abstract:"Quantum computers offer an intriguing path for a paradigmatic change of computing in the natural sciences and beyond, with the potential for achieving a so-called quantum advantage—namely, a significant (in some cases exponential) speedup of numerical simulations. The rapid development of hardware devices with various realizations of qubits enables the execution of small-scale but representative applications on quantum computers. In particular, the high-energy physics community plays a pivotal role in accessing the power of quantum computing, since the field is a driving source for challenging computational problems. This concerns, on the theoretical side, the exploration of models that are very hard or even impossible to address with classical techniques and, on the experimental side, the enormous data challenge of newly emerging experiments, such as the upgrade of the Large Hadron Collider. In this Roadmap paper, led by CERN, DESY, and IBM, we provide the status of high-energy physics quantum computations and give examples of theoretical and experimental target benchmark applications, which can be addressed in the near future. Having in mind hardware with about 100 qubits capable of executing several thousand two-qubit gates, where possible, we also provide resource estimates for the examples given using error-mitigated quantum computing. The ultimate declared goal of this task force is therefore to trigger further research in the high-energy physics community to develop interesting use cases for demonstrations on near-term quantum computers. Published by the American Physical Society 2024",keywords:["Quantum computer","Qubit","Large Hadron Collider","Computational science","Computer engineering","Quantum"],concepts:["Quantum computer","Qubit","Large Hadron Collider","Computational science","Computer engineering","Quantum"],pdf_url:"https://doi.org/10.1103/prxquantum.5.037001",is_oa:!0,n_refs:436,n_refs_in_core:42,degree:56,community:0,deg_w:1242,betweenness:.0083,pagerank:.00909,eigenvector:.134},{id:116,oaid:"W3108818881",doi:"10.1103/physreva.103.052416",title:"Solving nonlinear differential equations with differentiable quantum circuits",authors:[{name:"Oleksandr Kyriienko",institutions:["University of Exeter","Qu & Co. (Netherlands)"]},{name:"Annie E. Paine",institutions:["University of Exeter","Qu & Co. (Netherlands)"]},{name:"Vincent E. Elfving",institutions:["Qu & Co. (Netherlands)"]}],authorString:"Oleksandr Kyriienko; Annie E. Paine; Vincent E. Elfving",institutions:["Qu & Co. (Netherlands)","University of Exeter"],countries:["GB","NL"],year:2021,journal:"Physical review. A/Physical review, A",citations:189,abstract:"We propose a quantum algorithm to solve systems of nonlinear differential equations. Using a quantum feature map encoding, we define functions as expectation values of parametrized quantum circuits. We use automatic differentiation to represent function derivatives in an analytical form as differentiable quantum circuits (DQCs), thus avoiding inaccurate finite difference procedures for calculating gradients. We describe a hybrid quantum-classical workflow where DQCs are trained to satisfy differential equations and specified boundary conditions. As a particular example setting, we show how this approach can implement a spectral method for solving differential equations in a high-dimensional feature space. From a technical perspective, we design a Chebyshev quantum feature map that offers a powerful basis set of fitting polynomials and possesses rich expressivity. We simulate the algorithm to solve an instance of Navier-Stokes equations and compute density, temperature, and velocity profiles for the fluid flow in a convergent-divergent nozzle.",keywords:["Quantum algorithm","Quantum","Differentiable function","Feature","Nonlinear system","Applied mathematics","Differential equation"],concepts:["Quantum algorithm","Quantum","Differentiable function","Feature","Nonlinear system","Applied mathematics","Differential equation"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.103.052416",is_oa:!0,n_refs:238,n_refs_in_core:50,degree:65,community:0,deg_w:1372,betweenness:.0077,pagerank:.00975,eigenvector:.1466},{id:117,oaid:"W3141755656",doi:"10.22331/q-2022-05-24-720",title:"Quantum agents in the Gym: a variational quantum algorithm for deep Q-learning",authors:[{name:"Andrea Skolik",institutions:["Leiden University"]},{name:"Sofiène Jerbi",institutions:["Universität Innsbruck"]},{name:"Vedran Dunjko",institutions:["Leiden University"]}],authorString:"Andrea Skolik; Sofiène Jerbi; Vedran Dunjko",institutions:["Leiden University","Universität Innsbruck"],countries:["AT","NL"],year:2022,journal:"Quantum",citations:189,abstract:"Quantum machine learning (QML) has been identified as one of the key fields that could reap advantages from near-term quantum devices, next to optimization and quantum chemistry. Research in this area has focused primarily on variational quantum algorithms (VQAs), and several proposals to enhance supervised, unsupervised and reinforcement learning (RL) algorithms with VQAs have been put forward. Out of the three, RL is the least studied and it is still an open question whether VQAs can be competitive with state-of-the-art classical algorithms based on neural networks (NNs) even on simple benchmark tasks. In this work, we introduce a training method for parametrized quantum circuits (PQCs) that can be used to solve RL tasks for discrete and continuous state spaces based on the deep Q-learning algorithm. We investigate which architectural choices for quantum Q-learning agents are most important for successfully solving certain types of environments by performing ablation studies for a number of different data encoding and readout strategies. We provide insight into why the performance of a VQA-based Q-learning algorithm crucially depends on the observables of the quantum model and show how to choose suitable observables based on the learning task at hand. To compare our model against the classical DQN algorithm, we perform an extensive hyperparameter search of PQCs and NNs with varying numbers of parameters. We confirm that similar to results in classical literature, the architectural choices and hyperparameters contribute more to the agents&amp;apos; success in a RL setting than the number of parameters used in the model. Finally, we show when recent separation results between classical and quantum agents for policy gradient RL can be extended to inferring optimal Q-values in restricted families of environments.",keywords:["Quantum","Quantum algorithm","Algorithm","Q-learning","Quantum computer"],concepts:["Quantum","Quantum algorithm","Algorithm","Q-learning","Quantum computer"],pdf_url:"https://quantum-journal.org/papers/q-2022-05-24-720/pdf/",is_oa:!0,n_refs:86,n_refs_in_core:15,degree:31,community:0,deg_w:410,betweenness:.0014,pagerank:.00376,eigenvector:.0319},{id:118,oaid:"W3096987870",doi:"10.3929/ethz-b-000467868",title:"Quantum equation of motion for computing molecular excitation energies on a noisy quantum processor",authors:[{name:"Pauline J. Ollitrault",institutions:["ETH Zurich","IBM Research - Zurich"]},{name:"Abhinav Kandala",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Chun-Fu Chen",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Panagiotis Kl. Barkoutsos",institutions:["IBM Research - Zurich"]},{name:"Antonio Mezzacapo",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Marco Pistoia",institutions:["JPMorgan Chase & Co (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Sarah Sheldon",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Stefan Woerner",institutions:["IBM Research - Zurich"]},{name:"Jay Gambetta",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Ivano Tavernelli",institutions:["IBM Research - Zurich"]}],authorString:"Pauline J. Ollitrault; Abhinav Kandala; Chun-Fu Chen; Panagiotis Kl. Barkoutsos; Antonio Mezzacapo; Marco Pistoia; Sarah Sheldon; Stefan Woerner; Jay Gambetta; Ivano Tavernelli",institutions:["ETH Zurich","IBM Research - Thomas J. Watson Research Center","IBM Research - Zurich","JPMorgan Chase & Co (United States)"],countries:["CH","US"],year:2020,journal:"Repository for Publications and Research Data (ETH Zurich)",citations:186,abstract:"The computation of molecular excitation energies is essential for predicting photo-induced reactions of chemical and technological interest. While the classical computing resources needed for this task scale poorly, quantum algorithms emerge as promising alternatives. In particular, the extension of the variational quantum eigensolver algorithm to the computation of the excitation energies is an attractive option. However, there is currently a lack of such algorithms for correlated molecular systems that is amenable to near-term, noisy hardware. In this work, we propose an extension of the well-established classical equation of motion approach to a quantum algorithm for the calculation of molecular excitation energies on noisy quantum computers. In particular, we demonstrate the efficiency of this approach in the calculation of the excitation energies of the LiH molecule on an IBM Quantum computer.",keywords:["Excitation","Quantum","Motion","Quantum computer","Quantum mechanics","Classical mechanics"],concepts:["Excitation","Quantum","Motion","Quantum computer","Quantum mechanics"],pdf_url:"http://hdl.handle.net/20.500.11850/467868",is_oa:!0,n_refs:47,n_refs_in_core:12,degree:33,community:1,deg_w:423,betweenness:.0013,pagerank:.0035,eigenvector:.0412},{id:119,oaid:"W3137962867",doi:"10.1103/physrevlett.127.030503",title:"Efficient Estimation of Pauli Observables by Derandomization",authors:[{name:"Hsin-Yuan Huang",institutions:["California Institute of Technology"]},{name:"Richard Kueng",institutions:["Johannes Kepler University of Linz"]},{name:"John Preskill",institutions:["California Institute of Technology"]}],authorString:"Hsin-Yuan Huang; Richard Kueng; John Preskill",institutions:["California Institute of Technology","Johannes Kepler University of Linz"],countries:["AT","US"],year:2021,journal:"Physical Review Letters",citations:186,abstract:"We consider the problem of jointly estimating expectation values of many Pauli observables, a crucial subroutine in variational quantum algorithms. Starting with randomized measurements, we propose an efficient derandomization procedure that iteratively replaces random single-qubit measurements by fixed Pauli measurements; the resulting deterministic measurement procedure is guaranteed to perform at least as well as the randomized one. In particular, for estimating any L low-weight Pauli observables, a deterministic measurement on only of order log(L) copies of a quantum state suffices. In some cases, for example, when some of the Pauli observables have high weight, the derandomized procedure is substantially better than the randomized one. Specifically, numerical experiments highlight the advantages of our derandomized protocol over various previous methods for estimating the ground-state energies of small molecules.",keywords:["Observable","Pauli exclusion principle","Nuclear physics","Particle physics","Statistical physics","Hadron","Quantum mechanics"],concepts:["Observable","Pauli exclusion principle","Nuclear physics","Particle physics","Statistical physics","Hadron"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevLett.127.030503",is_oa:!0,n_refs:67,n_refs_in_core:13,degree:33,community:1,deg_w:459,betweenness:.0021,pagerank:.00385,eigenvector:.0363},{id:120,oaid:"W2968611999",doi:"10.1088/1367-2630/ab784c",title:"Noise resilience of variational quantum compiling",authors:[{name:"Kunal Sharma",institutions:["Louisiana State University","Los Alamos National Laboratory"]},{name:"Sumeet Khatri",institutions:["Louisiana State University"]},{name:"M Cerezo",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Kunal Sharma; Sumeet Khatri; M Cerezo; Patrick J Coles",institutions:["Los Alamos National Laboratory","Louisiana State University"],countries:["US"],year:2020,journal:"New Journal of Physics",citations:184,abstract:"Abstract Variational hybrid quantum-classical algorithms (VHQCAs) are near-term algorithms that leverage classical optimization to minimize a cost function, which is efficiently evaluated on a quantum computer. Recently VHQCAs have been proposed for quantum compiling, where a target unitary U is compiled into a short-depth gate sequence V . In this work, we report on a surprising form of noise resilience for these algorithms. Namely, we find one often learns the correct gate sequence V (i.e. the correct variational parameters) despite various sources of incoherent noise acting during the cost-evaluation circuit. Our main results are rigorous theorems stating that the optimal variational parameters are unaffected by a broad class of noise models, such as measurement noise, gate noise, and Pauli channel noise. Furthermore, our numerical implementations on IBM’s noisy simulator demonstrate resilience when compiling the quantum Fourier transform, Toffoli gate, and W-state preparation. Hence, variational quantum compiling, due to its robustness, could be practically useful for noisy intermediate-scale quantum devices. Finally, we speculate that this noise resilience may be a general phenomenon that applies to other VHQCAs such as the variational quantum eigensolver.",keywords:["Quantum","Noise","Pauli exclusion principle","Quantum error correction","Quantum Fourier transform","Quantum gate","Quantum algorithm","Toffoli gate"],concepts:["Quantum","Noise","Pauli exclusion principle","Quantum error correction","Quantum Fourier transform","Algorithm","Quantum gate"],pdf_url:"https://iopscience.iop.org/article/10.1088/1367-2630/ab784c/pdf",is_oa:!0,n_refs:41,n_refs_in_core:10,degree:36,community:0,deg_w:470,betweenness:.0015,pagerank:.00387,eigenvector:.0345},{id:121,oaid:"W4281287768",doi:"10.1038/s41534-022-00570-y",title:"Quantum circuit architecture search for variational quantum algorithms",authors:[{name:"Yuxuan Du",institutions:["The University of Sydney","Jingdong (China)"]},{name:"Tao Huang",institutions:["The University of Sydney"]},{name:"Shan You",institutions:["Group Sense (China)"]},{name:"Min-Hsiu Hsieh",institutions:["University of Technology Sydney","Centre for Quantum Computation and Communication Technology","Quanta Computer (Taiwan)"]},{name:"Dacheng Tao",institutions:["The University of Sydney","Jingdong (China)"]}],authorString:"Yuxuan Du; Tao Huang; Shan You; Min-Hsiu Hsieh; Dacheng Tao",institutions:["Centre for Quantum Computation and Communication Technology","Group Sense (China)","Jingdong (China)","Quanta Computer (Taiwan)","The University of Sydney","University of Technology Sydney"],countries:["AU","CN","TW"],year:2022,journal:"npj Quantum Information",citations:183,abstract:"Abstract Variational quantum algorithms (VQAs) are expected to be a path to quantum advantages on noisy intermediate-scale quantum devices. However, both empirical and theoretical results exhibit that the deployed ansatz heavily affects the performance of VQAs such that an ansatz with a larger number of quantum gates enables a stronger expressivity, while the accumulated noise may render a poor trainability. To maximally improve the robustness and trainability of VQAs, here we devise a resource and runtime efficient scheme termed quantum architecture search (QAS). In particular, given a learning task, QAS automatically seeks a near-optimal ansatz (i.e., circuit architecture) to balance benefits and side-effects brought by adding more noisy quantum gates to achieve a good performance. We implement QAS on both the numerical simulator and real quantum hardware, via the IBM cloud, to accomplish data classification and quantum chemistry tasks. In the problems studied, numerical and experimental results show that QAS cannot only alleviate the influence of quantum noise and barren plateaus but also outperforms VQAs with pre-selected ansatze.",keywords:["Quantum computer","Quantum algorithm","Ansatz","Quantum","Algorithm","Robustness","Quantum circuit"],concepts:["Quantum computer","Quantum algorithm","Ansatz","Quantum","Algorithm","Robustness","Quantum circuit"],pdf_url:"https://www.nature.com/articles/s41534-022-00570-y.pdf",is_oa:!0,n_refs:88,n_refs_in_core:25,degree:39,community:0,deg_w:610,betweenness:.0021,pagerank:.0048,eigenvector:.0598},{id:122,oaid:"W4327713021",doi:"10.1103/prxquantum.4.010328",title:"Exploiting Symmetry in Variational Quantum Machine Learning",authors:[{name:"Johannes Jakob Meyer",institutions:["Freie Universität Berlin"]},{name:"Marian Mularski",institutions:["Freie Universität Berlin"]},{name:"Elies Gil-Fuster",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Freie Universität Berlin"]},{name:"Antonio Anna Mele",institutions:["Freie Universität Berlin"]},{name:"Francesco Arzani",institutions:["Freie Universität Berlin"]},{name:"Alissa Wilms",institutions:["Freie Universität Berlin"]},{name:"Jens Eisert",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Helmholtz-Zentrum Berlin für Materialien und Energie","Freie Universität Berlin"]}],authorString:"Johannes Jakob Meyer; Marian Mularski; Elies Gil-Fuster; Antonio Anna Mele; Francesco Arzani; Alissa Wilms; Jens Eisert",institutions:["Fraunhofer Institute for Telecommunications, Heinrich Hertz Institute","Freie Universität Berlin","Helmholtz-Zentrum Berlin für Materialien und Energie"],countries:["DE"],year:2023,journal:"PRX Quantum",citations:182,abstract:"A blueprint for exploiting symmetries in the construction of variational quantum learning models that can result in improved generalization performance is developed and demonstrated on practical problems.",keywords:["Blueprint","Generalization","Homogeneous space","Symmetry","Quantum","Theoretical physics"],concepts:["Blueprint","Generalization","Homogeneous space","Symmetry","Quantum","Theoretical physics"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.4.010328",is_oa:!0,n_refs:62,n_refs_in_core:18,degree:33,community:0,deg_w:344,betweenness:.0018,pagerank:.0033,eigenvector:.0257},{id:123,oaid:"W2924355162",doi:"10.1103/physrevresearch.2.043158",title:"Sequential minimal optimization for quantum-classical hybrid algorithms",authors:[{name:"Ken M. Nakanishi",institutions:["The University of Tokyo"]},{name:"Keisuke Fujii",institutions:["Japan Science and Technology Agency","The University of Osaka"]},{name:"Synge Todo",institutions:["The University of Tokyo"]}],authorString:"Ken M. Nakanishi; Keisuke Fujii; Synge Todo",institutions:["Japan Science and Technology Agency","The University of Osaka","The University of Tokyo"],countries:["JP"],year:2020,journal:"Physical Review Research",citations:180,abstract:"We propose a sequential minimal optimization method for quantum-classical hybrid algorithms, which converges faster, robust against statistical error, and hyperparameter-free. Specifically, the optimization problem of the parameterized quantum circuits is divided into solvable subproblems by considering only a subset of the parameters. In fact, if we choose a single parameter, the cost function becomes a simple sine curve with period 2 , and hence we can exactly minimize with respect to the chosen parameter. Furthermore, even in general cases, the cost function is given by a simple sum of trigonometric functions with certain periods and hence can be minimized by using a classical computer. By repeatedly performing this procedure, we can optimize the parameterized quantum circuits so that the cost function becomes as small as possible. We perform numerical simulations and compare the proposed method with existing gradient-free and gradient-based optimization algorithms. We find that the proposed method substantially outperforms the existing optimization algorithms and converges to a solution almost independent of the initial choice of the parameters. This accelerates almost all quantum-classical hybrid algorithms readily and would be a key tool for harnessing near-term quantum devices.",keywords:["Parameterized complexity","Simple","Sine","Trigonometric functions","Function","Optimization problem","Key","Trigonometry"],concepts:["Parameterized complexity","Simple","Sine","Trigonometric functions","Mathematical optimization","Function","Algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.2.043158",is_oa:!0,n_refs:20,n_refs_in_core:7,degree:31,community:0,deg_w:228,betweenness:.0023,pagerank:.00244,eigenvector:.0179},{id:124,oaid:"W2978630019",doi:"10.1109/jproc.2019.2954005",title:"Challenges and Opportunities of Near-Term Quantum Computing Systems",authors:[{name:"Antonio D. Corcoles",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Abhinav Kandala",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Ali Javadi-Abhari",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Douglas T. McClure",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Andrew W. Cross",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Kristan Temme",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Paul D. Nation",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Matthias Steffen",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Jay M. Gambetta",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"]}],authorString:"Antonio D. Corcoles; Abhinav Kandala; Ali Javadi-Abhari; Douglas T. McClure; Andrew W. Cross; Kristan Temme; Paul D. Nation; Matthias Steffen; Jay M. Gambetta",institutions:["IBM (United States)","IBM Research - Thomas J. Watson Research Center"],countries:["US"],year:2019,journal:"Proceedings of the IEEE",citations:180,abstract:"The concept of quantum computing has inspired a whole new generation of scientists, including physicists, engineers, and computer scientists, to fundamentally change the landscape of information technology. With experimental demonstrations stretching back more than two decades, the quantum computing community has achieved a major milestone over the past few years: the ability to build systems that are stretching the limits of what can be classically simulated, and which enable cloud-based research for a wide range of scientists, thus increasing the pool of talent exploring early quantum systems. While such noisy near-term quantum computing systems fall far short of the requirements for fault-tolerant systems, they provide unique test beds for exploring the opportunities for quantum applications. Here, we highlight an IBM-specific perspective of the facets associated with these systems, including quantum software, cloud access, benchmarking quantum systems, error correction and mitigation in such systems, understanding the complexity of quantum circuits, and how early quantum applications can run on near-term quantum computers.",keywords:["Quantum computer","Quantum","Quantum information","Quantum network","Milestone","Quantum technology","Perspective"],concepts:["Quantum computer","Quantum","Quantum information","Quantum network","Milestone","Quantum technology","Perspective"],pdf_url:"https://ieeexplore.ieee.org/ielx7/5/9143211/08936946.pdf",is_oa:!0,n_refs:133,n_refs_in_core:18,degree:32,community:3,deg_w:422,betweenness:.0026,pagerank:.00366,eigenvector:.025},{id:125,oaid:"W3034033217",doi:"10.22331/q-2023-11-22-1188",title:"Variational Quantum Linear Solver",authors:[{name:"Carlos Bravo-Prieto",institutions:["Los Alamos National Laboratory","Barcelona Supercomputing Center","Universitat de Barcelona","Universitat Politècnica de Catalunya"]},{name:"Ryan LaRose",institutions:["Michigan State University"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory"]},{name:"Yiğit Subaşı",institutions:["Los Alamos National Laboratory"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Carlos Bravo-Prieto; Ryan LaRose; M. Cerezo; Yiğit Subaşı; Łukasz Cincio; Patrick J. Coles",institutions:["Barcelona Supercomputing Center","Los Alamos National Laboratory","Michigan State University","Universitat Politècnica de Catalunya","Universitat de Barcelona"],countries:["ES","US"],year:2023,journal:"Quantum",citations:177,abstract:`Previously proposed quantum algorithms for solving linear systems of equations cannot be implemented in the near term due to the required circuit depth. Here, we propose a hybrid quantum-classical algorithm, called Variational Quantum Linear Solver (VQLS), for solving linear systems on near-term quantum computers. VQLS seeks to variationally prepare <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo stretchy="false">|</mml:mo></mml:mrow><mml:mi>x</mml:mi><mml:mo fence="false" stretchy="false">&amp;#x27E9;</mml:mo></mml:math> such that <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>A</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo stretchy="false">|</mml:mo></mml:mrow><mml:mi>x</mml:mi><mml:mo fence="false" stretchy="false">&amp;#x27E9;</mml:mo><mml:mo>&amp;#x221D;</mml:mo><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo stretchy="false">|</mml:mo></mml:mrow><mml:mi>b</mml:mi><mml:mo fence="false" stretchy="false">&amp;#x27E9;</mml:mo></mml:math>. We derive an operationally meaningful termination condition for VQLS that allows one to guarantee that a desired solution precision <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>&amp;#x03F5;</mml:mi></mml:math> is achieved. Specifically, we prove that <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>C</mml:mi><mml:mo>&amp;#x2A7E;</mml:mo><mml:msup><mml:mi>&amp;#x03F5;</mml:mi><mml:mn>2</mml:mn></mml:msup><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo>/</mml:mo></mml:mrow><mml:msup><mml:mi>&amp;#x03BA;</mml:mi><mml:mn>2</mml:mn></mml:msup></mml:math>, where <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>C</mml:mi></mml:math> is the VQLS cost function and <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>&amp;#x03BA;</mml:mi></mml:math> is the condition number of <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>A</mml:mi></mml:math>. We present efficient quantum circuits to estimate <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>C</mml:mi></mml:math>, while providing evidence for the classical hardness of its estimation. Using Rigetti's quantum computer, we successfully implement VQLS up to a problem size of <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mn>1024</mml:mn><mml:mo>&amp;#x00D7;</mml:mo><mml:mn>1024</mml:mn></mml:math>. Finally, we numerically solve non-trivial problems of size up to <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:msup><mml:mn>2</mml:mn><mml:mrow class="MJX-TeXAtom-ORD"><mml:mn>50</mml:mn></mml:mrow></mml:msup><mml:mo>&amp;#x00D7;</mml:mo><mml:msup><mml:mn>2</mml:mn><mml:mrow class="MJX-TeXAtom-ORD"><mml:mn>50</mml:mn></mml:mrow></mml:msup></mml:math>. For the specific examples that we consider, we heuristically find that the time complexity of VQLS scales efficiently in <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>&amp;#x03F5;</mml:mi></mml:math>, <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>&amp;#x03BA;</mml:mi></mml:math>, and the system size <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>N</mml:mi></mml:math>.`,keywords:["Algorithm"],concepts:["Algorithm"],pdf_url:"https://quantum-journal.org/papers/q-2023-11-22-1188/pdf/",is_oa:!0,n_refs:101,n_refs_in_core:24,degree:41,community:0,deg_w:938.5,betweenness:.0013,pagerank:.00675,eigenvector:.0937},{id:126,oaid:"W3018348740",doi:"10.22331/q-2021-01-20-385",title:"Efficient quantum measurement of Pauli operators in the presence of finite sampling error",authors:[{name:"Ophelia Crawford",institutions:["Riverlane (United Kingdom)"]},{name:"Barnaby van Straaten",institutions:["Riverlane (United Kingdom)"]},{name:"Daochen Wang",institutions:["Riverlane (United Kingdom)","Joint Center for Quantum Information and Computer Science","University of Maryland, College Park"]},{name:"T.W. Parks",institutions:["Riverlane (United Kingdom)"]},{name:"Earl T. Campbell",institutions:["Riverlane (United Kingdom)","University of Sheffield"]},{name:"Stephen Brierley",institutions:["Riverlane (United Kingdom)"]}],authorString:"Ophelia Crawford; Barnaby van Straaten; Daochen Wang; T.W. Parks; Earl T. Campbell; Stephen Brierley",institutions:["Joint Center for Quantum Information and Computer Science","Riverlane (United Kingdom)","University of Maryland, College Park","University of Sheffield"],countries:["GB","US"],year:2021,journal:"Quantum",citations:175,abstract:'Estimating the expectation value of an operator corresponding to an observable is a fundamental task in quantum computation. It is often impossible to obtain such estimates directly, as the computer is restricted to measuring in a fixed computational basis. One common solution splits the operator into a weighted sum of Pauli operators and measures each separately, at the cost of many measurements. An improved version collects mutually commuting Pauli operators together before measuring all operators within a collection simultaneously. The effectiveness of doing this depends on two factors. Firstly, we must understand the improvement offered by a given arrangement of Paulis in collections. In our work, we propose two natural metrics for quantifying this, operating under the assumption that measurements are distributed optimally among collections so as to minimise the overall finite sampling error. Motivated by the mathematical form of these metrics, we introduce<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mstyle mathsize="1.2em"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi>S</mml:mi></mml:mrow></mml:mstyle></mml:math>ORTED<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mstyle mathsize="1.2em"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi>I</mml:mi></mml:mrow></mml:mstyle></mml:math>NSERTION, a collecting strategy that exploits the weighting of each Pauli operator in the overall sum. Secondly, to measure all Pauli operators within a collection simultaneously, a circuit is required to rotate them to the computational basis. In our work, we present two efficient circuit constructions that suitably rotate any collection of<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi mathvariant="bold-italic">k</mml:mi></mml:math>independent commuting<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi mathvariant="bold-italic">n</mml:mi></mml:math>-qubit Pauli operators using at most<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi mathvariant="bold-italic">k</mml:mi><mml:mi mathvariant="bold-italic">n</mml:mi><mml:mo mathvariant="bold">−</mml:mo><mml:mi mathvariant="bold-italic">k</mml:mi><mml:mo mathvariant="bold" stretchy="false">(</mml:mo><mml:mi mathvariant="bold-italic">k</mml:mi><mml:mo mathvariant="bold">+</mml:mo><mml:mn mathvariant="bold">1</mml:mn><mml:mo mathvariant="bold" stretchy="false">)</mml:mo><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo>/</mml:mo></mml:mrow><mml:mn mathvariant="bold">2</mml:mn></mml:math>and<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi mathvariant="bold-italic">O</mml:mi><mml:mo mathvariant="bold" stretchy="false">(</mml:mo><mml:mi mathvariant="bold-italic">k</mml:mi><mml:mi mathvariant="bold-italic">n</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo>/</mml:mo></mml:mrow><mml:mi mathvariant="bold">log</mml:mi><mml:mo>⁡</mml:mo><mml:mi mathvariant="bold-italic">k</mml:mi><mml:mo mathvariant="bold" stretchy="false">)</mml:mo></mml:math>two-qubit gates respectively. Our methods are numerically illustrated in the context of the Variational Quantum Eigensolver, where the operators in question are molecular Hamiltonians. As measured by our metrics,<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mstyle mathsize="1.2em"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi>S</mml:mi></mml:mrow></mml:mstyle></mml:math>ORTED<mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mstyle mathsize="1.2em"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mi>I</mml:mi></mml:mrow></mml:mstyle></mml:math>NSERTION outperforms four conventional greedy colouring algorithms that seek the minimum number of collections.',keywords:["Pauli exclusion principle","Operator","Basis","Weighting","Algorithm","Measure","Computation"],concepts:["Pauli exclusion principle","Operator","Basis","Weighting","Algorithm","Measure","Computation"],pdf_url:"https://quantum-journal.org/papers/q-2021-01-20-385/pdf/",is_oa:!0,n_refs:80,n_refs_in_core:21,degree:46,community:1,deg_w:775.5,betweenness:.0033,pagerank:.00582,eigenvector:.0613},{id:127,oaid:"W3178213288",doi:"10.1088/1361-6633/ac58a4",title:"Standard model physics and the digital quantum revolution: thoughts about the interface",authors:[{name:"Natalie Klco",institutions:["California Institute of Technology"]},{name:"Alessandro Roggero",institutions:["University of Washington"]},{name:"Martin J. Savage",institutions:["University of Washington"]}],authorString:"Natalie Klco; Alessandro Roggero; Martin J. Savage",institutions:["California Institute of Technology","University of Washington"],countries:["US"],year:2022,journal:"Reports on Progress in Physics",citations:174,abstract:"Abstract Advances in isolating, controlling and entangling quantum systems are transforming what was once a curious feature of quantum mechanics into a vehicle for disruptive scientific and technological progress. Pursuing the vision articulated by Feynman, a concerted effort across many areas of research and development is introducing prototypical digital quantum devices into the computing ecosystem available to domain scientists. Through interactions with these early quantum devices, the abstract vision of exploring classically-intractable quantum systems is evolving toward becoming a tangible reality. Beyond catalyzing these technological advances, entanglement is enabling parallel progress as a diagnostic for quantum correlations and as an organizational tool, both guiding improved understanding of quantum many-body systems and quantum field theories defining and emerging from the standard model. From the perspective of three domain science theorists, this article compiles thoughts about the interface on entanglement, complexity, and quantum simulation in an effort to contextualize recent NISQ-era progress with the scientific objectives of nuclear and high-energy physics.",keywords:["Interface","Physics beyond the Standard Model","Quantum","Theoretical physics","Quantum mechanics"],concepts:["Interface","Physics beyond the Standard Model","Quantum","Theoretical physics"],pdf_url:"https://iopscience.iop.org/article/10.1088/1361-6633/ac58a4/pdf",is_oa:!0,n_refs:654,n_refs_in_core:21,degree:36,community:3,deg_w:1110,betweenness:.002,pagerank:.0079,eigenvector:.1269},{id:128,oaid:"W4297102734",doi:"10.1007/s43673-022-00058-z",title:"NISQ computing: where are we and where do we go?",authors:[{name:"Jonathan Wei Zhong Lau",institutions:["Centre for Quantum Technologies","National University of Singapore"]},{name:"Kian Hwee Lim",institutions:["Centre for Quantum Technologies","National University of Singapore"]},{name:"Harshank Shrotriya",institutions:["Centre for Quantum Technologies","National University of Singapore"]},{name:"L. C. Kwek",institutions:["Centre for Quantum Technologies","National University of Singapore","Nanyang Technological University","UMI MajuLab"]}],authorString:"Jonathan Wei Zhong Lau; Kian Hwee Lim; Harshank Shrotriya; L. C. Kwek",institutions:["Centre for Quantum Technologies","Nanyang Technological University","National University of Singapore","UMI MajuLab"],countries:["SG"],year:2022,journal:"AAPPS bulletin",citations:173,abstract:"Abstract In this short review article, we aim to provide physicists not working within the quantum computing community a hopefully easy-to-read introduction to the state of the art in the field, with minimal mathematics involved. In particular, we focus on what is termed the Noisy Intermediate Scale Quantum era of quantum computing. We describe how this is increasingly seen to be a distinct phase in the development of quantum computers, heralding an era where we have quantum computers that are capable of doing certain quantum computations in a limited fashion, and subject to certain constraints and noise. We further discuss the prominent algorithms that are believed to hold the most potential for this era, and also describe the competing physical platforms on which to build a quantum computer that have seen the most success so far. We then talk about the applications that are most feasible in the near-term, and finish off with a short discussion on the state of the field. We hope that as non-experts read this article, it will give context to the recent developments in quantum computers that have garnered much popular press, and help the community understand how to place such developments in the timeline of quantum computing.",keywords:["Quantum computer","Timeline","Quantum","Context","Field","Theoretical computer science","Data science"],concepts:["Quantum computer","Timeline","Quantum","Context","Field","Theoretical computer science","Data science"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s43673-022-00058-z.pdf",is_oa:!0,n_refs:369,n_refs_in_core:43,degree:57,community:0,deg_w:1478,betweenness:.01,pagerank:.01042,eigenvector:.1701},{id:129,oaid:"W3030829226",doi:"10.1103/physrevlett.128.180505",title:"Trainability of Dissipative Perceptron-Based Quantum Neural Networks",authors:[{name:"Kunal Sharma",institutions:["Louisiana State University","Los Alamos National Laboratory"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Kunal Sharma; M. Cerezo; Łukasz Cincio; Patrick J. Coles",institutions:["Los Alamos National Laboratory","Louisiana State University"],countries:["US"],year:2022,journal:"Physical Review Letters",citations:172,abstract:"Several architectures have been proposed for quantum neural networks (QNNs), with the goal of efficiently performing machine learning tasks on quantum data. Rigorous scaling results are urgently needed for specific QNN constructions to understand which, if any, will be trainable at a large scale. Here, we analyze the gradient scaling (and hence the trainability) for a recently proposed architecture that we call dissipative QNNs (DQNNs), where the input qubits of each layer are discarded at the layer's output. We find that DQNNs can exhibit barren plateaus, i.e., gradients that vanish exponentially in the number of qubits. Moreover, we provide quantitative bounds on the scaling of the gradient for DQNNs under different conditions, such as different cost functions and circuit depths, and show that trainability is not always guaranteed. Our work represents the first rigorous analysis of the scalability of a perceptron-based QNN.",keywords:["Perceptron","Scaling","Scalability","Dissipative system","Qubit","Artificial neural network","Quantum"],concepts:["Perceptron","Scaling","Scalability","Dissipative system","Qubit","Artificial neural network","Quantum"],pdf_url:"https://arxiv.org/pdf/2005.12458",is_oa:!0,n_refs:84,n_refs_in_core:24,degree:45,community:0,deg_w:914.5,betweenness:.0027,pagerank:.00689,eigenvector:.0853},{id:130,oaid:"W2999682805",doi:"10.1103/physrevx.10.011004",title:"Increasing the Representation Accuracy of Quantum Simulations of Chemistry without Extra Quantum Resources",authors:[{name:"Tyler Y. Takeshita",institutions:["Mercedes-Benz Research and Development North America (United States)"]},{name:"Nicholas C. Rubin",institutions:["Google (United States)"]},{name:"Jiang Zhang",institutions:["Google (United States)"]},{name:"Eunseok Lee",institutions:["Mercedes-Benz Research and Development North America (United States)"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Jarrod R. McClean",institutions:["Google (United States)"]}],authorString:"Tyler Y. Takeshita; Nicholas C. Rubin; Jiang Zhang; Eunseok Lee; Ryan Babbush; Jarrod R. McClean",institutions:["Google (United States)","Mercedes-Benz Research and Development North America (United States)"],countries:["US"],year:2020,journal:"Physical Review X",citations:171,abstract:"Proposals for experiments in quantum chemistry on quantum computers leverage the ability to target a subset of degrees of freedom containing the essential quantum behavior, sometimes called the active space. This approximation allows one to treat more difficult problems using fewer qubits and lower gate depths than would otherwise be possible. However, while this approximation captures many important qualitative features, it may leave the results wanting in terms of absolute accuracy (basis error) of the representation. In traditional approaches, increasing this accuracy requires increasing the number of qubits and an appropriate increase in circuit depth as well. Here we explore two techniques requiring no additional qubits or circuit depth that are able to remove much of this approximation in favor of additional measurements. The techniques are constructed and analyzed theoretically, and some numerical proof-of-concept calculations are shown. As an example, we show how to achieve the accuracy of a 20-qubit representation using only four qubits and a modest number of additional measurements for a hydrogen molecule. We close with an outlook on the impact such techniques may have on both near-term and fault-tolerant quantum simulations.",keywords:["Qubit","Leverage","Representation","Quantum","Quantum computer","Quantum algorithm","Quantum chemistry"],concepts:["Qubit","Leverage","Representation","Quantum","Quantum computer","Quantum algorithm","Quantum chemistry"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.10.011004",is_oa:!0,n_refs:76,n_refs_in_core:16,degree:42,community:1,deg_w:836.5,betweenness:.0017,pagerank:.00602,eigenvector:.0769},{id:131,oaid:"W2996317883",doi:"10.1021/acs.jctc.9b01083",title:"Is the Trotterized UCCSD Ansatz Chemically Well-Defined?",authors:[{name:"Harper R. Grimsley",institutions:["Virginia Tech"]},{name:"Daniel Claudino",institutions:["Virginia Tech"]},{name:"Sophia E. Economou",institutions:["Virginia Tech"]},{name:"Edwin Barnes",institutions:["Virginia Tech"]},{name:"Nicholas J. Mayhall",institutions:["Virginia Tech"]}],authorString:"Harper R. Grimsley; Daniel Claudino; Sophia E. Economou; Edwin Barnes; Nicholas J. Mayhall",institutions:["Virginia Tech"],countries:["US"],year:2019,journal:"Journal of Chemical Theory and Computation",citations:166,abstract:', 2019 , 15 , 311 . arXiv, 2019 , quant-ph:1909.09114. https://arxiv.org/abs/1909.09114 ]. We observe a significant, system-dependent variation in the energies of Trotterizations with different operator orderings. The energy variations occur on a chemical scale, sometimes on the order of hundreds of kcal/mol. This Letter establishes the need to define not only the operators present in the ansatz but also the order in which they appear. This is necessary for adhering to the quantum chemical notion of a "model chemistry", in addition to the general importance of scientific reproducibility. As a final note, we suggest a useful strategy to select out of the combinatorial number of possibilities, a single well-defined and effective ordering of the operators.',keywords:["Ansatz","Computational science","Quantum mechanics"],concepts:["Ansatz","Computational science"],pdf_url:"https://arxiv.org/pdf/1910.10329",is_oa:!0,n_refs:46,n_refs_in_core:13,degree:36,community:1,deg_w:597.5,betweenness:.001,pagerank:.00457,eigenvector:.0537},{id:132,oaid:"W3088357939",doi:"10.1103/physrevresearch.3.033083",title:"Hardware-efficient variational quantum algorithms for time evolution",authors:[{name:"Marcello Benedetti",institutions:["Cambridge Quantum Computing (United Kingdom)"]},{name:"Mattia Fiorentini",institutions:["Cambridge Quantum Computing (United Kingdom)"]},{name:"Michael Lubasch",institutions:["Cambridge Quantum Computing (United Kingdom)"]}],authorString:"Marcello Benedetti; Mattia Fiorentini; Michael Lubasch",institutions:["Cambridge Quantum Computing (United Kingdom)"],countries:["GB"],year:2021,journal:"Physical Review Research",citations:157,abstract:"Parameterized quantum circuits are a promising technology for achieving a quantum advantage. An important application is the variational simulation of time evolution of quantum systems. To make the most of quantum hardware, variational algorithms need to be as hardware-efficient as possible. Here we present alternatives to the time-dependent variational principle that are hardware-efficient and do not require matrix inversion. In relation to imaginary time evolution, our approach significantly reduces the hardware requirements. With regards to real time evolution, where high precision can be important, we present algorithms of systematically increasing accuracy and hardware requirements. We numerically analyze the performance of our algorithms using quantum Hamiltonians with local interactions.",keywords:["Quantum algorithm","Parameterized complexity","Quantum","Quantum phase estimation algorithm","Imaginary time","Quantum computer","Quantum sort","Quantum circuit"],concepts:["Quantum algorithm","Parameterized complexity","Quantum","Quantum phase estimation algorithm","Algorithm","Imaginary time","Quantum computer"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.3.033083",is_oa:!0,n_refs:50,n_refs_in_core:17,degree:36,community:2,deg_w:363.5,betweenness:.0028,pagerank:.00346,eigenvector:.0245},{id:133,oaid:"W3138564161",doi:"10.1103/physrevlett.127.270502",title:"Mitigating Depolarizing Noise on Quantum Computers with Noise-Estimation Circuits",authors:[{name:"Miroslav Urbanek",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Benjamin Nachman",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Vincent R. Pascuzzi",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Andre He",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Christian W. Bauer",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Wibe A. de Jong",institutions:["Lawrence Berkeley National Laboratory"]}],authorString:"Miroslav Urbanek; Benjamin Nachman; Vincent R. Pascuzzi; Andre He; Christian W. Bauer; Wibe A. de Jong",institutions:["Lawrence Berkeley National Laboratory"],countries:["US"],year:2021,journal:"Physical Review Letters",citations:156,abstract:"A significant problem for current quantum computers is noise. While there are many distinct noise channels, the depolarizing noise model often appropriately describes average noise for large circuits involving many qubits and gates. We present a method to mitigate the depolarizing noise by first estimating its rate with a noise-estimation circuit and then correcting the output of the target circuit using the estimated rate. The method is experimentally validated on a simulation of the Heisenberg model. We find that our approach in combination with readout-error correction, randomized compiling, and zero-noise extrapolation produces close to exact results even for circuits containing hundreds of CNOT gates. We also show analytically that zero-noise extrapolation is improved when it is applied to the output of our method.",keywords:["Extrapolation","Controlled NOT gate","Noise","Qubit","Electronic circuit","Quantum computer","Depolarization","Quantum noise"],concepts:["Extrapolation","Controlled NOT gate","Noise","Qubit","Electronic circuit","Quantum computer","Depolarization"],pdf_url:"https://arxiv.org/pdf/2103.08591",is_oa:!0,n_refs:39,n_refs_in_core:11,degree:23,community:2,deg_w:203.5,betweenness:.001,pagerank:.00218,eigenvector:.0132},{id:134,oaid:"W2926552232",doi:"10.1038/s41534-020-00288-9",title:"The Born supremacy: quantum advantage and training of an Ising Born machine",authors:[{name:"Brian Coyle",institutions:["University of Edinburgh"]},{name:"Daniel Mills",institutions:["University of Edinburgh"]},{name:"Vincent Danos",institutions:["Centre National de la Recherche Scientifique","École Normale Supérieure - PSL","École Normale Supérieure","Institut de Recherche sur l'Architecture Antique","Département d'Informatique","Laboratoire de Géologie de l’École Normale Supérieure","University of Edinburgh"]},{name:"Elham Kashefi",institutions:["Centre National de la Recherche Scientifique","Sorbonne Université","Laboratoire Jacques-Louis Lions","University of Edinburgh"]}],authorString:"Brian Coyle; Daniel Mills; Vincent Danos; Elham Kashefi",institutions:["Centre National de la Recherche Scientifique","Département d'Informatique","Institut de Recherche sur l'Architecture Antique","Laboratoire Jacques-Louis Lions","Laboratoire de Géologie de l’École Normale Supérieure","Sorbonne Université","University of Edinburgh","École Normale Supérieure","École Normale Supérieure - PSL"],countries:["BI","FR","GB"],year:2020,journal:"npj Quantum Information",citations:155,abstract:"Abstract The search for an application of near-term quantum devices is widespread. Quantum machine learning is touted as a potential utilisation of such devices, particularly those out of reach of the simulation capabilities of classical computers. In this work, we study such an application in generative modelling, focussing on a class of quantum circuits known as Born machines. Specifically, we define a subset of this class based on Ising Hamiltonians and show that the circuits encountered during gradient-based training cannot be efficiently sampled from classically up to multiplicative error in the worst case. Our gradient-based training methods use cost functions known as the Sinkhorn divergence and the Stein discrepancy, which have not previously been used in the gradient-based training of quantum circuits, and we also introduce quantum kernels to generative modelling. We show that these methods outperform the previous standard method, which used maximum mean discrepancy (MMD) as a cost function, and achieve this with minimal overhead. Finally, we discuss the ability of the model to learn hard distributions and provide formal definitions for ‘quantum learning supremacy’. We also exemplify the work of this paper by using generative modelling to perform quantum circuit compilation.",keywords:["Quantum","Quantum computer","Quantum machine learning","Quantum circuit","Ising model","Divergence","Generative grammar"],concepts:["Quantum","Quantum computer","Quantum machine learning","Quantum circuit","Ising model","Divergence","Generative grammar"],pdf_url:"https://www.nature.com/articles/s41534-020-00288-9.pdf",is_oa:!0,n_refs:147,n_refs_in_core:13,degree:33,community:0,deg_w:543,betweenness:9e-4,pagerank:.00455,eigenvector:.046},{id:135,oaid:"W3021584456",doi:"10.1103/physrevresearch.2.043246",title:"Avoiding local minima in variational quantum eigensolvers with the natural gradient optimizer",authors:[{name:"David Wierichs",institutions:["University of Cologne"]},{name:"Christian Gogolin",institutions:["University of Cologne","Covestro (Germany)"]},{name:"Michael Kastoryano",institutions:["Amazon (United States)","University of Cologne"]}],authorString:"David Wierichs; Christian Gogolin; Michael Kastoryano",institutions:["Amazon (United States)","Covestro (Germany)","University of Cologne"],countries:["DE","US"],year:2020,journal:"Physical Review Research",citations:155,abstract:"We compare the BFGS optimizer, ADAM and NatGrad in the context of VQES. We systematically analyze their performance on the QAOA ansatz for the transverse field Ising and the XXZ model as well as on overparametrized circuits with the ability to break the symmetry of the Hamiltonian. The BFGS algorithm is frequently unable to find a global minimum for systems beyond about 20 spins and ADAM easily gets trapped in local minima or exhibits infeasible optimization durations. NatGrad on the other hand shows stable performance on all considered system sizes, rewarding its higher cost per epoch with reliability and competitive total run times. In sharp contrast to most classical gradient-based learning, the performance of all optimizers decreases upon seemingly benign overparametrization of the ansatz class, with BFGS and ADAM failing more often and more severely than NatGrad. This does not only stress the necessity for good ansatz circuits but also means that overparametrization, an established remedy for avoiding local minima in machine learning, does not seem to be a viable option in the context of VQES. The behavior in both investigated spin chains is similar, in particular the problems of BFGS and ADAM surface in both systems, even though their effective Hilbert space dimensions differ significantly. Overall our observations stress the importance of avoiding redundant degrees of freedom in ansatz circuits and to put established optimization algorithms and attached heuristics to test on larger system sizes. Natural gradient descent emerges as a promising choice to optimize large VQES.",keywords:["Ansatz","Maxima and minima","Context","Broyden–Fletcher–Goldfarb–Shanno algorithm","Gradient descent","Degrees of freedom","Symmetry"],concepts:["Ansatz","Maxima and minima","Context","Broyden–Fletcher–Goldfarb–Shanno algorithm","Gradient descent","Mathematical optimization","Degrees of freedom"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.2.043246",is_oa:!0,n_refs:37,n_refs_in_core:15,degree:29,community:2,deg_w:227,betweenness:.0019,pagerank:.00247,eigenvector:.0144},{id:136,oaid:"W3097716063",doi:"10.1103/physrevlett.127.110504",title:"Fermionic Partial Tomography via Classical Shadows",authors:[{name:"Andrew Zhao",institutions:["University of New Mexico"]},{name:"Nicholas C. Rubin",institutions:["Google (United States)"]},{name:"Akimasa Miyake",institutions:["University of New Mexico"]}],authorString:"Andrew Zhao; Nicholas C. Rubin; Akimasa Miyake",institutions:["Google (United States)","University of New Mexico"],countries:["US"],year:2021,journal:"Physical Review Letters",citations:154,abstract:"We propose a tomographic protocol for estimating any k-body reduced density matrix (k-RDM) of an n-mode fermionic state, a ubiquitous step in near-term quantum algorithms for simulating many-body physics, chemistry, and materials. Our approach extends the framework of classical shadows, a randomized approach to learning a collection of quantum-state properties, to the fermionic setting. Our sampling protocol uses randomized measurement settings generated by a discrete group of fermionic Gaussian unitaries, implementable with linear-depth circuits. We prove that estimating all k-RDM elements to additive precision ϵ requires on the order of (n/k)k^{3/2}log(n)/ϵ^{2} repeated state preparations, which is optimal up to the logarithmic factor. Furthermore, numerical calculations show that our protocol offers a substantial improvement in constant overheads for k≥2, as compared to prior deterministic strategies. We also adapt our method to particle-number symmetry, wherein the additional circuit depth may be halved at the cost of roughly 2-5 times more repetitions.",keywords:["RDM","Protocol","Gaussian","Logarithm","Density matrix","State"],concepts:["RDM","Protocol","Gaussian","Logarithm","Density matrix","State"],pdf_url:"https://arxiv.org/pdf/2010.16094",is_oa:!0,n_refs:155,n_refs_in_core:31,degree:48,community:1,deg_w:1111.5,betweenness:.0033,pagerank:.00792,eigenvector:.1086},{id:137,oaid:"W3026863321",doi:"10.1088/2058-9565/abd891",title:"Large gradients via correlation in random parameterized quantum circuits",authors:[{name:"Tyler Volkoff",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Tyler Volkoff; Patrick J. Coles",institutions:["Los Alamos National Laboratory"],countries:["US"],year:2021,journal:"Quantum Science and Technology",citations:152,abstract:'Abstract Scaling of variational quantum algorithms to large problem sizes requires efficient optimization of random parameterized quantum circuits. For such circuits with uncorrelated parameters, the presence of exponentially vanishing gradients in cost function landscapes is an obstacle to optimization by gradient descent methods. In this work, we prove that reducing the dimensionality of the parameter space by utilizing circuit modules containing spatially or temporally correlated gate layers can allow one to circumvent the vanishing gradient phenomenon. Examples are drawn from random separable circuits and asymptotically optimal variational versions of Grover’s algorithm based on the quantum alternating operator ansatz. In the latter scenario, our bounds on cost function variation imply a transition between vanishing gradients and efficient trainability as the number of layers is increased toward <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML" display="inline" overflow="scroll"> <mml:mi mathvariant="script">O</mml:mi> <mml:mrow> <mml:mo stretchy="false">(</mml:mo> <mml:mrow> <mml:msup> <mml:mrow> <mml:mn>2</mml:mn> </mml:mrow> <mml:mrow> <mml:mi>n</mml:mi> <mml:mo>/</mml:mo> <mml:mn>2</mml:mn> </mml:mrow> </mml:msup> </mml:mrow> <mml:mo stretchy="false">)</mml:mo> </mml:mrow> </mml:math> , the optimal oracle complexity of quantum unstructured search.',keywords:["Algorithm","Parameterized complexity","Quantum circuit","Quantum","Quantum algorithm","Quantum mechanics"],concepts:["Algorithm","Parameterized complexity","Quantum circuit","Quantum"],pdf_url:"https://arxiv.org/pdf/2005.12200",is_oa:!0,n_refs:109,n_refs_in_core:20,degree:47,community:0,deg_w:898,betweenness:.0033,pagerank:.00667,eigenvector:.087},{id:138,oaid:"W4285802213",doi:"10.1039/d2cs00203e",title:"Quantum machine learning for chemistry and physics",authors:[{name:"Manas Sajjan",institutions:["Purdue University West Lafayette"]},{name:"Junxu Li",institutions:["Purdue University West Lafayette"]},{name:"Raja Selvarajan",institutions:["Purdue University West Lafayette"]},{name:"Shree Hari Sureshbabu",institutions:["Purdue University West Lafayette"]},{name:"Sumit Suresh Kale",institutions:["Purdue University West Lafayette"]},{name:"Rishabh Gupta",institutions:["Purdue University West Lafayette"]},{name:"Vinit Singh",institutions:["Purdue University West Lafayette"]},{name:"Sabre Kais",institutions:["Purdue University West Lafayette"]}],authorString:"Manas Sajjan; Junxu Li; Raja Selvarajan; Shree Hari Sureshbabu; Sumit Suresh Kale; Rishabh Gupta; Vinit Singh; Sabre Kais",institutions:["Purdue University West Lafayette"],countries:["US"],year:2022,journal:"Chemical Society Reviews",citations:152,abstract:"Machine learning (ML) has emerged as a formidable force for identifying hidden but pertinent patterns within a given data set with the objective of subsequent generation of automated predictive behavior. In recent years, it is safe to conclude that ML and its close cousin, deep learning (DL), have ushered in unprecedented developments in all areas of physical sciences, especially chemistry. Not only classical variants of ML, even those trainable on near-term quantum hardwares have been developed with promising outcomes. Such algorithms have revolutionized materials design and performance of photovoltaics, electronic structure calculations of ground and excited states of correlated matter, computation of force-fields and potential energy surfaces informing chemical reaction dynamics, reactivity inspired rational strategies of drug designing and even classification of phases of matter with accurate identification of emergent criticality. In this review we shall explicate a subset of such topics and delineate the contributions made by both classical and quantum computing enhanced machine learning algorithms over the past few years. We shall not only present a brief overview of the well-known techniques but also highlight their learning strategies using statistical physical insight. The objective of the review is not only to foster exposition of the aforesaid techniques but also to empower and promote cross-pollination among future research in all areas of chemistry which can benefit from ML and in turn can potentially accelerate the growth of such algorithms.",keywords:["Set","Quantum","Quantum machine learning","Generality","Data science"],concepts:["Set","Quantum","Quantum machine learning","Generality","Data science"],pdf_url:"https://pubs.rsc.org/en/content/articlepdf/2022/cs/d2cs00203e",is_oa:!0,n_refs:658,n_refs_in_core:30,degree:45,community:0,deg_w:1044.5,betweenness:.0042,pagerank:.00796,eigenvector:.1104},{id:139,oaid:"W2990595942",doi:"10.1063/1.5141835",title:"Quantum orbital-optimized unitary coupled cluster methods in the strongly correlated regime: Can quantum algorithms outperform their classical equivalents?",authors:[{name:"Igor O. Sokolov",institutions:["IBM Research - Zurich"]},{name:"Panagiotis Kl. Barkoutsos",institutions:["IBM Research - Zurich"]},{name:"Pauline J. Ollitrault",institutions:["ETH Zurich","IBM Research - Zurich"]},{name:"Donny Greenberg",institutions:["IBM Research - Thomas J. Watson Research Center"]},{name:"Julia Rice",institutions:["IBM Research - Almaden"]},{name:"Marco Pistoia",institutions:["JPMorgan Chase & Co (United States)","IBM Research - Thomas J. Watson Research Center"]},{name:"Ivano Tavernelli",institutions:["IBM Research - Zurich"]}],authorString:"Igor O. Sokolov; Panagiotis Kl. Barkoutsos; Pauline J. Ollitrault; Donny Greenberg; Julia Rice; Marco Pistoia; Ivano Tavernelli",institutions:["ETH Zurich","IBM Research - Almaden","IBM Research - Thomas J. Watson Research Center","IBM Research - Zurich","JPMorgan Chase & Co (United States)"],countries:["CH","US"],year:2020,journal:"The Journal of Chemical Physics",citations:152,abstract:"The Coupled Cluster (CC) method is used to compute the electronic correlation energy in atoms and molecules and often leads to highly accurate results. However, due to its single-reference nature, standard CC in its projected form fails to describe quantum states characterized by strong electronic correlations and multi-reference projective methods become necessary. On the other hand, quantum algorithms for the solution of many-electron problems have also emerged recently. The quantum unitary variant of CC (UCC) with singles and doubles (q-UCCSD) is a popular wavefunction Ansatz for the variational quantum eigensolver algorithm. The variational nature of this approach can lead to significant advantages compared to its classical equivalent in the projected form, in particular, for the description of strong electronic correlation. However, due to the large number of gate operations required in q-UCCSD, approximations need to be introduced in order to make this approach implementable in a state-of-the-art quantum computer. In this work, we evaluate several variants of the standard q-UCCSD Ansatz in which only a subset of excitations is included. In particular, we investigate the singlet and pair q-UCCD approaches combined with orbital optimization. We show that these approaches can capture the dissociation/distortion profiles of challenging systems, such as H4, H2O, and N2 molecules, as well as the one-dimensional periodic Fermi–Hubbard chain. These results promote the future use of q-UCC methods for the solution of challenging electronic structure problems in quantum chemistry.",keywords:["Ansatz","Wave function","Coupled cluster","Quantum","Quantum algorithm","Unitary state","Electronic structure","Quantum computer"],concepts:["Ansatz","Wave function","Coupled cluster","Quantum","Quantum algorithm","Unitary state","Quantum mechanics","Electronic structure"],pdf_url:"https://arxiv.org/pdf/1911.10864",is_oa:!0,n_refs:66,n_refs_in_core:14,degree:30,community:1,deg_w:388.5,betweenness:.0012,pagerank:.00331,eigenvector:.0306},{id:140,oaid:"W2912395935",doi:"10.1103/physrevresearch.1.023025",title:"Variational quantum eigensolver with fewer qubits",authors:[{name:"Jin-Guo Liu",institutions:["Institute of Physics"]},{name:"Yi-Hong Zhang",institutions:["Tsinghua University"]},{name:"Yuan Wan",institutions:["Institute of Physics"]},{name:"Lei Wang",institutions:["Songshan Lake Materials Laboratory","Institute of Physics","University of Chinese Academy of Sciences"]}],authorString:"Jin-Guo Liu; Yi-Hong Zhang; Yuan Wan; Lei Wang",institutions:["Institute of Physics","Songshan Lake Materials Laboratory","Tsinghua University","University of Chinese Academy of Sciences"],countries:["CN"],year:2019,journal:"Physical Review Research",citations:149,abstract:"Scalability in a variatonal quantum eigensolver is limited by both the number of qubits available and the gradient vanishing problem. This paper shows several types of tensor network inspired circuit ansatzes. These are area law entangled, qubit efficient, and experimentally feasible while not having exponential contraction complexity problem as in their classical counterpart.",keywords:["Qubit","Quantum","Quantum computer","Scalability","Exponential function","Quantum algorithm","Tensor"],concepts:["Qubit","Quantum","Quantum computer","Scalability","Quantum mechanics","Exponential function","Quantum algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.1.023025",is_oa:!0,n_refs:58,n_refs_in_core:19,degree:41,community:2,deg_w:537.5,betweenness:.0029,pagerank:.00435,eigenvector:.0444},{id:141,oaid:"W4392595180",doi:"10.1038/s41467-024-46402-9",title:"Quantum many-body simulations on digital quantum computers: State-of-the-art and future challenges",authors:[{name:"Benedikt Fauseweh",institutions:["TU Dortmund University","Deutsches Zentrum für Luft- und Raumfahrt e. V. (DLR)"]}],authorString:"Benedikt Fauseweh",institutions:["Deutsches Zentrum für Luft- und Raumfahrt e. V. (DLR)","TU Dortmund University"],countries:["DE"],year:2024,journal:"Nature Communications",citations:145,abstract:"Simulating quantum many-body systems is a key application for emerging quantum processors. While analog quantum simulation has already demonstrated quantum advantage, its digital counterpart has recently become the focus of intense research interest due to the availability of devices that aim to realize general-purpose quantum computers. In this perspective, we give a selective overview of the currently pursued approaches, review the advances in digital quantum simulation by comparing non-variational with variational approaches and identify hardware and algorithmic challenges. Based on this review, the question arises: What are the most promising problems that can be tackled with digital quantum simulation? We argue that problems of a qualitative nature are much more suitable for near-term devices then approaches aiming purely for a quantitative accuracy improvement.",keywords:["Quantum","Perspective","Quantum computer","Focus","Key","Quantum simulator","Quantum state"],concepts:["Quantum","Perspective","Quantum computer","Focus","Key","Quantum simulator","Quantum state"],pdf_url:"https://www.nature.com/articles/s41467-024-46402-9.pdf",is_oa:!0,n_refs:219,n_refs_in_core:31,degree:45,community:3,deg_w:890,betweenness:.0061,pagerank:.0066,eigenvector:.1049},{id:142,oaid:"W3014684719",doi:"10.1038/s41534-022-00611-6",title:"Variational quantum state eigensolver",authors:[{name:"M. Cerezo",institutions:["Los Alamos National Laboratory"]},{name:"Kunal Sharma",institutions:["Louisiana State University","Los Alamos National Laboratory"]},{name:"Andrew Arrasmith",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"M. Cerezo; Kunal Sharma; Andrew Arrasmith; Patrick J. Coles",institutions:["Los Alamos National Laboratory","Louisiana State University"],countries:["US"],year:2022,journal:"npj Quantum Information",citations:145,abstract:'Abstract Extracting eigenvalues and eigenvectors of exponentially large matrices will be an important application of near-term quantum computers. The variational quantum eigensolver (VQE) treats the case when the matrix is a Hamiltonian. Here, we address the case when the matrix is a density matrix ρ . We introduce the variational quantum state eigensolver (VQSE), which is analogous to VQE in that it variationally learns the largest eigenvalues of ρ as well as a gate sequence V that prepares the corresponding eigenvectors. VQSE exploits the connection between diagonalization and majorization to define a cost function $$C={{{\\rm{Tr}}}}(\\tilde{\\rho }H)$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"> <mml:mrow> <mml:mi>C</mml:mi> <mml:mo>=</mml:mo> <mml:mi>Tr</mml:mi> <mml:mrow> <mml:mo>(</mml:mo> <mml:mrow> <mml:mover> <mml:mrow> <mml:mi>ρ</mml:mi> </mml:mrow> <mml:mrow> <mml:mo>̃</mml:mo> </mml:mrow> </mml:mover> <mml:mi>H</mml:mi> </mml:mrow> <mml:mo>)</mml:mo> </mml:mrow> </mml:mrow> </mml:math> where H is a non-degenerate Hamiltonian. Due to Schur-concavity, C is minimized when $$\\tilde{\\rho }=V\\rho {V}^{{\\dagger} }$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"> <mml:mrow> <mml:mover> <mml:mrow> <mml:mi>ρ</mml:mi> </mml:mrow> <mml:mrow> <mml:mo>̃</mml:mo> </mml:mrow> </mml:mover> <mml:mo>=</mml:mo> <mml:mi>V</mml:mi> <mml:mi>ρ</mml:mi> <mml:msup> <mml:mrow> <mml:mi>V</mml:mi> </mml:mrow> <mml:mrow> <mml:mo>†</mml:mo> </mml:mrow> </mml:msup> </mml:mrow> </mml:math> is diagonal in the eigenbasis of H . VQSE only requires a single copy of ρ (only n qubits) per iteration of the VQSE algorithm, making it amenable for near-term implementation. We heuristically demonstrate two applications of VQSE: (1) Principal component analysis, and (2) Error mitigation.',keywords:["Eigenvalues and eigenvectors","Hamiltonian","Quantum computer","Qubit","Degenerate energy levels","Hamiltonian matrix","Quantum","Quantum mechanics"],concepts:["Eigenvalues and eigenvectors","Hamiltonian","Quantum computer","Qubit","Degenerate energy levels","Hamiltonian matrix","Quantum","Quantum mechanics"],pdf_url:"https://www.nature.com/articles/s41534-022-00611-6.pdf",is_oa:!0,n_refs:103,n_refs_in_core:27,degree:45,community:0,deg_w:1067.5,betweenness:.0019,pagerank:.00759,eigenvector:.1103},{id:143,oaid:"W2974445049",doi:"10.1088/1367-2630/ab867b",title:"A non-orthogonal variational quantum eigensolver",authors:[{name:"William J Huggins",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"Joonho Lee",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"Unpil Baek",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"Bryan O’Gorman",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"K Birgitta Whaley",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]}],authorString:"William J Huggins; Joonho Lee; Unpil Baek; Bryan O’Gorman; K Birgitta Whaley",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"],countries:["US"],year:2020,journal:"New Journal of Physics",citations:145,abstract:"Variational algorithms for strongly correlated chemical and materials systems are one of the most promising applications of near-term quantum computers. We present an extension to the variational quantum eigensolver that approximates the ground state of a system by solving a generalized eigenvalue problem in a subspace spanned by a collection of parametrized quantum states. This allows for the systematic improvement of a logical wavefunction ansatz without a significant increase in circuit complexity. To minimize the circuit complexity of this approach, we propose a strategy for efficiently measuring the Hamiltonian and overlap matrix elements between states parametrized by circuits that commute with the total particle number operator. This strategy doubles the size of the state preparation circuits but not their depth, while adding a small number of additional two-qubit gates relative to standard variational quantum eigensolver. We also propose a classical Monte Carlo scheme to estimate the uncertainty in the ground state energy caused by a finite number of measurements of the matrix elements. We explain how this Monte Carlo procedure can be extended to adaptively schedule the required measurements, reducing the number of circuit executions necessary for a given accuracy. We apply these ideas to two model strongly correlated systems, a square configuration of H 4 and the -system of hexatriene (C 6 H 8 ).",keywords:["Ansatz","Hamiltonian","Wave function","Quantum Monte Carlo","Eigenvalues and eigenvectors","Ground state","Quantum","Subspace topology"],concepts:["Ansatz","Hamiltonian","Wave function","Quantum Monte Carlo","Eigenvalues and eigenvectors","Ground state","Quantum"],pdf_url:"https://iopscience.iop.org/article/10.1088/1367-2630/ab867b/pdf",is_oa:!0,n_refs:57,n_refs_in_core:16,degree:38,community:1,deg_w:545.5,betweenness:.0015,pagerank:.00425,eigenvector:.0522},{id:144,oaid:"W3081061531",doi:"10.1103/prxquantum.2.030334",title:"Simulating 2D Effects in Lattice Gauge Theories on a Quantum Computer",authors:[{name:"Danny Paulson",institutions:["University of Waterloo"]},{name:"Luca Dellantonio",institutions:["University of Waterloo"]},{name:"Jan F. Haase",institutions:["University of Waterloo","Universität Ulm"]},{name:"Alessio Celi",institutions:["Universitat Autònoma de Barcelona","Austrian Academy of Sciences","Universität Innsbruck"]},{name:"Angus Kan",institutions:["University of Waterloo"]},{name:"Andrew Jena",institutions:["University of Waterloo"]},{name:"Christian Kokail",institutions:["Austrian Academy of Sciences","Universität Innsbruck"]},{name:"Rick van Bijnen",institutions:["Austrian Academy of Sciences","Universität Innsbruck"]},{name:"Karl Jansen",institutions:["John von Neumann Institute for Computing"]},{name:"Peter Zoller",institutions:["Austrian Academy of Sciences","Universität Innsbruck"]},{name:"Christine A. Muschik",institutions:["University of Waterloo","Perimeter Institute"]}],authorString:"Danny Paulson; Luca Dellantonio; Jan F. Haase; Alessio Celi; Angus Kan; Andrew Jena; Christian Kokail; Rick van Bijnen; Karl Jansen; Peter Zoller; Christine A. Muschik",institutions:["Austrian Academy of Sciences","John von Neumann Institute for Computing","Perimeter Institute","Universitat Autònoma de Barcelona","University of Waterloo","Universität Innsbruck","Universität Ulm"],countries:["AT","CA","DE","ES"],year:2021,journal:"PRX Quantum",citations:142,abstract:"Quantum computing is in its greatest upswing, with so-called noisy-intermediate-scale-quantum devices heralding the computational power to be expected in the near future. While the field is progressing toward quantum advantage, quantum computers already have the potential to tackle classically intractable problems. Here, we consider gauge theories describing fundamental-particle interactions. On the way to their full-fledged quantum simulations, the challenge of limited resources on near-term quantum devices has to be overcome. We propose an experimental quantum simulation scheme to study ground-state properties in two-dimensional quantum electrodynamics (2D QED) using existing quantum technology. Our protocols can be adapted to larger lattices and offer the perspective to connect the lattice simulation to low-energy observable quantities, e.g., the hadron spectrum, in the continuum theory. By including both dynamical matter and a nonminimal gauge-field truncation, we provide the novel opportunity to observe 2D effects on present-day quantum hardware. More specifically, we present two variational-quantumeigensolver-(VQE) based protocols for the study of magnetic field effects and for taking an important first step toward computing the running coupling of QED. For both instances, we include variational quantum circuits for qubit-based hardware. We simulate the proposed VQE experiments classically to calculate the required measurement budget under realistic conditions. While this feasibility analysis is done for trapped ions, our approach can be directly adapted to other platforms. The techniques presented here, combined with advancements in quantum hardware, pave the way for reaching beyond the capabilities of classical simulations.",keywords:["Quantum simulator","Quantum computer","Open quantum system","Observable","Quantum","Quantum information","Quantum technology","Quantum algorithm"],concepts:["Quantum simulator","Quantum computer","Open quantum system","Observable","Quantum","Quantum information","Quantum technology"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.030334",is_oa:!0,n_refs:94,n_refs_in_core:14,degree:31,community:3,deg_w:352,betweenness:.0024,pagerank:.00315,eigenvector:.0282},{id:145,oaid:"W3201507639",doi:null,title:"Exponential error suppression for near-term quantum devices",authors:[{name:"Koczor, B",institutions:["University of Oxford"]}],authorString:"Koczor, B",institutions:["University of Oxford"],countries:["GB"],year:2021,journal:"Oxford University Research Archive (ORA) (University of Oxford)",citations:141,abstract:"Suppressing noise in physical systems is of fundamental importance. As quantum computers mature, quantum error correcting codes (QECs) will be adopted in order to suppress errors to any desired level. However in the noisy, intermediate-scale quantum (NISQ) era, the complexity and scale required to adopt even the smallest QEC is prohibitive: a single logical qubit needs to be encoded into many thousands of physical qubits. Here we show that, for the crucial case of estimating expectation values of observables (key to almost all NISQ algorithms) one can indeed achieve an effective exponential suppression. We take n independently prepared circuit outputs to create a state whose symmetries prevent errors from contributing bias to the expected value. The approach is very well suited for current and near-term quantum devices as it is modular in the main computation and requires only a shallow circuit that bridges the n copies immediately prior to measurement. Using no more than four circuit copies, we confirm error suppression below 10-6 for circuits consisting of several hundred noisy gates (2-qubit gate error 0.5%) in numerical simulations validating our approach.",keywords:["Term","Exponential function","Quantum","Exponential growth","Statistical physics","Quantum mechanics"],concepts:["Term","Exponential function","Quantum","Exponential growth","Statistical physics","Quantum mechanics"],pdf_url:null,is_oa:!1,n_refs:123,n_refs_in_core:16,degree:33,community:2,deg_w:645,betweenness:.0013,pagerank:.00481,eigenvector:.0636},{id:146,oaid:"W2782569940",doi:"10.1088/1367-2630/aab919",title:"Application of fermionic marginal constraints to hybrid quantum algorithms",authors:[{name:"Nicholas C Rubin",institutions:["Rigetti Computing (United States)"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Jarrod McClean",institutions:["Google (United States)"]}],authorString:"Nicholas C Rubin; Ryan Babbush; Jarrod McClean",institutions:["Google (United States)","Rigetti Computing (United States)"],countries:["US"],year:2018,journal:"New Journal of Physics",citations:139,abstract:"Many quantum algorithms, including recently proposed hybrid classical/quantum algorithms, make use of restricted tomography of the quantum state that measures the reduced density matrices, or marginals, of the full state. The most straightforward approach to this algorithmic step estimates each component of the marginal independently without making use of the algebraic and geometric structure of the marginals. Within the field of quantum chemistry, this structure is termed the fermionic n -representability conditions, and is supported by a vast amount of literature on both theoretical and practical results related to their approximations. In this work, we introduce these conditions in the language of quantum computation, and utilize them to develop several techniques to accelerate and improve practical applications for quantum chemistry on quantum computers. As a general result, we demonstrate how these marginals concentrate to diagonal quantities when measured on random quantum states. We also show that one can use fermionic n -representability conditions to reduce the total number of measurements required by more than an order of magnitude for medium sized systems in chemistry. As a practical demonstration, we simulate an efficient restoration of the physicality of energy curves for the dilation of a four qubit diatomic hydrogen system in the presence of three distinct one qubit error channels, providing evidence these techniques are useful for pre-fault tolerant quantum chemistry experiments.",keywords:["Quantum","Quantum algorithm","Qubit","Quantum error correction","Quantum computer","Quantum state","Quantum operation","Quantum process"],concepts:["Quantum","Quantum algorithm","Qubit","Quantum error correction","Quantum computer","Statistical physics","Quantum mechanics"],pdf_url:"https://iopscience.iop.org/article/10.1088/1367-2630/aab919/pdf",is_oa:!0,n_refs:101,n_refs_in_core:8,degree:43,community:1,deg_w:843,betweenness:.0016,pagerank:.00606,eigenvector:.0709},{id:147,oaid:"W2956731923",doi:"10.21468/scipostphys.6.3.029",title:"Efficient variational simulation of non-trivial quantum states",authors:[{name:"Wen Wei Ho",institutions:["Harvard University","Harvard University Press"]},{name:"Timothy H. Hsieh",institutions:["University of California, Santa Barbara","Perimeter Institute"]}],authorString:"Wen Wei Ho; Timothy H. Hsieh",institutions:["Harvard University","Harvard University Press","Perimeter Institute","University of California, Santa Barbara"],countries:["CA","US"],year:2019,journal:"SciPost Physics",citations:139,abstract:'We provide an efficient and general route for preparing non-trivial quantum states that are not adiabatically connected to unentangled product states. Our approach is a hybrid quantum-classical variational protocol that incorporates a feedback loop between a quantum simulator and a classical computer, and is experimentally realizable on near-term quantum devices of synthetic quantum systems. We find explicit protocols which prepare with perfect fidelities (i) the Greenberger-Horne-Zeilinger (GHZ) state, (ii) a quantum critical state, and (iii) a topologically ordered state, with \\bm{L} <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML" display="inline"> <mml:mstyle mathvariant="bold"> <mml:mi>𝐋</mml:mi> </mml:mstyle> </mml:math> variational parameters and physical runtimes \\bm{T} <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML" display="inline"> <mml:mstyle mathvariant="bold"> <mml:mi>𝐓</mml:mi> </mml:mstyle> </mml:math> that scale linearly with the system size \\bm{L} <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML" display="inline"> <mml:mstyle mathvariant="bold"> <mml:mi>𝐋</mml:mi> </mml:mstyle> </mml:math> . We furthermore conjecture and support numerically that our protocol can prepare, with perfect fidelity and similar operational costs, the ground state of every point in the one dimensional transverse field Ising model phase diagram. Besides being practically useful, our results also illustrate the utility of such variational Ansätze as good descriptions of non-trivial states of matter.',keywords:["Quantum","Ising model","Quantum computer","Quantum state","Quantum algorithm","Conjecture","Statistical physics"],concepts:["Quantum","Ising model","Quantum computer","Quantum state","Quantum algorithm","Conjecture","Statistical physics"],pdf_url:"https://scipost.org/10.21468/SciPostPhys.6.3.029/pdf",is_oa:!0,n_refs:56,n_refs_in_core:3,degree:24,community:0,deg_w:183.5,betweenness:.0015,pagerank:.00207,eigenvector:.0158},{id:148,oaid:"W2998262898",doi:"10.1103/physrevresearch.2.033212",title:"Quantum adversarial machine learning",authors:[{name:"Sirui Lu",institutions:["Max Planck Institute of Quantum Optics","Tsinghua University"]},{name:"Lu-Ming Duan",institutions:["Tsinghua University"]},{name:"Dong-Ling Deng",institutions:["ShangHai JiAi Genetics & IVF Institute","Tsinghua University"]}],authorString:"Sirui Lu; Lu-Ming Duan; Dong-Ling Deng",institutions:["Max Planck Institute of Quantum Optics","ShangHai JiAi Genetics & IVF Institute","Tsinghua University"],countries:["CN","DE"],year:2020,journal:"Physical Review Research",citations:138,abstract:"This work uncovers the vulnerability aspect for quantum machine learning, by showing that quantum classifiers are vulnerable to adversarial perturbations. The authors give generic recipes on how to generate adversarial perturbations and mitigate the vulnerability problem in various adversarial scenarios.",keywords:["Adversarial system","Vulnerability","Quantum","Work","Key","Vulnerability assessment"],concepts:["Adversarial system","Vulnerability","Quantum","Work","Theoretical computer science"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.2.033212",is_oa:!0,n_refs:96,n_refs_in_core:16,degree:30,community:0,deg_w:343.5,betweenness:.0018,pagerank:.00349,eigenvector:.0127},{id:149,oaid:"W2907242142",doi:"10.1103/physrevresearch.1.013006",title:"Methodology for replacing indirect measurements with direct measurements",authors:[{name:"Kosuke Mitarai",institutions:["The University of Osaka"]},{name:"Keisuke Fujii",institutions:["Kyoto University","Japan Science and Technology Agency","The University of Osaka"]}],authorString:"Kosuke Mitarai; Keisuke Fujii",institutions:["Japan Science and Technology Agency","Kyoto University","The University of Osaka"],countries:["JP"],year:2019,journal:"Physical Review Research",citations:137,abstract:"This work investigates the mechanism by which indirect measurements can be replaced by direct ones in quantum algorithms. The authors propose a protocol to simplify the measurement of correlators in the quantum simulation and derivatives with respect to the parameters in the variational algorithms, by reducing the required number of gates.",keywords:["Hadamard transform","Quantum","Metric","Algorithm","Quantum phase estimation algorithm","Quantum algorithm","Hessian matrix"],concepts:["Hadamard transform","Quantum","Metric","Algorithm","Quantum phase estimation algorithm","Quantum algorithm","Hessian matrix"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.1.013006",is_oa:!0,n_refs:35,n_refs_in_core:10,degree:40,community:2,deg_w:452.5,betweenness:.0021,pagerank:.00379,eigenvector:.0374},{id:150,oaid:"W4401815647",doi:"10.1038/s41467-024-49909-3",title:"A Lie algebraic theory of barren plateaus for deep parameterized quantum circuits",authors:[{name:"Michael Ragone",institutions:["University of California, Davis"]},{name:"Bojko Bakalov",institutions:["North Carolina State University"]},{name:"Frédéric Sauvage",institutions:["Los Alamos National Laboratory"]},{name:"A. F. Kemper",institutions:["North Carolina State University"]},{name:"Carlos Ortiz Marrero",institutions:["North Carolina State University","Pacific Northwest National Laboratory"]},{name:"Martín Larocca",institutions:["Los Alamos National Laboratory"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory","Los Alamos National Security (United States)"]}],authorString:"Michael Ragone; Bojko Bakalov; Frédéric Sauvage; A. F. Kemper; Carlos Ortiz Marrero; Martín Larocca; M. Cerezo",institutions:["Los Alamos National Laboratory","Los Alamos National Security (United States)","North Carolina State University","Pacific Northwest National Laboratory","University of California, Davis"],countries:["US"],year:2024,journal:"Nature Communications",citations:137,abstract:"Variational quantum computing schemes train a loss function by sending an initial state through a parametrized quantum circuit, and measuring the expectation value of some operator. Despite their promise, the trainability of these algorithms is hindered by barren plateaus (BPs) induced by the expressiveness of the circuit, the entanglement of the input data, the locality of the observable, or the presence of noise. Up to this point, these sources of BPs have been regarded as independent. In this work, we present a general Lie algebraic theory that provides an exact expression for the variance of the loss function of sufficiently deep parametrized quantum circuits, even in the presence of certain noise models. Our results allow us to understand under one framework all aforementioned sources of BPs. This theoretical leap resolves a standing conjecture about a connection between loss concentration and the dimension of the Lie algebra of the circuit’s generators. The barren plateau problem represents one of the major bottlenecks for parametrized quantum circuits algorithms. Here, the authors study the known sources of BP using the lens of Lie algebraic theory, finding an expression of the variance of the loss function depending on the dynamical Lie algebra of the circuit.",keywords:["Observable","Lie algebra","Parameterized complexity","Algebraic number","Pure mathematics","Algebra over a field"],concepts:["Observable","Lie algebra","Parameterized complexity","Algebraic number","Pure mathematics","Algebra over a field"],pdf_url:"https://www.nature.com/articles/s41467-024-49909-3.pdf",is_oa:!0,n_refs:80,n_refs_in_core:14,degree:28,community:0,deg_w:344,betweenness:.001,pagerank:.00314,eigenvector:.0291},{id:151,oaid:"W3105890456",doi:"10.1103/physrevx.11.031057",title:"Exponential Error Suppression for Near-Term Quantum Devices",authors:[{name:"Bálint Koczor",institutions:["University of Oxford"]}],authorString:"Bálint Koczor",institutions:["University of Oxford"],countries:["GB"],year:2021,journal:"Physical Review X",citations:136,abstract:"Suppressing noise in physical systems is of fundamental importance. As quantum computers mature, quantum error correcting codes (QECs) will be adopted in order to suppress errors to any desired level. However in the noisy, intermediate-scale quantum (NISQ) era, the complexity and scale required to adopt even the smallest QEC is prohibitive: a single logical qubit needs to be encoded into many thousands of physical qubits. Here we show that, for the crucial case of estimating expectation values of observables (key to almost all NISQ algorithms) one can indeed achieve an effective exponential suppression. We take n independently prepared circuit outputs to create a state whose symmetries prevent errors from contributing bias to the expected value. The approach is very well suited for current and near-term quantum devices as it is modular in the main computation and requires only a shallow circuit that bridges the n copies immediately prior to measurement. Using no more than four circuit copies, we confirm error suppression below 10 -6 for circuits consisting of several hundred noisy gates (2-qubit gate error 0.5%) in numerical simulations validating our approach.",keywords:["Quantum computer","Quantum error correction","Observable","Quantum","Quantum gate","Qubit","Quantum circuit","Noise"],concepts:["Quantum computer","Quantum error correction","Observable","Quantum","Quantum gate","Qubit","Quantum circuit"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.11.031057",is_oa:!0,n_refs:81,n_refs_in_core:22,degree:37,community:2,deg_w:547,betweenness:.0019,pagerank:.00433,eigenvector:.0373},{id:152,oaid:"W2890940799",doi:"10.1103/physrevapplied.11.044092",title:"Gate-Efficient Simulation of Molecular Eigenstates on a Quantum Computer",authors:[{name:"M. Ganzhorn",institutions:["IBM Research - Zurich"]},{name:"D.J. Egger",institutions:["IBM Research - Zurich"]},{name:"P. Barkoutsos",institutions:["IBM Research - Zurich"]},{name:"P. Ollitrault",institutions:["IBM Research - Zurich"]},{name:"G. Salis",institutions:["IBM Research - Zurich"]},{name:"N. Moll",institutions:["IBM Research - Zurich"]},{name:"M. Roth",institutions:["Forschungszentrum Jülich","RWTH Aachen University"]},{name:"A. Fuhrer",institutions:["IBM Research - Zurich"]},{name:"P. Mueller",institutions:["IBM Research - Zurich"]},{name:"S. Woerner",institutions:["IBM Research - Zurich"]},{name:"I. Tavernelli",institutions:["IBM Research - Zurich"]},{name:"S. Filipp",institutions:["IBM Research - Zurich"]}],authorString:"M. Ganzhorn; D.J. Egger; P. Barkoutsos; P. Ollitrault; G. Salis; N. Moll; M. Roth; A. Fuhrer; P. Mueller; S. Woerner; I. Tavernelli; S. Filipp",institutions:["Forschungszentrum Jülich","IBM Research - Zurich","RWTH Aachen University"],countries:["CH","DE"],year:2019,journal:"Physical Review Applied",citations:133,abstract:"Calculating the energy spectra of molecules is a key computational problem, and one where a quantum computer can shine. For present-day quantum computers, short quantum algorithms that finish within the coherence time of the system must be designed. Thus the authors present a set of gates tailored to the problem at hand, which can be directly implemented in hardware. Experiments show that exchange-type gates that conserve the number of excitations are ideally suited for calculations in quantum chemistry. The team determines the energy spectrum of molecular hydrogen using a variational quantum eigensolver, plus a method from computational chemistry to compute the excited states.",keywords:["Coherence","Excited state","Quantum","Quantum computer","Quantum simulator","Eigenvalues and eigenvectors","Quantum error correction","Quantum algorithm"],concepts:["Coherence","Excited state","Quantum","Quantum mechanics","Quantum computer","Quantum simulator","Eigenvalues and eigenvectors"],pdf_url:"https://arxiv.org/pdf/1809.05057",is_oa:!0,n_refs:37,n_refs_in_core:9,degree:38,community:1,deg_w:524,betweenness:.002,pagerank:.00411,eigenvector:.0432},{id:153,oaid:"W2966171903",doi:"10.1103/physreva.100.010302",title:"Experimental error mitigation via symmetry verification in a variational quantum eigensolver",authors:[{name:"Ramiro Sagastizabal",institutions:["QuTech","Delft University of Technology"]},{name:"Xavier Bonet-Monroig",institutions:["Leiden University","QuTech","Delft University of Technology"]},{name:"Meenakshi Singh",institutions:["QuTech","Delft University of Technology"]},{name:"M. A. Rol",institutions:["QuTech","Delft University of Technology"]},{name:"Cornelis Christiaan Bultink",institutions:["QuTech","Delft University of Technology"]},{name:"Xiang Fu",institutions:["QuTech","Delft University of Technology"]},{name:"Caspar Price",institutions:["Leiden University"]},{name:"Viacheslav Ostroukh",institutions:["QuTech","Delft University of Technology"]},{name:"Nandini Muthusubramanian",institutions:["QuTech","Delft University of Technology"]},{name:"Alessandro Bruno",institutions:["QuTech","Delft University of Technology"]},{name:"Marc Beekman",institutions:["QuTech","Delft University of Technology"]},{name:"Nadia Haider",institutions:["Netherlands Organisation for Applied Scientific Research","QuTech","Delft University of Technology"]},{name:"Thomas E. O’Brien",institutions:["Leiden University"]},{name:"L. DiCarlo",institutions:["QuTech","Delft University of Technology"]}],authorString:"Ramiro Sagastizabal; Xavier Bonet-Monroig; Meenakshi Singh; M. A. Rol; Cornelis Christiaan Bultink; Xiang Fu; Caspar Price; Viacheslav Ostroukh; Nandini Muthusubramanian; Alessandro Bruno; Marc Beekman; Nadia Haider et al.",institutions:["Delft University of Technology","Leiden University","Netherlands Organisation for Applied Scientific Research","QuTech"],countries:["NL"],year:2019,journal:"Physical review. A/Physical review, A",citations:132,abstract:"Variational quantum eigensolvers offer a small-scale testbed to demonstrate the performance of error mitigation techniques with low experimental overhead. We present successful error mitigation by applying the recently proposed symmetry verification technique to the experimental estimation of the ground-state energy and ground state of the hydrogen molecule. A finely adjustable exchange interaction between two qubits in a circuit QED processor efficiently prepares variational ansatz states in the single-excitation subspace respecting the parity symmetry of the qubit-mapped Hamiltonian. Symmetry verification improves the energy and state estimates by mitigating the effects of qubit relaxation and residual qubit excitation, which violate the symmetry. A full-density-matrix simulation matching the experiment dissects the contribution of these mechanisms from other calibrated error sources. Enforcing positivity of the measured density matrix via scalable convex optimization correlates the energy and state estimate improvements when using symmetry verification, with interesting implications for determining system properties beyond the ground-state energy.",keywords:["Qubit","Ansatz","Hamiltonian","Ground state","Quantum","Density matrix","Symmetry"],concepts:["Qubit","Ansatz","Hamiltonian","Ground state","Quantum","Density matrix","Symmetry"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.100.010302",is_oa:!0,n_refs:47,n_refs_in_core:18,degree:48,community:2,deg_w:906.5,betweenness:.0023,pagerank:.00649,eigenvector:.084},{id:154,oaid:"W4221051274",doi:"10.1103/prxquantum.3.010345",title:"Quantum Error Mitigation as a Universal Error Reduction Technique: Applications from the NISQ to the Fault-Tolerant Quantum Computing Eras",authors:[{name:"Yasunari Suzuki",institutions:["NTT (Japan)","Japan Science and Technology Agency"]},{name:"Suguru Endo",institutions:["NTT (Japan)","Japan Science and Technology Agency"]},{name:"Keisuke Fujii",institutions:["RIKEN Center for Emergent Matter Science","The University of Osaka"]},{name:"Yuuki Tokunaga",institutions:["NTT (Japan)"]}],authorString:"Yasunari Suzuki; Suguru Endo; Keisuke Fujii; Yuuki Tokunaga",institutions:["Japan Science and Technology Agency","NTT (Japan)","RIKEN Center for Emergent Matter Science","The University of Osaka"],countries:["JP"],year:2022,journal:"PRX Quantum",citations:132,abstract:"A computational architecture where quantum error mitigation and correction contribute equally is proposed, leading to a scheme that can dramatically alleviate computational overheads and hasten the arrival of the fault-tolerant era.",keywords:["Quantum computer","Quantum error correction","Qubit","Scalability","Error detection and correction","Computer engineering","Quantum"],concepts:["Quantum computer","Quantum error correction","Qubit","Scalability","Error detection and correction","Computer engineering","Quantum"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.3.010345",is_oa:!0,n_refs:90,n_refs_in_core:12,degree:27,community:2,deg_w:272.5,betweenness:.0018,pagerank:.00268,eigenvector:.0167},{id:155,oaid:"W4318983914",doi:"10.22331/q-2023-02-02-912",title:"TensorCircuit: a Quantum Software Framework for the NISQ Era",authors:[{name:"Shi‐Xin Zhang",institutions:["Tencent (China)"]},{name:"Jonathan Allcock",institutions:["Tencent (China)"]},{name:"Zhou‐Quan Wan",institutions:["Tencent (China)","Tsinghua University"]},{name:"Shuo Liu",institutions:["Tencent (China)","Tsinghua University"]},{name:"Jiace Sun",institutions:["California Institute of Technology"]},{name:"Hao Yu",institutions:["McGill University"]},{name:"Xing-Han Yang",institutions:["Tencent (China)","Shenzhen Baoan High School Group"]},{name:"Jiezhong Qiu",institutions:["Tencent (China)"]},{name:"Zhaofeng Ye",institutions:["Tencent (China)"]},{name:"Yuqin Chen",institutions:["Tencent (China)"]},{name:"Chee‐Kong Lee",institutions:["KLA (United States)"]},{name:"Yi-Cong Zheng",institutions:["Tencent (China)"]},{name:"Shao-Kai Jian",institutions:["Brandeis University"]},{name:"Hong Yao",institutions:["Tsinghua University"]},{name:"Chang‐Yu Hsieh",institutions:["Tencent (China)"]},{name:"Shengyu Zhang",institutions:["Tencent (China)"]}],authorString:"Shi‐Xin Zhang; Jonathan Allcock; Zhou‐Quan Wan; Shuo Liu; Jiace Sun; Hao Yu; Xing-Han Yang; Jiezhong Qiu; Zhaofeng Ye; Yuqin Chen; Chee‐Kong Lee; Yi-Cong Zheng et al.",institutions:["Brandeis University","California Institute of Technology","KLA (United States)","McGill University","Shenzhen Baoan High School Group","Tencent (China)","Tsinghua University"],countries:["CA","CN","US"],year:2023,journal:"Quantum",citations:132,abstract:"TensorCircuit is an open source quantum circuit simulator based on tensor network contraction, designed for speed, flexibility and code efficiency. Written purely in Python, and built on top of industry-standard machine learning frameworks, TensorCircuit supports automatic differentiation, just-in-time compilation, vectorized parallelism and hardware acceleration. These features allow TensorCircuit to simulate larger and more complex quantum circuits than existing simulators, and are especially suited to variational algorithms based on parameterized quantum circuits. TensorCircuit enables orders of magnitude speedup for various quantum simulation tasks compared to other common quantum software, and can simulate up to 600 qubits with moderate circuit depth and low-dimensional connectivity. With its time and space efficiency, flexible and extensible architecture and compact, user-friendly API, TensorCircuit has been built to facilitate the design, simulation and analysis of quantum algorithms in the Noisy Intermediate-Scale Quantum (NISQ) era.",keywords:["Speedup","Quantum circuit","Quantum computer","Computational science","Qubit","Python","Quantum"],concepts:["Speedup","Quantum circuit","Quantum computer","Computational science","Qubit","Python","Quantum"],pdf_url:"https://quantum-journal.org/papers/q-2023-02-02-912/pdf/",is_oa:!0,n_refs:68,n_refs_in_core:12,degree:26,community:0,deg_w:246,betweenness:.0012,pagerank:.00253,eigenvector:.0203},{id:156,oaid:"W4284976704",doi:"10.1103/physreva.106.010101",title:"Hybrid quantum-classical algorithms in the noisy intermediate-scale quantum era and beyond",authors:[{name:"Adam Callison",institutions:["University College London"]},{name:"Nicholas Chancellor",institutions:["Durham University"]}],authorString:"Adam Callison; Nicholas Chancellor",institutions:["Durham University","University College London"],countries:["GB"],year:2022,journal:"Physical review. A/Physical review, A",citations:129,abstract:"The coming era of quantum computing promises to revolutionize computation, but, given the efficiency of many classical routines as well as quantum hardware limitations, calls to quantum devices are and will continue to be used as subroutines in larger, hybrid quantum-classical algorithms. This Perspective explores the essential differences between pure and hybrid quantum algorithms, discusses some examples, and frames the future of hybrid quantum-classical algorithms in its natural context of classical heterotic computing.",keywords:["Quantum computer","Quantum sort","Quantum algorithm","Abstraction","Quantum","Algorithm","Perspective"],concepts:["Quantum computer","Quantum sort","Quantum algorithm","Abstraction","Quantum","Algorithm","Perspective"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.106.010101",is_oa:!0,n_refs:142,n_refs_in_core:14,degree:28,community:0,deg_w:324,betweenness:.0015,pagerank:.00292,eigenvector:.0261},{id:157,oaid:"W3205120504",doi:"10.1038/s42005-021-00730-0",title:"Qubit-excitation-based adaptive variational quantum eigensolver",authors:[{name:"Yordan S. Yordanov",institutions:["University of Cambridge","Hitachi (United Kingdom)"]},{name:"V. Armaos",institutions:["University of Patras"]},{name:"Crispin H. W. Barnes",institutions:["University of Cambridge"]},{name:"David R. M. Arvidsson-Shukur",institutions:["University of Cambridge","Hitachi (United Kingdom)"]}],authorString:"Yordan S. Yordanov; V. Armaos; Crispin H. W. Barnes; David R. M. Arvidsson-Shukur",institutions:["Hitachi (United Kingdom)","University of Cambridge","University of Patras"],countries:["GB","GR"],year:2021,journal:"Communications Physics",citations:129,abstract:'Abstract Molecular simulations with the variational quantum eigensolver (VQE) are a promising application for emerging noisy intermediate-scale quantum computers. Constructing accurate molecular ansätze that are easy to optimize and implemented by shallow quantum circuits is crucial for the successful implementation of such simulations. Ansätze are, generally, constructed as series of fermionic-excitation evolutions. Instead, we demonstrate the usefulness of constructing ansätze with "qubit-excitation evolutions”, which, contrary to fermionic excitation evolutions, obey "qubit commutation relations”. We show that qubit excitation evolutions, despite the lack of some of the physical features of fermionic excitation evolutions, accurately construct ansätze, while requiring asymptotically fewer gates. Utilizing qubit excitation evolutions, we introduce the qubit-excitation-based adaptive (QEB-ADAPT)-VQE protocol. The QEB-ADAPT-VQE is a modification of the ADAPT-VQE that performs molecular simulations using a problem-tailored ansatz, grown iteratively by appending evolutions of qubit excitation operators. By performing classical numerical simulations for small molecules, we benchmark the QEB-ADAPT-VQE, and compare it against the original fermionic-ADAPT-VQE and the qubit-ADAPT-VQE. In terms of circuit efficiency and convergence speed, we demonstrate that the QEB-ADAPT-VQE outperforms the qubit-ADAPT-VQE, which to our knowledge was the previous most circuit-efficient scalable VQE protocol for molecular simulations.',keywords:["Benchmark","Qubit","Excitation","Quantum","Convergence","Scalability","Construct","Quantum computer"],concepts:["Benchmark","Qubit","Excitation","Quantum","Convergence","Scalability","Construct"],pdf_url:"https://www.nature.com/articles/s42005-021-00730-0.pdf",is_oa:!0,n_refs:55,n_refs_in_core:17,degree:33,community:1,deg_w:486,betweenness:.0013,pagerank:.00391,eigenvector:.0427},{id:158,oaid:"W2995067406",doi:"10.22331/q-2020-10-11-341",title:"Yao.jl: Extensible, Efficient Framework for Quantum Algorithm Design",authors:[{name:"Xiu-Zhe Luo",institutions:["University of Waterloo","Perimeter Institute","Chinese Academy of Sciences","Institute of Theoretical Physics","Institute of Physics"]},{name:"Jin-Guo Liu",institutions:["Institute of Physics"]},{name:"Pan Zhang",institutions:["Chinese Academy of Sciences","Institute of Theoretical Physics"]},{name:"Lei Wang",institutions:["Songshan Lake Materials Laboratory","Institute of Physics"]}],authorString:"Xiu-Zhe Luo; Jin-Guo Liu; Pan Zhang; Lei Wang",institutions:["Chinese Academy of Sciences","Institute of Physics","Institute of Theoretical Physics","Perimeter Institute","Songshan Lake Materials Laboratory","University of Waterloo"],countries:["CA","CN"],year:2020,journal:"Quantum",citations:128,abstract:'We introduce <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mtext mathvariant="monospace">Yao</mml:mtext></mml:mrow></mml:math>, an extensible, efficient open-source framework for quantum algorithm design. <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mtext mathvariant="monospace">Yao</mml:mtext></mml:mrow></mml:math> features generic and differentiable programming of quantum circuits. It achieves state-of-the-art performance in simulating small to intermediate-sized quantum circuits that are relevant to near-term applications. We introduce the design principles and critical techniques behind <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mtext mathvariant="monospace">Yao</mml:mtext></mml:mrow></mml:math>. These include the quantum block intermediate representation of quantum circuits, a builtin automatic differentiation engine optimized for reversible computing, and batched quantum registers with GPU acceleration. The extensibility and efficiency of <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow class="MJX-TeXAtom-ORD"><mml:mtext mathvariant="monospace">Yao</mml:mtext></mml:mrow></mml:math> help boost innovation in quantum algorithm design.',keywords:["Quantum algorithm","Quantum","Quantum circuit","Quantum computer","Quantum phase estimation algorithm","Quantum gate","Representation","Quantum network"],concepts:["Quantum algorithm","Quantum","Quantum circuit","Quantum computer","Quantum phase estimation algorithm","Quantum gate","Representation"],pdf_url:"https://quantum-journal.org/papers/q-2020-10-11-341/pdf/",is_oa:!0,n_refs:70,n_refs_in_core:14,degree:29,community:0,deg_w:275.5,betweenness:.001,pagerank:.00277,eigenvector:.015},{id:159,oaid:"W4323364009",doi:"10.1007/s11467-022-1249-z",title:"Noisy intermediate-scale quantum computers",authors:[{name:"Bin Cheng",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Xiu–Hao Deng",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Xiu Gu",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Yu He",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Guangchong Hu",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Peihao Huang",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Jun Li",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Ben‐Chuan Lin",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Dawei Lu",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Yao Lu",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Chu-Dan Qiu",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Hui Wang",institutions:["University of Science and Technology of China","Hefei National Center for Physical Sciences at Nanoscale"]},{name:"Tao Xin",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Shi Yu",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Man‐Hong Yung",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Junkai Zeng",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Song Zhang",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Youpeng Zhong",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]},{name:"Xinhua Peng",institutions:["University of Science and Technology of China"]},{name:"Franco Nori",institutions:["University of Michigan","Pioneer (Japan)","RIKEN"]},{name:"Dapeng Yu",institutions:["Southern University of Science and Technology","Beijing Academy of Quantum Information Sciences"]}],authorString:"Bin Cheng; Xiu–Hao Deng; Xiu Gu; Yu He; Guangchong Hu; Peihao Huang; Jun Li; Ben‐Chuan Lin; Dawei Lu; Yao Lu; Chu-Dan Qiu; Hui Wang et al.",institutions:["Beijing Academy of Quantum Information Sciences","Hefei National Center for Physical Sciences at Nanoscale","Pioneer (Japan)","RIKEN","Southern University of Science and Technology","University of Michigan","University of Science and Technology of China"],countries:["CN","JP","US"],year:2023,journal:"Frontiers of Physics",citations:125,abstract:"Abstract Quantum computers have made extraordinary progress over the past decade, and significant milestones have been achieved along the path of pursuing universal fault-tolerant quantum computers. Quantum advantage, the tipping point heralding the quantum era, has been accomplished along with several waves of breakthroughs. Quantum hardware has become more integrated and architectural compared to its toddler days. The controlling precision of various physical systems is pushed beyond the fault-tolerant threshold. Meanwhile, quantum computation research has established a new norm by embracing industrialization and commercialization. The joint power of governments, private investors, and tech companies has significantly shaped a new vibrant environment that accelerates the development of this field, now at the beginning of the noisy intermediate-scale quantum era. Here, we first discuss the progress achieved in the field of quantum computation by reviewing the most important algorithms and advances in the most promising technical routes, and then summarizing the next-stage challenges. Furthermore, we illustrate our confidence that solid foundations have been built for the fault-tolerant quantum computer and our optimism that the emergence of quantum killer applications essential for human society shall happen in the future.",keywords:["Quantum computer","Quantum","Computer engineering","Quantum mechanics"],concepts:["Quantum computer","Quantum","Computer engineering"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s11467-022-1249-z.pdf",is_oa:!0,n_refs:911,n_refs_in_core:21,degree:35,community:3,deg_w:1300,betweenness:.0038,pagerank:.00954,eigenvector:.1213},{id:160,oaid:"W2969454111",doi:"10.1103/physreva.101.062322",title:"Measurement reduction in variational quantum algorithms",authors:[{name:"Andrew Zhao",institutions:["University of New Mexico"]},{name:"Andrew Tranter",institutions:["Tufts University"]},{name:"William Kirby",institutions:["Tufts University"]},{name:"Shu Fay Ung",institutions:["California Institute of Technology"]},{name:"Akimasa Miyake",institutions:["University of New Mexico"]},{name:"Peter J. Love",institutions:["Tufts University"]}],authorString:"Andrew Zhao; Andrew Tranter; William Kirby; Shu Fay Ung; Akimasa Miyake; Peter J. Love",institutions:["California Institute of Technology","Tufts University","University of New Mexico"],countries:["US"],year:2020,journal:"Physical review. A/Physical review, A",citations:123,abstract:"Variational quantum algorithms are promising applications of noisy intermediate-scale quantum (NISQ) computers. These algorithms consist of a number of separate prepare-and-measure experiments that estimate terms in a Hamiltonian. The number of terms can become overwhelmingly large for problems at the scale of NISQ hardware that may soon be available. We use unitary partitioning (developed independently by Izmaylov et al. [J. Chem. Theory Comput. 16, 190 (2020)]) to define variational quantum eigensolver procedures in which additional unitary operations are appended to the ansatz preparation to reduce the number of terms. This approach may be scaled to use all coherent resources available after ansatz preparation. We also study the use of asymmetric qubitization to implement the additional coherent operations with lower circuit depth. Using this technique, we find a constant factor speedup for lattice and random Pauli Hamiltonians. For electronic structure Hamiltonians, we prove that linear term reduction with respect to the number of orbitals, which has been previously observed in numerical studies, is always achievable. For systems represented on 10--30 qubits, we find that there is a reduction in the number of terms by approximately an order of magnitude. Applied to the plane-wave dual-basis representation of fermionic Hamiltonians, however, unitary partitioning offers only a constant factor reduction. Finally, we show that noncontextual Hamiltonians may be reduced to effective commuting Hamiltonians using unitary partitioning.",keywords:["Reduction","Algorithm","Quantum","Quantum algorithm","Quantum mechanics"],concepts:["Reduction","Algorithm","Quantum","Quantum algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.101.062322",is_oa:!0,n_refs:80,n_refs_in_core:16,degree:41,community:1,deg_w:894.5,betweenness:.0018,pagerank:.00647,eigenvector:.0837},{id:161,oaid:"W2981524394",doi:"10.1103/physrevresearch.2.033421",title:"Orbital optimized unitary coupled cluster theory for quantum computer",authors:[{name:"Wataru Mizukami",institutions:["Japan Science and Technology Agency","The University of Osaka"]},{name:"Kosuke Mitarai",institutions:["The University of Osaka"]},{name:"Yuya O. Nakagawa",institutions:[]},{name:"Takahiro Yamamoto",institutions:[]},{name:"Tennin Yan",institutions:[]},{name:"Yu‐ya Ohnishi",institutions:[]}],authorString:"Wataru Mizukami; Kosuke Mitarai; Yuya O. Nakagawa; Takahiro Yamamoto; Tennin Yan; Yu‐ya Ohnishi",institutions:["Japan Science and Technology Agency","The University of Osaka"],countries:["JP"],year:2020,journal:"Physical Review Research",citations:123,abstract:"This paper presents a wave-function method based on unitary coupled-cluster theory for quantum computers, to determine the quantum circuit parameters and molecular orbital parameters simultaneously, as well as molecular-geometry optimizations",keywords:["Unitary state","Wave function","Coupled cluster","Quantum","Cluster","Quantum mechanics"],concepts:["Unitary state","Wave function","Coupled cluster","Quantum","Cluster","Quantum mechanics"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.2.033421",is_oa:!0,n_refs:105,n_refs_in_core:18,degree:36,community:1,deg_w:625,betweenness:.001,pagerank:.00479,eigenvector:.0516},{id:162,oaid:"W3037811760",doi:"10.1007/s00220-022-04343-8",title:"Measurements of Quantum Hamiltonians with Locally-Biased Classical Shadows",authors:[{name:"Charles Hadfield",institutions:["IBM (United States)"]},{name:"Sergey Bravyi",institutions:["IBM (United States)"]},{name:"Rudy Raymond",institutions:["Keio University","IBM Research - Tokyo"]},{name:"Antonio Mezzacapo",institutions:["IBM (United States)"]}],authorString:"Charles Hadfield; Sergey Bravyi; Rudy Raymond; Antonio Mezzacapo",institutions:["IBM (United States)","IBM Research - Tokyo","Keio University"],countries:["JP","US"],year:2022,journal:"Communications in Mathematical Physics",citations:123,abstract:"Abstract Obtaining precise estimates of quantum observables is a crucial step of variational quantum algorithms. We consider the problem of estimating expectation values of quantum Hamiltonians, obtained on states prepared on a quantum computer. We propose a novel estimator for this task, which is locally optimised with knowledge of the Hamiltonian and a classical approximation to the underlying quantum state. Our estimator is based on the concept of classical shadows of a quantum state, and has the important property of not adding to the circuit depth for the state preparation. We test its performance numerically for molecular Hamiltonians of increasing size, finding a sizable reduction in variance with respect to current measurement protocols that do not increase circuit depths.",keywords:["Observable","Hamiltonian","Quantum","Estimator","Quantum algorithm","Statistical physics","Quantum state"],concepts:["Observable","Hamiltonian","Quantum","Estimator","Quantum algorithm","Statistical physics","Quantum state"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s00220-022-04343-8.pdf",is_oa:!0,n_refs:39,n_refs_in_core:8,degree:27,community:1,deg_w:337.5,betweenness:.0014,pagerank:.00303,eigenvector:.0272},{id:163,oaid:"W2922368061",doi:"10.1038/s41467-020-14341-w",title:"Decoding quantum errors with subspace expansions",authors:[{name:"Jarrod R. McClean",institutions:["Google (United States)"]},{name:"Zhang Jiang",institutions:["Google (United States)"]},{name:"Nicholas C. Rubin",institutions:["Google (United States)"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Hartmut Neven",institutions:["Google (United States)"]}],authorString:"Jarrod R. McClean; Zhang Jiang; Nicholas C. Rubin; Ryan Babbush; Hartmut Neven",institutions:["Google (United States)"],countries:["US"],year:2020,journal:"Nature Communications",citations:123,abstract:"With rapid developments in quantum hardware comes a push towards the first practical applications. While fully fault-tolerant quantum computers are not yet realized, there may exist intermediate forms of error correction that enable practical applications. In this work, we consider the idea of post-processing error decoders using existing quantum codes, which mitigate errors on logical qubits using post-processing without explicit syndrome measurements or additional qubits beyond the encoding overhead. This greatly simplifies the experimental exploration of quantum codes on real, near-term devices, removing the need for locality of syndromes or fast feed-forward. We develop the theory of the method and demonstrate it on an example with the perfect [[5, 1, 3]] code, which exhibits a pseudo-threshold of p ≈ 0.50 under a single qubit depolarizing channel applied to all qubits. We also provide a demonstration of improved performance on an unencoded hydrogen molecule.",keywords:["Qubit","Quantum error correction","Quantum","Error detection and correction","Decoding methods","Subspace topology","Encoding","Quantum computer"],concepts:["Qubit","Quantum error correction","Quantum","Error detection and correction","Algorithm","Decoding methods","Subspace topology"],pdf_url:"https://www.nature.com/articles/s41467-020-14341-w.pdf",is_oa:!0,n_refs:55,n_refs_in_core:17,degree:39,community:2,deg_w:579,betweenness:.0015,pagerank:.00444,eigenvector:.0496},{id:164,oaid:"W3095458419",doi:"10.1103/prxquantum.2.030307",title:"Adaptive Variational Quantum Dynamics Simulations",authors:[{name:"Yong-Xin Yao",institutions:["Iowa State University","Ames National Laboratory"]},{name:"Niladri Gomes",institutions:["Ames National Laboratory"]},{name:"Feng Zhang",institutions:["Ames National Laboratory"]},{name:"Cai-Zhuang Wang",institutions:["Iowa State University","Ames National Laboratory"]},{name:"Kai-Ming Ho",institutions:["Iowa State University","Ames National Laboratory"]},{name:"Thomas Iadecola",institutions:["Iowa State University","Ames National Laboratory"]},{name:"Peter P. Orth",institutions:["Iowa State University","Ames National Laboratory"]}],authorString:"Yong-Xin Yao; Niladri Gomes; Feng Zhang; Cai-Zhuang Wang; Kai-Ming Ho; Thomas Iadecola; Peter P. Orth",institutions:["Ames National Laboratory","Iowa State University"],countries:["US"],year:2021,journal:"PRX Quantum",citations:120,abstract:`We propose a general-purpose, self-adaptive approach to construct a variational wave-function ansatz for highly accurate quantum dynamics simulations based on McLachlan's variational principle. The key idea is to dynamically expand the variational ansatz along the time-evolution path such that the "McLachlan distance", which is a measure of the simulation accuracy, remains below a set threshold. We apply this adaptive variational quantum dynamics simulation (AVQDS) approach to the integrable Lieb-Schultz-Mattis spin chain and the nonintegrable mixed-field Ising model, where it captures both finite-rate and sudden post-quench dynamics with high fidelity. The AVQDS quantum circuits that prepare the timeevolved state are much shallower than those obtained from first-order Trotterization and contain up to 2 orders of magnitude fewer CNOT gate operations. We envision that a wide range of dynamical simulations of quantum many-body systems on near-term quantum-computing devices will be made possible through the AVQDS framework.`,keywords:["Ansatz","Quantum","Quantum simulator","Integrable system","Measure","Bethe ansatz","Quantum dynamics","Controlled NOT gate"],concepts:["Ansatz","Quantum","Statistical physics","Quantum simulator","Integrable system","Measure","Bethe ansatz"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.030307",is_oa:!0,n_refs:53,n_refs_in_core:19,degree:36,community:2,deg_w:458,betweenness:.0019,pagerank:.00387,eigenvector:.029},{id:165,oaid:"W4293162591",doi:"10.1103/physrevresearch.4.033154",title:"Measurements as a roadblock to near-term practical quantum advantage in chemistry: Resource analysis",authors:[{name:"Jérôme F. Gonthier",institutions:["Zapata (United States)"]},{name:"Maxwell D. Radin",institutions:["Zapata (United States)"]},{name:"Corneliu Buda",institutions:[]},{name:"Eric J. Doskocil",institutions:[]},{name:"Clena M. Abuan",institutions:["BP (United States)"]},{name:"Jonathan Romero",institutions:["Zapata (United States)"]}],authorString:"Jérôme F. Gonthier; Maxwell D. Radin; Corneliu Buda; Eric J. Doskocil; Clena M. Abuan; Jonathan Romero",institutions:["BP (United States)","Zapata (United States)"],countries:["US"],year:2022,journal:"Physical Review Research",citations:119,abstract:"Recent advances in quantum computing devices have brought attention to hybrid quantum-classical algorithms like the variational quantum eigensolver (VQE) as a potential route to practical quantum advantage in chemistry. However, it is not yet clear whether such algorithms, even in the absence of device error, could actually achieve quantum advantage for systems of practical interest. We have performed an exhaustive analysis to estimate the number of qubits and number of measurements required to compute the combustion energies of small organic molecules and related systems to within chemical accuracy of experimental values using the VQE. We consider several key modern improvements to the VQE, including low-rank factorizations of the Hamiltonian. Our results indicate that, although these techniques are useful, they will not be sufficient to achieve practical quantum computational advantage for our molecular set, or for similar molecules. This suggests that novel approaches to operator estimation leveraging quantum coherence, such as enhanced likelihood functions, may be required.",keywords:["Quantum","Quantum computer","Qubit","Quantum algorithm","Coherence","Hamiltonian","Quantum chemistry"],concepts:["Quantum","Quantum computer","Qubit","Quantum algorithm","Coherence","Hamiltonian","Quantum chemistry"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.4.033154",is_oa:!0,n_refs:86,n_refs_in_core:20,degree:35,community:1,deg_w:509,betweenness:.0019,pagerank:.00413,eigenvector:.0433},{id:166,oaid:"W2974883009",doi:"10.22331/q-2020-05-11-263",title:"An Adaptive Optimizer for Measurement-Frugal Variational Algorithms",authors:[{name:"Jonas M. Kübler",institutions:["Los Alamos National Laboratory","Max Planck Institute for Intelligent Systems"]},{name:"Andrew Arrasmith",institutions:["Los Alamos National Laboratory"]},{name:"Lukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Jonas M. Kübler; Andrew Arrasmith; Lukasz Cincio; Patrick J. Coles",institutions:["Los Alamos National Laboratory","Max Planck Institute for Intelligent Systems"],countries:["DE","US"],year:2020,journal:"Quantum",citations:117,abstract:"Variational hybrid quantum-classical algorithms (VHQCAs) have the potential to be useful in the era of near-term quantum computing. However, recently there has been concern regarding the number of measurements needed for convergence of VHQCAs. Here, we address this concern by investigating the classical optimizer in VHQCAs. We introduce a novel optimizer called individual Coupled Adaptive Number of Shots (iCANS). This adaptive optimizer frugally selects the number of measurements (i.e., number of shots) both for a given iteration and for a given partial derivative in a stochastic gradient descent. We numerically simulate the performance of iCANS for the variational quantum eigensolver and for variational quantum compiling, with and without noise. In all cases, and especially in the noisy case, iCANS tends to out-perform state-of-the-art optimizers for VHQCAs. We therefore believe this adaptive optimizer will be useful for realistic VHQCA implementations, where the number of measurements is limited.",keywords:["Convergence","Quantum","Derivative","Quantum algorithm","Benchmark"],concepts:["Convergence","Algorithm","Mathematical optimization","Quantum","Applied mathematics","Derivative"],pdf_url:"https://quantum-journal.org/papers/q-2020-05-11-263/pdf/",is_oa:!0,n_refs:45,n_refs_in_core:17,degree:47,community:0,deg_w:685.5,betweenness:.0041,pagerank:.00535,eigenvector:.0539},{id:167,oaid:"W3120410077",doi:"10.22331/q-2021-07-28-512",title:"An efficient quantum algorithm for the time evolution of parameterized circuits",authors:[{name:"Stefano Barison",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Filippo Vicentini",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Giuseppe Carleo",institutions:["École Polytechnique Fédérale de Lausanne"]}],authorString:"Stefano Barison; Filippo Vicentini; Giuseppe Carleo",institutions:["École Polytechnique Fédérale de Lausanne"],countries:["CH"],year:2021,journal:"Quantum",citations:115,abstract:`We introduce a novel hybrid algorithm to simulate the real-time evolution of quantum systems using parameterized quantum circuits. The method, named "projected – Variational Quantum Dynamics" (p-VQD) realizes an iterative, global projection of the exact time evolution onto the parameterized manifold. In the small time-step limit, this is equivalent to the McLachlan's variational principle. Our approach is efficient in the sense that it exhibits an optimal linear scaling with the total number of variational parameters. Furthermore, it is global in the sense that it uses the variational principle to optimize all parameters at once. The global nature of our approach then significantly extends the scope of existing efficient variational methods, that instead typically rely on the iterative optimization of a restricted subset of variational parameters. Through numerical experiments, we also show that our approach is particularly advantageous over existing global optimization algorithms based on the time-dependent variational principle that, due to a demanding quadratic scaling with parameter numbers, are unsuitable for large parameterized quantum circuits.`,keywords:["Parameterized complexity","Quantum","Quadratic equation","Scaling","Projection","Quantum algorithm","Variational principle","Quantum system"],concepts:["Parameterized complexity","Quantum","Quadratic equation","Scaling","Projection","Algorithm","Quantum algorithm"],pdf_url:"https://quantum-journal.org/papers/q-2021-07-28-512/pdf/",is_oa:!0,n_refs:58,n_refs_in_core:20,degree:39,community:0,deg_w:458,betweenness:.0036,pagerank:.00407,eigenvector:.0338},{id:168,oaid:"W3084133534",doi:"10.1103/prxquantum.2.010317",title:"Quantum Computation of Finite-Temperature Static and Dynamical Properties of Spin Systems Using Quantum Imaginary Time Evolution",authors:[{name:"Shi-Ning Sun",institutions:["California Institute of Technology"]},{name:"Mario Motta",institutions:["IBM Research - Almaden"]},{name:"Ruslan N. Tazhigulov",institutions:["California Institute of Technology"]},{name:"Adrian T.K. Tan",institutions:["California Institute of Technology"]},{name:"Garnet Kin-Lic Chan",institutions:["California Institute of Technology"]},{name:"Austin J. Minnich",institutions:["California Institute of Technology"]}],authorString:"Shi-Ning Sun; Mario Motta; Ruslan N. Tazhigulov; Adrian T.K. Tan; Garnet Kin-Lic Chan; Austin J. Minnich",institutions:["California Institute of Technology","IBM Research - Almaden"],countries:["US"],year:2021,journal:"PRX Quantum",citations:112,abstract:"Simulations of the finite-temperature quantum dynamics of spin systems are performed on digital quantum computers, enhancing many capabilities that are critical to study realistic many-body physics on near-term quantum hardware.",keywords:["Quantum","Open quantum system","Quantum dynamics","Quantum computer","Spin","Quantum network","Quantum dissipation","Quantum technology"],concepts:["Quantum","Quantum mechanics","Open quantum system","Quantum dynamics","Quantum computer","Spin","Quantum network"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.010317",is_oa:!0,n_refs:48,n_refs_in_core:11,degree:27,community:2,deg_w:259,betweenness:.0013,pagerank:.00253,eigenvector:.0207},{id:169,oaid:"W3182139769",doi:"10.1103/physrevresearch.4.013141",title:"Digitized-counterdiabatic quantum approximate optimization algorithm",authors:[{name:"Pranav Chandarana",institutions:["University of the Basque Country"]},{name:"Narendra N. Hegade",institutions:["Shanghai University"]},{name:"Koushik Paul",institutions:["Shanghai University"]},{name:"F. Albarrán-Arriagada",institutions:["Shanghai University"]},{name:"E. Solano",institutions:["Ikerbasque","Shanghai University","University of the Basque Country"]},{name:"Adolfo del Campo",institutions:["University of Luxembourg","Donostia International Physics Center"]},{name:"Xi Chen",institutions:["University of the Basque Country"]}],authorString:"Pranav Chandarana; Narendra N. Hegade; Koushik Paul; F. Albarrán-Arriagada; E. Solano; Adolfo del Campo; Xi Chen",institutions:["Donostia International Physics Center","Ikerbasque","Shanghai University","University of Luxembourg","University of the Basque Country"],countries:["CN","ES","LU"],year:2022,journal:"Physical Review Research",citations:112,abstract:'The quantum approximate optimization algorithm (QAOA) has proved to be an effective classical-quantum algorithm serving multiple purposes, from solving combinatorial optimization problems to finding the ground state of many-body quantum systems. Since the QAOA is an Ansatz-dependent algorithm, there is always a need to design Ans\\"atze for better optimization. To this end, we propose a digitized version of the QAOA enhanced via the use of shortcuts to adiabaticity. Specifically, we use a counterdiabatic (CD) driving term to design a better Ansatz, along with the Hamiltonian and mixing terms, enhancing the global performance. We apply our digitized-CD QAOA to Ising models, classical optimization problems, and the $P$-spin model, demonstrating that it outperforms the standard QAOA in all cases we study.',keywords:["Ansatz","Hamiltonian","Quantum computer","Quantum","Ising model","Optimization problem","Algorithm"],concepts:["Ansatz","Hamiltonian","Quantum computer","Quantum","Ising model","Optimization problem","Algorithm"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.4.013141",is_oa:!0,n_refs:115,n_refs_in_core:19,degree:33,community:0,deg_w:436,betweenness:.0012,pagerank:.00357,eigenvector:.0332},{id:170,oaid:"W3200635420",doi:"10.1103/physreva.105.022417",title:"Quantum Krylov subspace algorithms for ground- and excited-state energy estimation",authors:[{name:"Cristian L. Cortes",institutions:["Argonne National Laboratory"]},{name:"Stephen K. Gray",institutions:["Argonne National Laboratory"]}],authorString:"Cristian L. Cortes; Stephen K. Gray",institutions:["Argonne National Laboratory"],countries:["US"],year:2022,journal:"Physical review. A/Physical review, A",citations:110,abstract:"Quantum Krylov subspace diagonalization (QKSD) algorithms provide a low-cost alternative to the conventional quantum phase estimation algorithm for estimating the ground- and excited-state energies of a quantum many-body system. While QKSD algorithms typically rely on using the Hadamard test for estimating Krylov subspace matrix elements of the form $\\ensuremath{\\langle}{\\ensuremath{\\phi}}_{i}|{e}^{\\ensuremath{-}i\\stackrel{\\ifmmode \\hat{}\\else \\^{}\\fi{}}{H}\\ensuremath{\\tau}}|{\\ensuremath{\\phi}}_{j}\\ensuremath{\\rangle}$, the associated quantum circuits require an ancilla qubit with controlled multiqubit gates that can be quite costly for near-term quantum hardware. In this paper, we show that a wide class of Hamiltonians relevant to condensed-matter physics and quantum chemistry contain symmetries that can be exploited to avoid the use of the Hadamard test. We propose a multifidelity estimation protocol that can be used to compute such quantities, showing that our approach, when combined with efficient single-fidelity estimation protocols, provides a substantial reduction in circuit depth. In addition, we develop a unified theory of quantum Krylov subspace algorithms and present three quantum-classical algorithms for the ground- and excited-state energy estimation problems, where each algorithm provides various advantages and disadvantages in terms of total number of calls to the quantum computer, gate depth, classical complexity, and stability of the generalized eigenvalue problem within the Krylov subspace.",keywords:["Quantum phase estimation algorithm","Quantum computer","Qubit","Krylov subspace","Quantum algorithm","Algorithm","Hadamard transform","Quantum"],concepts:["Quantum phase estimation algorithm","Quantum computer","Qubit","Krylov subspace","Quantum algorithm","Algorithm","Hadamard transform","Quantum"],pdf_url:"https://arxiv.org/pdf/2109.06868",is_oa:!0,n_refs:88,n_refs_in_core:17,degree:31,community:3,deg_w:445,betweenness:.0016,pagerank:.00364,eigenvector:.0356},{id:171,oaid:"W3099621369",doi:"10.1088/1367-2630/aac54f",title:"Fermion-to-qubit mappings with varying resource requirements for quantum simulation",authors:[{name:"Mark Steudtner",institutions:["Leiden University","QuTech","Delft University of Technology"]},{name:"Stephanie Wehner",institutions:["QuTech","Delft University of Technology"]}],authorString:"Mark Steudtner; Stephanie Wehner",institutions:["Delft University of Technology","Leiden University","QuTech"],countries:["NL"],year:2018,journal:"New Journal of Physics",citations:109,abstract:"&lt;p&gt;The mapping of fermionic states onto qubit states, as well as the mapping of fermionic Hamiltonian into quantum gates enables us to simulate electronic systems with a quantum computer. Benefiting the understanding of many-body systems in chemistry and physics, quantum simulation is one of the great promises of the coming age of quantum computers. Interestingly, the minimal requirement of qubits for simulating Fermions seems to be agnostic of the actual number of particles as well as other symmetries. This leads to qubit requirements that are well above the minimal requirements as suggested by combinatorial considerations. In this work, we develop methods that allow us to trade-off qubit requirements against the complexity of the resulting quantum circuit. We first show that any classical code used to map the state of a fermionic Fock space to qubits gives rise to a mapping of fermionic models to quantum gates. As an illustrative example, we present a mapping based on a nonlinear classical error correcting code, which leads to significant qubit savings albeit at the expense of additional quantum gates. We proceed to use this framework to present a number of simpler mappings that lead to qubit savings with a more modest increase in gate difficulty. We discuss the role of symmetries such as particle conservation, and savings that could be obtained if an experimental platform could easily realize multi-controlled gates.&lt;/p&gt;",keywords:["Qubit","Quantum computer","Quantum gate","Hamiltonian","Quantum mechanics","Quantum","Quantum circuit"],concepts:["Qubit","Quantum computer","Quantum gate","Hamiltonian","Quantum mechanics","Quantum","Quantum circuit"],pdf_url:"https://iopscience.iop.org/article/10.1088/1367-2630/aac54f/pdf",is_oa:!0,n_refs:52,n_refs_in_core:7,degree:30,community:1,deg_w:562.5,betweenness:9e-4,pagerank:.0043,eigenvector:.056},{id:172,oaid:"W4313462631",doi:"10.1103/prxquantum.4.010301",title:"Scalable Measures of Magic Resource for Quantum Computers",authors:[{name:"Tobias Haug",institutions:["Imperial College London"]},{name:"M.S. Kim",institutions:["Imperial College London"]}],authorString:"Tobias Haug; M.S. Kim",institutions:["Imperial College London"],countries:["GB"],year:2023,journal:"PRX Quantum",citations:108,abstract:"Nonstabilizerness or magic resource characterizes the amount of non-Clifford operations needed to prepare quantum states. It is a crucial resource for quantum computing and a necessary condition for quantum advantage. However, quantifying magic resource beyond a few qubits has been a major challenge. Here, we introduce efficient measures of magic resource for pure quantum states with a sampling cost that is independent of the number of qubits. Our method uses Bell measurements over two copies of a state, which we implement in experiment together with a cost-free error-mitigation scheme. We show the transition of classically simulable stabilizer states into intractable quantum states on the IonQ quantum computer. For applications, we efficiently distinguish stabilizer and nonstabilizer states with low measurement cost even in the presence of experimental noise. Further, we propose a variational quantum algorithm to maximize our measure via the shift rule. Our algorithm can be free of barren plateaus even for highly expressible variational circuits. Finally, we experimentally demonstrate a Bell-measurement protocol for the stabilizer Rényi entropy as well as the Wallach-Meyer entanglement measure. Our results pave the way to understanding the nonclassical power of quantum computers, quantum simulators, and quantum many-body systems.",keywords:["Quantum entanglement","Quantum computer","Qubit","Quantum error correction","Quantum","MAGIC","Quantum information"],concepts:["Quantum entanglement","Quantum computer","Qubit","Quantum error correction","Quantum","MAGIC","Quantum information"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.4.010301",is_oa:!0,n_refs:87,n_refs_in_core:14,degree:28,community:0,deg_w:285,betweenness:.0013,pagerank:.00278,eigenvector:.0255},{id:173,oaid:"W3107600208",doi:"10.22331/q-2022-08-16-776",title:"Classical Shadows With Noise",authors:[{name:"Dax Enshan Koh",institutions:["Agency for Science, Technology and Research","Institute of High Performance Computing","Zapata (United States)"]},{name:"Sabee Grewal",institutions:["Zapata (United States)","The University of Texas at Austin"]}],authorString:"Dax Enshan Koh; Sabee Grewal",institutions:["Agency for Science, Technology and Research","Institute of High Performance Computing","The University of Texas at Austin","Zapata (United States)"],countries:["SG","US"],year:2022,journal:"Quantum",citations:108,abstract:"The classical shadows protocol, recently introduced by Huang, Kueng, and Preskill [Nat. Phys. 16, 1050 (2020)], is a quantum-classical protocol to estimate properties of an unknown quantum state. Unlike full quantum state tomography, the protocol can be implemented on near-term quantum hardware and requires few quantum measurements to make many predictions with a high success probability. In this paper, we study the effects of noise on the classical shadows protocol. In particular, we consider the scenario in which the quantum circuits involved in the protocol are subject to various known noise channels and derive an analytical upper bound for the sample complexity in terms of a shadow seminorm for both local and global noise. Additionally, by modifying the classical post-processing step of the noiseless protocol, we define a new estimator that remains unbiased in the presence of noise. As applications, we show that our results can be used to prove rigorous sample complexity upper bounds in the cases of depolarizing noise and amplitude damping.",keywords:["Noise","Quantum","Estimator","Quantum noise","Protocol","Upper and lower bounds","Quantum state"],concepts:["Noise","Quantum","Estimator","Quantum noise","Protocol","Upper and lower bounds","Quantum state"],pdf_url:"https://quantum-journal.org/papers/q-2022-08-16-776/pdf/",is_oa:!0,n_refs:135,n_refs_in_core:15,degree:31,community:1,deg_w:424,betweenness:.002,pagerank:.00358,eigenvector:.0456},{id:174,oaid:"W3004493589",doi:"10.1103/physreva.105.032418",title:"Quantum simulation of quantum field theory in the light-front formulation",authors:[{name:"Michael Kreshchuk",institutions:["Tufts University"]},{name:"William Kirby",institutions:["Tufts University"]},{name:"Gary R. Goldstein",institutions:["Tufts University"]},{name:"P. H. Beauchemin",institutions:["Tufts University"]},{name:"Peter J. Love",institutions:["Tufts University","Brookhaven National Laboratory"]}],authorString:"Michael Kreshchuk; William Kirby; Gary R. Goldstein; P. H. Beauchemin; Peter J. Love",institutions:["Brookhaven National Laboratory","Tufts University"],countries:["US"],year:2022,journal:"Physical review. A/Physical review, A",citations:106,abstract:"Quantum chromodynamics (QCD) describes the structure of hadrons such as the proton at a fundamental level. The precision of calculations in QCD limits the precision of the values of many physical parameters extracted from collider data. For example, uncertainty in the parton distribution function is the dominant source of error in the $W$ mass measurement at the Large Hadron Collider. Improving the precision of such measurements is essential in the search for new physics. Quantum simulation offers an efficient way of studying quantum field theories (QFTs) such as QCD nonperturbatively. Previous quantum algorithms for simulating QFTs have qubit requirements that are well beyond the most ambitious experimental proposals for large-scale quantum computers. Can the qubit requirements for such algorithms be brought into range of quantum computation with several thousand logical qubits? We show how this can be achieved by using the light-front formulation of quantum field theory. This work was inspired by the similarity of the light-front formulation to quantum chemistry, first noted by Wilson [Nucl. Phys. B, Proc. Suppl. 17, 82 (1990)].",keywords:["Quantum chromodynamics","Qubit","Quantum field theory","Quantum computer","Quantum algorithm","Quantum simulator","Particle physics"],concepts:["Quantum chromodynamics","Qubit","Quantum field theory","Quantum computer","Quantum algorithm","Quantum simulator","Particle physics"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevA.105.032418",is_oa:!0,n_refs:212,n_refs_in_core:15,degree:30,community:1,deg_w:570,betweenness:8e-4,pagerank:.00437,eigenvector:.0431},{id:175,oaid:"W3113541475",doi:"10.1109/tqe.2020.3035814",title:'<inline-formula><tex-math notation="LaTeX">$O(N^3)$</tex-math></inline-formula> Measurement Cost for Variational Quantum Eigensolver on Molecular Hamiltonians',authors:[{name:"Pranav Gokhale",institutions:[]},{name:"Olivia Angiuli",institutions:["University of California, Berkeley"]},{name:"Yongshan Ding",institutions:["University of Illinois Chicago","University of Chicago"]},{name:"Kaiwen Gui",institutions:["University of Illinois Chicago","University of Chicago"]},{name:"Teague Tomesh",institutions:["Princeton University"]},{name:"Martin Suchara",institutions:["Argonne National Laboratory"]},{name:"Margaret Martonosi",institutions:["Princeton University"]},{name:"Frederic T. Chong",institutions:["University of Illinois Chicago","University of Chicago"]}],authorString:"Pranav Gokhale; Olivia Angiuli; Yongshan Ding; Kaiwen Gui; Teague Tomesh; Martin Suchara; Margaret Martonosi; Frederic T. Chong",institutions:["Argonne National Laboratory","Princeton University","University of California, Berkeley","University of Chicago","University of Illinois Chicago"],countries:["US"],year:2020,journal:"DOAJ (DOAJ: Directory of Open Access Journals)",citations:105,abstract:"Variational quantum eigensolver (VQE) is a promising algorithm for near-term quantum machines. It can be used to estimate the ground state energy of a molecule by performing separate measurements of O(N<sup>4</sup>) terms. This quartic scaling appears to be a significant obstacle to practical applications. However, we note that it empirically reduces to O(N<sup>3</sup>) when we partition the terms into linear-sized commuting families that can be measured simultaneously. We confirm these empirical observations by studying the MIN-COMMUTING-PARTITION problem at the level of the fermionic Hamiltonian and its encoding into qubits. Moreover, we provide a fast, precomputable procedure for creating linearly sized commuting partitions by solving a round-robin scheduling problem via flow networks. In addition, we demonstrate how to construct the quantum circuits necessary for simultaneous measurement, and we discuss the statistical implication of simultaneous measurement. Our results are experimentally validated by a ground state estimation of deuteron with low shot budget on a 20-qubit IBM machine.",keywords:["Quartic function","Hamiltonian","Qubit","Quantum","Quantum computer","Quantum algorithm","Partition"],concepts:["Quartic function","Hamiltonian","Qubit","Quantum","Quantum computer","Quantum algorithm","Partition"],pdf_url:"https://doaj.org/article/5bca01f6783b4387a786f89146a64428",is_oa:!0,n_refs:100,n_refs_in_core:10,degree:30,community:1,deg_w:489.5,betweenness:.0012,pagerank:.00394,eigenvector:.0437},{id:176,oaid:"W3024586266",doi:"10.1088/2632-2153/abc17d",title:"Quantum machine learning in high energy physics",authors:[{name:"Wen Guan",institutions:["University of Wisconsin–Madison"]},{name:"Gabriel Perdue",institutions:["Fermi National Accelerator Laboratory"]},{name:"Arthur Pesah",institutions:["Technical University of Denmark"]},{name:"Maria Schuld",institutions:["University of KwaZulu-Natal"]},{name:"Koji Terashi",institutions:["The University of Tokyo"]},{name:"Sofia Vallecorsa",institutions:[]},{name:"Jean-Roch Vlimant",institutions:["California Institute of Technology"]}],authorString:"Wen Guan; Gabriel Perdue; Arthur Pesah; Maria Schuld; Koji Terashi; Sofia Vallecorsa; Jean-Roch Vlimant",institutions:["California Institute of Technology","Fermi National Accelerator Laboratory","Technical University of Denmark","The University of Tokyo","University of KwaZulu-Natal","University of Wisconsin–Madison"],countries:["DK","JP","US","ZA"],year:2020,journal:"Machine Learning Science and Technology",citations:103,abstract:"Abstract Machine learning has been used in high energy physics (HEP) for a long time, primarily at the analysis level with supervised classification. Quantum computing was postulated in the early 1980s as way to perform computations that would not be tractable with a classical computer. With the advent of noisy intermediate-scale quantum computing devices, more quantum algorithms are being developed with the aim at exploiting the capacity of the hardware for machine learning applications. An interesting question is whether there are ways to apply quantum machine learning to HEP. This paper reviews the first generation of ideas that use quantum machine learning on problems in HEP and provide an outlook on future applications.",keywords:["Quantum machine learning","Quantum computer","Quantum","Energy","Computation","Quantum algorithm","Computational learning theory"],concepts:["Quantum machine learning","Quantum computer","Quantum","Energy","Computation","Quantum algorithm"],pdf_url:"https://iopscience.iop.org/article/10.1088/2632-2153/abc17d/pdf",is_oa:!0,n_refs:83,n_refs_in_core:11,degree:27,community:0,deg_w:311.5,betweenness:.0015,pagerank:.00314,eigenvector:.0143},{id:177,oaid:"W3217665308",doi:"10.1103/physreva.107.032407",title:"Performance comparison of optimization methods on variational quantum algorithms",authors:[{name:"Xavier Bonet-Monroig",institutions:["Leiden University"]},{name:"Hao Wang",institutions:["Leiden University"]},{name:"Diederick Vermetten",institutions:["Leiden University"]},{name:"Bruno Senjean",institutions:["École Nationale Supérieure de Chimie de Montpellier","Leiden University","Centre National de la Recherche Scientifique","Université de Montpellier"]},{name:"Charles Moussa",institutions:["Leiden University"]},{name:"Thomas Bäck",institutions:["Leiden University"]},{name:"Vedran Dunjko",institutions:["Leiden University"]},{name:"Thomas E. O’Brien",institutions:["Leiden University"]}],authorString:"Xavier Bonet-Monroig; Hao Wang; Diederick Vermetten; Bruno Senjean; Charles Moussa; Thomas Bäck; Vedran Dunjko; Thomas E. O’Brien",institutions:["Centre National de la Recherche Scientifique","Leiden University","Université de Montpellier","École Nationale Supérieure de Chimie de Montpellier"],countries:["FR","NL"],year:2023,journal:"Physical review. A/Physical review, A",citations:103,abstract:"Variational quantum algorithms (VQAs) offer a promising path toward using near-term quantum hardware for applications in academic and industrial research. These algorithms aim to find approximate solutions to quantum problems by optimizing a parametrized quantum circuit using a classical optimization algorithm. A successful VQA requires fast and reliable classical optimization algorithms. Understanding and optimizing how off-the-shelf optimization methods perform in this context is important for the future of the field. In this work, we study the performance of four commonly used gradient-free optimization methods [sequential least-squares quadratic programming, constrained optimization by linear approximations, the covariance matrix adaptation evolutionary strategy (CMA-ES), and the simultaneous perturbation stochastic approximation (SPSA)] to find ground-state energies of a range of small chemistry and material science problems. We test a telescoping sampling scheme (where the accuracy of the cost-function estimate provided to the optimizer is increased as the optimization converges) for all methods, demonstrating mixed results across our range of optimizers and problems chosen. We further hyperparameter tune two of the four optimizers (CMA-ES and SPSA) across a large range of models and demonstrate that with appropriate hyperparameter tuning, CMA-ES is competitive with and sometimes outperforms SPSA (which is not observed in the absence of hyperparameter tuning). Finally, we investigate the ability of an optimizer to beat the ``sampling-noise floor'' given by the sampling noise of each cost-function estimate provided to the optimizer. Our results demonstrate the necessity for tailoring and hyperparameter tuning known optimization techniques for inherently noisy variational quantum algorithms and that the variational landscape that one finds in a VQA is highly problem and system dependent. This provides guidance for future implementations of these algorithms in experiments.",keywords:["Hyperparameter","Mathematical optimization","Simultaneous perturbation stochastic approximation","Algorithm","Range","Context","Quantum"],concepts:["Hyperparameter","Mathematical optimization","Simultaneous perturbation stochastic approximation","Algorithm","Range","Context","Quantum"],pdf_url:"https://arxiv.org/pdf/2111.13454",is_oa:!0,n_refs:74,n_refs_in_core:19,degree:33,community:1,deg_w:412,betweenness:.0016,pagerank:.00349,eigenvector:.0353},{id:178,oaid:"W3086716958",doi:"10.1103/prxquantum.2.010101",title:"From Pulses to Circuits and Back Again: A Quantum Optimal Control Perspective on Variational Quantum Algorithms",authors:[{name:"Alicia B. Magann",institutions:["Sandia National Laboratories California","Princeton University"]},{name:"Christian Arenz",institutions:["Princeton University"]},{name:"Matthew D. Grace",institutions:["Sandia National Laboratories California"]},{name:"Tak-San Ho",institutions:["Princeton University"]},{name:"Robert L. Kosut",institutions:["Princeton University","SC Solutions (United States)"]},{name:"Jarrod R. McClean",institutions:["Google (United States)"]},{name:"Herschel A. Rabitz",institutions:["Princeton University"]},{name:"Mohan Sarovar",institutions:["Sandia National Laboratories California"]}],authorString:"Alicia B. Magann; Christian Arenz; Matthew D. Grace; Tak-San Ho; Robert L. Kosut; Jarrod R. McClean; Herschel A. Rabitz; Mohan Sarovar",institutions:["Google (United States)","Princeton University","SC Solutions (United States)","Sandia National Laboratories California"],countries:["US"],year:2021,journal:"PRX Quantum",citations:103,abstract:"The last decade has witnessed remarkable progress in the development of quantum technologies. Although fault-tolerant devices likely remain years away, the noisy intermediate-scale quantum devices of today may be leveraged for other purposes. Leading candidates are variational quantum algorithms (VQAs), which have been developed for applications including chemistry, optimization, and machine learning, but whose implementations on quantum devices have yet to demonstrate improvements over classical capabilities. In this Perspective, we propose a variety of ways that the performance of VQAs could be informed by quantum optimal control theory. A major theme throughout is the need for sufficient control resources in VQA implementations; we discuss different ways this need can manifest, outline a variety of open questions, and look to the future.",keywords:["Variety","Quantum","Perspective","Optimal control","Quantum algorithm","Quantum computer","Implementation","Control"],concepts:["Variety","Quantum","Perspective","Optimal control","Quantum algorithm","Quantum computer","Implementation"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.010101",is_oa:!0,n_refs:122,n_refs_in_core:16,degree:33,community:1,deg_w:366,betweenness:.0018,pagerank:.00318,eigenvector:.0312},{id:179,oaid:"W2995465990",doi:"10.1038/s41534-019-0213-4",title:"Calculating energy derivatives for quantum chemistry on a quantum computer",authors:[{name:"Thomas E. O’Brien",institutions:["Leiden University"]},{name:"Bruno Senjean",institutions:["Leiden University","Vrije Universiteit Amsterdam"]},{name:"Ramiro Sagastizabal",institutions:["QuTech","Delft University of Technology"]},{name:"Xavier Bonet-Monroig",institutions:["Leiden University","QuTech","Delft University of Technology"]},{name:"Alicja Dutkiewicz",institutions:["Leiden University","University of Warsaw"]},{name:"Francesco Buda",institutions:["Leiden University"]},{name:"L. DiCarlo",institutions:["QuTech","Delft University of Technology"]},{name:"Lucas Visscher",institutions:["Vrije Universiteit Amsterdam"]}],authorString:"Thomas E. O’Brien; Bruno Senjean; Ramiro Sagastizabal; Xavier Bonet-Monroig; Alicja Dutkiewicz; Francesco Buda; L. DiCarlo; Lucas Visscher",institutions:["Delft University of Technology","Leiden University","QuTech","University of Warsaw","Vrije Universiteit Amsterdam"],countries:["NL","PL"],year:2019,journal:"npj Quantum Information",citations:101,abstract:'Abstract Modeling chemical reactions and complicated molecular systems has been proposed as the “killer application” of a future quantum computer. Accurate calculations of derivatives of molecular eigenenergies are essential toward this end, allowing for geometry optimization, transition state searches, predictions of the response to an applied electric or magnetic field, and molecular dynamics simulations. In this work, we survey methods to calculate energy derivatives, and present two new methods: one based on quantum phase estimation, the other on a low-order response approximation. We calculate asymptotic error bounds and approximate computational scalings for the methods presented. Implementing these methods, we perform geometry optimization on an experimental quantum processor, estimating the equilibrium bond length of the dihydrogen molecule to within $$0.014$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mn>0.014</mml:mn></mml:math> Å of the full configuration interaction value. Within the same experiment, we estimate the polarizability of the H $${}_{2}$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:msub><mml:mrow/><mml:mrow><mml:mn>2</mml:mn></mml:mrow></mml:msub></mml:math> molecule, finding agreement at the equilibrium bond length to within $$0.06$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mn>0.06</mml:mn></mml:math> a.u. ( $$2 \\%$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mrow><mml:mn>2</mml:mn><mml:mi>%</mml:mi></mml:mrow></mml:math> relative error).',keywords:["Polarizability","Quantum","Quantum chemistry","Bond length","Statistical physics","Quantum computer","Quantum algorithm","Field"],concepts:["Polarizability","Quantum","Quantum chemistry","Bond length","Statistical physics","Quantum computer","Quantum algorithm","Field"],pdf_url:"https://www.nature.com/articles/s41534-019-0213-4.pdf",is_oa:!0,n_refs:102,n_refs_in_core:15,degree:33,community:1,deg_w:608.5,betweenness:9e-4,pagerank:.00454,eigenvector:.061},{id:180,oaid:"W3214892380",doi:"10.1103/prxquantum.2.040342",title:"Learning to Measure: Adaptive Informationally Complete Generalized Measurements for Quantum Algorithms",authors:[{name:"Guillermo García-Pérez",institutions:["University of Helsinki","University of Turku"]},{name:"Matteo A. C. Rossi",institutions:["Aalto University"]},{name:"Boris Sokolov",institutions:["University of Helsinki"]},{name:"Francesco Tacchino",institutions:["IBM Research - Zurich"]},{name:"Panagiotis Kl. Barkoutsos",institutions:["IBM Research - Zurich"]},{name:"Guglielmo Mazzola",institutions:["IBM Research - Zurich"]},{name:"Ivano Tavernelli",institutions:["IBM Research - Zurich"]},{name:"Sabrina Maniscalco",institutions:["University of Helsinki","Aalto University"]}],authorString:"Guillermo García-Pérez; Matteo A. C. Rossi; Boris Sokolov; Francesco Tacchino; Panagiotis Kl. Barkoutsos; Guglielmo Mazzola; Ivano Tavernelli; Sabrina Maniscalco",institutions:["Aalto University","IBM Research - Zurich","University of Helsinki","University of Turku"],countries:["CH","FI"],year:2021,journal:"PRX Quantum",citations:100,abstract:"Many prominent quantum computing algorithms with applications in fields such as chemistry and materials science require a large number of measurements, which represents an important roadblock for future real-world use cases. We introduce a novel approach to tackle this problem through an adaptive measurement scheme. We present an algorithm that optimizes informationally complete positive operator-valued measurements (POVMs) on the fly in order to minimize the statistical fluctuations in the estimation of relevant cost functions. We show its advantage by improving the efficiency of the variational quantum eigensolver in calculating ground-state energies of molecular Hamiltonians with extensive numerical simulations. Our results indicate that the proposed method is competitive with state-of-the-art measurement-reduction approaches in terms of efficiency. In addition, the informational completeness of the approach offers a crucial advantage, as the measurement data can be reused to infer other quantities of interest. We demonstrate the feasibility of this prospect by reusing ground-state energy-estimation data to perform high-fidelity reduced state tomography.",keywords:["Measure","Algorithm","Quantum","Quantum algorithm","Theoretical computer science","Quantum mechanics"],concepts:["Measure","Algorithm","Quantum","Quantum algorithm","Theoretical computer science"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.040342",is_oa:!0,n_refs:82,n_refs_in_core:20,degree:37,community:1,deg_w:569,betweenness:.0019,pagerank:.00446,eigenvector:.0396},{id:181,oaid:"W3000216880",doi:"10.1021/acs.jctc.9b00963",title:"Jastrow-type Decomposition in Quantum Chemistry for Low-Depth Quantum Circuits",authors:[{name:"Yuta Matsuzawa",institutions:["Kyoto University"]},{name:"Yuki Kurashige",institutions:["Kyoto University"]}],authorString:"Yuta Matsuzawa; Yuki Kurashige",institutions:["Kyoto University"],countries:["JP"],year:2020,journal:"Journal of Chemical Theory and Computation",citations:99,abstract:"We propose an efficient O(N2)-parameter ansatz that consists of a sequence of exponential operators, each of which is a unitary variant of Neuscamman’s cluster Jastrow operator. The ansatz can also be derived as a decomposition of T2 amplitudes of the unitary coupled cluster with generalized singles and doubles, which gives a near full-CI energy. The proposed ansatz therefore can reproduce the uCCGSD energy, or rather will reach the exact full-CI energy because of the exponential operator product form. Because the cluster Jastrow operators are expressed by a product of number operators and the derived Pauli operator products, namely, the Jordan–Wigner strings, are all commutative, it does not require the Trotter approximation to implement to a quantum circuit and should be a good candidate for the variational quantum eigensolver algorithm of a near-term quantum computer. The accuracy of the ansatz was examined for dissociation of a nitrogen dimer, and compared with other existing O(N2)-parameter ansatzs. Not only the original ansatzs defined in the second-quantization form but also their Trotter-splitting variants, in which the cluster amplitudes are optimized to minimize the energy obtained with a few, typically single, Trotter steps, were examined by quantum circuit simulators.",keywords:["Quantum","Quantum chemistry","Decomposition","Electronic circuit","Quantum computer","Quantum chemical","Quantum circuit"],concepts:["Quantum","Quantum chemistry","Decomposition","Electronic circuit","Quantum computer","Quantum chemical","Quantum circuit"],pdf_url:"https://arxiv.org/pdf/1909.12410",is_oa:!0,n_refs:88,n_refs_in_core:14,degree:32,community:1,deg_w:542,betweenness:8e-4,pagerank:.00419,eigenvector:.0489},{id:182,oaid:"W4280546230",doi:"10.1103/physrevresearch.4.023136",title:"Approximate amplitude encoding in shallow parameterized quantum circuits and its application to financial market indicators",authors:[{name:"Kouhei Nakaji",institutions:["Keio University"]},{name:"Shumpei Uno",institutions:["Keio University","Mizuho (Japan)"]},{name:"Yohichi Suzuki",institutions:["Keio University"]},{name:"Rudy Raymond",institutions:["Keio University","IBM Research - Tokyo"]},{name:"Tamiya Onodera",institutions:["Keio University","IBM Research - Tokyo"]},{name:"Tomoki Tanaka",institutions:["Keio University","Sumitomo Mitsui Banking Corporation"]},{name:"Hiroyuki Tezuka",institutions:["Keio University"]},{name:"Naoki Mitsuda",institutions:["Keio University","Sumitomo Mitsui Banking Corporation"]},{name:"Naoki Yamamoto",institutions:["Keio University"]}],authorString:"Kouhei Nakaji; Shumpei Uno; Yohichi Suzuki; Rudy Raymond; Tamiya Onodera; Tomoki Tanaka; Hiroyuki Tezuka; Naoki Mitsuda; Naoki Yamamoto",institutions:["IBM Research - Tokyo","Keio University","Mizuho (Japan)","Sumitomo Mitsui Banking Corporation"],countries:["JP"],year:2022,journal:"Physical Review Research",citations:99,abstract:"Efficient methods for loading given classical data into quantum circuits are essential for various quantum algorithms. In this paper, we propose an algorithm called Approximate Amplitude Encoding that can effectively load all the components of a given real-valued data vector into the amplitude of quantum state, while the previous proposal can load only the absolute values of those components. The key of our algorithm is to variationally train a shallow parameterized quantum circuit, using the results of two types of measurement: the standard computational-basis measurement plus the measurement in the Hadamard-transformed basis, introduced in order to handle the sign of the data components. The variational algorithm changes the circuit parameters so as to minimize the sum of two costs corresponding to those two measurement basis, both of which are given by the efficiently computable maximum mean discrepancy. We also consider the problem of constructing the singular value decomposition entropy via the stock market data set to give a financial market indicator; a quantum algorithm (the variational singular value decomposition algorithm) is known to produce a solution faster than classical, which yet requires the sign-dependent amplitude encoding. We demonstrate, with an in-depth numerical analysis, that our algorithm realizes loading of time series of real stock prices on quantum state with small approximation error, and thereby it enables constructing an indicator of the financial market based on the stock prices.",keywords:["Parameterized complexity","Singular value decomposition","Quantum algorithm","Algorithm","Quantum","Stock market","Quantum circuit"],concepts:["Parameterized complexity","Singular value decomposition","Quantum algorithm","Algorithm","Quantum","Stock market","Quantum circuit"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.4.023136",is_oa:!0,n_refs:94,n_refs_in_core:13,degree:27,community:0,deg_w:215,betweenness:.0019,pagerank:.00244,eigenvector:.0083},{id:183,oaid:"W3048017836",doi:"10.1103/prxquantum.2.010333",title:"Quantum Power Method by a Superposition of Time-Evolved States",authors:[{name:"Kazuhiro Seki",institutions:["RIKEN Center for Emergent Matter Science"]},{name:"Seiji Yunoki",institutions:["Pioneer (Japan)","RIKEN Center for Computational Science","RIKEN Center for Emergent Matter Science"]}],authorString:"Kazuhiro Seki; Seiji Yunoki",institutions:["Pioneer (Japan)","RIKEN Center for Computational Science","RIKEN Center for Emergent Matter Science"],countries:["JP"],year:2021,journal:"PRX Quantum",citations:98,abstract:"We propose a quantum-classical hybrid algorithm of the power method, here dubbed as the quantum power method, to evaluate n | with quantum computers, where n is a non-negative integer, is a time-independent Hamiltonian of interest, and | is a quantum state. We show that the number of gates required for approximating n scales linearly in the power and the number of qubits, making it a promising application for near-term quantum computers. Using numerical simulation, we show that the power method can control systematic errors in approximating the Hamiltonian power n for n as large as 100. As an application, we combine our method with a multireference Krylov-subspace-diagonalization scheme to show how one can improve the estimation of ground-state energies and the ground-state fidelities found using a variational-quantum-eigensolver scheme. Finally, we outline other applications of the quantum power method, including several moment-based methods. We numerically demonstrate the connectedmoment expansion for the imaginary-time evolution and compare the results with the multireference Krylov-subspace diagonalization.",keywords:["Quantum computer","Hamiltonian","Krylov subspace","Qubit","Quantum","Quantum mechanics"],concepts:["Quantum computer","Hamiltonian","Krylov subspace","Qubit","Quantum","Quantum mechanics"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.010333",is_oa:!0,n_refs:158,n_refs_in_core:20,degree:37,community:2,deg_w:788,betweenness:.0017,pagerank:.00577,eigenvector:.0873},{id:184,oaid:"W4387042027",doi:"10.1109/tqe.2023.3319319",title:"Hybrid Quantum–Classical Generative Adversarial Network for High-Resolution Image Generation",authors:[{name:"S. Tsang",institutions:["The University of Melbourne"]},{name:"Maxwell T. West",institutions:["The University of Melbourne"]},{name:"Sarah Erfani",institutions:["The University of Melbourne"]},{name:"Muhammad Usman",institutions:["Commonwealth Scientific and Industrial Research Organisation","The University of Melbourne","Data61"]}],authorString:"S. Tsang; Maxwell T. West; Sarah Erfani; Muhammad Usman",institutions:["Commonwealth Scientific and Industrial Research Organisation","Data61","The University of Melbourne"],countries:["AU"],year:2023,journal:"IEEE Transactions on Quantum Engineering",citations:98,abstract:"Quantum machine learning (QML) has received increasing attention due to its potential to outperform classical machine learning methods in problems such as classification and identification tasks. A subclass of QML methods is quantum generative adversarial networks (QGANs) which have been studied as a quantum counterpart of classical GANs widely used in image manipulation and generation tasks. The existing work on QGANs is still limited to small-scale proof-of-concept examples based on images with significant down-scaling. Here we integrate classical and quantum techniques to propose a new hybrid quantum-classical GAN framework. We demonstrate its superior learning capabilities over existing quantum techniques by generating 28×28 pixels grey-scale images without dimensionality reduction or classical pre/post-processing on multiple classes of the standard MNIST and Fashion MNIST datasets, which achieves comparable results to classical frameworks with three orders of magnitude less trainable generator parameters. To gain further insight into the working of our hybrid approach, we systematically explore the impact of its parameter space by varying the number of qubits, the size of image patches, the number of layers in the generator, the shape of the patches and the choice of prior distribution. Our results show that increasing the quantum generator size generally improves the learning capability of the network. The developed framework provides a foundation for future design of QGANs with optimal parameter set tailored for complex image generation tasks",keywords:["MNIST database","Quantum","Quantum machine learning","Generator","Qubit","Curse of dimensionality"],concepts:["MNIST database","Quantum","Quantum machine learning","Generator","Qubit","Curse of dimensionality"],pdf_url:"https://ieeexplore.ieee.org/ielx7/8924785/8961200/10264175.pdf",is_oa:!0,n_refs:73,n_refs_in_core:13,degree:27,community:0,deg_w:245,betweenness:.0013,pagerank:.00267,eigenvector:.0095},{id:185,oaid:"W4380873283",doi:"10.1016/j.drudis.2023.103675",title:"Quantum computing for near-term applications in generative chemistry and drug discovery",authors:[{name:"Alexey N. Pyrkov",institutions:["Insilicogen (South Korea)"]},{name:"Alex Aliper",institutions:[]},{name:"Dmitry S. Bezrukov",institutions:[]},{name:"Yen‐Chu Lin",institutions:[]},{name:"Daniil Polykovskiy",institutions:[]},{name:"Petrina Kamya",institutions:[]},{name:"Feng Ren",institutions:[]},{name:"Alex Zhavoronkov",institutions:[]}],authorString:"Alexey N. Pyrkov; Alex Aliper; Dmitry S. Bezrukov; Yen‐Chu Lin; Daniil Polykovskiy; Petrina Kamya; Feng Ren; Alex Zhavoronkov",institutions:["Insilicogen (South Korea)"],countries:["KR"],year:2023,journal:"Drug Discovery Today",citations:97,abstract:"In recent years, drug discovery and life sciences have been revolutionized with machine learning and artificial intelligence (AI) methods. Quantum computing is touted to be the next most significant leap in technology; one of the main early practical applications for quantum computing solutions is predicted to be in quantum chemistry simulations. Here, we review the near-term applications of quantum computing and their advantages for generative chemistry and highlight the challenges that can be addressed with noisy intermediate-scale quantum (NISQ) devices. We also discuss the possible integration of generative systems running on quantum computers into established generative AI platforms.",keywords:["Generative grammar","Drug discovery","Quantum computer","Term","Quantum","Generative model","Quantum chemistry"],concepts:["Generative grammar","Drug discovery","Quantum computer","Term","Quantum","Generative model","Quantum chemistry"],pdf_url:"https://doi.org/10.1016/j.drudis.2023.103675",is_oa:!0,n_refs:141,n_refs_in_core:17,degree:31,community:0,deg_w:485,betweenness:.002,pagerank:.004,eigenvector:.0593},{id:186,oaid:"W2969241977",doi:"10.1088/1367-2630/ab965e",title:"Variational-state quantum metrology",authors:[{name:"Bálint Koczor",institutions:["University of Oxford"]},{name:"Suguru Endo",institutions:["University of Oxford"]},{name:"Tyson Jones",institutions:["University of Oxford"]},{name:"Yuichiro Matsuzaki",institutions:["National Institute of Advanced Industrial Science and Technology"]},{name:"Simon C Benjamin",institutions:["University of Oxford"]}],authorString:"Bálint Koczor; Suguru Endo; Tyson Jones; Yuichiro Matsuzaki; Simon C Benjamin",institutions:["National Institute of Advanced Industrial Science and Technology","University of Oxford"],countries:["GB","JP"],year:2020,journal:"New Journal of Physics",citations:96,abstract:"Abstract Quantum technologies exploit entanglement to enhance various tasks beyond their classical limits including computation, communication and measurements. Quantum metrology aims to increase the precision of a measured quantity that is estimated in the presence of statistical errors using entangled quantum states. We present a novel approach for finding (near) optimal states for metrology in the presence of noise, using variational techniques as a tool for efficiently searching the high-dimensional space of quantum states, which would be classically intractable. We comprehensively explore systems consisting of up to 9 qubits and find new highly entangled states that are not symmetric under permutations and non-trivially outperform previously known states up to a constant factor 2. We consider a range of environmental noise models; while passive quantum states cannot achieve a fundamentally superior scaling (as established by prior asymptotic results) we do observe a significant absolute quantum advantage. We finally outline a possible experimental setup for variational quantum metrology which can be implemented in near-term hardware.",keywords:["Quantum metrology","Metrology","Quantum sensor","Quantum entanglement","Qubit","Quantum","Quantum technology","Scaling"],concepts:["Quantum metrology","Metrology","Quantum sensor","Quantum entanglement","Quantum mechanics","Statistical physics","Qubit"],pdf_url:"https://iopscience.iop.org/article/10.1088/1367-2630/ab965e/pdf",is_oa:!0,n_refs:84,n_refs_in_core:8,degree:30,community:0,deg_w:244.5,betweenness:.0021,pagerank:.00235,eigenvector:.0223},{id:187,oaid:"W3027746348",doi:"10.22331/q-2021-01-25-386",title:"Measuring Analytic Gradients of General Quantum Evolution with the Stochastic Parameter Shift Rule",authors:[{name:"Leonardo Banchi",institutions:["Istituto Nazionale di Fisica Nucleare, Sezione di Firenze","University of Florence"]},{name:"Gavin E. Crooks",institutions:[]}],authorString:"Leonardo Banchi; Gavin E. Crooks",institutions:["Istituto Nazionale di Fisica Nucleare, Sezione di Firenze","University of Florence"],countries:["IT"],year:2021,journal:"Quantum",citations:94,abstract:"Hybrid quantum-classical optimization algorithms represent one of the most promising application for near-term quantum computers. In these algorithms the goal is to optimize an observable quantity with respect to some classical parameters, using feedback from measurements performed on the quantum device. Here we study the problem of estimating the gradient of the function to be optimized directly from quantum measurements, generalizing and simplifying some approaches present in the literature, such as the so-called parameter-shift rule. We derive a mathematically exact formula that provides a stochastic algorithm for estimating the gradient of any multi-qubit parametric quantum evolution, without the introduction of ancillary qubits or the use of Hamiltonian simulation techniques. The gradient measurement is possible when the underlying device can realize all Pauli rotations in the expansion of the Hamiltonian whose coefficients depend on the parameter. Our algorithm continues to work, although with some approximations, even when all the available quantum gates are noisy, for instance due to the coupling between the quantum device and an unknown environment.",keywords:["Hamiltonian","Quantum algorithm","Quantum","Observable","Quantum phase estimation algorithm","Pauli exclusion principle","Quantum process","Quantum operation"],concepts:["Hamiltonian","Quantum algorithm","Quantum","Observable","Statistical physics","Quantum phase estimation algorithm","Pauli exclusion principle"],pdf_url:"https://quantum-journal.org/papers/q-2021-01-25-386/pdf/",is_oa:!0,n_refs:34,n_refs_in_core:14,degree:30,community:0,deg_w:247.5,betweenness:.0012,pagerank:.00259,eigenvector:.0108},{id:188,oaid:"W2967803592",doi:"10.1103/physrevx.10.031064",title:"Nearly Optimal Measurement Scheduling for Partial Tomography of Quantum States",authors:[{name:"Xavier Bonet-Monroig",institutions:["Leiden University","QuTech","Delft University of Technology"]},{name:"Ryan Babbush",institutions:["Google (United States)"]},{name:"Thomas E. O’Brien",institutions:["Leiden University","Google (United States)"]}],authorString:"Xavier Bonet-Monroig; Ryan Babbush; Thomas E. O’Brien",institutions:["Delft University of Technology","Google (United States)","Leiden University","QuTech"],countries:["NL","US"],year:2020,journal:"Physical Review X",citations:91,abstract:"A new analysis provides bounds on the size of ``clique covers''---mutually commuting subsets of quantum state observables---and hence the time required for certain near-term quantum computing applications.",keywords:["Quantum state","Quantum","Quantum computer","Quantum tomography","State","Scheduling","Quantum algorithm","Quantum information"],concepts:["Quantum state","Quantum","Quantum computer","Quantum tomography","State","Scheduling","Statistical physics"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevX.10.031064",is_oa:!0,n_refs:26,n_refs_in_core:14,degree:33,community:1,deg_w:396.5,betweenness:.001,pagerank:.0033,eigenvector:.0323},{id:189,oaid:"W3013067859",doi:"10.1039/d0sc01908a",title:"Hardware efficient quantum algorithms for vibrational structure calculations",authors:[{name:"Pauline J. Ollitrault",institutions:["IBM Research - Zurich"]},{name:"Alberto Baiardi",institutions:["ETH Zurich"]},{name:"Markus Reiher",institutions:["ETH Zurich"]},{name:"Ivano Tavernelli",institutions:["IBM Research - Zurich"]}],authorString:"Pauline J. Ollitrault; Alberto Baiardi; Markus Reiher; Ivano Tavernelli",institutions:["ETH Zurich","IBM Research - Zurich"],countries:["CH"],year:2020,journal:"Chemical Science",citations:90,abstract:". In particular, we define a novel compact heuristic circuit and demonstrate that it provides a good compromise in terms of circuit depth, optimization costs, and accuracy. We evaluate the requirements, number of qubits and circuit depth, for the calculation of vibrational energies on quantum hardware and compare them with state-of-the-art classical vibrational structure algorithms for molecules with up to seven atoms.",keywords:["Quantum","Algorithm","Quantum algorithm","Computational science","Quantum mechanics"],concepts:["Quantum","Algorithm","Quantum algorithm","Computational science"],pdf_url:"https://pubs.rsc.org/en/content/articlepdf/2020/sc/d0sc01908a",is_oa:!0,n_refs:102,n_refs_in_core:21,degree:38,community:1,deg_w:485.5,betweenness:.0016,pagerank:.00393,eigenvector:.0394},{id:190,oaid:"W3092073280",doi:"10.1103/physrevapplied.15.034026",title:"Mitigating Realistic Noise in Practical Noisy Intermediate-Scale Quantum Devices",authors:[{name:"Jinzhao Sun",institutions:["University of Oxford"]},{name:"Xiao Yuan",institutions:["Peking University","University of Oxford","Stanford University"]},{name:"Takahiro Tsunoda",institutions:["University of Oxford"]},{name:"Vlatko Vedral",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Oxford"]},{name:"Simon C. Benjamin",institutions:["University of Oxford"]},{name:"Suguru Endo",institutions:["NTT (Japan)","University of Oxford"]}],authorString:"Jinzhao Sun; Xiao Yuan; Takahiro Tsunoda; Vlatko Vedral; Simon C. Benjamin; Suguru Endo",institutions:["Centre for Quantum Technologies","NTT (Japan)","National University of Singapore","Peking University","Stanford University","University of Oxford"],countries:["CN","GB","JP","SG","US"],year:2021,journal:"Physical Review Applied",citations:90,abstract:"Quantum error mitigation (QEM) is vital for noisy intermediate-scale quantum (NISQ) devices. While most conventional QEM schemes assume discrete gate-based circuits with noise appearing either before or after each gate, the assumptions are inappropriate for describing realistic noise that may have strong gate dependence and complicated nonlocal effects, and general computing models such as analog quantum simulators. To address these challenges, we first extend the scenario, where each computation process, being either digital or analog, is described by a continuous time evolution. For noise from imperfections of the engineered Hamiltonian or additional noise operators, we show it can be effectively suppressed by a stochastic QEM method. Since our method assumes only accurate single qubit controls, it is applicable to all digital quantum computers and various analog simulators. Meanwhile, errors in the mitigation procedure can be suppressed by leveraging the Richardson extrapolation method. As we numerically test our method with various Hamiltonians under energy relaxation and dephasing noise and digital quantum circuits with additional two-qubit crosstalk, we show an improvement of simulation accuracy by 2 orders. We assess the resource cost of our scheme and conclude the feasibility of accurate quantum computing with NISQ devices.",keywords:["Noise","Qubit","Quantum computer","Dephasing","Quantum error correction","Quantum","Hamiltonian","Quantum noise"],concepts:["Noise","Qubit","Quantum computer","Dephasing","Quantum error correction","Quantum","Hamiltonian"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevApplied.15.034026",is_oa:!0,n_refs:83,n_refs_in_core:13,degree:29,community:3,deg_w:291,betweenness:.0018,pagerank:.00277,eigenvector:.017},{id:191,oaid:"W2803434569",doi:"10.1007/s42484-020-00025-7",title:"Universal discriminative quantum neural networks",authors:[{name:"Hongxiang Chen",institutions:["Clifton Hospital","University College London"]},{name:"Leonard Wossnig",institutions:["Clifton Hospital","University College London"]},{name:"Simone Severini",institutions:["Shanghai Jiao Tong University","University College London"]},{name:"Hartmut Neven",institutions:["Google (United States)"]},{name:"Morteza Mohseni",institutions:["Google (United States)"]}],authorString:"Hongxiang Chen; Leonard Wossnig; Simone Severini; Hartmut Neven; Morteza Mohseni",institutions:["Clifton Hospital","Google (United States)","Shanghai Jiao Tong University","University College London"],countries:["CN","GB","US"],year:2020,journal:"Quantum Machine Intelligence",citations:88,abstract:"Abstract Recent results have demonstrated the successful applications of quantum-classical hybrid methods to train quantum circuits for a variety of machine learning tasks. A natural question to ask is consequentially whether we can also train such quantum circuits to discriminate quantum data, i.e., perform classification on data stored in form of quantum states. Although quantum mechanics fundamentally forbids deterministic discrimination of non-orthogonal states, we show in this work that it is possible to train a quantum circuit to discriminate such data with a trade-off between minimizing error rates and inconclusiveness rates of the classification tasks. Our approach achieves at the same time a performance which is close to the theoretically optimal values and a generalization ability to previously unseen quantum data. This generalization power hence distinguishes our work from previous circuit optimization results and furthermore provides an example of a quantum machine learning task that has inherently no classical analogue.",keywords:["Quantum circuit","Quantum process","Quantum phase estimation algorithm","Quantum algorithm","Quantum","Quantum network","Quantum information"],concepts:["Quantum circuit","Quantum process","Quantum phase estimation algorithm","Quantum algorithm","Quantum","Quantum network","Quantum information"],pdf_url:"https://link.springer.com/content/pdf/10.1007/s42484-020-00025-7.pdf",is_oa:!0,n_refs:89,n_refs_in_core:10,degree:27,community:0,deg_w:279,betweenness:.001,pagerank:.0029,eigenvector:.012},{id:192,oaid:"W4387043683",doi:"10.1038/s41467-023-41217-6",title:"The complexity of NISQ",authors:[{name:"Sitan Chen",institutions:["Harvard University","University of California, Berkeley"]},{name:"Jordan Cotler",institutions:["Harvard University Press"]},{name:"Hsin-Yuan Huang",institutions:["California Institute of Technology"]},{name:"Jerry Li",institutions:["Microsoft (United States)","Microsoft Research (United Kingdom)"]}],authorString:"Sitan Chen; Jordan Cotler; Hsin-Yuan Huang; Jerry Li",institutions:["California Institute of Technology","Harvard University","Harvard University Press","Microsoft (United States)","Microsoft Research (United Kingdom)","University of California, Berkeley"],countries:["GB","US"],year:2023,journal:"Nature Communications",citations:88,abstract:"The recent proliferation of NISQ devices has made it imperative to understand their power. In this work, we define and study the complexity class NISQ, which encapsulates problems that can be efficiently solved by a classical computer with access to noisy quantum circuits. We establish super-polynomial separations in the complexity among classical computation, NISQ, and fault-tolerant quantum computation to solve some problems based on modifications of Simon's problems. We then consider the power of NISQ for three well-studied problems. For unstructured search, we prove that NISQ cannot achieve a Grover-like quadratic speedup over classical computers. For the Bernstein-Vazirani problem, we show that NISQ only needs a number of queries logarithmic in what is required for classical computers. Finally, for a quantum state learning problem, we prove that NISQ is exponentially weaker than classical computers with access to noiseless constant-depth quantum circuits.",keywords:["Quantum computer","Speedup","Theoretical computer science","Computation","Logarithm","Quantum algorithm","Quantum"],concepts:["Quantum computer","Speedup","Theoretical computer science","Computation","Logarithm","Quantum algorithm","Quantum"],pdf_url:"https://www.nature.com/articles/s41467-023-41217-6.pdf",is_oa:!0,n_refs:76,n_refs_in_core:14,degree:28,community:0,deg_w:305,betweenness:.0019,pagerank:.00292,eigenvector:.0255},{id:193,oaid:"W3139445264",doi:"10.1103/prxquantum.3.020323",title:"Real-Time Evolution for Ultracompact Hamiltonian Eigenstates on Quantum Hardware",authors:[{name:"Katherine Klymko",institutions:["Lawrence Berkeley National Laboratory","National Energy Research Scientific Computing Center"]},{name:"Carlos Mejuto-Zaera",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"Stephen J. Cotton",institutions:["Ames Research Center","KBR (United States)"]},{name:"Filip Wudarski",institutions:["Ames Research Center","Research Institute for Advanced Computer Science"]},{name:"Miroslav Urbánek",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Diptarka Hait",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"Martin Head‐Gordon",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]},{name:"K. Birgitta Whaley",institutions:["University of California, Berkeley"]},{name:"Jonathan E. Moussa",institutions:["Molecular Sciences Software Institute"]},{name:"Nathan Wiebe",institutions:["University of Toronto"]},{name:"Wibe A. de Jong",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Norm M. Tubman",institutions:["Ames Research Center"]}],authorString:"Katherine Klymko; Carlos Mejuto-Zaera; Stephen J. Cotton; Filip Wudarski; Miroslav Urbánek; Diptarka Hait; Martin Head‐Gordon; K. Birgitta Whaley; Jonathan E. Moussa; Nathan Wiebe; Wibe A. de Jong; Norm M. Tubman",institutions:["Ames Research Center","KBR (United States)","Lawrence Berkeley National Laboratory","Molecular Sciences Software Institute","National Energy Research Scientific Computing Center","Research Institute for Advanced Computer Science","University of California, Berkeley","University of Toronto"],countries:["CA","US"],year:2022,journal:"PRX Quantum",citations:88,abstract:"In this work we present a detailed analysis of variational quantum phase estimation (VQPE), a method based on real-time evolution for ground-and excited-state estimation on near-term hardware. We derive the theoretical ground on which the approach stands, and demonstrate that it provides one of the most compact variational expansions to date for solving strongly correlated Hamiltonians, when starting from an appropriate reference state. At the center of VQPE lies a set of equations, with a simple geometrical interpretation, which provides conditions for the time evolution grid in order to decouple eigenstates out of the set of time-evolved expansion states, and connects the method to the classical filter-diagonalization algorithm. Furthermore, we introduce what we call the unitary formulation of VQPE, in which the number of matrix elements that need to be measured scales linearly with the number of expansion states, and we provide an analysis of the effects of noise that substantially improves previous considerations. The unitary formulation allows for a direct comparison to iterative phase estimation. Our results mark VQPE as both a natural and highly efficient quantum algorithm for ground-and excited-state calculations of general manybody systems. We demonstrate a hardware implementation of VQPE for the transverse field Ising model. Furthermore, we illustrate its power on a paradigmatic example of strong correlation (Cr 2 in the def2-SVP basis set), and show that it is possible to reach chemical accuracy with as few as approximately 50 time steps.",keywords:["Hamiltonian","Unitary transformation","Eigenvalues and eigenvectors","Ising model","Excited state","Quantum","Quantum phase estimation algorithm","Statistical physics"],concepts:["Hamiltonian","Unitary transformation","Eigenvalues and eigenvectors","Ising model","Excited state","Quantum","Quantum phase estimation algorithm","Statistical physics"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.3.020323",is_oa:!0,n_refs:73,n_refs_in_core:13,degree:28,community:2,deg_w:248.5,betweenness:.0025,pagerank:.00251,eigenvector:.0136},{id:194,oaid:"W2974956294",doi:"10.1103/physrevresearch.2.033281",title:"Calculation of the Green's function on near-term quantum computers",authors:[{name:"Suguru Endo",institutions:[]},{name:"Iori Kurata",institutions:["The University of Tokyo"]},{name:"Yuya O. Nakagawa",institutions:[]}],authorString:"Suguru Endo; Iori Kurata; Yuya O. Nakagawa",institutions:["The University of Tokyo"],countries:["JP"],year:2020,journal:"Physical Review Research",citations:87,abstract:"The authors propose a method to calculate the Green's function on near-term quantum computers. The method enables the calculation of several physical properties of the system of interest on near-term quantum computers.",keywords:["Quantum computer","Quantum","Function","Quantum algorithm","Quantum system","Quantum error correction","Open quantum system","Quantum operation"],concepts:["Quantum computer","Quantum","Function","Quantum algorithm","Quantum system","Quantum error correction","Quantum mechanics"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.2.033281",is_oa:!0,n_refs:60,n_refs_in_core:19,degree:41,community:2,deg_w:656,betweenness:.0018,pagerank:.00492,eigenvector:.0672},{id:195,oaid:"W3212431276",doi:"10.1103/prxquantum.2.040202",title:"Practical Guide for Building Superconducting Quantum Devices",authors:[{name:"Yvonne Y. Gao",institutions:["Centre for Quantum Technologies","National University of Singapore"]},{name:"M. A. Rol",institutions:[]},{name:"Steven Touzard",institutions:["Centre for Quantum Technologies","National University of Singapore"]},{name:"Chen Wang",institutions:["University of Massachusetts Amherst"]}],authorString:"Yvonne Y. Gao; M. A. Rol; Steven Touzard; Chen Wang",institutions:["Centre for Quantum Technologies","National University of Singapore","University of Massachusetts Amherst"],countries:["SG","US"],year:2021,journal:"PRX Quantum",citations:87,abstract:"Quantum computing offers a powerful new paradigm of information processing that has the potential to transform a wide range of industries. In the pursuit of the tantalizing promises of a universal quantum computer, a multitude of new knowledge and expertise has been developed, enabling the construction of novel quantum algorithms as well as increasingly robust quantum hardware. In particular, we have witnessed rapid progress in the circuit quantum electrodynamics (cQED) technology, which has emerged as one of the most promising physical systems that is capable of addressing the key challenges in realizing full-stack quantum computing on a large scale. In this Tutorial, we present some of the most crucial building blocks developed by the cQED community in recent years and a prcis of the latest achievements towards robust universal quantum computation. More importantly, we aim to provide a synoptic outline of the core techniques that underlie most cQED experiments and offer a practical guide for a novice experimentalist to design, construct, and characterize their first quantum device.",keywords:["Quantum computer","Quantum technology","License","Quantum information","Quantum","Sociology","Data science"],concepts:["Quantum computer","Quantum technology","License","Quantum information","Quantum","Sociology","Data science"],pdf_url:"http://link.aps.org/pdf/10.1103/PRXQuantum.2.040202",is_oa:!0,n_refs:327,n_refs_in_core:11,degree:23,community:3,deg_w:672.5,betweenness:.0012,pagerank:.00543,eigenvector:.0466},{id:196,oaid:"W2997315313",doi:"10.1103/physreva.101.052340",title:"Symmetry-adapted variational quantum eigensolver",authors:[{name:"Kazuhiro Seki",institutions:["RIKEN Center for Emergent Matter Science"]},{name:"Tomonori Shirakawa",institutions:["RIKEN Center for Computational Science"]},{name:"Seiji Yunoki",institutions:["Pioneer (Japan)","RIKEN Center for Computational Science","RIKEN Center for Emergent Matter Science"]}],authorString:"Kazuhiro Seki; Tomonori Shirakawa; Seiji Yunoki",institutions:["Pioneer (Japan)","RIKEN Center for Computational Science","RIKEN Center for Emergent Matter Science"],countries:["JP"],year:2020,journal:"Physical review. A/Physical review, A",citations:86,abstract:"We propose a scheme to restore spatial symmetry of Hamiltonian in the variational-quantum-eigensolver (VQE) algorithm for which the quantum circuit structures used usually break the Hamiltonian symmetry. The symmetry-adapted VQE scheme introduced here simply applies the projection operator, which is Hermitian but not unitary, to restore the spatial symmetry in a desired irreducible representation of the spatial group. The entanglement of a quantum state is still represented in a quantum circuit but the nonunitarity of the projection operator is treated classically as postprocessing in the VQE framework. By numerical simulations for a spin-$1/2$ Heisenberg model on a one-dimensional ring, we demonstrate that the symmetry-adapted VQE scheme with a shallower quantum circuit can achieve significant improvement in terms of the fidelity of the ground state and has a great advantage in terms of the ground-state energy with decent accuracy, as compared to the non-symmetry-adapted VQE scheme. We also demonstrate that the present scheme can approximate low-lying excited states that can be specified by symmetry sectors, using the same circuit structure for the ground-state calculation.",keywords:["Hamiltonian","Ground state","Quantum circuit","Quantum algorithm","Quantum mechanics","Quantum","Topology"],concepts:["Hamiltonian","Ground state","Quantum circuit","Quantum algorithm","Quantum mechanics","Quantum","Topology"],pdf_url:"https://arxiv.org/pdf/1912.13146",is_oa:!0,n_refs:115,n_refs_in_core:21,degree:37,community:2,deg_w:500.5,betweenness:.003,pagerank:.00412,eigenvector:.0347},{id:197,oaid:"W3127043585",doi:"10.1109/tqe.2021.3140190",title:"Layer VQE: A Variational Approach for Combinatorial Optimization on Noisy Quantum Computers",authors:[{name:"Xiaoyuan Liu",institutions:["University of Delaware"]},{name:"Anthony Angone",institutions:["Clemson University"]},{name:"Ruslan Shaydulin",institutions:["Argonne National Laboratory"]},{name:"Ilya Safro",institutions:["University of Delaware"]},{name:"Yuri Alexeev",institutions:["Argonne National Laboratory"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]}],authorString:"Xiaoyuan Liu; Anthony Angone; Ruslan Shaydulin; Ilya Safro; Yuri Alexeev; Łukasz Cincio",institutions:["Argonne National Laboratory","Clemson University","Los Alamos National Laboratory","University of Delaware"],countries:["US"],year:2022,journal:"IEEE Transactions on Quantum Engineering",citations:85,abstract:"Combinatorial optimization on near-term quantum devices is a promising path to demonstrating quantum advantage. However, the capabilities of these devices are constrained by high noise or error rates. In this article, inspired by the variational quantum eigensolver (VQE), we propose an iterative layer VQE (L-VQE) approach. We present a large-scale numerical study, simulating circuits with up to 40 qubits and 352 parameters, that demonstrates the potential of the proposed approach. We evaluate quantum optimization heuristics on the problem of detecting multiple communities in networks, for which we introduce a novel qubit-frugal formulation. We numerically compare L-VQE with the quantum approximate optimization algorithm (QAOA) and demonstrate that QAOA achieves lower approximation ratios while requiring significantly deeper circuits. We show that L-VQE is more robust to finite sampling errors and has a higher chance of finding the solution as compared with standard VQE approaches. Our simulation results show that L-VQE performs well under realistic hardware noise.",keywords:["Qubit","Quantum","Quantum computer","Heuristics","Quantum circuit","Optimization problem","Quantum algorithm"],concepts:["Qubit","Quantum","Quantum computer","Heuristics","Quantum circuit","Optimization problem","Quantum algorithm"],pdf_url:"https://ieeexplore.ieee.org/ielx7/8924785/9669178/09669165.pdf",is_oa:!0,n_refs:129,n_refs_in_core:16,degree:32,community:0,deg_w:528,betweenness:.0017,pagerank:.00418,eigenvector:.0495},{id:198,oaid:"W3047180424",doi:"10.1103/physrevresearch.3.023092",title:"Quantum-optimal-control-inspired ansatz for variational quantum algorithms",authors:[{name:"Alexandre Choquette",institutions:["Université de Sherbrooke","IBM Research - Zurich"]},{name:"Agustín Di Paolo",institutions:["Université de Sherbrooke"]},{name:"Panagiotis Kl. Barkoutsos",institutions:["IBM Research - Zurich"]},{name:"David Sénéchal",institutions:["Université de Sherbrooke"]},{name:"Ivano Tavernelli",institutions:["IBM Research - Zurich"]},{name:"Alexandre Blais",institutions:["Canadian Institute for Advanced Research","Université de Sherbrooke"]}],authorString:"Alexandre Choquette; Agustín Di Paolo; Panagiotis Kl. Barkoutsos; David Sénéchal; Ivano Tavernelli; Alexandre Blais",institutions:["Canadian Institute for Advanced Research","IBM Research - Zurich","Université de Sherbrooke"],countries:["CA","CH"],year:2021,journal:"Physical Review Research",citations:84,abstract:"The authors propose a quantum circuit, inspired by the theory of quantum optimal control, to prepare the ground state of the few-body Hubbard model and the water molecule with high-fidelity in a quantum computer.",keywords:["Ansatz","Quantum","Quantum algorithm","Quantum control","Algorithm","Optimal control"],concepts:["Ansatz","Quantum","Quantum algorithm","Quantum control","Algorithm","Optimal control"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevResearch.3.023092",is_oa:!0,n_refs:103,n_refs_in_core:18,degree:34,community:1,deg_w:615,betweenness:.0014,pagerank:.00459,eigenvector:.0729},{id:199,oaid:"W3045606049",doi:"10.1038/s41467-021-27045-6",title:"Noise-induced barren plateaus in variational quantum algorithms",authors:[{name:"Samson Wang",institutions:["Los Alamos National Laboratory","Imperial College London"]},{name:"Enrico Fontana",institutions:["Los Alamos National Laboratory","National Physical Laboratory","University of Strathclyde"]},{name:"M. Cerezo",institutions:["Los Alamos National Laboratory","Los Alamos National Security (United States)"]},{name:"Kunal Sharma",institutions:["Louisiana State University","Los Alamos National Laboratory","Joint Center for Quantum Information and Computer Science","University of Maryland, College Park"]},{name:"Akira Sone",institutions:["Los Alamos National Laboratory","Invicro (United States)"]},{name:"Łukasz Cincio",institutions:["Los Alamos National Laboratory"]},{name:"Patrick J. Coles",institutions:["Los Alamos National Laboratory"]}],authorString:"Samson Wang; Enrico Fontana; M. Cerezo; Kunal Sharma; Akira Sone; Łukasz Cincio; Patrick J. Coles",institutions:["Imperial College London","Invicro (United States)","Joint Center for Quantum Information and Computer Science","Los Alamos National Laboratory","Los Alamos National Security (United States)","Louisiana State University","National Physical Laboratory","University of Maryland, College Park","University of Strathclyde"],countries:["GB","US"],year:2021,journal:"Nature Communications",citations:82,abstract:"Variational Quantum Algorithms (VQAs) may be a path to quantum advantage on Noisy Intermediate-Scale Quantum (NISQ) computers. A natural question is whether noise on NISQ devices places fundamental limitations on VQA performance. We rigorously prove a serious limitation for noisy VQAs, in that the noise causes the training landscape to have a barren plateau (i.e., vanishing gradient). Specifically, for the local Pauli noise considered, we prove that the gradient vanishes exponentially in the number of qubits n if the depth of the ansatz grows linearly with n. These noise-induced barren plateaus (NIBPs) are conceptually different from noise-free barren plateaus, which are linked to random parameter initialization. Our result is formulated for a generic ansatz that includes as special cases the Quantum Alternating Operator Ansatz and the Unitary Coupled Cluster Ansatz, among others. For the former, our numerical heuristics demonstrate the NIBP phenomenon for a realistic hardware noise model.",keywords:["Ansatz","Noise","Quantum computer","Initialization","Quantum algorithm","Qubit","Polynomial","Heuristics"],concepts:["Ansatz","Noise","Quantum computer","Initialization","Quantum algorithm","Qubit","Polynomial","Heuristics"],pdf_url:"https://www.nature.com/articles/s41467-021-27045-6.pdf",is_oa:!0,n_refs:130,n_refs_in_core:31,degree:51,community:0,deg_w:1190,betweenness:.0034,pagerank:.00841,eigenvector:.1261}],t={n_papers:200,papers_with_refs:200,mean_refs:112.3,direct_citation_edges:2690,coupling_edges_kept:1288,total_edges_kept:4010,data_mode:"co-citation",reference_source:"OpenAlex referenced_works"},i={papers:e,completeness:t};export{t as completeness,i as default,e as papers};
